/**
 * Bajar la copia de la nube y ponerla en este teléfono.
 *
 * Vive aparte porque lo piden dos sitios: la pantalla de cuenta, cuando la
 * persona va a buscarlo, y el aviso del teléfono vacío, al cambiar de equipo.
 * Un solo camino para los dos, para que no se arreglen por separado.
 */

import { t } from '../i18n';
import { useApp } from './useApp';
import { useAuth } from './useAuth';

/** Devuelve el error que hay que mostrar, o null si todo salió bien. */
export async function bajarCopia(): Promise<string | null> {
  const resultado = await useAuth.getState().pullBackup();
  if (typeof resultado === 'string') return resultado;

  // Pasa por el mismo control que un archivo: si viene roto, no se toca nada
  if (!useApp.getState().restoreFromCloud(resultado)) return t('cuentaNube.laCopiaDeLa');

  useApp.getState().notify(t('cuentaNube.datosRestauradosDesdeLa'));
  return null;
}
