/**
 * Estado inicial y constantes del almacenamiento.
 */

import type { AppData, Country, Profile, Settings } from '../domain/types';
import type { Currency } from '../lib/money';
import { DEFAULT_CATEGORIES, DEFAULT_INCOME_SOURCES } from '../domain/categories';
import { createCashAccount } from '../domain/accounts';
import { DEFAULT_RATE } from '../lib/fx';

/** Sube cuando el modelo cambie de forma incompatible. */
export const SCHEMA_VERSION = 3;

/** Clave de la versión 3. Las claves grd3_* de la versión vieja no se tocan. */
export const STORAGE_KEY = 'gestorrd.v3.data';

/** La moneda principal sale del país donde se registra la persona. */
export function currencyForCountry(country: Country): Currency {
  return country === 'US' ? 'USD' : 'DOP';
}

export function createProfile(country: Country): Profile {
  return {
    country,
    mainCurrency: currencyForCountry(country),
    createdAt: new Date().toISOString(),
  };
}

export function createSettings(): Settings {
  return {
    theme: 'auto',
    privacy: false,
    biometrics: false,
    remindDaysBefore: 3,
  };
}

/** Estado de una instalación nueva, sin datos. */
export function createEmptyData(country: Country = 'DO'): AppData {
  return {
    schemaVersion: SCHEMA_VERSION,
    profile: createProfile(country),
    settings: createSettings(),
    fx: { ...DEFAULT_RATE },
    // El efectivo existe desde el primer día: si no, un gasto en billetes
    // no tendría de dónde salir.
    accounts: [createCashAccount(country)],
    transactions: [],
    categories: DEFAULT_CATEGORIES.map((category) => ({ ...category })),
    incomeSources: DEFAULT_INCOME_SOURCES.map((source) => ({ ...source })),
    budgets: [],
    debts: [],
    goals: [],
    recurrences: [],
    updatedAt: new Date().toISOString(),
  };
}
