/**
 * Primer arranque.
 *
 * Tres pantallas y fuera. Se pregunta dónde vive la persona, porque de eso
 * depende en qué moneda se le habla, y si quiere ponerle llave a la app.
 * Todo lo demás se puede cambiar después en Ajustes, así que no hay por qué
 * preguntarlo ahora.
 */

import { useEffect, useState } from 'react';
import { t } from '../../i18n';
import { useApp } from '../../store/useApp';
import type { Country } from '../../domain/types';
import { Button, Notice } from '../../ui/primitives';
import { Field } from '../../ui/forms';
import { paisDelTelefono } from '../../lib/region';
import { PIN_MAXIMO, validatePin } from '../../lib/pin';
import { nombreDeBiometria, tipoDeBiometria, type Biometria } from '../../lib/nativo';

export function Bienvenida() {
  const completarBienvenida = useApp((state) => state.completarBienvenida);
  const [paso, setPaso] = useState<'saludo' | 'pais' | 'proteger'>('saludo');
  const [pais, setPais] = useState<Country>(() => paisDelTelefono());

  if (paso === 'saludo') {
    return (
      <div className="bienvenida">
        <div className="bienvenida__centro">
          <p className="bienvenida__marca">GestorRD</p>
          <h1 className="bienvenida__titulo">{t('bienvenida.tusPesosYTus')}</h1>
          <p className="bienvenida__texto">
            Apunta lo que entra y lo que sale, lleva tus cuentas y tarjetas, y mira en qué se te va
            el dinero. Todo se guarda en tu teléfono.
          </p>
        </div>

        <div className="bienvenida__pie">
          <Button wide onClick={() => setPaso('pais')}>
            Empezar
          </Button>
        </div>
      </div>
    );
  }

  if (paso === 'proteger') {
    return <Proteger onTerminar={() => completarBienvenida(pais)} />;
  }

  return (
    <div className="bienvenida">
      <div className="bienvenida__centro">
        <h1 className="bienvenida__titulo">{t('bienvenida.dondeVives')}</h1>
        <p className="bienvenida__texto">{t('bienvenida.esParaSaberEn')}</p>

        <div className="bienvenida__opciones">
          <button
            type="button"
            className="pais"
            aria-pressed={pais === 'DO'}
            onClick={() => setPais('DO')}
          >
            <span className="pais__bandera" aria-hidden="true">🇩🇴</span>
            <span className="pais__centro">
              <span className="pais__nombre">República Dominicana</span>
              <span className="pais__detalle">{t('bienvenida.tusCifrasEnPesos')}</span>
            </span>
          </button>

          <button
            type="button"
            className="pais"
            aria-pressed={pais === 'US'}
            onClick={() => setPais('US')}
          >
            <span className="pais__bandera" aria-hidden="true">🇺🇸</span>
            <span className="pais__centro">
              <span className="pais__nombre">Estados Unidos</span>
              <span className="pais__detalle">{t('bienvenida.tusCifrasEnDolares')}</span>
            </span>
          </button>
        </div>
      </div>

      <div className="bienvenida__pie">
        <Button wide onClick={() => setPaso('proteger')}>
          Seguir
        </Button>
        <p className="campo__ayuda" style={{ marginTop: 'var(--e3)' }}>{t('bienvenida.sePuedeCambiarDespues')}</p>
      </div>
    </div>
  );
}

/**
 * La llave de la app.
 *
 * Se ofrece, no se exige. Face ID no puede ir solo: cuando la cara no pasa
 * tiene que haber otra entrada, y esa es el PIN. Y como olvidar el PIN
 * significa empezar de cero, eso se dice aquí y no en letra chica.
 */
function Proteger({ onTerminar }: { onTerminar: () => void }) {
  const setPin = useApp((state) => state.setPin);
  const edit = useApp((state) => state.edit);
  const notify = useApp((state) => state.notify);

  const [tipo, setTipo] = useState<Biometria>('ninguna');
  const [uno, setUno] = useState('');
  const [dos, setDos] = useState('');
  const [error, setError] = useState('');
  const [guardando, setGuardando] = useState(false);

  useEffect(() => {
    void tipoDeBiometria().then(setTipo);
  }, []);

  async function activar() {
    const problema = validatePin(uno);
    if (problema) {
      setError(problema);
      return;
    }
    if (uno !== dos) {
      setError(t('proteger.noSonIguales'));
      return;
    }

    setGuardando(true);
    await setPin(uno);
    // Si el teléfono tiene cara o huella, se deja puesta: quien acaba de
    // escribir un PIN no quiere volver a escribirlo mañana.
    if (tipo !== 'ninguna') {
      edit((draft) => {
        draft.settings.biometrics = true;
      });
    }
    setGuardando(false);
    notify(t('proteger.listo'));
    onTerminar();
  }

  return (
    <div className="bienvenida">
      <div className="bienvenida__centro bienvenida__centro--alto">
        <h1 className="bienvenida__titulo">{t('proteger.titulo')}</h1>
        <p className="bienvenida__texto">
          {t('proteger.texto')}
          {tipo !== 'ninguna' && ` ${t('proteger.conCara', { nombre: nombreDeBiometria(tipo) })}`}
        </p>

        <Field
          label={t('proteger.pin')}
          type="password"
          inputMode="numeric"
          maxLength={PIN_MAXIMO}
          autoComplete="new-password"
          value={uno}
          error={error}
          hint={t('proteger.largo')}
          onChange={(event) => {
            setError('');
            setUno(event.target.value.replace(/\D/g, ''));
          }}
        />

        <Field
          label={t('proteger.otraVez')}
          type="password"
          inputMode="numeric"
          maxLength={PIN_MAXIMO}
          autoComplete="new-password"
          value={dos}
          onChange={(event) => {
            setError('');
            setDos(event.target.value.replace(/\D/g, ''));
          }}
        />

        <div className="seccion">
          <Notice tone="ambar" icon="🔑">
            {t('proteger.aviso')}
          </Notice>
        </div>
      </div>

      <div className="bienvenida__pie">
        <Button wide disabled={guardando} onClick={() => void activar()}>
          {guardando ? t('proteger.activando') : t('proteger.activar')}
        </Button>
        <Button wide variant="texto" className="seccion" disabled={guardando} onClick={onTerminar}>
          {t('proteger.ahoraNo')}
        </Button>
        <p className="campo__ayuda" style={{ marginTop: 'var(--e3)' }}>
          {t('proteger.despues')}
        </p>
      </div>
    </div>
  );
}
