/**
 * Entrada de monto con selector de moneda.
 *
 * Guarda lo que la persona escribe tal cual mientras escribe, y solo convierte
 * a centavos cuando el texto es un monto válido. Así puede borrar, escribir un
 * punto y seguir, sin que el campo pelee con ella.
 */

import { useEffect, useState } from 'react';
import type { Cents, Currency } from '../lib/money';
import { CURRENCY_SYMBOL, CURRENCY_TAG, formatNumber, parseAmount } from '../lib/money';
import { convert } from '../lib/fx';

export interface AmountInputProps {
  cents: Cents | null;
  currency: Currency;
  /** Monedas entre las que se puede elegir. Con una sola, no se muestra nada. */
  monedas?: readonly Currency[];
  onChange: (cents: Cents | null) => void;
  onCurrencyChange?: (currency: Currency) => void;
  /** Tasa para mostrar el equivalente en la otra moneda. */
  rate?: number;
  autoFocus?: boolean;
  label?: string;
}

export function AmountInput({
  cents,
  currency,
  monedas,
  onChange,
  onCurrencyChange,
  rate,
  autoFocus,
  label,
}: AmountInputProps) {
  const [texto, setTexto] = useState(() => (cents === null ? '' : formatNumber(cents)));

  // Si el monto cambia desde fuera (por ejemplo, al calcular el cambio), refresca
  useEffect(() => {
    const propio = parseAmount(texto);
    if (cents !== propio) setTexto(cents === null ? '' : formatNumber(cents));
    // Solo cuando cambia el valor de fuera
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cents]);

  function escribir(valor: string) {
    // Deja escribir dígitos, coma, punto y nada más
    const limpio = valor.replace(/[^\d.,]/g, '');
    setTexto(limpio);
    onChange(limpio === '' ? null : parseAmount(limpio));
  }

  const otra: Currency = currency === 'DOP' ? 'USD' : 'DOP';
  const equivale =
    cents !== null && cents > 0 && rate
      ? `${CURRENCY_TAG[otra]} ${formatNumber(convert(cents, currency, otra, rate))}`
      : '';

  return (
    <div className="monto-entrada">
      {onCurrencyChange && (monedas ?? ['DOP', 'USD']).length > 1 && (
        <div className="monto-entrada__monedas" role="group" aria-label="Moneda">
          {(monedas ?? (['DOP', 'USD'] as const)).map((opcion) => (
            <button
              key={opcion}
              type="button"
              className="monto-entrada__moneda"
              aria-pressed={opcion === currency}
              onClick={() => onCurrencyChange(opcion)}
            >
              {CURRENCY_TAG[opcion]}
            </button>
          ))}
        </div>
      )}

      <div className="monto-entrada__campo">
        <span className="monto-entrada__simbolo" aria-hidden="true">
          {CURRENCY_SYMBOL[currency]}
        </span>
        <input
          className="monto-entrada__valor"
          inputMode="decimal"
          autoComplete="off"
          placeholder="0.00"
          value={texto}
          onChange={(event) => escribir(event.target.value)}
          autoFocus={autoFocus}
          aria-label={label ?? 'Monto'}
        />
      </div>

      <p className="monto-entrada__equivale">{equivale}</p>
    </div>
  );
}
