/**
 * Migración desde la versión 1 de GestorRD.
 *
 * La v1 guardaba todo en localStorage bajo claves grd3_*, con los montos en
 * números con decimales y sin registrar la tasa de cada movimiento.
 * Aquí se convierte a la forma nueva sin tocar los datos viejos: si algo sale
 * mal, la persona todavía tiene su versión anterior intacta.
 */

import type {
  Account,
  AppData,
  Budget,
  Category,
  Country,
  Debt,
  DebtKind,
  ExpenseTx,
  Goal,
  IncomeSource,
  IncomeTx,
  Recurrence,
  Transaction,
} from '../domain/types';
import type { Currency } from '../lib/money';
import type { IsoDate } from '../lib/date';
import { toCents } from '../lib/money';
import { isValidRate } from '../lib/fx';
import { isValidIsoDate, today } from '../lib/date';
import { newId } from '../lib/id';
import { countOf, plural } from '../lib/text';
import {
  DEFAULT_CATEGORIES,
  DEFAULT_INCOME_SOURCES,
  FALLBACK_CATEGORY_ID,
  FALLBACK_INCOME_SOURCE_ID,
  extractIcon,
  findCategoryByName,
  findIncomeSourceByName,
  stripIcon,
} from '../domain/categories';
import { createEmptyData, currencyForCountry } from './schema';
import { ensureCashAccount } from '../domain/accounts';

/* ------------------------------------------------------------------ */
/* Claves de la versión vieja                                          */
/* ------------------------------------------------------------------ */

export const LEGACY_KEYS = {
  data: 'grd3_data',
  customCats: 'grd3_custom_cats',
  theme: 'grd3_theme',
  pinV2: 'grd3_pin_v2',
  mode: 'grd3_mode',
} as const;

export interface LegacySources {
  data: unknown;
  customCats?: unknown;
  theme?: string | null;
  pinHash?: string | null;
  mode?: string | null;
}

export interface MigrationReport {
  accounts: number;
  cards: number;
  transactions: number;
  budgets: number;
  debts: number;
  goals: number;
  recurrences: number;
  customCategories: number;
  /** Cosas que la persona debería saber después de migrar. */
  notes: string[];
}

export interface MigrationResult {
  data: AppData;
  report: MigrationReport;
}

/* ------------------------------------------------------------------ */
/* Lectura defensiva                                                   */
/* ------------------------------------------------------------------ */

type Dict = Record<string, unknown>;

function asDict(value: unknown): Dict | null {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
    ? (value as Dict)
    : null;
}

function asArray(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

function asText(value: unknown, fallback = ''): string {
  return typeof value === 'string' ? value : fallback;
}

function asNumber(value: unknown, fallback = 0): number {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string') {
    const parsed = Number(value.replace(/,/g, ''));
    if (Number.isFinite(parsed)) return parsed;
  }
  return fallback;
}

function asCurrency(value: unknown): Currency {
  return asText(value).toUpperCase() === 'DOP' ? 'DOP' : 'USD';
}

function asDate(value: unknown): IsoDate {
  const text = asText(value);
  return isValidIsoDate(text) ? text : today();
}

/** El día del mes puede venir como "5" o como "2026-11-05". */
function asDayOfMonth(value: unknown): number | undefined {
  const text = asText(value).trim();
  if (/^\d{1,2}$/.test(text)) {
    const day = Number(text);
    return day >= 1 && day <= 31 ? day : undefined;
  }
  if (isValidIsoDate(text)) return Number(text.slice(8, 10));
  const num = asNumber(value, 0);
  return num >= 1 && num <= 31 ? Math.trunc(num) : undefined;
}

/* ------------------------------------------------------------------ */
/* Detección                                                           */
/* ------------------------------------------------------------------ */

/** ¿Hay datos de la versión vieja que valga la pena migrar? */
export function hasLegacyData(storage: Pick<Storage, 'getItem'>): boolean {
  try {
    const raw = storage.getItem(LEGACY_KEYS.data);
    if (!raw) return false;
    const parsed: unknown = JSON.parse(raw);
    const dict = asDict(parsed);
    if (!dict) return false;
    return (
      asArray(dict.gastos).length > 0 ||
      asArray(dict.ingresos).length > 0 ||
      asArray(dict.bancos).length > 0 ||
      asArray(dict.deudas).length > 0 ||
      asArray(dict.metas).length > 0
    );
  } catch {
    return false;
  }
}

export function readLegacySources(storage: Pick<Storage, 'getItem'>): LegacySources | null {
  try {
    const raw = storage.getItem(LEGACY_KEYS.data);
    if (!raw) return null;
    const data: unknown = JSON.parse(raw);

    let customCats: unknown = [];
    const rawCats = storage.getItem(LEGACY_KEYS.customCats);
    if (rawCats) {
      try {
        customCats = JSON.parse(rawCats);
      } catch {
        customCats = [];
      }
    }

    return {
      data,
      customCats,
      theme: storage.getItem(LEGACY_KEYS.theme),
      pinHash: storage.getItem(LEGACY_KEYS.pinV2),
      mode: storage.getItem(LEGACY_KEYS.mode),
    };
  } catch {
    return null;
  }
}

/* ------------------------------------------------------------------ */
/* Migración                                                           */
/* ------------------------------------------------------------------ */

export function migrateFromLegacy(sources: LegacySources): MigrationResult {
  const legacy = asDict(sources.data) ?? {};
  const now = new Date().toISOString();

  const notes: string[] = [];

  // --- País y moneda principal ---------------------------------------
  const legacyCountry = asText(legacy.pais).toLowerCase();
  const legacyMode = asText(sources.mode ?? legacy.mode).toLowerCase();
  const country: Country = legacyCountry === 'us' ? 'US' : 'DO';
  const mainCurrency: Currency =
    legacyMode === 'us' ? 'USD' : legacyMode === 'rd' ? 'DOP' : currencyForCountry(country);

  const data = createEmptyData(country);
  data.profile.mainCurrency = mainCurrency;

  const name = [asText(legacy.nombre), asText(legacy.apellido)].filter(Boolean).join(' ').trim();
  if (name) data.profile.name = name;
  else if (asText(legacy.userName)) data.profile.name = asText(legacy.userName);
  const email = asText(legacy.email);
  if (email) data.profile.email = email;

  // --- Tasa de cambio -------------------------------------------------
  const legacyRate = asNumber(legacy.tasa, 0);
  if (isValidRate(legacyRate)) {
    data.fx = { dopPerUsd: legacyRate, updatedAt: now, source: 'manual' };
  }
  const rateForHistory = isValidRate(legacyRate) ? legacyRate : data.fx.dopPerUsd;

  // --- Ajustes --------------------------------------------------------
  const theme = asText(sources.theme ?? legacy.tema, 'auto');
  data.settings.theme = theme === 'light' || theme === 'dark' ? theme : 'auto';
  const pinHash = asText(sources.pinHash);
  if (pinHash.startsWith('pbkdf2$')) data.settings.pinHash = pinHash;

  // --- Categorías propias --------------------------------------------
  const categories: Category[] = DEFAULT_CATEGORIES.map((category) => ({ ...category }));
  const incomeSources: IncomeSource[] = DEFAULT_INCOME_SOURCES.map((source) => ({ ...source }));
  let customCategoryCount = 0;

  for (const entry of asArray(sources.customCats)) {
    // La v1 guardaba ["🏷️ Colmado", "🏷️"]
    const label = Array.isArray(entry) ? asText(entry[0]) : asText(entry);
    if (!label) continue;
    const plainName = stripIcon(label);
    if (!plainName || findCategoryByName(categories, plainName)) continue;
    categories.push({
      id: newId(),
      name: plainName,
      icon: extractIcon(label) ?? '🏷️',
      group: 'otros',
      custom: true,
    });
    customCategoryCount++;
  }

  /** Busca la categoría por su etiqueta vieja; si no existe, la crea. */
  function resolveCategoryId(label: string): string {
    const plainName = stripIcon(label);
    if (!plainName) return FALLBACK_CATEGORY_ID;

    const found = findCategoryByName(categories, plainName);
    if (found) return found.id;

    const created: Category = {
      id: newId(),
      name: plainName,
      icon: extractIcon(label) ?? '🏷️',
      group: 'otros',
      custom: true,
    };
    categories.push(created);
    customCategoryCount++;
    return created.id;
  }

  function resolveIncomeSourceId(label: string): string {
    const plainName = stripIcon(label);
    if (!plainName) return FALLBACK_INCOME_SOURCE_ID;

    const found = findIncomeSourceByName(incomeSources, plainName);
    if (found) return found.id;

    const created: IncomeSource = {
      id: newId(),
      name: plainName,
      icon: extractIcon(label) ?? '🧺',
      custom: true,
    };
    incomeSources.push(created);
    return created.id;
  }

  // --- Cuentas y tarjetas ---------------------------------------------
  /** id viejo (número) -> id nuevo (uuid) */
  const accountIdMap = new Map<string, string>();
  const accounts: Account[] = [];
  let cardCount = 0;

  for (const raw of asArray(legacy.bancos)) {
    const bank = asDict(raw);
    if (!bank) continue;

    const legacyId = String(asNumber(bank.id, 0) || asText(bank.id));
    const id = newId();
    accountIdMap.set(legacyId, id);

    const bankName = asText(bank.banco, 'Cuenta');
    const nickname = asText(bank.nom);
    const isCard = bank.esTarjeta === true;
    const accountCountry: Country = asText(bank.pais).toUpperCase() === 'US' ? 'US' : 'DO';
    const last4 = asText(bank.ultimos).replace(/\D/g, '').slice(0, 4);

    if (isCard) {
      cardCount++;
      const limitUsd = toCents(asNumber(bank.limUSD, 0));
      const limitDop = toCents(asNumber(bank.limDOP, 0));
      const owedUsd = toCents(asNumber(bank.saldoUSD, 0));
      const owedDop = toCents(asNumber(bank.saldoDOP, 0));

      const balances: Partial<Record<Currency, number>> = {};
      // En una tarjeta el saldo es negativo: representa lo que se debe
      if (limitUsd > 0 || owedUsd > 0) balances.USD = -owedUsd;
      if (limitDop > 0 || owedDop > 0) balances.DOP = -owedDop;

      const limits: Partial<Record<Currency, number>> = {};
      if (limitUsd > 0) limits.USD = limitUsd;
      if (limitDop > 0) limits.DOP = limitDop;

      const account: Account = {
        id,
        kind: 'credit',
        bank: bankName,
        country: accountCountry,
        balances,
        credit: { limits },
        createdAt: now,
        updatedAt: now,
      };
      if (nickname && nickname !== bankName) account.nickname = nickname;
      if (last4) account.last4 = last4;
      const statementDay = asDayOfMonth(bank.corte);
      if (statementDay) account.credit = { ...account.credit, limits, statementDay };
      const dueDay = asDayOfMonth(bank.pagoFecha);
      if (dueDay) account.credit = { ...account.credit, limits, dueDay, ...(statementDay ? { statementDay } : {}) };

      accounts.push(account);
    } else {
      const currency = asCurrency(bank.mon);
      const account: Account = {
        id,
        kind: 'bank',
        bank: bankName,
        country: accountCountry,
        balances: { [currency]: toCents(asNumber(bank.bal, 0)) },
        createdAt: now,
        updatedAt: now,
      };
      if (nickname && nickname !== bankName) account.nickname = nickname;
      if (last4) account.last4 = last4;
      accounts.push(account);
    }
  }

  /** La v1 guardaba el origen como "banco_123". */
  function resolveAccountId(source: unknown): string | undefined {
    const text = asText(source);
    if (!text.startsWith('banco_')) return undefined;
    return accountIdMap.get(text.slice('banco_'.length));
  }

  // --- Movimientos -----------------------------------------------------
  const transactions: Transaction[] = [];

  for (const raw of asArray(legacy.gastos)) {
    const expense = asDict(raw);
    if (!expense) continue;
    const amount = toCents(asNumber(expense.monto, 0));
    if (amount <= 0) continue;

    const tx: ExpenseTx = {
      id: newId(),
      kind: 'expense',
      date: asDate(expense.fecha),
      amount,
      currency: asCurrency(expense.mon),
      categoryId: resolveCategoryId(asText(expense.cat)),
      fxRate: rateForHistory,
      fxEstimated: true,
      createdAt: now,
      updatedAt: now,
    };
    const note = asText(expense.desc).trim();
    if (note) tx.note = note;
    const accountId = resolveAccountId(expense.source);
    if (accountId) tx.accountId = accountId;

    transactions.push(tx);
  }

  for (const raw of asArray(legacy.ingresos)) {
    const income = asDict(raw);
    if (!income) continue;
    const amount = toCents(asNumber(income.monto, 0));
    if (amount <= 0) continue;

    const tx: IncomeTx = {
      id: newId(),
      kind: 'income',
      date: asDate(income.fecha),
      amount,
      currency: asCurrency(income.mon),
      sourceId: resolveIncomeSourceId(asText(income.fuente)),
      fxRate: rateForHistory,
      fxEstimated: true,
      createdAt: now,
      updatedAt: now,
    };
    const note = asText(income.metodo).trim();
    if (note) tx.note = note;

    transactions.push(tx);
  }

  // --- Deudas ----------------------------------------------------------
  const debts: Debt[] = [];
  let cardDebtsSkipped = 0;

  const DEBT_KINDS: Record<string, DebtKind> = {
    'préstamo personal': 'personal',
    'prestamo personal': 'personal',
    'préstamo vehículo': 'vehiculo',
    'prestamo vehiculo': 'vehiculo',
    hipoteca: 'hipoteca',
    'préstamo estudiantil': 'estudiantil',
    'prestamo estudiantil': 'estudiantil',
    familiar: 'familiar',
  };

  for (const raw of asArray(legacy.deudas)) {
    const debt = asDict(raw);
    if (!debt) continue;

    // Las deudas de tarjeta ahora viven en el saldo de la tarjeta
    if (debt.esTCDeuda === true || debt.tcId !== undefined) {
      cardDebtsSkipped++;
      continue;
    }
    if (asText(debt.estado).toLowerCase() === 'pagado') continue;

    const currency = asCurrency(debt.mon);
    const balance = toCents(asNumber(debt.bal, 0));
    const original = toCents(asNumber(debt.original, 0)) || balance;
    const kindText = asText(debt.tipo).toLowerCase();

    const entry: Debt = {
      id: newId(),
      name: asText(debt.nom, 'Deuda'),
      kind: DEBT_KINDS[kindText] ?? 'otro',
      currency,
      balance,
      original,
      createdAt: now,
      updatedAt: now,
    };
    const apr = asNumber(debt.tasa, 0);
    if (apr > 0) entry.apr = apr;
    const dueDay = asDayOfMonth(debt.fecha);
    if (dueDay) entry.dueDay = dueDay;

    debts.push(entry);
  }

  // --- Metas -----------------------------------------------------------
  const goals: Goal[] = [];
  for (const raw of asArray(legacy.metas)) {
    const goal = asDict(raw);
    if (!goal) continue;
    const target = toCents(asNumber(goal.total, 0));
    if (target <= 0) continue;

    const entry: Goal = {
      id: newId(),
      name: asText(goal.nom, 'Meta'),
      currency: asCurrency(goal.mon),
      target,
      saved: toCents(asNumber(goal.actual, 0)),
      createdAt: now,
      updatedAt: now,
    };
    const targetDate = asText(goal.fecha);
    if (isValidIsoDate(targetDate)) entry.targetDate = targetDate;

    goals.push(entry);
  }

  // --- Presupuesto ------------------------------------------------------
  const budgets: Budget[] = [];
  for (const raw of asArray(legacy.presupuesto)) {
    const budget = asDict(raw);
    if (!budget) continue;
    const limit = toCents(asNumber(budget.lim, 0));
    if (limit <= 0) continue;

    budgets.push({
      id: newId(),
      categoryId: resolveCategoryId(asText(budget.cat)),
      limit,
      currency: asCurrency(budget.mon),
    });
  }

  // --- Gastos fijos ------------------------------------------------------
  const recurrences: Recurrence[] = [];
  for (const raw of asArray(legacy.gastosFijos)) {
    const fixed = asDict(raw);
    if (!fixed) continue;
    const amount = toCents(asNumber(fixed.monto, 0));
    if (amount <= 0) continue;

    const entry: Recurrence = {
      id: newId(),
      kind: 'expense',
      name: asText(fixed.desc, 'Gasto fijo'),
      amount,
      currency: asCurrency(fixed.mon),
      dayOfMonth: asDayOfMonth(fixed.dia) ?? 1,
      categoryId: resolveCategoryId(asText(fixed.cat)),
      // Se migran apagados: encenderlos solos crearía gastos que la persona no pidió
      autoApply: false,
      createdAt: now,
      updatedAt: now,
    };
    const accountId = fixed.bancoId !== undefined && fixed.bancoId !== null
      ? accountIdMap.get(String(asNumber(fixed.bancoId, 0)))
      : undefined;
    if (accountId) entry.accountId = accountId;

    recurrences.push(entry);
  }

  // --- Notas para la persona ---------------------------------------------
  if (transactions.length > 0) {
    notes.push(
      'Los movimientos viejos no guardaban la tasa del día, así que se les puso la última tasa conocida. Los totales en una sola moneda son exactos; las conversiones del pasado son aproximadas.',
    );
  }
  if (cardDebtsSkipped > 0) {
    notes.push(
      `${plural(cardDebtsSkipped, 'Se omitió', 'Se omitieron')} ${countOf(cardDebtsSkipped, 'deuda de tarjeta', 'deudas de tarjeta')} porque ahora el saldo de la tarjeta ya representa lo que se debe.`,
    );
  }
  if (recurrences.length > 0) {
    // En singular no se escribe el número: "Tu gasto fijo", no "Tu 1 gasto fijo"
    const cuantos =
      recurrences.length === 1
        ? 'gasto fijo'
        : countOf(recurrences.length, 'gasto fijo', 'gastos fijos');
    notes.push(
      `${plural(recurrences.length, 'Tu', 'Tus')} ${cuantos} ${plural(recurrences.length, 'quedó', 'quedaron')} en manual. Puedes activar que se registren solos desde Ajustes.`,
    );
  }
  if (asArray(legacy.ahorros).length > 0 && goals.length > 0) {
    notes.push('La lista de ahorros duplicaba las metas, así que se unificó en metas.');
  }

  // --- Armado final --------------------------------------------------------
  data.categories = categories;
  data.incomeSources = incomeSources;
  data.accounts = accounts;
  // Esto pisa el arreglo que traía createEmptyData, efectivo incluido
  ensureCashAccount(data);
  data.transactions = transactions.sort((a, b) => (a.date < b.date ? 1 : -1));
  data.debts = debts;
  data.goals = goals;
  data.budgets = budgets;
  data.recurrences = recurrences;
  data.updatedAt = now;

  return {
    data,
    report: {
      accounts: accounts.length - cardCount,
      cards: cardCount,
      transactions: transactions.length,
      budgets: budgets.length,
      debts: debts.length,
      goals: goals.length,
      recurrences: recurrences.length,
      customCategories: customCategoryCount,
      notes,
    },
  };
}
