/**
 * Préstamos y deudas que no son tarjetas de crédito.
 *
 * Las tarjetas viven en las cuentas, porque su saldo es su deuda.
 * Aquí entra lo demás: el préstamo del carro, la hipoteca, lo que le
 * debes a un familiar.
 *
 * El cálculo del plan de pago se hace mes por mes en centavos enteros,
 * no con la fórmula cerrada, para que el resultado sea exactamente lo
 * que la persona va a ver pasar en su cuenta.
 */

import type { Debt } from './types';
import type { Cents } from '../lib/money';
import type { YearMonth } from '../lib/date';
import { currentYearMonth, shiftMonth } from '../lib/date';
import type { ValidationIssue } from './ledger';
import { t } from '../i18n';

/** Tope de la simulación: 50 años. Más allá, la deuda es impagable. */
const MAX_MESES = 600;

export const DEBT_LABELS: Record<Debt['kind'], string> = {
  personal: t('deuda.personal'),
  vehiculo: t('deuda.vehiculo'),
  hipoteca: t('deuda.hipoteca'),
  estudiantil: t('deuda.estudiantil'),
  familiar: t('deuda.familiar'),
  otro: t('deuda.otro'),
};

export const DEBT_ICONS: Record<Debt['kind'], string> = {
  personal: '📄',
  vehiculo: '🚗',
  hipoteca: '🏠',
  estudiantil: '🎓',
  familiar: '🤝',
  otro: '📉',
};

export interface DebtProgress {
  /** Lo que ya pagaste del capital. */
  paid: Cents;
  /** Lo que falta. */
  left: Cents;
  percent: number;
  done: boolean;
}

export function debtProgress(debt: Debt): DebtProgress {
  const paid = Math.max(0, debt.original - debt.balance);
  const percent = debt.original > 0 ? Math.min(100, Math.round((paid / debt.original) * 100)) : 0;
  return { paid, left: Math.max(0, debt.balance), percent, done: debt.balance <= 0 };
}

/** Interés que se le suma a la deuda este mes si no la tocas. */
export function monthlyInterest(debt: Debt): Cents {
  if (!debt.apr || debt.apr <= 0 || debt.balance <= 0) return 0;
  return Math.round((debt.balance * debt.apr) / 100 / 12);
}

export interface PayoffPlan {
  /** Cuántas cuotas faltan, contando la de este mes. */
  months: number;
  /** Interés que vas a pagar de aquí al final. */
  totalInterest: Cents;
  /** Todo lo que vas a desembolsar. */
  totalPaid: Cents;
  /** Mes de la última cuota. */
  endsOn: YearMonth;
}

/**
 * Cuánto falta para salir de la deuda pagando una cuota fija.
 *
 * Devuelve null si la cuota no alcanza ni para el interés del mes: en ese
 * caso la deuda crece sola y no hay plan que mostrar.
 */
export function payoffPlan(
  debt: Debt,
  monthlyPayment: Cents,
  from: YearMonth = currentYearMonth(),
): PayoffPlan | null {
  if (monthlyPayment <= 0 || debt.balance <= 0) return null;

  const tasaMensual = (debt.apr ?? 0) / 100 / 12;
  let saldo = debt.balance;
  let interes = 0;
  let pagado = 0;

  for (let mes = 1; mes <= MAX_MESES; mes++) {
    const cargo = Math.round(saldo * tasaMensual);

    // Si la cuota no cubre el interés, el saldo nunca baja
    if (cargo >= monthlyPayment) return null;

    const cuota = Math.min(monthlyPayment, saldo + cargo);
    saldo = saldo + cargo - cuota;
    interes += cargo;
    pagado += cuota;

    if (saldo <= 0) {
      return {
        months: mes,
        totalInterest: interes,
        totalPaid: pagado,
        endsOn: shiftMonth(from, mes - 1),
      };
    }
  }

  return null;
}

export interface ExtraSaving {
  /** Meses que te ahorras. */
  months: number;
  /** Interés que te ahorras. */
  interest: Cents;
}

/**
 * Qué te ahorras si le echas un poco más cada mes.
 * Es la cifra que convence: el interés que te quitas de encima.
 */
export function savingFromExtra(
  debt: Debt,
  monthlyPayment: Cents,
  extra: Cents,
): ExtraSaving | null {
  if (extra <= 0) return null;
  const base = payoffPlan(debt, monthlyPayment);
  const conExtra = payoffPlan(debt, monthlyPayment + extra);
  if (!base || !conExtra) return null;
  return {
    months: base.months - conExtra.months,
    interest: base.totalInterest - conExtra.totalInterest,
  };
}

export function validateDebt(debt: Debt): ValidationIssue[] {
  const issues: ValidationIssue[] = [];

  if (!debt.name.trim()) {
    issues.push({ field: 'name', message: t('deuda.error.nombre') });
  }
  if (debt.balance < 0) {
    issues.push({ field: 'balance', message: t('deuda.error.saldoNegativo') });
  }
  if (debt.original <= 0) {
    issues.push({ field: 'original', message: t('deuda.error.original') });
  }
  if (debt.balance > debt.original) {
    issues.push({
      field: 'balance',
      message: t('deuda.error.saldoMayor'),
    });
  }
  if (debt.apr !== undefined && (debt.apr < 0 || debt.apr > 200)) {
    issues.push({ field: 'apr', message: t('deuda.error.tasa') });
  }
  if (debt.dueDay !== undefined && (debt.dueDay < 1 || debt.dueDay > 31)) {
    issues.push({ field: 'dueDay', message: t('deuda.error.dia') });
  }
  if (
    debt.monthlyPayment !== undefined &&
    debt.monthlyPayment > 0 &&
    monthlyInterest(debt) >= debt.monthlyPayment
  ) {
    issues.push({
      field: 'monthlyPayment',
      message: t('deuda.error.cuota'),
    });
  }

  return issues;
}
