/**
 * Registrar un gasto.
 *
 * Todo en una sola pantalla, sin pasos: registrar un gasto tiene que tomar
 * segundos, porque se hace de pie en la caja de un colmado.
 */

import { useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData } from '../../store/useApp';
import type { Cents, Currency } from '../../lib/money';
import type { ExpenseTx } from '../../domain/types';
import { AmountInput } from '../../ui/AmountInput';
import { useMonedasPermitidas } from '../../store/useMonedas';
import { defaultAccountId } from '../../domain/accounts';
import { CategoryPicker, AccountPicker } from '../../ui/pickers';
import { Button, Notice } from '../../ui/primitives';
import { Field } from '../../ui/forms';
import { overdraftWarning, validateTransaction } from '../../domain/ledger';
import { baseInicial, errorDe, sello } from './comun';
import { today } from '../../lib/date';
import type { ValidationIssue } from '../../domain/ledger';

export function GastoForm({
  onDone,
  transaction,
}: {
  onDone: () => void;
  /** Si viene, se corrige ese gasto en vez de crear uno nuevo. */
  transaction?: ExpenseTx;
}) {
  const editando = transaction !== undefined;
  const data = useData();
  const addTransaction = useApp((state) => state.addTransaction);
  const replaceTransaction = useApp((state) => state.replaceTransaction);
  const notify = useApp((state) => state.notify);

  const [monto, setMonto] = useState<Cents | null>(transaction?.amount ?? null);
  const monedas = useMonedasPermitidas();
  const [moneda, setMoneda] = useState<Currency>(
    transaction?.currency ?? data.profile.mainCurrency,
  );
  const [categoria, setCategoria] = useState(transaction?.categoryId ?? '');
  const [cuenta, setCuenta] = useState<string | undefined>(
    // Al editar se respeta lo que había, incluso si era efectivo
    transaction ? transaction.accountId : defaultAccountId(data),
  );
  const [base, setBase] = useState(() =>
    transaction ? { fecha: transaction.date, nota: transaction.note ?? '' } : baseInicial(),
  );
  const [problemas, setProblemas] = useState<ValidationIssue[]>([]);

  function construir(): ExpenseTx {
    const tx: ExpenseTx = {
      ...sello(data),
      kind: 'expense',
      date: base.fecha,
      amount: monto ?? 0,
      currency: moneda,
      categoryId: categoria,
    };
    if (cuenta) tx.accountId = cuenta;
    if (base.nota.trim()) tx.note = base.nota.trim();
    return tx;
  }

  // Al corregir, el gasto viejo sigue aplicado en los saldos, así que el aviso
  // de fondos saldría mal. Solo se muestra al registrar algo nuevo.
  const aviso = !editando && monto && categoria ? overdraftWarning(data, construir()) : null;

  function guardar() {
    const tx = construir();
    const encontrados = validateTransaction(data, tx);
    setProblemas(encontrados);
    if (encontrados.length > 0) return;

    if (editando) {
      replaceTransaction(transaction.id, tx);
      notify(t('gasto.gastoCorregido'));
    } else {
      addTransaction(tx);
      notify(t('gasto.gastoGuardado'));
    }
    onDone();
  }

  return (
    <>
      <AmountInput
        cents={monto}
        currency={moneda}
        monedas={monedas}
        onChange={setMonto}
        onCurrencyChange={setMoneda}
        rate={data.fx.dopPerUsd}
        autoFocus
        label={t('gasto.cuantoGastaste')}
      />
      {errorDe(problemas, 'amount') && (
        <p className="campo__error" style={{ textAlign: 'center', marginTop: 0 }}>
          {errorDe(problemas, 'amount')}
        </p>
      )}

      <p className="campo__etiqueta">En qué</p>
      <CategoryPicker categories={data.categories} value={categoria} onChange={setCategoria} />
      {errorDe(problemas, 'categoryId') && (
        <p className="campo__error">{errorDe(problemas, 'categoryId')}</p>
      )}

      <p className="campo__etiqueta" style={{ marginTop: 'var(--e5)' }}>{t('gasto.conQuePagaste')}</p>
      <AccountPicker
        accounts={data.accounts}
        value={cuenta}
        onChange={setCuenta}
        currency={moneda}
      />

      {aviso && (
        <div style={{ marginBottom: 'var(--e4)' }}>
          <Notice tone="ambar" icon="⚠️">
            {aviso} Puedes guardarlo igual si así fue.
          </Notice>
        </div>
      )}

      <div style={{ marginTop: 'var(--e5)' }}>
        <Field
          label="Fecha"
          type="date"
          value={base.fecha}
          max={today()}
          onChange={(event) => setBase({ ...base, fecha: event.target.value })}
        />
        <Field
          label="Nota"
          type="text"
          placeholder="Supermercado Nacional"
          value={base.nota}
          onChange={(event) => setBase({ ...base, nota: event.target.value })}
        />
      </div>

      <div className="hoja__pie">
        <Button wide onClick={guardar}>
          {editando ? t('gasto.guardarCambios') : t('gasto.guardarGasto')}
        </Button>
      </div>
    </>
  );
}
