/**
 * El asesor.
 *
 * No adivina ni predica: cada consejo sale de una cifra que está en los datos
 * y dice qué hacer con ella. Si no hay nada que decir, no dice nada; es mejor
 * callar que llenar la pantalla de consejos genéricos.
 *
 * Cada regla devuelve un consejo o nada. El peso decide el orden: primero lo
 * que puede costarle dinero a la persona esta semana.
 */

import type { AppData } from './types';
import type { Cents, Currency } from '../lib/money';
import type { YearMonth } from '../lib/date';
import { monthTotals } from './compute';
import { cardUsagePercent } from './accounts';
import { allBudgetProgress } from './budgets';
import { monthlyInterest } from './debts';
import { goalProgress, isLate } from './goals';
import { averageExpense, unusualCategories } from './reports';
import { daysSinceBackup } from './cloud';
import { availableBalance } from './compute';
import { formatMoney } from '../lib/money';
import { joinList, plural } from '../lib/text';
import { t } from '../i18n';

export interface Advice {
  id: string;
  tone: 'verde' | 'azul' | 'ambar' | 'roja';
  icon: string;
  title: string;
  text: string;
  /** Más alto, más arriba. */
  weight: number;
}

/** Meses de gasto que cubre el dinero disponible. */
export function monthsOfCushion(data: AppData, month: YearMonth, target: Currency): number | null {
  const promedio = averageExpense(data, month, 3, target);
  if (promedio <= 0) return null;
  return Math.round((availableBalance(data, target) / promedio) * 10) / 10;
}

export function advice(data: AppData, month: YearMonth): Advice[] {
  const moneda = data.profile.mainCurrency;
  const lista: Advice[] = [];
  const dinero = (cents: Cents) => formatMoney(cents, moneda, { compact: true });

  const { income, expense } = monthTotals(data, month, moneda);

  /* Gastaste más de lo que entró ------------------------------------------- */
  if (income > 0 && expense > income) {
    lista.push({
      id: 'deficit',
      tone: 'roja',
      icon: '⚠️',
      title: t('asesor.deficit.titulo'),
      text: t('asesor.deficit.texto', { monto: dinero(expense - income) }),
      weight: 100,
    });
  }

  /* Tarjetas apretadas ----------------------------------------------------- */
  for (const cuenta of data.accounts) {
    if (cuenta.archived || cuenta.kind !== 'credit') continue;
    for (const divisa of ['DOP', 'USD'] as const) {
      const uso = cardUsagePercent(cuenta, divisa);
      if (uso === null || uso < 70) continue;
      lista.push({
        id: `tarjeta-${cuenta.id}-${divisa}`,
        tone: uso >= 90 ? 'roja' : 'ambar',
        icon: '💳',
        title: t('asesor.tarjeta.titulo', {
          cuenta: cuenta.nickname ?? cuenta.bank,
          porcentaje: uso,
        }),
        text: uso >= 90 ? t('asesor.tarjeta.critica') : t('asesor.tarjeta.alta'),
        weight: uso >= 90 ? 95 : 72,
      });
    }
  }

  /* Presupuestos pasados --------------------------------------------------- */
  const pasados = allBudgetProgress(data, month).filter((item) => item.overspent);
  if (pasados.length > 0) {
    const nombres = pasados.slice(0, 3).map((item) => {
      const categoria = data.categories.find((cat) => cat.id === item.budget.categoryId);
      return categoria?.name ?? 'una categoría';
    });
    lista.push({
      id: 'presupuesto-pasado',
      tone: 'ambar',
      icon: '📊',
      title: t('asesor.presupuesto.titulo', {
        cuantas: pasados.length,
        categorias: plural(pasados.length, 'categoría', 'categorías'),
      }),
      text: t('asesor.presupuesto.texto', { nombres: joinList(nombres) }),
      weight: 90,
    });
  }

  /* Deuda cara ------------------------------------------------------------- */
  const caras = data.debts
    .filter((deuda) => !deuda.archived && deuda.balance > 0 && (deuda.apr ?? 0) >= 20)
    .sort((a, b) => (b.apr ?? 0) - (a.apr ?? 0));
  const peor = caras[0];
  if (peor) {
    const interes = monthlyInterest(peor);
    lista.push({
      id: `deuda-cara-${peor.id}`,
      tone: 'ambar',
      icon: '📉',
      title: t('asesor.deudaCara.titulo', {
        nombre: peor.name,
        monto: formatMoney(interes, peor.currency, { compact: true }),
      }),
      text: t('asesor.deudaCara.texto', { tasa: peor.apr ?? 0 }),
      weight: 88,
    });
  }

  /* Colchón de emergencia -------------------------------------------------- */
  const colchon = monthsOfCushion(data, month, moneda);
  if (colchon !== null) {
    if (colchon < 1) {
      lista.push({
        id: 'colchon-bajo',
        tone: 'ambar',
        icon: '🛟',
        title: t('asesor.colchonBajo.titulo'),
        text: t('asesor.colchonBajo.texto'),
        weight: 85,
      });
    } else if (colchon >= 3) {
      lista.push({
        id: 'colchon-bueno',
        tone: 'verde',
        icon: '🛟',
        title: t('asesor.colchonBueno.titulo', {
          meses: colchon,
          unidad: plural(Math.round(colchon), 'mes', 'meses'),
        }),
        text: t('asesor.colchonBueno.texto'),
        weight: 35,
      });
    }
  }

  /* Un gasto que se salió de lo normal ------------------------------------- */
  const raras = unusualCategories(data, month, moneda, 100000);
  const rara = raras[0];
  if (rara) {
    lista.push({
      id: `inusual-${rara.categoryId}`,
      tone: 'azul',
      icon: rara.icon,
      title: t('asesor.inusual.titulo', { categoria: rara.name, porcentaje: rara.percent }),
      text: t('asesor.inusual.texto', { ahora: dinero(rara.now), antes: dinero(rara.before) }),
      weight: 75,
    });
  }

  /* Metas atrasadas -------------------------------------------------------- */
  const atrasadas = data.goals.filter((meta) => !meta.archived && isLate(meta));
  const atrasada = atrasadas[0];
  if (atrasada) {
    const falta = goalProgress(atrasada).left;
    lista.push({
      id: `meta-atrasada-${atrasada.id}`,
      tone: 'ambar',
      icon: '🎯',
      title: t('asesor.metaAtrasada.titulo', { nombre: atrasada.name }),
      text: t('asesor.metaAtrasada.texto', {
        monto: formatMoney(falta, atrasada.currency, { compact: true }),
      }),
      weight: 70,
    });
  }

  /* Fijos pendientes ------------------------------------------------------- */
  const pendientes = data.recurrences.filter(
    (item) => !item.archived && !item.autoApply && item.lastAppliedMonth !== month,
  );
  if (pendientes.length > 0) {
    lista.push({
      id: 'fijos-pendientes',
      tone: 'azul',
      icon: '🔁',
      title: t('asesor.fijosPendientes.titulo', {
        cuantos: pendientes.length,
        fijos: plural(pendientes.length, 'movimiento fijo', 'movimientos fijos'),
      }),
      text: t('asesor.fijosPendientes.texto'),
      weight: 65,
    });
  }

  /* Lo que lograste -------------------------------------------------------- */
  if (income > 0 && expense < income) {
    const guardado = income - expense;
    const porcentaje = Math.round((guardado / income) * 100);
    lista.push({
      id: 'ahorro-del-mes',
      tone: 'verde',
      icon: '✅',
      title: t('asesor.ahorro.titulo', { porcentaje }),
      text: t('asesor.ahorro.texto', { monto: dinero(guardado) }),
      weight: 55,
    });
  }

  /* Copia vieja o inexistente ---------------------------------------------- */
  const diasCopia = daysSinceBackup(data);
  if (data.transactions.length >= 20) {
    if (diasCopia === null) {
      lista.push({
        id: 'sin-copia',
        tone: 'ambar',
        icon: '💾',
        title: t('asesor.sinCopia.titulo'),
        text: t('asesor.sinCopia.texto'),
        weight: 78,
      });
    } else if (diasCopia > 30) {
      lista.push({
        id: 'copia-vieja',
        tone: 'azul',
        icon: '💾',
        title: t('asesor.copiaVieja.titulo', { dias: diasCopia }),
        text: t('asesor.copiaVieja.texto'),
        weight: 48,
      });
    }
  }

  /* Tasa vieja ------------------------------------------------------------- */
  /*
   * La tasa de fábrica trae fecha de 1970, así que contar días desde ahí daba
   * "tu tasa tiene 20776 días" en un teléfono recién instalado. Mientras sea
   * la de arranque no hay nada que contar: Ajustes ya la marca como tal.
   */
  const dias = data.fx.source === 'default' ? null : diasDesde(data.fx.updatedAt);
  if (dias !== null && dias > 7) {
    lista.push({
      id: 'tasa-vieja',
      tone: 'azul',
      icon: '💱',
      title: t('asesor.tasaVieja.titulo'),
      text: t('asesor.tasaVieja.texto', { dias, unidad: plural(dias, 'día', 'días') }),
      weight: 45,
    });
  }

  /* Mes vacío -------------------------------------------------------------- */
  if (income === 0 && expense === 0) {
    lista.push({
      id: 'mes-vacio',
      tone: 'azul',
      icon: '📝',
      title: t('asesor.mesVacio.titulo'),
      text: t('asesor.mesVacio.texto'),
      weight: 20,
    });
  }

  return lista.sort((a, b) => b.weight - a.weight);
}

function diasDesde(iso: string | undefined): number | null {
  if (!iso) return null;
  const fecha = new Date(iso);
  if (Number.isNaN(fecha.getTime())) return null;
  const dias = Math.floor((Date.now() - fecha.getTime()) / 86400000);
  return dias >= 0 ? dias : null;
}
