/**
 * Metas de ahorro.
 *
 * Una meta no es una cuenta aparte: es dinero que ya está en el banco y que
 * tiene dueño. Apartar no mueve ningún saldo, solo le pone nombre. Así el
 * saldo que muestra la app sigue siendo el que muestra el banco.
 */

import type { AppData, Goal } from './types';
import type { Cents, Currency } from '../lib/money';
import type { IsoDate } from '../lib/date';
import { parseIsoDate, today } from '../lib/date';
import type { ValidationIssue } from './ledger';

export interface GoalProgress {
  percent: number;
  left: Cents;
  done: boolean;
}

export function goalProgress(goal: Goal): GoalProgress {
  const percent = goal.target > 0 ? Math.min(100, Math.round((goal.saved / goal.target) * 100)) : 0;
  return { percent, left: Math.max(0, goal.target - goal.saved), done: goal.saved >= goal.target };
}

/** Meses completos entre dos fechas. Negativo si la segunda ya pasó. */
export function monthsBetween(from: IsoDate, to: IsoDate): number {
  const inicio = parseIsoDate(from);
  const fin = parseIsoDate(to);
  let meses = (fin.getFullYear() - inicio.getFullYear()) * 12 + (fin.getMonth() - inicio.getMonth());
  if (fin.getDate() < inicio.getDate()) meses -= 1;
  return meses;
}

/**
 * Cuánto hay que apartar cada mes para llegar a tiempo.
 * Si la fecha ya pasó o está este mismo mes, es todo lo que falta.
 */
export function neededPerMonth(goal: Goal, from: IsoDate = today()): Cents | null {
  if (!goal.targetDate) return null;
  const { left, done } = goalProgress(goal);
  if (done) return null;
  const meses = Math.max(1, monthsBetween(from, goal.targetDate));
  return Math.ceil(left / meses);
}

/** A este ritmo, en cuántos meses llegas. */
export function monthsAtPace(goal: Goal, perMonth: Cents): number | null {
  if (perMonth <= 0) return null;
  const { left, done } = goalProgress(goal);
  if (done) return 0;
  return Math.ceil(left / perMonth);
}

/** true si la fecha de la meta ya pasó y todavía falta dinero. */
export function isLate(goal: Goal, from: IsoDate = today()): boolean {
  if (!goal.targetDate) return false;
  if (goalProgress(goal).done) return false;
  return goal.targetDate < from;
}

/**
 * Cuánto te pasaste apartando: si sumas todas las metas de una moneda y da
 * más de lo que hay en los bancos, estás contando dinero que no tienes.
 */
export function overReserved(data: AppData, currency: Currency): Cents {
  const apartado = data.goals
    .filter((goal) => !goal.archived && goal.currency === currency)
    .reduce((total, goal) => total + goal.saved, 0);

  const enBanco = data.accounts
    .filter((account) => account.kind !== 'credit' && !account.archived)
    .reduce((total, account) => total + (account.balances[currency] ?? 0), 0);

  return Math.max(0, apartado - enBanco);
}

export function validateGoal(goal: Goal): ValidationIssue[] {
  const issues: ValidationIssue[] = [];

  if (!goal.name.trim()) {
    issues.push({ field: 'name', message: 'Ponle un nombre a la meta.' });
  }
  if (goal.target <= 0) {
    issues.push({ field: 'target', message: 'Escribe cuánto quieres juntar.' });
  }
  if (goal.saved < 0) {
    issues.push({ field: 'saved', message: 'Lo apartado no puede ser negativo.' });
  }

  return issues;
}
