/**
 * Efecto de cada movimiento sobre los saldos.
 *
 * Toda la aritmética de cuentas vive aquí, en funciones que reciben los datos
 * y los modifican. Así el efecto de registrar y el de deshacer son el mismo
 * código con el signo cambiado, y no hay forma de que se desincronicen.
 */

import type { Account, AppData, Transaction } from './types';
import type { Cents, Currency } from '../lib/money';

/** Suma (o resta, si es negativo) a una moneda de una cuenta. */
function addToBalance(account: Account, currency: Currency, delta: Cents): void {
  const actual = account.balances[currency] ?? 0;
  account.balances[currency] = actual + delta;
}

function findAccount(data: AppData, id: string | undefined): Account | undefined {
  if (!id) return undefined;
  return data.accounts.find((account) => account.id === id);
}

/**
 * Aplica un movimiento a los saldos.
 * `signo` es 1 al registrar y -1 al deshacer.
 */
function applyWithSign(data: AppData, tx: Transaction, signo: 1 | -1): void {
  switch (tx.kind) {
    case 'expense': {
      const account = findAccount(data, tx.accountId);
      // Sin cuenta es un gasto en efectivo: no mueve ningún saldo
      if (account) addToBalance(account, tx.currency, -tx.amount * signo);

      if (tx.debtId) {
        const debt = data.debts.find((d) => d.id === tx.debtId);
        if (debt) {
          debt.balance = Math.max(0, debt.balance - tx.amount * signo);
          debt.updatedAt = new Date().toISOString();
        }
      }
      break;
    }

    case 'income': {
      const account = findAccount(data, tx.accountId);
      if (account) addToBalance(account, tx.currency, tx.amount * signo);
      break;
    }

    case 'transfer': {
      const origen = findAccount(data, tx.fromAccountId);
      const destino = findAccount(data, tx.toAccountId);
      const comision = tx.fee ?? 0;

      // De la cuenta de origen sale el monto más la comisión del banco
      if (origen) addToBalance(origen, tx.currency, -(tx.amount + comision) * signo);
      if (destino) addToBalance(destino, tx.currency, tx.amount * signo);
      break;
    }

    case 'exchange': {
      const origen = findAccount(data, tx.fromAccountId);
      const destino = findAccount(data, tx.toAccountId);
      const comision = tx.fee ?? 0;

      if (origen) addToBalance(origen, tx.fromCurrency, -(tx.fromAmount + comision) * signo);
      if (destino) addToBalance(destino, tx.toCurrency, tx.toAmount * signo);
      break;
    }
  }

  // La cuenta tocada queda marcada como modificada
  for (const id of accountsTouched(tx)) {
    const account = findAccount(data, id);
    if (account) account.updatedAt = new Date().toISOString();
  }
}

/** Qué cuentas toca un movimiento. */
export function accountsTouched(tx: Transaction): string[] {
  switch (tx.kind) {
    case 'expense':
    case 'income':
      return tx.accountId ? [tx.accountId] : [];
    case 'transfer':
    case 'exchange':
      return [tx.fromAccountId, tx.toAccountId].filter((id): id is string => Boolean(id));
  }
}

/** Registra el movimiento y mueve los saldos. */
export function applyTransaction(data: AppData, tx: Transaction): void {
  applyWithSign(data, tx, 1);
}

/** Deshace el efecto de un movimiento sobre los saldos. */
export function revertTransaction(data: AppData, tx: Transaction): void {
  applyWithSign(data, tx, -1);
}

/* ------------------------------------------------------------------ */
/* Validación                                                          */
/* ------------------------------------------------------------------ */

export interface ValidationIssue {
  field: string;
  message: string;
}

/** Revisa un movimiento antes de guardarlo. Devuelve los problemas encontrados. */
export function validateTransaction(data: AppData, tx: Transaction): ValidationIssue[] {
  const issues: ValidationIssue[] = [];

  if (tx.kind === 'exchange') {
    if (tx.fromAmount <= 0) issues.push({ field: 'fromAmount', message: 'Escribe cuánto cambias.' });
    if (tx.toAmount <= 0) issues.push({ field: 'toAmount', message: 'Escribe cuánto recibes.' });
    if (tx.fromCurrency === tx.toCurrency) {
      issues.push({ field: 'toCurrency', message: 'Las dos monedas son la misma.' });
    }
    if (tx.fromAccountId && tx.fromAccountId === tx.toAccountId) {
      issues.push({ field: 'toAccountId', message: 'Elige una cuenta distinta para el destino.' });
    }
  } else {
    if (tx.amount <= 0) issues.push({ field: 'amount', message: 'Escribe un monto mayor que cero.' });
  }

  if (tx.kind === 'transfer') {
    if (!tx.fromAccountId) issues.push({ field: 'fromAccountId', message: 'Elige de dónde sale.' });
    if (!tx.toAccountId) issues.push({ field: 'toAccountId', message: 'Elige a dónde va.' });
    if (tx.fromAccountId && tx.fromAccountId === tx.toAccountId) {
      issues.push({ field: 'toAccountId', message: 'El origen y el destino no pueden ser la misma cuenta.' });
    }
  }

  if (tx.kind === 'expense' && !tx.categoryId) {
    issues.push({ field: 'categoryId', message: 'Elige una categoría.' });
  }
  if (tx.kind === 'income' && !tx.sourceId) {
    issues.push({ field: 'sourceId', message: 'Elige de dónde viene el dinero.' });
  }

  for (const id of accountsTouched(tx)) {
    if (!findAccount(data, id)) {
      issues.push({ field: 'accountId', message: 'Esa cuenta ya no existe.' });
    }
  }

  return issues;
}

/**
 * Avisa si el movimiento deja una cuenta de banco en rojo o pasa el límite
 * de una tarjeta. No impide guardar: es información, porque puede ser real.
 */
export function overdraftWarning(data: AppData, tx: Transaction): string | null {
  if (tx.kind === 'income') return null;

  const id = tx.kind === 'expense' ? tx.accountId : tx.fromAccountId;
  const account = findAccount(data, id);
  if (!account) return null;

  const currency = tx.kind === 'exchange' ? tx.fromCurrency : tx.currency;
  const monto = tx.kind === 'exchange' ? tx.fromAmount + (tx.fee ?? 0) : tx.amount;
  const saldo = account.balances[currency] ?? 0;
  const nombre = account.nickname ?? account.bank;

  if (account.kind === 'cash') return null;

  if (account.kind === 'bank') {
    if (monto > saldo) return `Esto deja ${nombre} en negativo.`;
    return null;
  }

  // En una tarjeta el saldo es negativo y el límite marca el tope
  const limite = account.credit?.limits[currency];
  if (limite === undefined || limite <= 0) return null;
  const usadoDespues = Math.abs(Math.min(0, saldo)) + monto;
  if (usadoDespues > limite) return `Esto pasa el límite de ${nombre}.`;
  return null;
}
