/**
 * Selectores de categoría, fuente de ingreso y cuenta.
 */

import type { Account, Category, IncomeSource } from '../domain/types';
import type { Currency } from '../lib/money';
import { CATEGORY_GROUPS } from '../domain/categories';
import { Amount } from './Amount';
import { Icon } from './Icon';

/* --- Categorías ------------------------------------------------------------ */

export function CategoryPicker({
  categories,
  value,
  onChange,
}: {
  categories: readonly Category[];
  value: string;
  onChange: (id: string) => void;
}) {
  const activas = categories.filter((categoria) => !categoria.archived);

  return (
    <div>
      {CATEGORY_GROUPS.map((grupo) => {
        const delGrupo = activas.filter((categoria) => categoria.group === grupo.id);
        if (delGrupo.length === 0) return null;

        return (
          <div className="grupo" key={grupo.id}>
            <p className="grupo__nombre">{grupo.name}</p>
            <div className="rejilla">
              {delGrupo.map((categoria) => (
                <button
                  key={categoria.id}
                  type="button"
                  className="ficha"
                  aria-pressed={categoria.id === value}
                  onClick={() => onChange(categoria.id)}
                >
                  <span className="ficha__icono" aria-hidden="true">
                    {categoria.icon}
                  </span>
                  <span className="ficha__nombre">{categoria.name}</span>
                </button>
              ))}
            </div>
          </div>
        );
      })}
    </div>
  );
}

/* --- Fuentes de ingreso ---------------------------------------------------- */

export function SourcePicker({
  sources,
  value,
  onChange,
}: {
  sources: readonly IncomeSource[];
  value: string;
  onChange: (id: string) => void;
}) {
  return (
    <div className="rejilla">
      {sources.map((fuente) => (
        <button
          key={fuente.id}
          type="button"
          className="ficha"
          aria-pressed={fuente.id === value}
          onClick={() => onChange(fuente.id)}
        >
          <span className="ficha__icono" aria-hidden="true">
            {fuente.icon}
          </span>
          <span className="ficha__nombre">{fuente.name}</span>
        </button>
      ))}
    </div>
  );
}

/* --- Cuentas ---------------------------------------------------------------- */

export interface AccountPickerProps {
  accounts: readonly Account[];
  value: string | undefined;
  onChange: (id: string | undefined) => void;
  /** Moneda del movimiento, para mostrar el saldo que corresponde. */
  currency: Currency;
  /** Oculta una cuenta, para no elegir la misma en origen y destino. */
  exclude?: string;
  /** Sin tarjetas: no sirven para recibir ni para mover dinero entre cuentas. */
  banksOnly?: boolean;
}

export function AccountPicker({
  accounts,
  value,
  onChange,
  currency,
  exclude,
  banksOnly = false,
}: AccountPickerProps) {
  const disponibles = accounts.filter(
    (cuenta) =>
      !cuenta.archived && cuenta.id !== exclude && (!banksOnly || cuenta.kind !== 'credit'),
  );

  return (
    <div>
      {disponibles.map((cuenta) => {
        const saldo = cuenta.balances[currency];
        const esTarjeta = cuenta.kind === 'credit';
        const esEfectivo = cuenta.kind === 'cash';
        const limite = cuenta.credit?.limits[currency];
        const disponible =
          esTarjeta && limite !== undefined
            ? Math.max(0, limite - Math.abs(Math.min(0, saldo ?? 0)))
            : saldo;

        return (
          <button
            key={cuenta.id}
            type="button"
            className="opcion"
            aria-pressed={value === cuenta.id}
            onClick={() => onChange(cuenta.id)}
          >
            <span className="opcion__icono">
              {esEfectivo ? (
                <span aria-hidden="true">💵</span>
              ) : (
                <Icon name={esTarjeta ? 'tarjeta' : 'cuenta'} size={19} />
              )}
            </span>
            <span className="opcion__centro">
              <span className="opcion__nombre">
                {cuenta.nickname ?? cuenta.bank}
                {cuenta.last4 ? ` ····${cuenta.last4}` : ''}
              </span>
              <span className="opcion__detalle">
                {disponible === undefined ? (
                  'Sin saldo en esta moneda'
                ) : (
                  <>
                    {esTarjeta ? 'Disponible ' : 'Saldo '}
                    <Amount cents={disponible} currency={currency} size="menor" />
                  </>
                )}
              </span>
            </span>
            <span className="opcion__marca" aria-hidden="true">
              ✓
            </span>
          </button>
        );
      })}

      {disponibles.length === 0 && (
        <p className="texto-menor">
          Todavía no tienes cuentas registradas. Agrégalas desde la pantalla de Cuentas.
        </p>
      )}
    </div>
  );
}
