/**
 * PIN de entrada: ponerlo, cambiarlo o quitarlo.
 */

import { useEffect, useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData } from '../../store/useApp';
import { Sheet } from '../../ui/overlays';
import { Button, Notice } from '../../ui/primitives';
import { Field } from '../../ui/forms';
import { PIN_MAXIMO, validatePin } from '../../lib/pin';
import { nombreDeBiometria, tipoDeBiometria, type Biometria } from '../../lib/nativo';
import { Row } from '../../ui/Row';
import { Card } from '../../ui/primitives';

export function SeguridadSheet({ open, onClose }: { open: boolean; onClose: () => void }) {
  const data = useData();
  const tienePin = data.settings.pinHash !== undefined;

  return (
    <Sheet
      open={open}
      title={tienePin ? t('seguridad.cambiarElPin') : t('seguridad.ponerUnPin')}
      subtitle={t('seguridad.paraQueNadieMas')}
      onClose={onClose}
    >
      {tienePin ? (
        <>
          <Biometrica />
          <CambiarPin onDone={onClose} />
        </>
      ) : (
        <PonerPin onDone={onClose} />
      )}
    </Sheet>
  );
}

/**
 * Face ID o Touch ID para entrar sin escribir el PIN.
 * Solo aparece si el teléfono lo tiene; en el navegador no se muestra.
 */
function Biometrica() {
  const data = useData();
  const edit = useApp((state) => state.edit);
  const notify = useApp((state) => state.notify);
  const [tipo, setTipo] = useState<Biometria>('ninguna');

  useEffect(() => {
    void tipoDeBiometria().then(setTipo);
  }, []);

  if (tipo === 'ninguna') return null;

  const nombre = nombreDeBiometria(tipo);
  const activa = data.settings.biometrics;

  return (
    <Card className="seccion">
      <Row
        title={`Entrar con ${nombre}`}
        detail={`El PIN sigue sirviendo si ${nombre} falla`}
        wrapDetail
        right={<span className="texto-menor">{activa ? 'Activado' : 'Apagado'}</span>}
        onClick={() => {
          edit((draft) => {
            draft.settings.biometrics = !draft.settings.biometrics;
          });
          notify(activa ? `${nombre} apagado` : `${nombre} activado`);
        }}
      />
    </Card>
  );
}

function PonerPin({ onDone }: { onDone: () => void }) {
  const setPin = useApp((state) => state.setPin);
  const notify = useApp((state) => state.notify);

  const [uno, setUno] = useState('');
  const [dos, setDos] = useState('');
  const [error, setError] = useState('');
  const [guardando, setGuardando] = useState(false);

  async function guardar() {
    const problema = validatePin(uno);
    if (problema) {
      setError(problema);
      return;
    }
    if (uno !== dos) {
      setError(t('seguridad.losDosNoSon'));
      return;
    }
    setGuardando(true);
    await setPin(uno);
    setGuardando(false);
    notify('PIN activado');
    onDone();
  }

  return (
    <>
      <div className="seccion">
        <Notice tone="azul" icon="🔒">
          El PIN evita que alguien abra la app si agarra tu teléfono desbloqueado. No cifra los
          datos: quien tenga acceso al sistema de archivos del teléfono los puede leer igual. Para
          eso está la clave del propio teléfono. Apúntalo donde no se te pierda: si lo olvidas, la
          única salida es empezar de cero.
        </Notice>
      </div>

      <Field
        label="PIN nuevo"
        type="password"
        inputMode="numeric"
        maxLength={PIN_MAXIMO}
        autoComplete="new-password"
        value={uno}
        error={error}
        hint={t('seguridad.de4A8')}
        onChange={(event) => setUno(event.target.value.replace(/\D/g, ''))}
      />

      <Field
        label={t('seguridad.escribeloOtraVez')}
        type="password"
        inputMode="numeric"
        maxLength={PIN_MAXIMO}
        autoComplete="new-password"
        value={dos}
        onChange={(event) => setDos(event.target.value.replace(/\D/g, ''))}
      />

      <div className="hoja__pie">
        <Button wide disabled={guardando} onClick={guardar}>
          {guardando ? 'Guardando…' : t('seguridad.activarElPin')}
        </Button>
      </div>
    </>
  );
}

function CambiarPin({ onDone }: { onDone: () => void }) {
  const setPin = useApp((state) => state.setPin);
  const clearPin = useApp((state) => state.clearPin);
  const unlock = useApp((state) => state.unlock);
  const notify = useApp((state) => state.notify);

  const [actual, setActual] = useState('');
  const [nuevo, setNuevo] = useState('');
  const [error, setError] = useState('');
  const [ocupado, setOcupado] = useState(false);

  async function cambiar() {
    if (!(await comprobarActual())) return;

    const problema = validatePin(nuevo);
    if (problema) {
      setError(problema);
      return;
    }
    setOcupado(true);
    await setPin(nuevo);
    setOcupado(false);
    notify('PIN cambiado');
    onDone();
  }

  async function quitar() {
    setOcupado(true);
    const bien = await clearPin(actual);
    setOcupado(false);
    if (!bien) {
      setError(t('seguridad.eseNoEsTu'));
      return;
    }
    notify('PIN quitado');
    onDone();
  }

  async function comprobarActual(): Promise<boolean> {
    setOcupado(true);
    const bien = await unlock(actual);
    setOcupado(false);
    if (!bien) setError(t('seguridad.eseNoEsTu'));
    return bien;
  }

  return (
    <>
      <Field
        label="PIN actual"
        type="password"
        inputMode="numeric"
        maxLength={PIN_MAXIMO}
        autoComplete="current-password"
        value={actual}
        error={error}
        onChange={(event) => {
          setError('');
          setActual(event.target.value.replace(/\D/g, ''));
        }}
      />

      <Field
        label="PIN nuevo"
        type="password"
        inputMode="numeric"
        maxLength={PIN_MAXIMO}
        autoComplete="new-password"
        value={nuevo}
        hint={t('seguridad.dejaloVacioSiSolo')}
        onChange={(event) => setNuevo(event.target.value.replace(/\D/g, ''))}
      />

      <div className="hoja__pie">
        <Button wide disabled={ocupado || !actual || !nuevo} onClick={cambiar}>{t('seguridad.cambiarElPin')}</Button>
        <Button
          wide
          variant="peligro"
          className="seccion"
          disabled={ocupado || !actual}
          onClick={quitar}
        >{t('seguridad.quitarElPin')}</Button>
      </div>
    </>
  );
}
