/**
 * Aviso de copia en la nube, para un teléfono que está vacío.
 *
 * Es el momento de cambiar de equipo. Antes, la oferta de bajar la copia
 * estaba solo dentro de Ajustes → Tu cuenta, y nadie va a buscar a Ajustes
 * algo que no sabe que existe: se instalaba la app, se veía en cero, y la
 * copia se quedaba en la nube sin que nadie lo dijera.
 *
 * Es una carta y no una hoja encima de todo a propósito: aparece sola en el
 * inicio mientras no haya nada, y se va sin que haya que cerrarla en cuanto
 * se apunte el primer movimiento.
 */

import { useEffect, useState } from 'react';
import { t } from '../../i18n';
import { useApp } from '../../store/useApp';
import { useAuth } from '../../store/useAuth';
import { bajarCopia } from '../../store/bajarCopia';
import { isEmptyData } from '../../domain/accounts';
import { countOf } from '../../lib/text';
import { relativeDate, toIsoDate } from '../../lib/date';
import { Button, Card, Notice } from '../../ui/primitives';
import { Row } from '../../ui/Row';
import { CuentaSheet } from './CuentaSheet';

export function AvisoDeCopia() {
  const estado = useAuth((state) => state.estado);
  const cloud = useAuth((state) => state.cloud);
  const cloudEstado = useAuth((state) => state.cloudEstado);
  const vacio = useApp((state) => isEmptyData(state.data));

  const [abierta, setAbierta] = useState(false);
  const [bajando, setBajando] = useState(false);
  const [error, setError] = useState('');

  // Con sesión y sin datos, la copia puede estar esperando. Se mira una sola
  // vez: fetchCloud deja el estado en 'cargando' y luego en 'listo'.
  useEffect(() => {
    if (estado !== 'dentro' || !vacio) return;
    if (cloudEstado !== 'desconocido') return;
    void useAuth.getState().fetchCloud();
  }, [estado, vacio, cloudEstado]);

  // En cuanto hay un movimiento, este aviso no tiene nada que decir
  if (!vacio) return null;
  if (estado === 'cargando' || estado === 'sin-config') return null;

  if (estado === 'fuera') {
    return (
      <>
        <Card className="seccion" title={t('avisoCopia.yaUsabas')}>
          <p className="texto-menor">{t('avisoCopia.entraYLaBajo')}</p>
          <Button wide variant="contorno" className="seccion" onClick={() => setAbierta(true)}>
            {t('avisoCopia.entrarConMiCuenta')}
          </Button>
        </Card>
        <CuentaSheet open={abierta} onClose={() => setAbierta(false)} />
      </>
    );
  }

  // Dentro, pero sin copia que ofrecer: mejor callarse
  if (cloud === null || cloud.count === 0) return null;

  async function bajar() {
    setBajando(true);
    const fallo = await bajarCopia();
    setBajando(false);
    setError(fallo ?? '');
  }

  return (
    <Card className="seccion" title={t('avisoCopia.titulo')}>
      <Notice tone="azul" icon="☁️">
        {t('avisoCopia.esteTelefonoEstaVacio', {
          movimientos: countOf(cloud.count, 'movimiento', 'movimientos'),
        })}
      </Notice>

      <Row
        title={t('avisoCopia.guardada')}
        right={
          <span className="texto-menor">
            {relativeDate(toIsoDate(new Date(cloud.updatedAt)))}
          </span>
        }
      />
      {cloud.device !== null && (
        <Row
          title={t('avisoCopia.desde')}
          right={<span className="texto-menor">{cloud.device}</span>}
        />
      )}

      {error !== '' && (
        <Notice tone="roja" icon="⚠️">
          {error}
        </Notice>
      )}

      <p className="campo__ayuda seccion">{t('avisoCopia.siTeniasCodigo')}</p>
      <Button wide disabled={bajando} onClick={() => void bajar()}>
        {bajando ? t('avisoCopia.bajando') : t('avisoCopia.bajarLaCopia')}
      </Button>
    </Card>
  );
}
