/**
 * El saludo del inicio.
 *
 * La hora la pone el teléfono, así que alguien en Nueva York y alguien en
 * Santo Domingo ven cada uno lo suyo sin que la app tenga que saber dónde
 * está ninguno de los dos.
 */

import { t } from '../i18n';
import type { TextKey } from '../i18n';

export type MomentoDelDia = 'manana' | 'tarde' | 'noche';

/**
 * Solo el primer nombre. "Buenas noches, Juan" se lee como habla la gente;
 * "Buenas noches, Juan Alberto Pérez Reyes" se lee como una carta del banco.
 */
export function primerNombre(nombre: string | undefined): string {
  const limpio = (nombre ?? '').trim();
  if (!limpio) return '';
  return limpio.split(/\s+/)[0] ?? '';
}

/** En República Dominicana se dan las buenas tardes hasta que oscurece. */
export function momentoDelDia(hora: number): MomentoDelDia {
  if (hora < 12) return 'manana';
  if (hora < 19) return 'tarde';
  return 'noche';
}

const SIN_NOMBRE: Record<MomentoDelDia, TextKey> = {
  manana: 'saludo.manana',
  tarde: 'saludo.tarde',
  noche: 'saludo.noche',
};

const CON_NOMBRE: Record<MomentoDelDia, TextKey> = {
  manana: 'saludo.mananaCon',
  tarde: 'saludo.tardeCon',
  noche: 'saludo.nocheCon',
};

/** Sin nombre no queda cojo: saluda igual, solo que sin llamarte. */
export function saludo(nombre: string | undefined, ahora: Date = new Date()): string {
  const momento = momentoDelDia(ahora.getHours());
  const quien = primerNombre(nombre);
  return quien ? t(CON_NOMBRE[momento], { nombre: quien }) : t(SIN_NOMBRE[momento]);
}
