/**
 * La hoja de un movimiento: su detalle y, si se corrige, el formulario.
 */

import { useData } from '../../store/useApp';
import { t } from '../../i18n';
import { Sheet } from '../../ui/overlays';
import { MovimientoDetalle } from './MovimientoDetalle';
import { EditarMovimiento } from './EditarMovimiento';
import { describeTransaction } from '../../domain/describe';

export type MovimientoVista =
  | { modo: 'cerrada' }
  | { modo: 'detalle'; id: string }
  | { modo: 'editar'; id: string };

const TITULO_TIPO = {
  expense: 'Gasto',
  income: 'Ingreso',
  transfer: 'Transferencia',
  exchange: t('movHoja.cambioDeMoneda'),
} as const;

export function MovimientosSheet({
  vista,
  onCerrar,
  onCambiarVista,
}: {
  vista: MovimientoVista;
  onCerrar: () => void;
  onCambiarVista: (vista: MovimientoVista) => void;
}) {
  const data = useData();

  if (vista.modo === 'cerrada') return null;

  const tx = data.transactions.find((item) => item.id === vista.id);
  if (!tx) return null;

  const { title } = describeTransaction(tx, data);

  return (
    <Sheet
      open
      title={vista.modo === 'editar' ? t('movHoja.corregirMovimiento') : title}
      subtitle={vista.modo === 'detalle' ? TITULO_TIPO[tx.kind] : undefined}
      onClose={onCerrar}
      onBack={vista.modo === 'editar' ? () => onCambiarVista({ modo: 'detalle', id: tx.id }) : undefined}
    >
      {vista.modo === 'detalle' ? (
        <MovimientoDetalle
          tx={tx}
          onEditar={() => onCambiarVista({ modo: 'editar', id: tx.id })}
          onDone={onCerrar}
        />
      ) : (
        <EditarMovimiento tx={tx} onDone={() => onCambiarVista({ modo: 'detalle', id: tx.id })} />
      )}
    </Sheet>
  );
}
