/**
 * Detalle de una cuenta: saldos, límites y qué puedes hacer con ella.
 */

import { useApp, useData, usePrivacy } from '../../store/useApp';
import { t } from '../../i18n';
import type { Account } from '../../domain/types';
import type { Currency } from '../../lib/money';
import {
  accountCurrencies,
  accountUsage,
  canDelete,
  cardAvailable,
  cardUsagePercent,
  cardUsed,
} from '../../domain/accounts';
import { Amount } from '../../ui/Amount';
import { Button, Card, Chip, Notice } from '../../ui/primitives';
import { Row } from '../../ui/Row';
import { countOf } from '../../lib/text';
import { daysUntilMonthDay } from '../../lib/date';

export function CuentaDetalle({
  account,
  onEditar,
  onContarEfectivo,
  onDone,
}: {
  account: Account;
  onEditar: () => void;
  onContarEfectivo: () => void;
  onDone: () => void;
}) {
  const data = useData();
  const privacy = usePrivacy();
  const archiveAccount = useApp((state) => state.archiveAccount);
  const deleteAccount = useApp((state) => state.deleteAccount);
  const notify = useApp((state) => state.notify);

  const usos = accountUsage(data, account.id);
  const sePuedeBorrar = canDelete(data, account.id);
  const monedas = accountCurrencies(account);
  const esTarjeta = account.kind === 'credit';
  const esEfectivo = account.kind === 'cash';

  function archivar() {
    archiveAccount(account.id);
    notify(t('cuentaDetalle.cuentaArchivada'));
    onDone();
  }

  function borrar() {
    deleteAccount(account.id);
    notify(t('cuentaDetalle.cuentaEliminada'));
    onDone();
  }

  return (
    <>
      {monedas.length === 0 && (
        <Notice tone="ambar" icon="🤔">{t('cuentaDetalle.estaCuentaNoTiene')}</Notice>
      )}

      {monedas.map((moneda) =>
        esTarjeta ? (
          <TarjetaMoneda key={moneda} account={account} currency={moneda} privacy={privacy} />
        ) : (
          <Card key={moneda} className="seccion">
            <p className="texto-menor">Saldo en {moneda === 'DOP' ? 'pesos' : 'dólares'}</p>
            <Amount
              cents={account.balances[moneda] ?? 0}
              currency={moneda}
              size="grande"
              tag
              hidden={privacy}
            />
          </Card>
        ),
      )}

      <Card className="seccion">
        <Row title="Banco" right={<span className="texto-menor">{account.bank}</span>} />
        <Row
          title="País"
          right={
            <span className="texto-menor">
              {account.country === 'US' ? 'Estados Unidos' : 'República Dominicana'}
            </span>
          }
        />
        {account.last4 && (
          <Row
            title="Dígitos"
            right={<span className={t('cuentaDetalle.textoMenorMonto')}>····{account.last4}</span>}
          />
        )}
        {esTarjeta && account.credit?.statementDay !== undefined && (
          <Row
            title={t('cuentaDetalle.diaDeCorte')}
            right={<span className="texto-menor">Día {account.credit.statementDay}</span>}
          />
        )}
        {esTarjeta && account.credit?.dueDay !== undefined && (
          <Row
            title={t('cuentaDetalle.diaDePago')}
            detail={diasParaPagar(account.credit.dueDay)}
            right={<span className="texto-menor">Día {account.credit.dueDay}</span>}
          />
        )}
        <Row
          title="Movimientos"
          right={<span className="texto-menor">{countOf(usos, 'movimiento', 'movimientos')}</span>}
        />
      </Card>

      {esEfectivo ? (
        <div className="seccion">
          <Button wide variant="suave" onClick={onContarEfectivo}>
            {t('cuentaDetalle.contarEfectivo')}
          </Button>
          <p className="campo__ayuda seccion">{t('cuentaDetalle.efectivoNoSeEdita')}</p>
        </div>
      ) : (
      <div className="seccion">
        <Button wide variant="suave" onClick={onEditar}>{t('cuentaDetalle.editarCuenta')}</Button>

        {sePuedeBorrar ? (
          <Button wide variant="peligro" className="seccion" onClick={borrar}>
            Eliminar
          </Button>
        ) : (
          <>
            <Button wide variant="contorno" className="seccion" onClick={archivar}>
              Archivar
            </Button>
            <p className="campo__ayuda">
              No se puede eliminar porque {countOf(usos, t('cuentaDetalle.movimientoDepende'), t('cuentaDetalle.movimientosDependen'))} de
              ella. Archivarla la saca de las listas y deja el historial intacto.
            </p>
          </>
        )}
      </div>
      )}
    </>
  );
}

function diasParaPagar(dia: number): string | undefined {
  const faltan = daysUntilMonthDay(dia);
  if (faltan === null) return undefined;
  if (faltan === 0) return 'Vence hoy';
  return faltan === 1 ? t('cuentaDetalle.venceManana') : `Faltan ${faltan} días`;
}

function TarjetaMoneda({
  account,
  currency,
  privacy,
}: {
  account: Account;
  currency: Currency;
  privacy: boolean;
}) {
  const limite = account.credit?.limits[currency] ?? 0;
  const usado = cardUsed(account, currency);
  const disponible = cardAvailable(account, currency) ?? 0;
  const porcentaje = cardUsagePercent(account, currency) ?? 0;

  const tono = porcentaje > 80 ? 'roja' : porcentaje > 50 ? 'ambar' : 'verde';
  const color =
    porcentaje > 80 ? 'var(--rojo)' : porcentaje > 50 ? 'var(--ambar)' : 'var(--verde)';

  return (
    <Card className="seccion">
      <div className="carta__cabeza">
        <h2 className="titulo-seccion">{currency === 'DOP' ? 'Pesos' : 'Dólares'}</h2>
        <Chip tone={tono}>{porcentaje}% usado</Chip>
      </div>

      <div className="grid-2" style={{ marginBottom: 'var(--e4)' }}>
        <div>
          <p className="texto-micro">Disponible</p>
          <Amount
            cents={disponible}
            currency={currency}
            size="titulo"
            tone="positiva"
            hidden={privacy}
          />
        </div>
        <div>
          <p className="texto-micro">Debes</p>
          <Amount
            cents={usado}
            currency={currency}
            size="titulo"
            tone="negativa"
            hidden={privacy}
          />
        </div>
      </div>

      <div className="bar">
        <div
          className="bar-fill"
          style={{ width: `${Math.min(100, porcentaje)}%`, background: color }}
        />
      </div>
      <p className="texto-micro" style={{ marginTop: 6 }}>
        Límite <Amount cents={limite} currency={currency} size="menor" hidden={privacy} />
      </p>
    </Card>
  );
}
