/**
 * Ajustes.
 *
 * Por ahora están los que ya funcionan de verdad: tema, privacidad y la
 * información de la cuenta. El resto se va sumando en sus pasos.
 */

import { useState } from 'react';
import { useApp, useData } from '../store/useApp';
import { TopBar } from '../app/TopBar';
import { Card } from '../ui/primitives';
import { Segmented } from '../ui/forms';
import { Row } from '../ui/Row';
import { t } from '../i18n';
import { CURRENCY_NAME } from '../lib/money';
import { formatRate } from '../lib/fx';
import type { ThemePreference } from '../domain/types';
import { PresupuestoSheet } from './plan/PresupuestoSheet';
import { RecurrentesSheet } from './plan/RecurrentesSheet';
import { DeudasSheet } from './plan/DeudasSheet';
import { MetasSheet } from './plan/MetasSheet';
import { SeguridadSheet } from './seguridad/SeguridadSheet';
import { RespaldoSheet } from './ajustes/RespaldoSheet';
import { TasaSheet } from './ajustes/TasaSheet';
import { NombreSheet } from './ajustes/NombreSheet';
import { ImportarSheet } from './ajustes/ImportarSheet';
import { CuentaSheet } from './cuenta/CuentaSheet';
import { useAuth } from '../store/useAuth';
import { usePremium } from '../store/usePremium';
import { PremiumSheet } from './premium/PremiumSheet';
import { textoDeEstado } from '../domain/premium';
import { countOf } from '../lib/text';

const TEMAS = [
  { value: 'auto' as const, label: t('ajustes.tema.auto') },
  { value: 'light' as const, label: t('ajustes.tema.dia') },
  { value: 'dark' as const, label: t('ajustes.tema.noche') },
];

export function Ajustes() {
  const data = useData();
  const setTheme = useApp((state) => state.setTheme);
  const togglePrivacy = useApp((state) => state.togglePrivacy);

  const pais = data.profile.country === 'US' ? 'Estados Unidos' : 'República Dominicana';
  const [hoja, setHoja] = useState<
        | 'ninguna'
    | 'nombre'
    | 'presupuesto'
    | 'recurrentes'
    | 'deudas'
    | 'metas'
    | 'seguridad'
    | 'respaldo'
    | 'tasa'
    | 'importar'
    | 'cuenta'
    | 'premium'
  >('ninguna');
  const tienePin = data.settings.pinHash !== undefined;
  const estadoCuenta = useAuth((state) => state.estado);
  const suscripcion = usePremium((state) => state.estado);
  const correo = useAuth((state) => state.email);
  const activos = data.recurrences.filter((item) => !item.archived).length;

  return (
    <>
      <TopBar title={t('ajustes.titulo')} />

      <main className="contenido">
        <Card title={t('ajustes.preferencias')}>
          <p className="campo__etiqueta">{t('ajustes.tema')}</p>
          <Segmented
            options={TEMAS}
            value={data.settings.theme}
            onChange={(value: ThemePreference) => setTheme(value)}
            label={t('ajustes.tema')}
          />

          <div style={{ marginTop: 'var(--e5)' }}>
            <Row
              title={t('ajustes.privacidad')}
              detail={t('ajustes.privacidad.ayuda')}
              wrapDetail
              right={
                <span className={`pastilla pastilla--${data.settings.privacy ? 'azul' : 'neutra'}`}>
                  {data.settings.privacy ? 'Activado' : 'Desactivado'}
                </span>
              }
              onClick={togglePrivacy}
            />
          </div>
        </Card>

        <section className="seccion">
          <Card title={t('ajustesPlan.tuPlanDelMes')}>
            <Row
              title={t('comun.presupuesto')}
              detail={t('ajustesPlan.cuantoQuieresGastarEn')}
              wrapDetail
              right={
                <span className="texto-menor">
                  {countOf(data.budgets.length, 'categoría', 'categorías')}
                </span>
              }
              onClick={() => setHoja('presupuesto')}
            />
            <Row
              title={t('ajustesPlan.movimientosFijos')}
              detail={t('ajustesPlan.elAlquilerElInternet')}
              wrapDetail
              right={<span className="texto-menor">{countOf(activos, 'activo', 'activos')}</span>}
              onClick={() => setHoja('recurrentes')}
            />
            <Row
              title="Deudas"
              detail={t('ajustesPlan.prestamosYDineroQue')}
              wrapDetail
              right={
                <span className="texto-menor">
                  {countOf(
                    data.debts.filter((item) => !item.archived).length,
                    'deuda',
                    'deudas',
                  )}
                </span>
              }
              onClick={() => setHoja('deudas')}
            />
            <Row
              title={t('ajustesPlan.metasDeAhorro')}
              detail={t('ajustesPlan.dineroApartadoConNombre')}
              wrapDetail
              right={
                <span className="texto-menor">
                  {countOf(data.goals.filter((item) => !item.archived).length, 'meta', 'metas')}
                </span>
              }
              onClick={() => setHoja('metas')}
            />
          </Card>
        </section>

        <section className="seccion">
          <Card title="Suscripción">
            <Row
              title={suscripcion.activo ? 'GestorRD Premium' : t('ajustesPlan.haztePremium')}
              detail={
                suscripcion.activo
                  ? textoDeEstado(suscripcion)
                  : t('ajustesPlan.reportesCopiaEnLa')
              }
              wrapDetail
              onClick={() => setHoja('premium')}
            />
          </Card>
        </section>

        <section className="seccion">
          <Card title="Tu cuenta">
            <Row
              title={estadoCuenta === 'dentro' ? 'Conectada' : t('ajustesPlan.entrarOCrearCuenta')}
              detail={
                estadoCuenta === 'dentro'
                  ? (correo ?? undefined)
                  : t('ajustesPlan.paraGuardarUnaCopia')
              }
              wrapDetail
              onClick={() => setHoja('cuenta')}
            />
          </Card>
        </section>

        <section className="seccion">
          <Card title={t('ajustes.cuenta')}>
            <Row
              title={t('ajustes.tuNombre')}
              right={
                <span className="texto-menor">
                  {data.profile.name ?? t('ajustes.sinNombre')}
                </span>
              }
              onClick={() => setHoja('nombre')}
            />
            <Row title={t('ajustes.pais')} right={<span className="texto-menor">{pais}</span>} />
            <Row
              title={t('ajustes.moneda')}
              right={
                <span className="texto-menor">{CURRENCY_NAME[data.profile.mainCurrency]}</span>
              }
            />
            <Row
              title={t('ajustesPlan.tasaDeCambio')}
              detail={data.fx.source === 'default' ? t('ajustesPlan.valorDeArranque') : undefined}
              right={<span className={t('ajustesPlan.textoMenorMonto')}>{formatRate(data.fx.dopPerUsd)}</span>}
              onClick={() => setHoja('tasa')}
            />
            <Row title={t('ajustes.version')} right={<span className="texto-menor">3.0.0</span>} />
          </Card>
        </section>

        <section className="seccion">
          <Card title={t('ajustesPlan.seguridadYDatos')}>
            <Row
              title={t('ajustesPlan.pinDeEntrada')}
              detail={
                tienePin
                  ? t('ajustesPlan.activadoTeLoPide')
                  : t('ajustesPlan.paraQueNadieMas')
              }
              wrapDetail
              right={<span className="texto-menor">{tienePin ? 'Activado' : 'Apagado'}</span>}
              onClick={() => setHoja('seguridad')}
            />
            <Row
              title={t('ajustesPlan.importarDelBanco')}
              detail={t('ajustesPlan.subeElCsvDe')}
              wrapDetail
              onClick={() => setHoja('importar')}
            />
            <Row
              title="Respaldo"
              detail={t('ajustesPlan.guardaUnaCopiaDe')}
              wrapDetail
              onClick={() => setHoja('respaldo')}
            />
          </Card>
        </section>
      </main>

      <PresupuestoSheet open={hoja === 'presupuesto'} onClose={() => setHoja('ninguna')} />
      <RecurrentesSheet open={hoja === 'recurrentes'} onClose={() => setHoja('ninguna')} />
      <DeudasSheet open={hoja === 'deudas'} onClose={() => setHoja('ninguna')} />
      <MetasSheet open={hoja === 'metas'} onClose={() => setHoja('ninguna')} />
      <SeguridadSheet open={hoja === 'seguridad'} onClose={() => setHoja('ninguna')} />
      <RespaldoSheet open={hoja === 'respaldo'} onClose={() => setHoja('ninguna')} />
      <TasaSheet open={hoja === 'tasa'} onClose={() => setHoja('ninguna')} />
      <NombreSheet open={hoja === 'nombre'} onClose={() => setHoja('ninguna')} />
      <ImportarSheet open={hoja === 'importar'} onClose={() => setHoja('ninguna')} />
      <CuentaSheet open={hoja === 'cuenta'} onClose={() => setHoja('ninguna')} />
      <PremiumSheet open={hoja === 'premium'} onClose={() => setHoja('ninguna')} />
    </>
  );
}
