/**
 * PIN de entrada.
 *
 * El PIN nunca se guarda en claro: se deriva con PBKDF2 y se compara el
 * resultado. Aun así, conviene ser claro sobre qué protege y qué no.
 *
 * Qué protege: que alguien que agarre el teléfono desbloqueado abra la app
 * y vea tus cuentas.
 *
 * Qué no: los datos siguen guardados sin cifrar en el teléfono. Quien tenga
 * acceso al sistema de archivos los puede leer sin saber el PIN. La barrera
 * de verdad para eso es la clave del propio teléfono.
 */

const ITERACIONES = 210000;
const LARGO_SAL = 16;
const LARGO_CLAVE = 32;

export const PIN_MINIMO = 4;
export const PIN_MAXIMO = 8;

function aHex(bytes: Uint8Array): string {
  return [...bytes].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

function deHex(hex: string): Uint8Array {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < bytes.length; i++) {
    bytes[i] = Number.parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  return bytes;
}

async function derivar(pin: string, sal: Uint8Array): Promise<string> {
  const clave = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(pin),
    'PBKDF2',
    false,
    ['deriveBits'],
  );
  const bits = await crypto.subtle.deriveBits(
    { name: 'PBKDF2', salt: sal as BufferSource, iterations: ITERACIONES, hash: 'SHA-256' },
    clave,
    LARGO_CLAVE * 8,
  );
  return aHex(new Uint8Array(bits));
}

/** Devuelve la cadena que se guarda: algoritmo, vueltas, sal y resultado. */
export async function hashPin(pin: string): Promise<string> {
  const sal = crypto.getRandomValues(new Uint8Array(LARGO_SAL));
  const hash = await derivar(pin, sal);
  return `pbkdf2$${ITERACIONES}$${aHex(sal)}$${hash}`;
}

/** Compara sin salirse antes de tiempo, para no filtrar por dónde falló. */
function igualEnTiempoConstante(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diferencia = 0;
  for (let i = 0; i < a.length; i++) {
    diferencia |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diferencia === 0;
}

export async function verifyPin(pin: string, guardado: string): Promise<boolean> {
  const partes = guardado.split('$');
  if (partes.length !== 4 || partes[0] !== 'pbkdf2') return false;

  const vueltas = Number(partes[1]);
  const salHex = partes[2];
  const esperado = partes[3];
  if (!Number.isFinite(vueltas) || !salHex || !esperado) return false;

  const clave = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(pin),
    'PBKDF2',
    false,
    ['deriveBits'],
  );
  const bits = await crypto.subtle.deriveBits(
    { name: 'PBKDF2', salt: deHex(salHex) as BufferSource, iterations: vueltas, hash: 'SHA-256' },
    clave,
    LARGO_CLAVE * 8,
  );

  return igualEnTiempoConstante(aHex(new Uint8Array(bits)), esperado);
}

/** Revisa el formato antes de guardar. Devuelve el problema o null. */
export function validatePin(pin: string): string | null {
  if (!/^\d+$/.test(pin)) return 'El PIN son solo números.';
  if (pin.length < PIN_MINIMO) return `El PIN lleva al menos ${PIN_MINIMO} números.`;
  if (pin.length > PIN_MAXIMO) return `El PIN lleva ${PIN_MAXIMO} números como máximo.`;
  if (new Set(pin).size === 1) return 'Ese PIN es el mismo número repetido. Usa otro.';
  if (esSeguido(pin)) return 'Ese PIN va en orden seguido. Usa otro.';
  return null;
}

function esSeguido(pin: string): boolean {
  let sube = true;
  let baja = true;
  for (let i = 1; i < pin.length; i++) {
    const anterior = Number(pin[i - 1]);
    const actual = Number(pin[i]);
    if (actual !== anterior + 1) sube = false;
    if (actual !== anterior - 1) baja = false;
  }
  return sube || baja;
}
