/**
 * Presupuestos: cuánto quieres gastar al mes en cada categoría.
 *
 * Lo gastado se convierte a la moneda del presupuesto con la tasa que guardó
 * cada movimiento, no con la de hoy, para que el mes pasado no cambie solo.
 */

import type { AppData, Budget } from './types';
import type { Cents } from '../lib/money';
import type { YearMonth } from '../lib/date';
import { convert } from '../lib/fx';
import { shiftMonth, yearMonthOf } from '../lib/date';

/** Cuántos meses hacia atrás se acumula el arrastre. */
const MESES_DE_ARRASTRE = 12;

export interface BudgetProgress {
  budget: Budget;
  /** Límite del mes, sin contar el arrastre. */
  limit: Cents;
  /** Lo que sobró o faltó de meses anteriores, si el arrastre está activo. */
  carried: Cents;
  /** Límite más arrastre: lo que de verdad puedes gastar este mes. */
  available: Cents;
  spent: Cents;
  /** Lo que queda. Negativo si te pasaste. */
  left: Cents;
  /** Porcentaje gastado sobre lo disponible. */
  percent: number;
  overspent: boolean;
}

/** Lo gastado en una categoría durante un mes, en la moneda del presupuesto. */
export function spentInCategory(
  data: AppData,
  categoryId: string,
  month: YearMonth,
  currency: Budget['currency'],
): Cents {
  let total = 0;
  for (const tx of data.transactions) {
    if (tx.kind !== 'expense') continue;
    if (tx.categoryId !== categoryId) continue;
    if (yearMonthOf(tx.date) !== month) continue;
    total += convert(tx.amount, tx.currency, currency, tx.fxRate);
  }
  return total;
}

/** Lo que sobró o faltó en los meses anteriores, si el arrastre está activo. */
function carriedOver(data: AppData, budget: Budget, month: YearMonth): Cents {
  if (!budget.rollover) return 0;

  let acumulado = 0;
  for (let atras = MESES_DE_ARRASTRE; atras >= 1; atras--) {
    const mes = shiftMonth(month, -atras);
    const gastado = spentInCategory(data, budget.categoryId, mes, budget.currency);
    // Un mes sin gastos no arrastra nada: lo más probable es que el
    // presupuesto todavía no existiera
    if (gastado === 0) continue;
    acumulado += budget.limit - gastado;
  }
  return acumulado;
}

export function budgetProgress(data: AppData, budget: Budget, month: YearMonth): BudgetProgress {
  const spent = spentInCategory(data, budget.categoryId, month, budget.currency);
  const carried = carriedOver(data, budget, month);
  const available = Math.max(0, budget.limit + carried);
  const left = available - spent;

  return {
    budget,
    limit: budget.limit,
    carried,
    available,
    spent,
    left,
    percent: available > 0 ? Math.round((spent / available) * 100) : 0,
    overspent: spent > available,
  };
}

/** Todos los presupuestos activos, del más apretado al más holgado. */
export function allBudgetProgress(data: AppData, month: YearMonth): BudgetProgress[] {
  return data.budgets
    .filter((budget) => !budget.archived)
    .map((budget) => budgetProgress(data, budget, month))
    .sort((a, b) => b.percent - a.percent);
}

/** Los que ya se pasaron o están por pasarse. */
export function budgetsAtRisk(data: AppData, month: YearMonth, umbral = 80): BudgetProgress[] {
  return allBudgetProgress(data, month).filter((progreso) => progreso.percent >= umbral);
}
