/**
 * Lector de CSV.
 *
 * Cada banco exporta distinto: unos separan con coma, otros con punto y coma,
 * algunos ponen el nombre del cliente y el número de cuenta antes de la tabla.
 * Esto solo parte el archivo en filas y celdas; entender qué significa cada
 * columna es trabajo de domain/import.ts.
 */

/** Separadores que se prueban, en orden de qué tan común es cada uno. */
const CANDIDATOS = [',', ';', '\t', '|'] as const;

/** Adivina el separador: el que dé más columnas repetidas fila tras fila. */
export function detectDelimiter(texto: string): string {
  const muestra = texto.split(/\r?\n/).filter((linea) => linea.trim()).slice(0, 20);
  if (muestra.length === 0) return ',';

  let mejor = ',';
  let mejorPuntaje = -1;

  for (const separador of CANDIDATOS) {
    const cuentas = muestra.map((linea) => contarFuera(linea, separador));
    const maximo = Math.max(...cuentas);
    if (maximo === 0) continue;

    // Premia que todas las filas tengan el mismo número de separadores
    const iguales = cuentas.filter((valor) => valor === maximo).length;
    const puntaje = maximo * 10 + iguales;
    if (puntaje > mejorPuntaje) {
      mejorPuntaje = puntaje;
      mejor = separador;
    }
  }

  return mejor;
}

/** Cuenta separadores que no estén dentro de comillas. */
function contarFuera(linea: string, separador: string): number {
  let dentro = false;
  let total = 0;
  for (let i = 0; i < linea.length; i++) {
    const letra = linea[i];
    if (letra === '"') {
      if (dentro && linea[i + 1] === '"') i++;
      else dentro = !dentro;
    } else if (letra === separador && !dentro) {
      total++;
    }
  }
  return total;
}

/**
 * Parte el texto en filas de celdas.
 * Respeta comillas, comillas dobles escapadas y saltos de línea dentro de una celda.
 */
export function parseCsv(texto: string, separador?: string): string[][] {
  // Quita la marca de orden de bytes que pone Excel
  const limpio = texto.replace(/^﻿/, '');
  const sep = separador ?? detectDelimiter(limpio);

  const filas: string[][] = [];
  let fila: string[] = [];
  let celda = '';
  let dentro = false;

  for (let i = 0; i < limpio.length; i++) {
    const letra = limpio[i];

    if (dentro) {
      if (letra === '"') {
        if (limpio[i + 1] === '"') {
          celda += '"';
          i++;
        } else {
          dentro = false;
        }
      } else {
        celda += letra;
      }
      continue;
    }

    if (letra === '"') {
      dentro = true;
    } else if (letra === sep) {
      fila.push(celda.trim());
      celda = '';
    } else if (letra === '\n') {
      fila.push(celda.trim());
      celda = '';
      filas.push(fila);
      fila = [];
    } else if (letra === '\r') {
      // El salto de Windows se maneja al llegar al \n
    } else {
      celda += letra;
    }
  }

  if (celda || fila.length > 0) {
    fila.push(celda.trim());
    filas.push(fila);
  }

  // Fuera las filas completamente vacías
  return filas.filter((item) => item.some((valor) => valor !== ''));
}

/** Escribe un CSV, poniendo comillas solo donde hacen falta. */
export function toCsv(filas: readonly (readonly string[])[]): string {
  return filas
    .map((fila) =>
      fila
        .map((celda) =>
          /[",\n\r]/.test(celda) ? `"${celda.replace(/"/g, '""')}"` : celda,
        )
        .join(','),
    )
    .join('\r\n');
}
