/**
 * Identificadores únicos.
 *
 * Usamos UUID de verdad desde el principio: cuando los datos se respalden en
 * la nube y la persona entre desde otro dispositivo, dos registros creados
 * en lugares distintos no pueden chocar.
 */

export function newId(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }

  // Respaldo para entornos sin randomUUID
  const bytes = new Uint8Array(16);
  if (typeof crypto !== 'undefined' && typeof crypto.getRandomValues === 'function') {
    crypto.getRandomValues(bytes);
  } else {
    for (let i = 0; i < 16; i++) bytes[i] = Math.floor(Math.random() * 256);
  }

  // Marca de versión 4
  bytes[6] = ((bytes[6] ?? 0) & 0x0f) | 0x40;
  bytes[8] = ((bytes[8] ?? 0) & 0x3f) | 0x80;

  const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

/** Id estable a partir de un texto, para no duplicar al migrar dos veces. */
export function stableId(prefix: string, seed: string | number): string {
  return `${prefix}_${String(seed)}`;
}
