/**
 * Guardar y cargar los datos en el dispositivo.
 *
 * Local primero: todo vive aquí y la app funciona sin internet.
 * La copia en la nube se sube aparte, cuando hay señal.
 */

import type { AppData } from '../domain/types';
import { ensureCashAccount } from '../domain/accounts';
import { SCHEMA_VERSION, STORAGE_KEY, createEmptyData } from './schema';
import { guardarEnElSistema, leerDelSistema } from '../lib/nativo';
import { hasLegacyData, migrateFromLegacy, readLegacySources } from './migrate';
import type { MigrationReport } from './migrate';

export interface LoadResult {
  data: AppData;
  /** 'nuevo' si no había nada, 'guardado' si se leyó del disco, 'migrado' si vino de la v1. */
  origin: 'nuevo' | 'guardado' | 'migrado';
  migration?: MigrationReport;
  /** Se llenó si el archivo guardado estaba dañado y hubo que empezar de cero. */
  error?: string;
}

function storage(): Storage | null {
  try {
    if (typeof localStorage === 'undefined') return null;
    // Safari en modo privado deja leer pero falla al escribir
    const probe = '__gestorrd_probe__';
    localStorage.setItem(probe, '1');
    localStorage.removeItem(probe);
    return localStorage;
  } catch {
    return null;
  }
}

/** Comprueba que lo guardado tenga la forma esperada antes de confiar en ello. */
function looksValid(value: unknown): value is AppData {
  if (value === null || typeof value !== 'object') return false;
  const data = value as Partial<AppData>;
  return (
    typeof data.schemaVersion === 'number' &&
    Array.isArray(data.accounts) &&
    Array.isArray(data.transactions) &&
    Array.isArray(data.categories) &&
    data.profile !== undefined &&
    data.settings !== undefined
  );
}

/** Rellena campos que falten, por si el archivo viene de una versión anterior. */
function reconcile(data: AppData): AppData {
  const base = createEmptyData(data.profile?.country ?? 'DO');
  const completo: AppData = {
    ...base,
    ...data,
    profile: { ...base.profile, ...data.profile },
    settings: { ...base.settings, ...data.settings },
    fx: { ...base.fx, ...data.fx },
    accounts: data.accounts ?? [],
    transactions: data.transactions ?? [],
    categories: data.categories?.length ? data.categories : base.categories,
    incomeSources: data.incomeSources?.length ? data.incomeSources : base.incomeSources,
    budgets: data.budgets ?? [],
    debts: data.debts ?? [],
    goals: data.goals ?? [],
    recurrences: data.recurrences ?? [],
    schemaVersion: SCHEMA_VERSION,
  };

  // Toda la carga pasa por aquí: arranque, respaldo en archivo y copia de la
  // nube. Es el único sitio donde hace falta asegurar el efectivo.
  ensureCashAccount(completo);
  return completo;
}

export function load(): LoadResult {
  const store = storage();
  if (!store) {
    return { data: createEmptyData(), origin: 'nuevo', error: 'Este navegador no deja guardar datos.' };
  }

  const raw = store.getItem(STORAGE_KEY);

  if (raw) {
    try {
      const parsed: unknown = JSON.parse(raw);
      if (looksValid(parsed)) return { data: reconcile(parsed), origin: 'guardado' };
      return {
        data: createEmptyData(),
        origin: 'nuevo',
        error: 'Los datos guardados no tenían el formato esperado.',
      };
    } catch {
      return {
        data: createEmptyData(),
        origin: 'nuevo',
        error: 'No se pudieron leer los datos guardados.',
      };
    }
  }

  // Primera vez en la versión 3: ¿hay datos de la versión vieja?
  if (hasLegacyData(store)) {
    const sources = readLegacySources(store);
    if (sources) {
      const { data, report } = migrateFromLegacy(sources);
      save(data);
      return { data, origin: 'migrado', migration: report };
    }
  }

  return { data: createEmptyData(), origin: 'nuevo' };
}

export function save(data: AppData): boolean {
  const store = storage();
  if (!store) return false;
  try {
    const contenido = JSON.stringify(data);
    store.setItem(STORAGE_KEY, contenido);
    // Copia en el almacenamiento del sistema, que iOS no borra. No se espera:
    // si tarda o falla, lo guardado aquí ya está a salvo.
    void guardarEnElSistema(contenido);
    return true;
  } catch {
    // Cuota llena o modo privado
    return false;
  }
}

/**
 * Último recurso: el almacenamiento web apareció vacío y el del sistema no.
 * Pasa si iOS limpió los datos del navegador para hacer sitio.
 */
export async function recoverFromDevice(): Promise<AppData | null> {
  const contenido = await leerDelSistema();
  if (!contenido) return null;

  const datos = fromBackupFile(JSON.stringify({ data: JSON.parse(contenido) as unknown }));
  if (!datos) return null;

  save(datos);
  return datos;
}

/** Contenido del archivo que la persona descarga como respaldo. */
export interface BackupFile {
  app: 'GestorRD';
  version: number;
  exportedAt: string;
  data: AppData;
}

export function toBackupFile(data: AppData): BackupFile {
  return {
    app: 'GestorRD',
    version: SCHEMA_VERSION,
    exportedAt: new Date().toISOString(),
    data,
  };
}

/** Lee un respaldo descargado. Acepta también el formato viejo de la v1. */
export function fromBackupFile(raw: string): AppData | null {
  try {
    const parsed: unknown = JSON.parse(raw);
    if (parsed === null || typeof parsed !== 'object') return null;

    const maybe = parsed as Partial<BackupFile> & Record<string, unknown>;

    if (maybe.data !== undefined && looksValid(maybe.data)) {
      return reconcile(maybe.data as AppData);
    }
    if (looksValid(parsed)) return reconcile(parsed as AppData);

    // Respaldo de la versión 1: traía el objeto DATA tal cual
    if (Array.isArray(maybe.gastos) || Array.isArray(maybe.bancos)) {
      return migrateFromLegacy({ data: parsed }).data;
    }
    if (maybe.data !== undefined) {
      const inner = maybe.data as Record<string, unknown>;
      if (Array.isArray(inner.gastos) || Array.isArray(inner.bancos)) {
        return migrateFromLegacy({ data: inner }).data;
      }
      /*
       * Copia en la nube de la versión 1: allá se guardaba un sobre
       * { version, fecha, datos } y lo de verdad va dentro de "datos".
       * Sin esto, quien ya tenía cuenta no podría bajar lo suyo.
       */
      const sobre = inner.datos as Record<string, unknown> | undefined;
      if (sobre && (Array.isArray(sobre.gastos) || Array.isArray(sobre.bancos))) {
        return migrateFromLegacy({ data: sobre }).data;
      }
    }

    // El mismo sobre, pero suelto
    const sobre = maybe.datos as Record<string, unknown> | undefined;
    if (sobre && (Array.isArray(sobre.gastos) || Array.isArray(sobre.bancos))) {
      return migrateFromLegacy({ data: sobre }).data;
    }

    return null;
  } catch {
    return null;
  }
}

/** Borra solo los datos de la versión 3. Los de la v1 se quedan donde están. */
export function wipe(): void {
  const store = storage();
  if (!store) return;
  try {
    store.removeItem(STORAGE_KEY);
  } catch {
    // nada que hacer
  }
}
