/**
 * Qué es gratis y qué no.
 *
 * Lo esencial para llevar tus cuentas —registrar, cuentas y tarjetas,
 * presupuesto, movimientos fijos, deudas, metas y el respaldo en archivo—
 * es gratis para todo el mundo. Una app que te cobra por apuntar un gasto
 * no sirve de nada a quien más falta le hace.
 *
 * Detrás de la suscripción quedan las cosas que ahorran trabajo —los reportes
 * con el asesor, la copia en la nube y la importación del banco— y manejar las
 * dos monedas a la vez. Con el plan gratis se trabaja en la que se eligió al
 * empezar, que para la mayoría es la única que usa.
 */

import { t } from '../i18n';
import type { ProductoTienda } from '../lib/nativo';
import { CURRENCY_TAG, formatNumber, toCents } from '../lib/money';

export type FuncionPremium = 'reportes' | 'nube' | 'importar' | 'monedas';

export interface EstadoSuscripcion {
  activo: boolean;
  /** Identificador del plan en la tienda. */
  producto?: string;
  /** Hasta cuándo está pagada, en ISO. */
  hasta?: string;
  /** true cuando no hay tienda: el navegador no puede cobrar. */
  sinTienda?: boolean;
}

export const LIBRE: EstadoSuscripcion = { activo: false };

export function puedeUsar(_funcion: FuncionPremium, estado: EstadoSuscripcion): boolean {
  return estado.activo;
}

export interface Explicacion {
  titulo: string;
  texto: string;
  icono: string;
}

const ICONOS: Record<FuncionPremium, string> = {
  reportes: '📊',
  monedas: '💱',
  nube: '☁️',
  importar: '📄',
};

export function explicar(funcion: FuncionPremium): Explicacion {
  return {
    icono: ICONOS[funcion],
    titulo: t(`premium.${funcion}.titulo`),
    texto: t(`premium.${funcion}.texto`),
  };
}

export function todasLasFunciones(): FuncionPremium[] {
  return ['reportes', 'monedas', 'nube', 'importar'];
}

/** Días que faltan para que venza. Negativo si ya venció. */
export function diasRestantes(estado: EstadoSuscripcion, hoy = Date.now()): number | null {
  if (!estado.hasta) return null;
  const fin = new Date(estado.hasta).getTime();
  if (Number.isNaN(fin)) return null;
  return Math.ceil((fin - hoy) / 86400000);
}

/** Lo que se le dice a la persona sobre su suscripción. */
export function textoDeEstado(estado: EstadoSuscripcion, hoy = Date.now()): string {
  if (!estado.activo) return t('premium.estado.gratis');

  const dias = diasRestantes(estado, hoy);
  if (dias === null) return t('premium.estado.activo');
  if (dias <= 0) return t('premium.estado.vencido');
  if (dias === 1) return t('premium.estado.renuevaManana');
  if (dias <= 7) return t('premium.estado.renuevaEn', { dias });
  return t('premium.estado.activo');
}

/**
 * El precio de un plan, escrito como escribe la app.
 *
 * Apple lo manda ya formateado, pero con su estilo ("USD 24.99") y en una app
 * que maneja pesos y dólares a la vez eso se lee distinto a todo lo demás. Si
 * la tienda de la persona usa una moneda que sabemos escribir, lo escribimos
 * nosotros. Si no —alguien con tienda de España, por ejemplo—, se deja el de
 * Apple, que al menos será correcto.
 */
export function precioDelPlan(plan: ProductoTienda): string {
  const moneda = plan.moneda;
  if (plan.precioNumero === undefined || moneda === undefined) return plan.precio;
  if (moneda !== 'DOP' && moneda !== 'USD') return plan.precio;

  return `${CURRENCY_TAG[moneda]}${formatNumber(toCents(plan.precioNumero))}`;
}
