/**
 * Estado de la suscripción.
 *
 * Vive aparte de los datos de la app a propósito: quién tiene premium lo dice
 * Apple, no un campo guardado en el teléfono. Si estuviera en AppData, bastaría
 * con restaurar un respaldo ajeno para desbloquearlo todo.
 */

import { create } from 'zustand';
import type { EstadoSuscripcion } from '../domain/premium';
import { LIBRE } from '../domain/premium';
import type { ProductoTienda, RespuestaSuscripcion } from '../lib/nativo';
import {
  alCambiarSuscripcion,
  comprarPlan,
  estadoDeSuscripcion,
  hayTienda,
  planesDeLaTienda,
  restaurarCompras,
} from '../lib/nativo';

export interface PremiumStore {
  estado: EstadoSuscripcion;
  planes: ProductoTienda[];
  cargando: boolean;
  init: () => void;
  cargarPlanes: () => Promise<void>;
  /** Devuelve el error, o null si salió bien o si la persona canceló. */
  comprar: (productId: string) => Promise<string | null>;
  restaurar: () => Promise<string | null>;
}

let escuchando = false;

export const usePremium = create<PremiumStore>((set) => ({
  estado: { ...LIBRE, sinTienda: true },
  planes: [],
  cargando: false,

  init: () => {
    if (!hayTienda()) {
      set({ estado: { ...LIBRE, sinTienda: true } });
      return;
    }
    if (escuchando) return;
    escuchando = true;

    void estadoDeSuscripcion().then((respuesta) => {
      if (respuesta) set({ estado: aEstado(respuesta) });
    });

    void alCambiarSuscripcion((respuesta) => {
      set({ estado: aEstado(respuesta) });
    });
  },

  cargarPlanes: async () => {
    set({ cargando: true });
    const planes = await planesDeLaTienda();
    set({ planes, cargando: false });
  },

  comprar: async (productId) => {
    set({ cargando: true });
    const respuesta = await comprarPlan(productId);
    set({ cargando: false });

    if (typeof respuesta === 'string') return respuesta;
    set({ estado: aEstado(respuesta) });

    // Cancelar no es un error: la persona cambió de idea
    if (respuesta.cancelado) return null;
    if (respuesta.pendiente) {
      return 'Tu pago quedó pendiente de aprobación. Te avisamos cuando se complete.';
    }
    return null;
  },

  restaurar: async () => {
    set({ cargando: true });
    const respuesta = await restaurarCompras();
    set({ cargando: false });

    if (typeof respuesta === 'string') return respuesta;
    set({ estado: aEstado(respuesta) });
    return respuesta.activo ? null : 'No encontré ninguna suscripción con este Apple ID.';
  },
}));

function aEstado(respuesta: RespuestaSuscripcion): EstadoSuscripcion {
  const estado: EstadoSuscripcion = { activo: respuesta.activo === true };
  if (respuesta.producto) estado.producto = respuesta.producto;
  if (respuesta.hasta) estado.hasta = respuesta.hasta;
  return estado;
}

/** Atajo para las pantallas: ¿tiene premium ahora mismo? */
export const usePremiumActivo = () => usePremium((state) => state.estado.activo);
