/**
 * El nombre.
 *
 * Solo sirve para saludar. No viaja a ningún lado, no se pide al registrarse
 * y se puede quitar cuando se quiera, así que no hay nada que explicar más
 * allá de eso.
 */

import { useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData } from '../../store/useApp';
import { Sheet } from '../../ui/overlays';
import { Button } from '../../ui/primitives';
import { Field } from '../../ui/forms';

const LARGO_MAXIMO = 40;

export function NombreSheet({ open, onClose }: { open: boolean; onClose: () => void }) {
  const data = useData();
  const setName = useApp((state) => state.setName);
  const notify = useApp((state) => state.notify);

  const [valor, setValor] = useState(data.profile.name ?? '');

  function guardar() {
    const limpio = valor.trim();
    setName(limpio);
    notify(limpio ? t('nombre.guardado') : t('nombre.quitado'));
    onClose();
  }

  return (
    <Sheet open={open} title={t('nombre.titulo')} subtitle={t('nombre.subtitulo')} onClose={onClose}>
      <Field
        label={t('nombre.campo')}
        type="text"
        autoComplete="given-name"
        maxLength={LARGO_MAXIMO}
        placeholder="Juan"
        value={valor}
        hint={t('nombre.ayuda')}
        onChange={(event) => setValor(event.target.value)}
      />

      <div className="hoja__pie">
        <Button wide onClick={guardar}>{t('nombre.guardar')}</Button>
        {data.profile.name && (
          <Button
            wide
            variant="texto"
            className="seccion"
            onClick={() => {
              setValor('');
              setName('');
              notify(t('nombre.quitado'));
              onClose();
            }}
          >{t('nombre.quitar')}</Button>
        )}
      </div>
    </Sheet>
  );
}
