/** Quita acentos, emojis y mayúsculas para poder comparar nombres escritos de distinta forma. */
export function normalizeName(value: string): string {
  return value
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^\p{Letter}\p{Number}\s]/gu, '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

/** Busca una categoría por nombre, venga como venga escrito. */
export function findCategoryByName(
  categories: readonly Category[],
  rawName: string,
): Category | undefined {
  const target = normalizeName(rawName);
  if (!target) return undefined;
  return categories.find((category) => normalizeName(category.name) === target);
}

export function findIncomeSourceByName(
  sources: readonly IncomeSource[],
  rawName: string,
): IncomeSource | undefined {
  const target = normalizeName(rawName);
  if (!target) return undefined;
  return sources.find((source) => normalizeName(source.name) === target);
}

/** Saca el emoji inicial de un texto como "🛒 Supermercado". */
export function extractIcon(label: string): string | undefined {
  const match = label.match(/^(\p{Extended_Pictographic}(?:‍\p{Extended_Pictographic})*)/u);
  return match?.[1];
}

/** Quita el emoji inicial: "🛒 Supermercado" da "Supermercado". */
export function stripIcon(label: string): string {
  return label
    .replace(/^(\p{Extended_Pictographic}(?:‍\p{Extended_Pictographic})*)\s*/u, '')
    .trim();
}
