/**
 * Fila de lista y las reglas de la cinta.
 *
 * La cinta es la forma de la pantalla principal: los días en secuencia,
 * cada uno con su nombre a la izquierda, una regla fina y su total a la derecha.
 */

import type { ReactNode } from 'react';

export interface RowProps {
  icon?: ReactNode;
  title: string;
  detail?: string;
  right?: ReactNode;
  rightDetail?: ReactNode;
  onClick?: () => void;
  /** Deja que el detalle use varias líneas en vez de cortarse con puntos. */
  wrapDetail?: boolean;
}

export function Row({ icon, title, detail, right, rightDetail, onClick, wrapDetail }: RowProps) {
  const content = (
    <>
      {icon !== undefined && (
        <span className="fila__icono" aria-hidden="true">
          {icon}
        </span>
      )}
      <span className="fila__centro">
        <span className="fila__titulo">{title}</span>
        {detail && (
          <span className={`fila__detalle${wrapDetail ? ' fila__detalle--largo' : ''}`}>
            {detail}
          </span>
        )}
      </span>
      {(right ?? rightDetail) && (
        <span className="fila__derecha">
          {right}
          {rightDetail && <span className="fila__detalle">{rightDetail}</span>}
        </span>
      )}
    </>
  );

  if (onClick) {
    return (
      <button type="button" className="fila fila--tocable" onClick={onClick}>
        {content}
      </button>
    );
  }

  return <div className="fila">{content}</div>;
}

/** Encabezado de un día dentro de la cinta. */
export function TapeDay({ label, total }: { label: string; total?: ReactNode }) {
  return (
    <div className="cinta__dia">
      <span className="cinta__dia-nombre">{label}</span>
      <span className="cinta__regla" aria-hidden="true" />
      {total}
    </div>
  );
}
