/**
 * Dinero en centavos enteros.
 *
 * Nunca guardamos montos con decimales: 450.75 en coma flotante acumula
 * errores al sumar muchas veces. Un gasto de RD$450.75 se guarda como 45075.
 */

export type Cents = number;
export type Currency = 'DOP' | 'USD';

export const CURRENCIES: readonly Currency[] = ['DOP', 'USD'] as const;

/** Símbolo que se muestra delante del monto. */
export const CURRENCY_SYMBOL: Record<Currency, string> = {
  DOP: 'RD$',
  USD: '$',
};

/**
 * Etiqueta explícita de moneda.
 * A diferencia del símbolo, deja claro de qué dólar se habla: en una app que
 * maneja pesos y dólares a la vez, un "$" suelto se presta a confusión.
 */
export const CURRENCY_TAG: Record<Currency, string> = {
  DOP: 'RD$',
  USD: 'US$',
};

export const CURRENCY_NAME: Record<Currency, string> = {
  DOP: 'Pesos dominicanos',
  USD: 'Dólares estadounidenses',
};

/** Monto máximo aceptado: mil millones. Evita que un dedazo rompa los totales. */
const MAX_CENTS = 100_000_000_000;

/**
 * Convierte lo que la persona escribió a centavos.
 * Acepta "1,234.56", "1234.5", "RD$ 1.200" y devuelve null si no es un monto válido.
 */
export function parseAmount(input: string): Cents | null {
  if (typeof input !== 'string') return null;

  // Quita símbolos, espacios y separadores de miles
  const cleaned = input
    .replace(/[\s ]/g, '')
    .replace(/RD\$|US\$|\$/gi, '')
    .replace(/,/g, '');

  if (cleaned === '' || !/^-?\d*\.?\d*$/.test(cleaned)) return null;

  const value = Number(cleaned);
  if (!Number.isFinite(value)) return null;

  const cents = Math.round(value * 100);
  if (!Number.isSafeInteger(cents)) return null;
  if (Math.abs(cents) > MAX_CENTS) return null;

  return cents;
}

/** Pasa centavos a número con decimales. Solo para mostrar o exportar. */
export function toDecimal(cents: Cents): number {
  return cents / 100;
}

/** Pasa un número con decimales a centavos. */
export function toCents(value: number): Cents {
  return Math.round(value * 100);
}

export interface FormatOptions {
  /** Oculta el monto detrás de puntos, para el modo privado. */
  hidden?: boolean;
  /** Muestra el signo + delante de los positivos. */
  showSign?: boolean;
  /** Omite los centavos cuando son exactos: RD$1,200 en vez de RD$1,200.00 */
  compact?: boolean;
}

/**
 * Escribe solo el número, sin símbolo ni signo: "1,234.56".
 * Lo usa el componente que pone la moneda en una etiqueta aparte.
 */
export function formatNumber(cents: Cents, options: Pick<FormatOptions, 'compact'> = {}): string {
  const abs = Math.abs(cents);
  const exact = abs % 100 === 0;
  const decimals = options.compact && exact ? 0 : 2;

  return (abs / 100).toLocaleString('es-DO', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
}

/** Devuelve el signo que corresponde: "−", "+" o nada. */
export function signOf(cents: Cents, showSign = false): string {
  if (cents < 0) return '−';
  return showSign ? '+' : '';
}

/** Escribe un monto listo para mostrar: "RD$1,234.56" */
export function formatMoney(
  cents: Cents,
  currency: Currency,
  options: FormatOptions = {},
): string {
  const symbol = CURRENCY_SYMBOL[currency];

  if (options.hidden) return `${symbol} ••••`;

  return `${signOf(cents, options.showSign)}${symbol}${formatNumber(cents, options)}`;
}

/** Suma segura: redondea para que no se cuelen fracciones de centavo. */
export function sumCents(values: readonly Cents[]): Cents {
  return values.reduce<Cents>((total, value) => total + Math.round(value), 0);
}

/**
 * Reparte un monto entre n partes sin perder centavos.
 * Útil para cuotas: 100.00 entre 3 da 33.34, 33.33, 33.33.
 */
export function splitCents(total: Cents, parts: number): Cents[] {
  if (parts <= 0) return [];
  const base = Math.floor(total / parts);
  const remainder = total - base * parts;
  return Array.from({ length: parts }, (_, index) => base + (index < remainder ? 1 : 0));
}
