/**
 * Campos de formulario y control segmentado.
 */

import { useId } from 'react';
import type { InputHTMLAttributes, ReactNode, SelectHTMLAttributes } from 'react';

/* --- Campo de texto -------------------------------------------------------- */

export interface FieldProps extends InputHTMLAttributes<HTMLInputElement> {
  label: string;
  hint?: string;
  error?: string;
}

export function Field({ label, hint, error, className, id, ...rest }: FieldProps) {
  const generated = useId();
  const fieldId = id ?? generated;
  const describedBy = error ? `${fieldId}-error` : hint ? `${fieldId}-hint` : undefined;

  return (
    <div className={['campo', error ? 'campo--error' : '', className].filter(Boolean).join(' ')}>
      <label className="campo__etiqueta" htmlFor={fieldId}>
        {label}
      </label>
      <input
        id={fieldId}
        className="campo__control"
        aria-invalid={error ? true : undefined}
        aria-describedby={describedBy}
        {...rest}
      />
      {error ? (
        <p className="campo__error" id={`${fieldId}-error`}>
          {error}
        </p>
      ) : (
        hint && (
          <p className="campo__ayuda" id={`${fieldId}-hint`}>
            {hint}
          </p>
        )
      )}
    </div>
  );
}

/* --- Campo de selección ---------------------------------------------------- */

export interface SelectFieldProps extends SelectHTMLAttributes<HTMLSelectElement> {
  label: string;
  hint?: string;
  children: ReactNode;
}

export function SelectField({ label, hint, className, id, children, ...rest }: SelectFieldProps) {
  const generated = useId();
  const fieldId = id ?? generated;

  return (
    <div className={['campo', className].filter(Boolean).join(' ')}>
      <label className="campo__etiqueta" htmlFor={fieldId}>
        {label}
      </label>
      <select id={fieldId} className="campo__control" {...rest}>
        {children}
      </select>
      {hint && <p className="campo__ayuda">{hint}</p>}
    </div>
  );
}

/* --- Segmentado ------------------------------------------------------------ */

export interface SegmentedOption<T extends string> {
  value: T;
  label: string;
}

export interface SegmentedProps<T extends string> {
  options: readonly SegmentedOption<T>[];
  value: T;
  onChange: (value: T) => void;
  label?: string;
}

export function Segmented<T extends string>({
  options,
  value,
  onChange,
  label,
}: SegmentedProps<T>) {
  return (
    <div className="segmentado" role="group" aria-label={label}>
      {options.map((option) => (
        <button
          key={option.value}
          type="button"
          className="segmentado__opcion"
          aria-pressed={option.value === value}
          onClick={() => onChange(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}
