/**
 * Presupuestos: cuánto quieres gastar al mes en cada categoría.
 */

import { useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData, usePrivacy } from '../../store/useApp';
import type { Budget } from '../../domain/types';
import type { Currency } from '../../lib/money';
import { Sheet } from '../../ui/overlays';
import { Amount } from '../../ui/Amount';
import { Button, Card, Empty, Notice } from '../../ui/primitives';
import { Field, SelectField, Segmented } from '../../ui/forms';
import { SelectorMoneda } from '../../ui/SelectorMoneda';
import { allBudgetProgress } from '../../domain/budgets';
import { currentYearMonth, monthName } from '../../lib/date';
import { formatNumber, parseAmount } from '../../lib/money';
import { newId } from '../../lib/id';

const ARRASTRE = [
  { value: 'no' as const, label: t('presupuesto.empezarDeCero') },
  { value: 'si' as const, label: t('presupuesto.arrastrarLoQueSobre') },
];

export function PresupuestoSheet({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [editando, setEditando] = useState<Budget | 'nuevo' | null>(null);

  return (
    <Sheet
      open={open}
      title={editando ? (editando === 'nuevo' ? t('presupuesto.nuevoPresupuesto') : t('presupuesto.editarPresupuesto')) : 'Presupuesto'}
      subtitle={editando ? undefined : `Lo que planeas gastar en ${monthName(currentYearMonth()).toLowerCase()}`}
      onClose={onClose}
      onBack={editando ? () => setEditando(null) : undefined}
    >
      {editando ? (
        <PresupuestoForm
          budget={editando === 'nuevo' ? undefined : editando}
          onDone={() => setEditando(null)}
        />
      ) : (
        <ListaPresupuestos onNuevo={() => setEditando('nuevo')} onEditar={setEditando} />
      )}
    </Sheet>
  );
}

function ListaPresupuestos({
  onNuevo,
  onEditar,
}: {
  onNuevo: () => void;
  onEditar: (budget: Budget) => void;
}) {
  const data = useData();
  const privacy = usePrivacy();
  const avances = allBudgetProgress(data, currentYearMonth());

  if (avances.length === 0) {
    return (
      <Empty
        mark="📊"
        title={t('presupuesto.sinPresupuestosTodavia')}
        text={t('presupuesto.ponUnLimiteEn')}
        action={<Button small onClick={onNuevo}>{t('presupuesto.crearMiPrimerPresupuesto')}</Button>}
      />
    );
  }

  return (
    <>
      {avances.map((avance) => {
        const categoria = data.categories.find((item) => item.id === avance.budget.categoryId);
        const color = avance.overspent
          ? 'var(--rojo)'
          : avance.percent > 80
            ? 'var(--ambar)'
            : 'var(--verde)';

        return (
          <Card key={avance.budget.id} className="seccion">
            <button
              type="button"
              style={{ width: '100%', textAlign: 'left' }}
              onClick={() => onEditar(avance.budget)}
            >
              <div className="fila-entre" style={{ marginBottom: 8 }}>
                <span className="fila__titulo">
                  {categoria?.icon} {categoria?.name ?? t('presupuesto.categoriaEliminada')}
                </span>
                <span style={{ color, fontWeight: 600, fontSize: 'var(--t-menor)' }}>
                  {avance.percent}%
                </span>
              </div>

              <div className="bar">
                <div
                  className="bar-fill"
                  style={{ width: `${Math.min(100, avance.percent)}%`, background: color }}
                />
              </div>

              <p className="texto-menor" style={{ marginTop: 8 }}>
                <Amount cents={avance.spent} currency={avance.budget.currency} size="menor" hidden={privacy} />
                {' de '}
                <Amount cents={avance.available} currency={avance.budget.currency} size="menor" hidden={privacy} />
                {avance.carried !== 0 && (
                  <>
                    {' · '}
                    {avance.carried > 0 ? 'incluye ' : 'descontando '}
                    <Amount cents={Math.abs(avance.carried)} currency={avance.budget.currency} size="menor" hidden={privacy} />
                    {avance.carried > 0 ? ' que sobró' : t('presupuesto.queTePasaste')}
                  </>
                )}
              </p>

              {avance.overspent && (
                <p className="texto-menor" style={{ color: 'var(--rojo)', marginTop: 4 }}>{t('presupuesto.tePasastePor')}{' '}<Amount cents={-avance.left} currency={avance.budget.currency} size="menor" hidden={privacy} />
                </p>
              )}
            </button>
          </Card>
        );
      })}

      <div className="seccion">
        <Button wide variant="contorno" onClick={onNuevo}>{t('presupuesto.agregarOtroPresupuesto')}</Button>
      </div>
    </>
  );
}

function PresupuestoForm({ budget, onDone }: { budget?: Budget; onDone: () => void }) {
  const data = useData();
  const addBudget = useApp((state) => state.addBudget);
  const updateBudget = useApp((state) => state.updateBudget);
  const removeBudget = useApp((state) => state.removeBudget);
  const notify = useApp((state) => state.notify);

  const editando = budget !== undefined;
  const [categoria, setCategoria] = useState(budget?.categoryId ?? 'supermercado');
  const [limite, setLimite] = useState(budget ? formatNumber(budget.limit) : '');
  const [moneda, setMoneda] = useState<Currency>(budget?.currency ?? data.profile.mainCurrency);
  const [arrastre, setArrastre] = useState<'si' | 'no'>(budget?.rollover ? 'si' : 'no');
  const [error, setError] = useState('');

  function guardar() {
    const monto = parseAmount(limite);
    if (!monto || monto <= 0) {
      setError(t('presupuesto.escribeCuantoQuieresGastar'));
      return;
    }

    const nuevo: Budget = {
      id: budget?.id ?? newId(),
      categoryId: categoria,
      limit: monto,
      currency: moneda,
      rollover: arrastre === 'si',
    };

    if (editando) {
      updateBudget(nuevo.id, nuevo);
      notify(t('presupuesto.presupuestoActualizado'));
    } else {
      addBudget(nuevo);
      notify(t('presupuesto.presupuestoCreado'));
    }
    onDone();
  }

  function borrar() {
    if (!budget) return;
    removeBudget(budget.id);
    notify(t('presupuesto.presupuestoEliminado'));
    onDone();
  }

  return (
    <>
      <SelectField
        label={t('comun.categoria')}
        value={categoria}
        onChange={(event) => setCategoria(event.target.value)}
        hint={editando ? undefined : t('presupuesto.cadaCategoriaPuedeTener')}
      >
        {data.categories
          .filter((item) => !item.archived)
          .map((item) => (
            <option key={item.id} value={item.id}>
              {item.icon} {item.name}
            </option>
          ))}
      </SelectField>

      <Field
        label={t('presupuesto.limiteAlMes')}
        type="text"
        inputMode="decimal"
        placeholder="0.00"
        value={limite}
        error={error}
        onChange={(event) => setLimite(event.target.value)}
      />

      <SelectorMoneda value={moneda} onChange={setMoneda} />

      <p className="campo__etiqueta">{t('presupuesto.siSobraOFalta')}</p>
      <div style={{ marginBottom: 'var(--e3)' }}>
        <Segmented options={ARRASTRE} value={arrastre} onChange={setArrastre} label={t('comun.arrastre')} />
      </div>
      <p className="campo__ayuda" style={{ marginBottom: 'var(--e4)' }}>
        {arrastre === 'si'
          ? t('presupuesto.loQueNoGastes')
          : t('presupuesto.cadaMesEmpiezaCon')}
      </p>

      {editando && (
        <div style={{ marginBottom: 'var(--e4)' }}>
          <Notice tone="azul" icon="ℹ️">{t('presupuesto.cambiarElLimiteNo')}</Notice>
        </div>
      )}

      <div className="hoja__pie">
        <Button wide onClick={guardar}>
          {editando ? t('presupuesto.guardarCambios') : t('presupuesto.crearPresupuesto')}
        </Button>
        {editando && (
          <Button wide variant="peligro" className="seccion" onClick={borrar}>{t('presupuesto.eliminarPresupuesto')}</Button>
        )}
      </div>
    </>
  );
}
