/**
 * Contar el efectivo.
 *
 * El saldo del efectivo sale de lo que se apunta, y al principio nadie apuntó
 * de dónde salieron los billetes que ya andaba encima. Aquí se dice cuánto
 * hay ahora mismo y se acabó la discusión: igual que el saldo inicial que se
 * escribe al registrar una cuenta de banco, no es un ingreso ni un gasto, así
 * que no ensucia los reportes del mes.
 */

import { useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData } from '../../store/useApp';
import { useMonedasPermitidas } from '../../store/useMonedas';
import { Button, Notice } from '../../ui/primitives';
import { Field } from '../../ui/forms';
import { formatNumber, parseAmount } from '../../lib/money';
import type { Cents } from '../../lib/money';
import { cashAccount } from '../../domain/accounts';

function textoDe(cents: Cents | undefined): string {
  return cents === undefined ? '' : formatNumber(cents);
}

export function EfectivoSheet({ onDone }: { onDone: () => void }) {
  const data = useData();
  const edit = useApp((state) => state.edit);
  const notify = useApp((state) => state.notify);
  const monedas = useMonedasPermitidas();

  const efectivo = cashAccount(data);
  const [dop, setDop] = useState(textoDe(efectivo?.balances.DOP));
  const [usd, setUsd] = useState(textoDe(efectivo?.balances.USD));

  function guardar() {
    const enPesos = parseAmount(dop);
    const enDolares = parseAmount(usd);

    edit((draft) => {
      const cuenta = cashAccount(draft);
      if (!cuenta) return;
      // En blanco significa "no tengo de esta moneda", no "no lo toques"
      if (monedas.includes('DOP')) cuenta.balances.DOP = dop.trim() === '' ? 0 : (enPesos ?? 0);
      if (monedas.includes('USD')) cuenta.balances.USD = usd.trim() === '' ? 0 : (enDolares ?? 0);
      cuenta.updatedAt = new Date().toISOString();
    });

    notify(t('efectivo.contado'));
    onDone();
  }

  return (
    <>
      <div className="seccion">
        <Notice tone="azul" icon="💵">
          {t('efectivo.explicacion')}
        </Notice>
      </div>

      {monedas.includes('DOP') && (
        <Field
          label={monedas.length > 1 ? 'En pesos' : t('efectivo.cuantoHay')}
          type="text"
          inputMode="decimal"
          placeholder="0.00"
          value={dop}
          onChange={(event) => setDop(event.target.value)}
        />
      )}

      {monedas.includes('USD') && (
        <Field
          label={monedas.length > 1 ? 'En dólares' : t('efectivo.cuantoHay')}
          type="text"
          inputMode="decimal"
          placeholder="0.00"
          value={usd}
          onChange={(event) => setUsd(event.target.value)}
        />
      )}

      <div className="hoja__pie">
        <Button wide onClick={guardar}>{t('efectivo.guardar')}</Button>
      </div>
    </>
  );
}
