/**
 * Detalle de un movimiento, con la opción de corregirlo o borrarlo.
 */

import { useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData, usePrivacy } from '../../store/useApp';
import type { Transaction } from '../../domain/types';
import { Amount } from '../../ui/Amount';
import { Button, Card, Notice } from '../../ui/primitives';
import { Row } from '../../ui/Row';
import { describeTransaction } from '../../domain/describe';
import { formatRate } from '../../lib/fx';
import { parseIsoDate } from '../../lib/date';
import { MONTHS } from '../../lib/date';

export function MovimientoDetalle({
  tx,
  onEditar,
  onDone,
}: {
  tx: Transaction;
  onEditar: () => void;
  onDone: () => void;
}) {
  const data = useData();
  const privacy = usePrivacy();
  const removeTransaction = useApp((state) => state.removeTransaction);
  const notify = useApp((state) => state.notify);
  const [confirmando, setConfirmando] = useState(false);

  const { icon } = describeTransaction(tx, data);

  function borrar() {
    removeTransaction(tx.id);
    notify(t('movDetalle.movimientoEliminado'));
    onDone();
  }

  const monto = tx.kind === 'exchange' ? tx.toAmount : tx.amount;
  const moneda = tx.kind === 'exchange' ? tx.toCurrency : tx.currency;
  const esGasto = tx.kind === 'expense';

  return (
    <>
      <Card className="seccion" style={{ textAlign: 'center' }}>
        <div style={{ fontSize: 30, marginBottom: 6 }} aria-hidden="true">
          {icon}
        </div>
        <Amount
          cents={esGasto ? -monto : monto}
          currency={moneda}
          size="grande"
          tone={esGasto ? 'negativa' : tx.kind === 'income' ? 'positiva' : 'normal'}
          hidden={privacy}
        />
        <p className="texto-menor" style={{ marginTop: 4 }}>
          {fechaLarga(tx.date)}
        </p>
      </Card>

      <Card className="seccion">
        {detallesDe(tx, data).map((fila) => (
          <Row key={fila.etiqueta} title={fila.etiqueta} right={<span className="texto-menor">{fila.valor}</span>} />
        ))}
      </Card>

      {tx.fxEstimated && (
        <div className="seccion">
          <Notice tone="ambar" icon="📌">
            Este movimiento viene de la versión anterior, que no guardaba la tasa del día. La
            conversión a la otra moneda es aproximada.
          </Notice>
        </div>
      )}

      <div className="seccion">
        <Button wide variant="suave" onClick={onEditar}>
          Corregir
        </Button>

        {confirmando ? (
          <>
            <Notice tone="roja" icon="⚠️">{t('movDetalle.alBorrarloLosSaldos')}</Notice>
            <div className="seccion" style={{ display: 'flex', gap: 'var(--e3)' }}>
              <Button variant="contorno" onClick={() => setConfirmando(false)} wide>
                Cancelar
              </Button>
              <Button variant="peligro" onClick={borrar} wide>
                Sí, borrar
              </Button>
            </div>
          </>
        ) : (
          <Button wide variant="peligro" className="seccion" onClick={() => setConfirmando(true)}>
            Eliminar
          </Button>
        )}
      </div>
    </>
  );
}

function fechaLarga(iso: string): string {
  const fecha = parseIsoDate(iso);
  return `${fecha.getDate()} de ${MONTHS[fecha.getMonth()]?.toLowerCase()} de ${fecha.getFullYear()}`;
}

function detallesDe(tx: Transaction, data: ReturnType<typeof useData>) {
  const cuenta = (id: string | undefined) => {
    if (!id) return 'Efectivo';
    const encontrada = data.accounts.find((item) => item.id === id);
    return encontrada ? (encontrada.nickname ?? encontrada.bank) : t('movDetalle.cuentaEliminada');
  };

  const filas: { etiqueta: string; valor: string }[] = [];

  switch (tx.kind) {
    case 'expense': {
      const categoria = data.categories.find((item) => item.id === tx.categoryId);
      filas.push({ etiqueta: 'Categoría', valor: categoria?.name ?? t('movDetalle.sinCategoria') });
      filas.push({ etiqueta: 'Pagado con', valor: cuenta(tx.accountId) });
      break;
    }
    case 'income': {
      const fuente = data.incomeSources.find((item) => item.id === tx.sourceId);
      filas.push({ etiqueta: 'Fuente', valor: fuente?.name ?? 'Sin fuente' });
      filas.push({ etiqueta: 'Entró a', valor: cuenta(tx.accountId) });
      break;
    }
    case 'transfer': {
      filas.push({ etiqueta: 'De', valor: cuenta(tx.fromAccountId) });
      filas.push({ etiqueta: 'A', valor: cuenta(tx.toAccountId) });
      if (tx.fee) filas.push({ etiqueta: 'Comisión', valor: (tx.fee / 100).toFixed(2) });
      break;
    }
    case 'exchange': {
      filas.push({
        etiqueta: 'Entregó',
        valor: `${(tx.fromAmount / 100).toLocaleString('es-DO', { minimumFractionDigits: 2 })} ${tx.fromCurrency}`,
      });
      filas.push({
        etiqueta: 'Recibió',
        valor: `${(tx.toAmount / 100).toLocaleString('es-DO', { minimumFractionDigits: 2 })} ${tx.toCurrency}`,
      });
      filas.push({ etiqueta: 'Tasa', valor: formatRate(tx.fxRate) });
      filas.push({ etiqueta: 'De', valor: cuenta(tx.fromAccountId) });
      filas.push({ etiqueta: 'A', valor: cuenta(tx.toAccountId) });
      break;
    }
  }

  if (tx.note) filas.push({ etiqueta: 'Nota', valor: tx.note });

  return filas;
}
