/**
 * De dónde es quien acaba de instalar la app.
 *
 * Es una sugerencia, nunca una decisión: la persona elige en pantalla. Se
 * mira primero la zona horaria, que es más fiable que el idioma — muchos
 * dominicanos en Estados Unidos tienen el teléfono en español.
 */

import type { Country } from '../domain/types';

const ZONAS_RD = ['America/Santo_Domingo'];

const ZONAS_US = [
  'America/New_York',
  'America/Chicago',
  'America/Denver',
  'America/Los_Angeles',
  'America/Phoenix',
  'America/Anchorage',
  'America/Detroit',
  'America/Puerto_Rico',
  'Pacific/Honolulu',
];

export function sugerirPais(zona: string | undefined, idioma: string | undefined): Country {
  if (zona) {
    if (ZONAS_RD.includes(zona)) return 'DO';
    if (ZONAS_US.includes(zona)) return 'US';
    // Cualquier otra zona de Estados Unidos
    if (zona.startsWith('US/')) return 'US';
  }

  if (idioma) {
    const region = idioma.split('-')[1]?.toUpperCase();
    if (region === 'DO') return 'DO';
    if (region === 'US') return 'US';
  }

  // La app nació para República Dominicana: ante la duda, pesos
  return 'DO';
}

/** Lo que el teléfono dice de sí mismo, para pasárselo a sugerirPais. */
export function paisDelTelefono(): Country {
  let zona: string | undefined;
  try {
    zona = Intl.DateTimeFormat().resolvedOptions().timeZone;
  } catch {
    zona = undefined;
  }
  const idioma = typeof navigator === 'undefined' ? undefined : navigator.language;
  return sugerirPais(zona, idioma);
}
