/**
 * Acceso a los textos.
 *
 * Hoy solo hay español. Cuando haya otro idioma, se agrega su archivo con las
 * mismas claves y se elige aquí según la preferencia de la persona.
 */

import { es } from './es';
import type { TextKey } from './es';

export type { TextKey };

const textos = es;

/**
 * Devuelve el texto de una clave.
 * Acepta variables entre llaves: t('migracion.resumen', { movimientos: 12 })
 */
export function t(key: TextKey, vars?: Record<string, string | number>): string {
  const base: string = textos[key];
  if (!vars) return base;

  return base.replace(/\{(\w+)\}/g, (match, name: string) => {
    const value = vars[name];
    return value === undefined ? match : String(value);
  });
}
