/**
 * Pantalla de entrada cuando hay PIN puesto.
 *
 * Tras varios intentos fallidos hay que esperar. No es una barrera fuerte
 * (los datos siguen en el teléfono sin cifrar), pero evita que alguien
 * pruebe los diez mil PIN de cuatro cifras en un minuto.
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import { t } from '../i18n';
import { useApp } from '../store/useApp';
import { Button } from '../ui/primitives';
import { PIN_MINIMO, PIN_MAXIMO } from '../lib/pin';
import { nombreDeBiometria, pedirBiometria, tipoDeBiometria, type Biometria } from '../lib/nativo';

const INTENTOS_LIBRES = 5;
const ESPERA_POR_INTENTO = 30;

export function Bloqueo() {
  const unlock = useApp((state) => state.unlock);
  const fallos = useApp((state) => state.failedAttempts);
  const biometriaPuesta = useApp((state) => state.data.settings.biometrics);
  const [biometria, setBiometria] = useState<Biometria>('ninguna');

  const [pin, setPin] = useState('');
  const [error, setError] = useState('');
  const [espera, setEspera] = useState(0);
  const [comprobando, setComprobando] = useState(false);
  const caraPedida = useRef(false);

  // Face ID solo si la persona lo activó y el teléfono lo tiene
  useEffect(() => {
    if (!biometriaPuesta) return;
    void tipoDeBiometria().then(setBiometria);
  }, [biometriaPuesta]);

  // Cuenta atrás mientras hay que esperar
  useEffect(() => {
    if (espera <= 0) return;
    const reloj = setTimeout(() => setEspera((segundos) => segundos - 1), 1000);
    return () => clearTimeout(reloj);
  }, [espera]);

  const bloqueado = espera > 0 || comprobando;

  function teclear(numero: string) {
    if (bloqueado || pin.length >= PIN_MAXIMO) return;
    setError('');
    setPin(pin + numero);
  }

  function borrar() {
    if (bloqueado) return;
    setError('');
    setPin(pin.slice(0, -1));
  }

  const entrarConCara = useCallback(async () => {
    if (bloqueado) return;
    setComprobando(true);
    const paso = await pedirBiometria();
    setComprobando(false);
    // La biometría la comprueba el teléfono, no la app: si dice que sí, se abre
    if (paso) useApp.setState({ unlocked: true, failedAttempts: 0 });
  }, [bloqueado]);

  /*
   * Face ID se lanza solo al abrir, que es como funciona todo lo demás en el
   * teléfono. Una sola vez: si la persona lo cancela o la cara no pasa, se
   * queda el teclado y el botón para volver a intentarlo. Repetirlo la
   * dejaría atrapada en la ventanita de Apple.
   */
  useEffect(() => {
    if (caraPedida.current || biometria === 'ninguna' || espera > 0) return;
    caraPedida.current = true;
    void entrarConCara();
  }, [biometria, espera, entrarConCara]);

  async function entrar() {
    if (bloqueado || pin.length < PIN_MINIMO) return;
    setComprobando(true);
    const bien = await unlock(pin);
    setComprobando(false);

    if (bien) return;

    setPin('');
    const seguidos = fallos + 1;
    if (seguidos >= INTENTOS_LIBRES) {
      const segundos = ESPERA_POR_INTENTO * (seguidos - INTENTOS_LIBRES + 1);
      setEspera(segundos);
      setError(`Muchos intentos. Espera ${segundos} segundos.`);
    } else {
      setError(t('bloqueo.eseNoEsEl'));
    }
  }

  return (
    <div className="bloqueo">
      <div className="bloqueo__cabeza">
        <p className="bloqueo__marca">GestorRD</p>
        <p className="bloqueo__texto">
          {comprobando
            ? 'Comprobando…'
            : espera > 0
              ? `Espera ${espera} ${espera === 1 ? 'segundo' : 'segundos'}`
              : t('bloqueo.escribeTuPin')}
        </p>

        <div className="bloqueo__puntos" aria-live="polite" aria-label={`${pin.length} números escritos`}>
          {Array.from({ length: Math.max(PIN_MINIMO, pin.length) }, (_, i) => (
            <span key={i} className={`bloqueo__punto${i < pin.length ? ' bloqueo__punto--lleno' : ''}`} />
          ))}
        </div>

        <p className="bloqueo__error" role="alert">
          {error}
        </p>
      </div>

      <div className="teclado">
        {['1', '2', '3', '4', '5', '6', '7', '8', '9'].map((numero) => (
          <button
            key={numero}
            type="button"
            className="tecla"
            disabled={bloqueado}
            onClick={() => teclear(numero)}
          >
            {numero}
          </button>
        ))}
        <button type="button" className="tecla tecla--suave" disabled={bloqueado} onClick={borrar}>
          Borrar
        </button>
        <button type="button" className="tecla" disabled={bloqueado} onClick={() => teclear('0')}>
          0
        </button>
        <button
          type="button"
          className="tecla tecla--principal"
          disabled={bloqueado || pin.length < PIN_MINIMO}
          onClick={entrar}
        >
          Entrar
        </button>
      </div>

      <div className="bloqueo__pie">
        {biometria !== 'ninguna' && (
          <Button
            variant="texto"
            className="seccion"
            disabled={bloqueado}
            onClick={() => void entrarConCara()}
          >
            Entrar con {nombreDeBiometria(biometria)}
          </Button>
        )}
        <Olvido />
      </div>
    </div>
  );
}

function Olvido() {
  const resetAll = useApp((state) => state.resetAll);
  const [abierto, setAbierto] = useState(false);

  if (!abierto) {
    return (
      <Button variant="texto" small onClick={() => setAbierto(true)}>{t('bloqueo.olvideMiPin')}</Button>
    );
  }

  return (
    <div className="bloqueo__olvido">
      <p className="texto-menor">
        El PIN no se puede recuperar, porque no se guarda en ningún lado: solo queda una huella
        suya. La única salida es borrar los datos de la app y volver a empezar, o restaurarlos
        desde un respaldo tuyo.
      </p>
      <Button
        wide
        variant="peligro"
        className="seccion"
        onClick={() => {
          resetAll();
          window.location.reload();
        }}
      >{t('bloqueo.borrarLosDatosY')}</Button>
      <Button wide variant="texto" onClick={() => setAbierto(false)}>{t('bloqueo.mejorSigoIntentando')}</Button>
    </div>
  );
}
