/** Cuántos movimientos dependen de esta cuenta. */
/**
 * Qué cuenta proponer al registrar algo.
 *
 * La última que se usó, porque la gente repite: si pagaste las últimas cinco
 * cosas con la cuenta de nómina, la sexta sale de ahí. Si no hay historia,
 * la primera cuenta de banco.
 *
 * A quien acaba de instalar le toca el efectivo, que es la única cuenta que
 * trae. Eso también está bien: ya baja un saldo de verdad.
 */
export function defaultAccountId(data: AppData): string | undefined {
  const activas = data.accounts.filter((cuenta) => !cuenta.archived);
  if (activas.length === 0) return undefined;

  // Los movimientos vienen del más nuevo al más viejo
  for (const tx of data.transactions) {
    const id =
      tx.kind === 'expense' || tx.kind === 'income' ? tx.accountId : undefined;
    if (id && activas.some((cuenta) => cuenta.id === id)) return id;
  }

  return activas.find((cuenta) => cuenta.kind === 'bank')?.id ?? activas[0]?.id;
}

export function accountUsage(data: AppData, accountId: string): number {
  return data.transactions.filter((tx) => {
    if (tx.kind === 'expense' || tx.kind === 'income') return tx.accountId === accountId;
    return tx.fromAccountId === accountId || tx.toAccountId === accountId;
  }).length;
}

/**
 * Una cuenta solo se puede borrar de verdad si nada la usa.
 * Si tiene movimientos, borrarla dejaría el historial mintiendo.
 */
export function canDelete(data: AppData, accountId: string): boolean {
  return accountUsage(data, accountId) === 0;
}

/** Disponible de una tarjeta en una moneda: el límite menos lo usado. */
export function cardAvailable(account: Account, currency: Currency): Cents | null {
  const limite = account.credit?.limits[currency];
  if (limite === undefined) return null;
  const usado = Math.abs(Math.min(0, account.balances[currency] ?? 0));
  return Math.max(0, limite - usado);
}

/** Cuánto se debe de una tarjeta en una moneda, como número positivo. */
export function cardUsed(account: Account, currency: Currency): Cents {
  return Math.abs(Math.min(0, account.balances[currency] ?? 0));
}

/** Porcentaje del límite ya usado, de 0 a 100. */
export function cardUsagePercent(account: Account, currency: Currency): number | null {
  const limite = account.credit?.limits[currency];
  if (limite === undefined || limite <= 0) return null;
  return Math.round((cardUsed(account, currency) / limite) * 100);
}

/** Monedas que esta cuenta maneja de verdad. */
export function accountCurrencies(account: Account): Currency[] {
  const monedas = new Set<Currency>();
  for (const moneda of Object.keys(account.balances) as Currency[]) monedas.add(moneda);
  for (const moneda of Object.keys(account.credit?.limits ?? {}) as Currency[]) monedas.add(moneda);
  return [...monedas];
}

export interface AccountIssue {
  field: string;
  message: string;
}

/** Revisa una cuenta antes de guardarla. */
export function validateAccount(account: Account): AccountIssue[] {
  const issues: AccountIssue[] = [];

  if (!account.bank.trim()) {
    issues.push({ field: 'bank', message: 'Escribe el nombre del banco.' });
  }

  if (account.last4 && !/^\d{4}$/.test(account.last4)) {
    issues.push({ field: 'last4', message: 'Son los últimos cuatro dígitos, nada más.' });
  }

  if (account.kind === 'credit') {
    const limites = account.credit?.limits ?? {};
    const algunLimite = (Object.values(limites) as number[]).some((valor) => valor > 0);
    if (!algunLimite) {
      issues.push({ field: 'limits', message: 'Una tarjeta necesita al menos un límite.' });
    }

    for (const moneda of Object.keys(limites) as Currency[]) {
      const limite = limites[moneda] ?? 0;
      const usado = cardUsed(account, moneda);
      if (usado > limite) {
        issues.push({
          field: `used-${moneda}`,
          message: 'Lo usado no puede ser mayor que el límite.',
        });
      }
    }

    const corte = account.credit?.statementDay;
    const pago = account.credit?.dueDay;
    for (const [campo, dia] of [
      ['statementDay', corte],
      ['dueDay', pago],
    ] as const) {
      if (dia !== undefined && (dia < 1 || dia > 31)) {
        issues.push({ field: campo, message: 'El día va del 1 al 31.' });
      }
    }
  }

  return issues;
}

/* --- El efectivo ------------------------------------------------------------ */

export const NOMBRE_EFECTIVO = 'Efectivo';

/** La cuenta de efectivo, si ya existe. Nunca hay más de una. */
export function cashAccount(data: AppData): Account | undefined {
  return data.accounts.find((cuenta) => cuenta.kind === 'cash');
}

/** Una cuenta de efectivo nueva, en cero. */
export function createCashAccount(country: Country): Account {
  return {
    id: newId(),
    kind: 'cash',
    bank: NOMBRE_EFECTIVO,
    country,
    balances: {},
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
}

/**
 * Se asegura de que haya efectivo, y devuelve si hubo que crearlo.
 *
 * Corre al cargar los datos, no solo al instalar: quien ya tenía la app
 * también necesita la cuenta, y sin esto sus gastos en billetes seguirían
 * sin bajar nada. Arranca en cero a propósito — lo que se apuntó antes se
 * queda como está, porque nadie apuntó de dónde salió aquel dinero.
 */
export function ensureCashAccount(data: AppData): boolean {
  if (cashAccount(data)) return false;
  data.accounts.push(createCashAccount(data.profile.country));
  return true;
}

/**
 * Un teléfono donde todavía no hay nada de nadie.
 *
 * El efectivo recién creado no cuenta: lo pone la app, no la persona. Sin
 * esta distinción, a quien estrena teléfono no se le ofrecería bajar su copia
 * de la nube, porque su instalación vacía ya trae una cuenta.
 */
export function isEmptyData(data: AppData): boolean {
  if (data.transactions.length > 0) return false;
  return data.accounts.every(
    (cuenta) => cuenta.kind === 'cash' && Object.values(cuenta.balances).every((saldo) => !saldo),
  );
}

/** El efectivo no se edita ni se borra como las demás. */
export function isCash(account: Account): boolean {
  return account.kind === 'cash';
}
