/**
 * Comparar lo que hay en el teléfono con lo que hay en la nube.
 *
 * Esto no es sincronización: es una copia. Y en una copia la regla más
 * importante es no pisar datos buenos con datos vacíos. Por eso nada se sube
 * ni se baja solo; aquí únicamente se describe la situación para que la
 * persona decida con las dos cifras delante.
 */

import type { AppData } from './types';
import { isEmptyData } from './accounts';

export interface CloudCopy {
  updatedAt: string;
  count: number;
  device: string | null;
}

export type CloudState =
  | 'sin-copia'
  | 'al-dia'
  | 'telefono-adelante'
  | 'nube-adelante'
  | 'telefono-vacio'
  | 'distintas';

export interface CloudComparison {
  state: CloudState;
  localCount: number;
  cloudCount: number;
  /** Lo que hay que decirle a la persona, en una frase. */
  message: string;
  /** true cuando bajar la copia borraría cosas que solo están en el teléfono. */
  pullIsRisky: boolean;
  /** true cuando subir borraría cosas que solo están en la nube. */
  pushIsRisky: boolean;
}

export function localCount(data: AppData): number {
  return data.transactions.length;
}

export function compareWithCloud(data: AppData, copia: CloudCopy | null): CloudComparison {
  const local = localCount(data);
  const guardada = data.settings.lastBackup;

  if (!copia) {
    return {
      state: 'sin-copia',
      localCount: local,
      cloudCount: 0,
      message:
        local === 0
          ? 'Todavía no hay nada que guardar.'
          : 'No hay copia en la nube. Sube una para no depender solo de este teléfono.',
      pullIsRisky: false,
      pushIsRisky: false,
    };
  }

  if (local === 0 && copia.count > 0) {
    return {
      state: 'telefono-vacio',
      localCount: 0,
      cloudCount: copia.count,
      message: `En la nube hay una copia con ${copia.count} movimientos y este teléfono está vacío.`,
      pullIsRisky: false,
      // Subir ahora borraría la copia buena y dejaría la nube vacía
      pushIsRisky: true,
    };
  }

  // Esta copia la subió este mismo teléfono y nada cambió desde entonces
  if (guardada && guardada.at === copia.updatedAt && guardada.count === local) {
    return {
      state: 'al-dia',
      localCount: local,
      cloudCount: copia.count,
      message: 'La copia está al día.',
      pullIsRisky: false,
      pushIsRisky: false,
    };
  }

  if (local > copia.count) {
    return {
      state: 'telefono-adelante',
      localCount: local,
      cloudCount: copia.count,
      message: `Este teléfono tiene ${local - copia.count} movimientos más que la copia.`,
      pullIsRisky: true,
      pushIsRisky: false,
    };
  }

  if (copia.count > local) {
    return {
      state: 'nube-adelante',
      localCount: local,
      cloudCount: copia.count,
      message: `La copia tiene ${copia.count - local} movimientos más que este teléfono.`,
      pullIsRisky: false,
      pushIsRisky: true,
    };
  }

  return {
    state: 'distintas',
    localCount: local,
    cloudCount: copia.count,
    message: 'Los dos tienen la misma cantidad de movimientos, pero no son la misma copia.',
    pullIsRisky: true,
    pushIsRisky: true,
  };
}

/**
 * Teléfono recién instalado y copia con datos: es el caso de cambiar de
 * equipo, y es el único donde ofrecer bajar sin que lo pidan tiene sentido.
 */
export function shouldOfferRestore(data: AppData, copia: CloudCopy | null): boolean {
  if (!copia || copia.count === 0) return false;
  return isEmptyData(data);
}

/** Días desde la última copia, o null si nunca se hizo una. */
export function daysSinceBackup(data: AppData, hoy = Date.now()): number | null {
  const guardada = data.settings.lastBackup;
  if (!guardada) return null;
  const fecha = new Date(guardada.at).getTime();
  if (Number.isNaN(fecha)) return null;
  return Math.floor((hoy - fecha) / 86400000);
}

/** Tamaño aproximado de la copia, para avisar antes de subir con datos móviles. */
export function backupSizeMb(data: AppData): number {
  try {
    return Math.round((JSON.stringify(data).length / 1048576) * 10) / 10;
  } catch {
    return 0;
  }
}
