import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';

// Las fuentes van empaquetadas en la app: tiene que verse igual sin internet
import '@fontsource/ibm-plex-sans/latin-400.css';
import '@fontsource/ibm-plex-sans/latin-500.css';
import '@fontsource/ibm-plex-sans/latin-600.css';
import '@fontsource/ibm-plex-mono/latin-400.css';
import '@fontsource/ibm-plex-mono/latin-500.css';
import '@fontsource/ibm-plex-mono/latin-600.css';

import './ui/tokens.css';
import './ui/base.css';
import './ui/components.css';

import App from './App';
import { registrarServicio } from './lib/servicio';

/*
 * Atajos para revisar la app en el navegador, solo en desarrollo.
 * Vite borra este bloque entero al compilar para producción, así que no hay
 * forma de encender premium en la app que se instala.
 */
if (import.meta.env.DEV) {
  void import('./store/usePremium').then(({ usePremium }) => {
    (globalThis as { gestorrd?: unknown }).gestorrd = {
      premium: (activo = true) => {
        usePremium.setState({ estado: { activo } });
        return activo ? 'Premium encendido para esta revisión' : 'Premium apagado';
      },
    };
    console.info('Para revisar lo de pago: gestorrd.premium()');
  });
}

registrarServicio();

const container = document.getElementById('root');
if (!container) throw new Error('Falta el contenedor #root en index.html');

createRoot(container).render(
  <StrictMode>
    <App />
  </StrictMode>,
);
