/**
 * La cuenta.
 *
 * La app es local primero: sin cuenta funciona igual. Entrar sirve para
 * guardar una copia en la nube, recuperar el PIN si se olvida y, más
 * adelante, la suscripción.
 *
 * Nada de aquí bloquea la app: si no hay conexión o falta la configuración,
 * el estado queda en 'sin-config' o la acción devuelve un error que se
 * muestra, y los datos del teléfono siguen intactos.
 */

import { create } from 'zustand';
import type { Session, SupabaseClient } from '@supabase/supabase-js';
import {
  cuentaConfigurada,
  getSupabase,
  haySesionGuardada,
  vieneDeProveedor,
} from '../lib/supabase';
import { codigoDelEnlace, describeDevice, explainAuthError, nombreDeLaSesion } from '../domain/auth';
import { useApp } from './useApp';
import {
  abrirNavegador,
  alVolverDeLogin,
  cerrarNavegador,
  enElTelefono,
  VUELTA_DE_LOGIN,
} from '../lib/nativo';
import type { AppData } from '../domain/types';
import type { CloudCopy } from '../domain/cloud';
import { localCount } from '../domain/cloud';

export type AuthState = 'cargando' | 'sin-config' | 'fuera' | 'dentro';

export interface AuthStore {
  estado: AuthState;
  session: Session | null;
  email: string | null;
  init: () => void;
  /** Entra con Apple. Devuelve el error o null. */
  signInWith: (provider: 'apple') => Promise<string | null>;
  signOut: () => Promise<void>;

  /** Lo que hay guardado en la nube, o null si no hay nada. */
  cloud: CloudCopy | null;
  cloudEstado: 'desconocido' | 'cargando' | 'listo' | 'error';
  /** Lee la ficha de la copia. Devuelve el error o null. */
  fetchCloud: () => Promise<string | null>;
  /** Sube los datos del teléfono. Devuelve el error o null. */
  pushBackup: (data: AppData) => Promise<string | null>;
  /** Baja la copia. Devuelve los datos, o un error como texto. */
  pullBackup: () => Promise<AppData | string>;
}

let escuchando = false;
let suscrito = false;

export const useAuth = create<AuthStore>((set, get) => ({
  estado: 'cargando',
  session: null,
  email: null,
  cloud: null,
  cloudEstado: 'desconocido',

  init: () => {
    if (!cuentaConfigurada()) {
      set({ estado: 'sin-config' });
      return;
    }
    if (escuchando) return;

    // El enlace de vuelta puede llegar en cualquier momento, incluso antes
    // de que nadie abra la pantalla de cuenta
    if (enElTelefono()) void escucharLaVuelta(set);

    // Sin sesión guardada no hay nada que restaurar: no se carga la librería
    if (!haySesionGuardada() && !vieneDeProveedor()) {
      set({ estado: 'fuera' });
      return;
    }

    escuchando = true;
    void conectar(set);
  },

  signInWith: async (provider) => {
    const supabase = await conectar(set);
    if (!supabase) return 'La cuenta no está disponible en esta versión.';

    /*
     * En el teléfono no se puede redirigir y ya: la página de Apple tiene que
     * abrirse en el navegador del sistema y volver por un enlace propio de la
     * app. Por eso se pide la dirección sin navegar y se abre a mano.
     */
    if (enElTelefono()) {
      const { data, error } = await supabase.auth.signInWithOAuth({
        provider,
        options: { redirectTo: VUELTA_DE_LOGIN, skipBrowserRedirect: true },
      });
      if (error) return explainAuthError(error.message);
      if (!data.url) return 'No se pudo abrir la página para entrar.';

      const abierto = await abrirNavegador(data.url);
      return abierto ? null : 'No se pudo abrir el navegador del teléfono.';
    }

    const { error } = await supabase.auth.signInWithOAuth({
      provider,
      options: { redirectTo: window.location.origin },
    });
    return error ? explainAuthError(error.message) : null;
  },

  fetchCloud: async () => {
    const supabase = await getSupabase();
    const sesion = get().session;
    if (!supabase || !sesion) return 'Entra a tu cuenta primero.';

    set({ cloudEstado: 'cargando' });
    try {
      const { data, error } = await supabase
        .from('app_backups')
        .select('updated_at, records_count, device')
        .eq('user_id', sesion.user.id)
        .maybeSingle();

      if (error) {
        set({ cloudEstado: 'error' });
        return explainAuthError(error.message);
      }

      set({
        cloudEstado: 'listo',
        cloud: data
          ? {
              updatedAt: String(data.updated_at),
              count: Number(data.records_count ?? 0),
              device: (data.device as string | null) ?? null,
            }
          : null,
      });
      return null;
    } catch (fallo) {
      set({ cloudEstado: 'error' });
      return explainAuthError(fallo instanceof Error ? fallo.message : 'No se pudo consultar.');
    }
  },

  pushBackup: async (datos) => {
    const supabase = await getSupabase();
    const sesion = get().session;
    if (!supabase || !sesion) return 'Entra a tu cuenta primero.';

    const ahora = new Date().toISOString();
    try {
      const { error } = await supabase.from('app_backups').upsert(
        {
          user_id: sesion.user.id,
          email: sesion.user.email ?? null,
          data: datos,
          records_count: localCount(datos),
          device: describeDevice(typeof navigator === 'undefined' ? '' : navigator.userAgent),
          updated_at: ahora,
        },
        { onConflict: 'user_id' },
      );

      if (error) return explainAuthError(error.message);

      set({
        cloud: {
          updatedAt: ahora,
          count: localCount(datos),
          device: describeDevice(typeof navigator === 'undefined' ? '' : navigator.userAgent),
        },
        cloudEstado: 'listo',
      });
      return null;
    } catch (fallo) {
      return explainAuthError(fallo instanceof Error ? fallo.message : 'No se pudo subir.');
    }
  },

  pullBackup: async () => {
    const supabase = await getSupabase();
    const sesion = get().session;
    if (!supabase || !sesion) return 'Entra a tu cuenta primero.';

    try {
      const { data, error } = await supabase
        .from('app_backups')
        .select('data')
        .eq('user_id', sesion.user.id)
        .maybeSingle();

      if (error) return explainAuthError(error.message);
      if (!data?.data) return 'No hay copia en la nube.';
      return data.data as AppData;
    } catch (fallo) {
      return explainAuthError(fallo instanceof Error ? fallo.message : 'No se pudo bajar.');
    }
  },

  signOut: async () => {
    const supabase = await getSupabase();
    if (!supabase) return;
    await supabase.auth.signOut();
    // Salir de la cuenta no borra nada del teléfono
    set({ estado: 'fuera', session: null, email: null, cloud: null, cloudEstado: 'desconocido' });
  },
}));

type Set = (parcial: Partial<AuthStore>) => void;

/**
 * Espera el enlace con el que el teléfono devuelve el control a la app
 * después de entrar con Apple o Google, y canjea el código por la sesión.
 */
async function escucharLaVuelta(set: Set): Promise<void> {
  await alVolverDeLogin((url) => {
    void (async () => {
      const codigo = codigoDelEnlace(url);
      if (!codigo) {
        // Volvió sin código: canceló, o Apple mandó un error. No hay nada
        // que canjear y tampoco nada que reportar.
        set({ estado: 'fuera' });
        await cerrarNavegador();
        return;
      }

      const supabase = await conectar(set);
      if (!supabase) return;
      try {
        const { error } = await supabase.auth.exchangeCodeForSession(codigo);
        if (error) {
          console.warn('[GestorRD] No se pudo canjear el código:', error.message);
          set({ estado: 'fuera' });
        }
      } catch (fallo) {
        console.warn('[GestorRD] Falló el canje del código:', fallo);
        set({ estado: 'fuera' });
      } finally {
        await cerrarNavegador();
      }
    })();
  });
}

/**
 * Carga la librería si todavía no está, restaura la sesión y se queda
 * escuchando los cambios. Llamarla dos veces no hace daño.
 */
async function conectar(set: Set): Promise<SupabaseClient | null> {
  const supabase = await getSupabase();
  if (!supabase) {
    set({ estado: 'sin-config' });
    return null;
  }

  if (!suscrito) {
    suscrito = true;
    supabase.auth.onAuthStateChange((_evento, sesion) => {
      aplicarSesion(set, sesion);
      if (sesion) void guardarPerfil(sesion);
    });

    try {
      const { data } = await supabase.auth.getSession();
      aplicarSesion(set, data.session);
    } catch {
      set({ estado: 'fuera' });
    }
  }

  return supabase;
}

function aplicarSesion(set: Set, sesion: Session | null): void {
  set({
    session: sesion,
    email: sesion?.user.email ?? null,
    estado: sesion ? 'dentro' : 'fuera',
  });

  if (sesion) adoptarNombre(sesion);
}

/**
 * Se queda con el nombre del proveedor solo si aquí no hay ninguno.
 *
 * Quien ya escribió el suyo en Ajustes manda: nadie quiere abrir la app y
 * encontrarse llamado como en el documento de identidad.
 */
function adoptarNombre(sesion: Session): void {
  const estado = useApp.getState();
  if (estado.data.profile.name) return;

  const nombre = nombreDeLaSesion(sesion.user.user_metadata);
  if (nombre) estado.setName(nombre);
}

/** Deja constancia de quién entró y desde dónde. Si falla, no pasa nada. */
async function guardarPerfil(sesion: Session): Promise<void> {
  const supabase = await getSupabase();
  if (!supabase) return;

  const agente = typeof navigator === 'undefined' ? '' : navigator.userAgent;

  try {
    await supabase.from('profiles').upsert(
      {
        id: sesion.user.id,
        email: sesion.user.email ?? null,
        last_login_at: new Date().toISOString(),
        app_version: '3.0.0',
        user_agent: describeDevice(agente),
      },
      { onConflict: 'id' },
    );
  } catch {
    // El perfil es para estadística: si no se guarda, la app sigue igual
  }
}
