/**
 * Movimientos: la cinta completa, mes por mes, con filtros y búsqueda.
 */

import { useMemo, useState } from 'react';
import { useData, usePrivacy } from '../store/useApp';
import { TopBar } from '../app/TopBar';
import { Amount } from '../ui/Amount';
import { Empty } from '../ui/primitives';
import { Segmented } from '../ui/forms';
import { Icon } from '../ui/Icon';
import { TapeDay } from '../ui/Row';
import { TransactionRow } from '../ui/TransactionRow';
import { signedAmount } from '../domain/describe';
import { t } from '../i18n';
import { currentYearMonth, monthName, relativeDate, shiftMonth, yearOf } from '../lib/date';
import {
  groupByDay,
  matchesFilter,
  monthTotals,
  searchTransactions,
  transactionsOfMonth,
} from '../domain/compute';
import type { TransactionFilter } from '../domain/compute';
import type { Transaction } from '../domain/types';
import { MovimientosSheet } from './movimientos/MovimientosSheet';
import type { MovimientoVista } from './movimientos/MovimientosSheet';

const FILTROS = [
  { value: 'todo' as const, label: t('movimientos.todo') },
  { value: 'gastos' as const, label: t('movimientos.gastos') },
  { value: 'ingresos' as const, label: t('movimientos.ingresos') },
];

export function Movimientos() {
  const data = useData();
  const privacy = usePrivacy();

  const [mes, setMes] = useState(currentYearMonth());
  const [filtro, setFiltro] = useState<TransactionFilter>('todo');
  const [busqueda, setBusqueda] = useState('');
  const [vista, setVista] = useState<MovimientoVista>({ modo: 'cerrada' });

  const buscando = busqueda.trim().length >= 2;

  const visibles = useMemo<Transaction[]>(() => {
    const base = buscando ? searchTransactions(data, busqueda) : transactionsOfMonth(data, mes);
    return base.filter((tx) => matchesFilter(tx, filtro));
  }, [data, mes, filtro, busqueda, buscando]);

  const dias = useMemo(() => groupByDay(visibles), [visibles]);
  const totales = monthTotals(data, mes, data.profile.mainCurrency);
  const principal = data.profile.mainCurrency;

  return (
    <>
      <TopBar title={t('movimientos.titulo')} />

      <main className="contenido">
        <div className="buscador">
          <Icon name="buscar" size={18} />
          <input
            type="search"
            className="buscador__campo"
            placeholder={t('movPant.buscarPorNotaCategoria')}
            value={busqueda}
            onChange={(event) => setBusqueda(event.target.value)}
            aria-label={t('movPant.buscarMovimientos')}
          />
          {busqueda && (
            <button type="button" onClick={() => setBusqueda('')} aria-label={t('movPant.borrarLaBusqueda')}>
              ✕
            </button>
          )}
        </div>

        {!buscando && (
          <div className="mes-nav">
            <button
              type="button"
              className="barra-sup__accion"
              onClick={() => setMes(shiftMonth(mes, -1))}
              aria-label={t('movPant.mesAnterior')}
            >
              <Icon name="flechaIzq" size={20} />
            </button>
            <span className="etiqueta">
              {monthName(mes)} {yearOf(mes)}
            </span>
            <button
              type="button"
              className="barra-sup__accion"
              onClick={() => setMes(shiftMonth(mes, 1))}
              aria-label={t('movPant.mesSiguiente')}
            >
              <Icon name="flechaDer" size={20} />
            </button>
          </div>
        )}

        <Segmented options={FILTROS} value={filtro as 'todo'} onChange={(valor) => setFiltro(valor)} label="Filtrar" />

        {!buscando && (
          <div className={t('movPant.mesSeccion')}>
            <div className="mes__caja">
              <p className="mes__etiqueta">{t('inicio.entro')}</p>
              <Amount
                cents={totales.income}
                currency={principal}
                size="titulo"
                tone="positiva"
                hidden={privacy}
                compact
              />
            </div>
            <div className="mes__caja">
              <p className="mes__etiqueta">{t('inicio.salio')}</p>
              <Amount
                cents={totales.expense}
                currency={principal}
                size="titulo"
                tone="negativa"
                hidden={privacy}
                compact
              />
            </div>
          </div>
        )}

        {buscando && (
          <p className={t('movPant.textoMenorSeccion')}>
            {visibles.length === 0
              ? t('movPant.nadaCoincideConLo')
              : `${visibles.length} ${visibles.length === 1 ? 'resultado' : 'resultados'}`}
          </p>
        )}

        <section className="seccion">
          {dias.length === 0 ? (
            buscando ? null : (
              <Empty
                mark="🧾"
                title={`Sin movimientos en ${monthName(mes).toLowerCase()}`}
                text={t('movPant.cambiaDeMesCon')}
              />
            )
          ) : (
            dias.map((dia) => (
              <div key={dia.date}>
                <TapeDay
                  label={relativeDate(dia.date)}
                  total={
                    <Amount
                      cents={dia.items.reduce((total, tx) => total + signedAmount(tx, principal), 0)}
                      currency={principal}
                      size="menor"
                      tone="apagada"
                      hidden={privacy}
                      sign
                    />
                  }
                />
                {dia.items.map((tx) => (
                  <TransactionRow
                    key={tx.id}
                    tx={tx}
                    data={data}
                    privacy={privacy}
                    onClick={() => setVista({ modo: 'detalle', id: tx.id })}
                  />
                ))}
              </div>
            ))
          )}
        </section>
      </main>

      <MovimientosSheet
        vista={vista}
        onCerrar={() => setVista({ modo: 'cerrada' })}
        onCambiarVista={setVista}
      />
    </>
  );
}
