/**
 * Deudas: préstamos, hipotecas, lo que le debes a alguien.
 *
 * Las tarjetas de crédito no entran aquí: viven en Cuentas, porque su
 * saldo ya es su deuda.
 */

import { useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData, usePrivacy } from '../../store/useApp';
import type { Debt, DebtKind } from '../../domain/types';
import type { Currency } from '../../lib/money';
import { Sheet } from '../../ui/overlays';
import { Amount } from '../../ui/Amount';
import { Button, Card, Empty, Notice } from '../../ui/primitives';
import { Field, SelectField } from '../../ui/forms';
import { SelectorMoneda } from '../../ui/SelectorMoneda';
import { Row } from '../../ui/Row';
import {
  DEBT_ICONS,
  DEBT_LABELS,
  debtProgress,
  monthlyInterest,
  payoffPlan,
  savingFromExtra,
  validateDebt,
} from '../../domain/debts';
import { formatNumber, parseAmount } from '../../lib/money';
import { monthName } from '../../lib/date';
import { plural } from '../../lib/text';
import { newId } from '../../lib/id';

const TIPOS: DebtKind[] = ['personal', 'vehiculo', 'hipoteca', 'estudiantil', 'familiar', 'otro'];

type Vista = { modo: 'lista' } | { modo: 'detalle'; id: string } | { modo: 'forma'; id?: string };

export function DeudasSheet({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [vista, setVista] = useState<Vista>({ modo: 'lista' });
  const data = useData();

  const deuda = vista.modo === 'lista' ? undefined : data.debts.find((item) => item.id === vista.id);

  const titulo =
    vista.modo === 'lista'
      ? 'Deudas'
      : vista.modo === 'detalle'
        ? (deuda?.name ?? 'Deuda')
        : deuda
          ? t('deudas.editarDeuda')
          : 'Nueva deuda';

  return (
    <Sheet
      open={open}
      title={titulo}
      subtitle={vista.modo === 'lista' ? t('deudas.prestamosYDineroQue') : undefined}
      onClose={() => {
        setVista({ modo: 'lista' });
        onClose();
      }}
      onBack={vista.modo === 'lista' ? undefined : () => setVista({ modo: 'lista' })}
    >
      {vista.modo === 'lista' && (
        <ListaDeudas
          onNueva={() => setVista({ modo: 'forma' })}
          onAbrir={(id) => setVista({ modo: 'detalle', id })}
        />
      )}

      {vista.modo === 'detalle' && deuda && (
        <DetalleDeuda
          debt={deuda}
          onEditar={() => setVista({ modo: 'forma', id: deuda.id })}
          onVolver={() => setVista({ modo: 'lista' })}
        />
      )}

      {vista.modo === 'forma' && (
        <DeudaForm debt={deuda} onDone={() => setVista({ modo: 'lista' })} />
      )}
    </Sheet>
  );
}

function ListaDeudas({
  onNueva,
  onAbrir,
}: {
  onNueva: () => void;
  onAbrir: (id: string) => void;
}) {
  const data = useData();
  const privacy = usePrivacy();
  const activas = data.debts.filter((item) => !item.archived);

  if (activas.length === 0) {
    return (
      <Empty
        mark="📉"
        title={t('deudas.sinDeudasRegistradas')}
        text={t('deudas.siTienesUnPrestamo')}
        action={<Button small onClick={onNueva}>{t('deudas.registrarUnaDeuda')}</Button>}
      />
    );
  }

  return (
    <>
      {activas.map((deuda) => {
        const avance = debtProgress(deuda);

        return (
          <Card key={deuda.id} className="seccion">
            <button type="button" style={{ width: '100%', textAlign: 'left' }} onClick={() => onAbrir(deuda.id)}>
              <div className="fila-entre" style={{ marginBottom: 8 }}>
                <span className="fila__titulo">
                  {DEBT_ICONS[deuda.kind]} {deuda.name}
                </span>
                <Amount cents={avance.left} currency={deuda.currency} size="normal" hidden={privacy} />
              </div>

              <div className="bar">
                <div
                  className="bar-fill"
                  style={{ width: `${avance.percent}%`, background: 'var(--verde)' }}
                />
              </div>

              <p className="texto-menor" style={{ marginTop: 8 }}>
                {avance.done ? (
                  t('deudas.pagadaCompleta')
                ) : (
                  <>
                    Pagado el {avance.percent}%
                    {deuda.dueDay !== undefined && ` · vence el ${deuda.dueDay} de cada mes`}
                  </>
                )}
              </p>
            </button>
          </Card>
        );
      })}

      <div className="seccion">
        <Button wide variant="contorno" onClick={onNueva}>{t('deudas.registrarOtraDeuda')}</Button>
      </div>
    </>
  );
}

function DetalleDeuda({
  debt,
  onEditar,
  onVolver,
}: {
  debt: Debt;
  onEditar: () => void;
  onVolver: () => void;
}) {
  const data = useData();
  const privacy = usePrivacy();
  const payDebt = useApp((state) => state.payDebt);
  const notify = useApp((state) => state.notify);

  const [monto, setMonto] = useState(debt.monthlyPayment ? formatNumber(debt.monthlyPayment) : '');
  const [cuenta, setCuenta] = useState('');
  const [error, setError] = useState('');

  const avance = debtProgress(debt);
  const interes = monthlyInterest(debt);
  const cuota = debt.monthlyPayment ?? 0;
  const plan = cuota > 0 ? payoffPlan(debt, cuota) : null;
  const extra = cuota > 0 ? savingFromExtra(debt, cuota, Math.round(cuota * 0.2)) : null;
  const cuentas = data.accounts.filter((item) => !item.archived && item.kind !== 'credit');

  function registrar() {
    const cantidad = parseAmount(monto);
    if (!cantidad || cantidad <= 0) {
      setError(t('deudas.escribeCuantoVasA'));
      return;
    }
    payDebt(debt.id, cantidad, cuenta || undefined);
    notify(`Pago de ${debt.name} registrado`);
    onVolver();
  }

  return (
    <>
      <Card className="seccion">
        <div className="fila-entre">
          <span className="texto-menor">{t('deudas.faltaPorPagar')}</span>
          <Amount cents={avance.left} currency={debt.currency} size="grande" hidden={privacy} />
        </div>
        <div className="bar" style={{ marginTop: 'var(--e3)' }}>
          <div className="bar-fill" style={{ width: `${avance.percent}%`, background: 'var(--verde)' }} />
        </div>
        <p className="texto-menor" style={{ marginTop: 8 }}>{t('deudas.yaPagaste')}{' '}<Amount cents={avance.paid} currency={debt.currency} size="menor" hidden={privacy} />
          {' de '}
          <Amount cents={debt.original} currency={debt.currency} size="menor" hidden={privacy} />
        </p>
      </Card>

      {interes > 0 && (
        <Card className="seccion" title={t('deudas.loQueCuestaEsperar')}>
          <p className="texto-menor">
            Al {debt.apr}% anual, este mes se le suman{' '}
            <Amount cents={interes} currency={debt.currency} size="menor" hidden={privacy} />
            {t('deudas.deInteresSiNo')}
          </p>
        </Card>
      )}

      {plan && (
        <Card className="seccion" title={t('deudas.siSiguesPagandoLa')}>
          <Row
            title={`${plan.months} ${plural(plan.months, 'cuota', 'cuotas')}`}
            detail={`Terminas en ${monthName(plan.endsOn).toLowerCase()} de ${plan.endsOn.slice(0, 4)}`}
            wrapDetail
          />
          <Row
            title={t('deudas.interesQueVasA')}
            detail={t('deudas.deAquiAlFinal')}
            wrapDetail
            right={
              <Amount cents={plan.totalInterest} currency={debt.currency} size="normal" tone="negativa" hidden={privacy} />
            }
          />
          {extra && extra.months > 0 && (
            <div style={{ marginTop: 'var(--e3)' }}>
              <Notice tone="verde" icon="💡">
                Si le echas un 20% más cada mes, sales {extra.months}{' '}
                {plural(extra.months, 'mes', 'meses')} antes y te ahorras{' '}
                <Amount cents={extra.interest} currency={debt.currency} size="menor" hidden={privacy} /> de
                interés.
              </Notice>
            </div>
          )}
        </Card>
      )}

      {!avance.done && (
        <Card className="seccion" title={t('deudas.registrarUnPago')}>
          <Field
            label="Monto"
            type="text"
            inputMode="decimal"
            placeholder="0.00"
            value={monto}
            error={error}
            onChange={(event) => setMonto(event.target.value)}
          />
          <SelectField
            label="Sale de"
            value={cuenta}
            onChange={(event) => setCuenta(event.target.value)}
            hint={t('deudas.elPagoQuedaComo')}
          >
            <option value="">{t('deudas.efectivoSinAfectarCuentas')}</option>
            {cuentas.map((item) => (
              <option key={item.id} value={item.id}>
                {item.nickname ?? item.bank}
              </option>
            ))}
          </SelectField>
          <Button wide onClick={registrar}>{t('deudas.registrarPago')}</Button>
          <p className="campo__ayuda" style={{ marginTop: 'var(--e3)' }}>{t('deudas.tuPatrimonioNoBaja')}</p>
        </Card>
      )}

      <div className="hoja__pie">
        <Button wide variant="contorno" onClick={onEditar}>{t('deudas.editarLaDeuda')}</Button>
      </div>
    </>
  );
}

function DeudaForm({ debt, onDone }: { debt?: Debt; onDone: () => void }) {
  const addDebt = useApp((state) => state.addDebt);
  const updateDebt = useApp((state) => state.updateDebt);
  const removeDebt = useApp((state) => state.removeDebt);
  const notify = useApp((state) => state.notify);
  const data = useData();

  const editando = debt !== undefined;
  const [nombre, setNombre] = useState(debt?.name ?? '');
  const [tipo, setTipo] = useState<DebtKind>(debt?.kind ?? 'personal');
  const [moneda, setMoneda] = useState<Currency>(debt?.currency ?? data.profile.mainCurrency);
  const [original, setOriginal] = useState(debt ? formatNumber(debt.original) : '');
  const [balance, setBalance] = useState(debt ? formatNumber(debt.balance) : '');
  const [tasa, setTasa] = useState(debt?.apr !== undefined ? String(debt.apr) : '');
  const [cuota, setCuota] = useState(debt?.monthlyPayment ? formatNumber(debt.monthlyPayment) : '');
  const [dia, setDia] = useState(debt?.dueDay !== undefined ? String(debt.dueDay) : '');
  const [errores, setErrores] = useState<Record<string, string>>({});

  function guardar() {
    const ahora = new Date().toISOString();
    const candidata: Debt = {
      id: debt?.id ?? newId(),
      name: nombre.trim(),
      kind: tipo,
      currency: moneda,
      balance: parseAmount(balance) ?? 0,
      original: parseAmount(original) ?? 0,
      createdAt: debt?.createdAt ?? ahora,
      updatedAt: ahora,
    };
    if (tasa.trim()) candidata.apr = Number(tasa);
    if (parseAmount(cuota)) candidata.monthlyPayment = parseAmount(cuota) ?? 0;
    if (dia.trim()) candidata.dueDay = Number(dia);

    const problemas = validateDebt(candidata);
    if (problemas.length > 0) {
      const mapa: Record<string, string> = {};
      for (const problema of problemas) mapa[problema.field] = problema.message;
      setErrores(mapa);
      return;
    }

    if (editando) {
      updateDebt(candidata.id, candidata);
      notify(t('deudas.deudaActualizada'));
    } else {
      addDebt(candidata);
      notify(t('deudas.deudaRegistrada'));
    }
    onDone();
  }

  function borrar() {
    if (!debt) return;
    removeDebt(debt.id);
    notify(t('deudas.deudaEliminada'));
    onDone();
  }

  return (
    <>
      <Field
        label="Nombre"
        type="text"
        placeholder={t('deudas.prestamoDelCarro')}
        value={nombre}
        error={errores.name}
        onChange={(event) => setNombre(event.target.value)}
      />

      <SelectField label="Tipo" value={tipo} onChange={(event) => setTipo(event.target.value as DebtKind)}>
        {TIPOS.map((item) => (
          <option key={item} value={item}>
            {DEBT_ICONS[item]} {DEBT_LABELS[item]}
          </option>
        ))}
      </SelectField>

      <SelectorMoneda value={moneda} onChange={setMoneda} />

      <Field
        label={t('deudas.montoOriginal')}
        type="text"
        inputMode="decimal"
        placeholder="0.00"
        value={original}
        error={errores.original}
        hint={t('deudas.conCuantoEmpezoPara')}
        onChange={(event) => setOriginal(event.target.value)}
      />

      <Field
        label={t('deudas.faltaPorPagar')}
        type="text"
        inputMode="decimal"
        placeholder="0.00"
        value={balance}
        error={errores.balance}
        onChange={(event) => setBalance(event.target.value)}
      />

      <Field
        label={t('deudas.cuotaMensual')}
        type="text"
        inputMode="decimal"
        placeholder="Opcional"
        value={cuota}
        error={errores.monthlyPayment}
        hint={t('deudas.conEstoPuedoCalcular')}
        onChange={(event) => setCuota(event.target.value)}
      />

      <Field
        label={t('deudas.tasaAnual')}
        type="text"
        inputMode="decimal"
        placeholder="Opcional: 14.5"
        value={tasa}
        error={errores.apr}
        onChange={(event) => setTasa(event.target.value)}
      />

      <Field
        label={t('deudas.diaDePago')}
        type="number"
        min={1}
        max={31}
        placeholder="Opcional"
        value={dia}
        error={errores.dueDay}
        onChange={(event) => setDia(event.target.value)}
      />

      <div className="hoja__pie">
        <Button wide onClick={guardar}>
          {editando ? t('deudas.guardarCambios') : t('deudas.registrarDeuda')}
        </Button>
        {editando && (
          <Button wide variant="peligro" className="seccion" onClick={borrar}>{t('deudas.eliminarDeuda')}</Button>
        )}
      </div>
    </>
  );
}
