/**
 * Cliente de Supabase, cargado solo cuando hace falta.
 *
 * La app es local primero y la mayoría de la gente la usa sin cuenta. La
 * librería pesa unos 380 kB, así que no entra en el arranque: se carga la
 * primera vez que alguien abre la pantalla de cuenta, o cuando ya hay una
 * sesión guardada que restaurar.
 */

import type { SupabaseClient } from '@supabase/supabase-js';

const URL = import.meta.env.VITE_SUPABASE_URL as string | undefined;
const KEY = import.meta.env.VITE_SUPABASE_KEY as string | undefined;

let promesa: Promise<SupabaseClient | null> | null = null;

/** true si el proyecto está configurado. No carga nada. */
export function cuentaConfigurada(): boolean {
  return Boolean(URL && KEY);
}

/** Clave donde Supabase guarda la sesión: sb-<proyecto>-auth-token */
function claveDeSesion(): string | null {
  if (!URL) return null;
  try {
    const referencia = new globalThis.URL(URL).hostname.split('.')[0];
    return referencia ? `sb-${referencia}-auth-token` : null;
  } catch {
    return null;
  }
}

/** true si ya hay una sesión guardada en este teléfono. No carga nada. */
export function haySesionGuardada(): boolean {
  const clave = claveDeSesion();
  if (!clave) return false;
  try {
    return localStorage.getItem(clave) !== null;
  } catch {
    return false;
  }
}

/** true si venimos de volver de Apple o Google con el token en la dirección. */
export function vieneDeProveedor(): boolean {
  if (typeof window === 'undefined') return false;
  return (
    window.location.hash.includes('access_token') ||
    new URLSearchParams(window.location.search).has('code')
  );
}

export async function getSupabase(): Promise<SupabaseClient | null> {
  if (!promesa) promesa = cargar();
  return promesa;
}

async function cargar(): Promise<SupabaseClient | null> {
  if (!URL || !KEY) return null;
  try {
    const { createClient } = await import('@supabase/supabase-js');
    return createClient(URL, KEY, {
      auth: {
        persistSession: true,
        autoRefreshToken: true,
        detectSessionInUrl: true,
        // PKCE: el código vuelve por el enlace de la app y se canjea aquí.
        // Es lo que permite que Apple y Google funcionen dentro del teléfono.
        flowType: 'pkce',
      },
    });
  } catch {
    return null;
  }
}
