/**
 * La hoja de cuentas: ver el detalle, crear una nueva o editar la que hay.
 */

import { useState } from 'react';
import { t } from '../../i18n';
import { useData } from '../../store/useApp';
import { Sheet } from '../../ui/overlays';
import { CuentaForm } from './CuentaForm';
import { CuentaDetalle } from './CuentaDetalle';
import { TransferenciaForm } from '../registrar/TransferenciaForm';
import { EfectivoSheet } from './EfectivoSheet';

export type CuentaVista =
  | { modo: 'cerrada' }
  | { modo: 'nueva' }
  | { modo: 'detalle'; id: string }
  | { modo: 'editar'; id: string }
  | { modo: 'retiro' }
  | { modo: 'efectivo' };

export function CuentasSheet({
  vista,
  onCerrar,
  onCambiarVista,
}: {
  vista: CuentaVista;
  onCerrar: () => void;
  onCambiarVista: (vista: CuentaVista) => void;
}) {
  const data = useData();
  const [recienCerrada, setRecienCerrada] = useState(false);

  if (vista.modo === 'cerrada') return null;

  const cuenta =
    vista.modo === 'detalle' || vista.modo === 'editar'
      ? data.accounts.find((item) => item.id === vista.id)
      : undefined;

  // Si la cuenta desapareció mientras la hoja estaba abierta
  if ((vista.modo === 'detalle' || vista.modo === 'editar') && !cuenta) {
    if (!recienCerrada) {
      setRecienCerrada(true);
      onCerrar();
    }
    return null;
  }

  const titulo =
    vista.modo === 'efectivo'
      ? t('efectivo.titulo')
      : vista.modo === 'retiro'
        ? t('retiro.titulo')
        : vista.modo === 'nueva'
          ? t('cuentasHoja.nuevaCuenta')
          : vista.modo === 'editar'
            ? t('cuentasHoja.editarCuenta')
            : (cuenta?.nickname ?? cuenta?.bank ?? 'Cuenta');

  const subtitulo =
    vista.modo === 'efectivo'
      ? t('efectivo.sub')
      : vista.modo === 'retiro'
        ? t('retiro.sub')
        : vista.modo === 'detalle'
          ? cuenta?.kind === 'credit'
            ? t('cuentasHoja.tarjetaDeCredito')
            : cuenta?.kind === 'cash'
              ? t('cuentasHoja.efectivo')
              : t('cuentasHoja.cuentaDeBanco')
          : vista.modo === 'nueva'
            ? t('cuentasHoja.bancoOTarjetaDe')
            : undefined;

  return (
    <Sheet
      open
      title={titulo}
      subtitle={subtitulo}
      onClose={onCerrar}
      onBack={vista.modo === 'editar' ? () => onCambiarVista({ modo: 'detalle', id: vista.id }) : undefined}
    >
      {vista.modo === 'nueva' && <CuentaForm onDone={onCerrar} />}

      {vista.modo === 'retiro' && <TransferenciaForm onDone={onCerrar} haciaEfectivo />}

      {vista.modo === 'efectivo' && <EfectivoSheet onDone={onCerrar} />}

      {vista.modo === 'editar' && cuenta && (
        <CuentaForm account={cuenta} onDone={() => onCambiarVista({ modo: 'detalle', id: cuenta.id })} />
      )}

      {vista.modo === 'detalle' && cuenta && (
        <CuentaDetalle
          account={cuenta}
          onEditar={() => onCambiarVista({ modo: 'editar', id: cuenta.id })}
          onContarEfectivo={() => onCambiarVista({ modo: 'efectivo' })}
          onDone={onCerrar}
        />
      )}
    </Sheet>
  );
}
