/**
 * Gastos e ingresos que se repiten cada mes.
 *
 * Los que están en automático los registra la app sola al llegar el día.
 * Los que están en manual esperan a que la persona los aplique.
 */

import { useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData, usePrivacy } from '../../store/useApp';
import type { Recurrence } from '../../domain/types';
import type { Currency } from '../../lib/money';
import { Sheet } from '../../ui/overlays';
import { Amount } from '../../ui/Amount';
import { Button, Card, Chip, Empty, Notice } from '../../ui/primitives';
import { Field, SelectField, Segmented } from '../../ui/forms';
import { SelectorMoneda } from '../../ui/SelectorMoneda';
import { Row } from '../../ui/Row';
import { isDue } from '../../domain/recurrences';
import { formatNumber, parseAmount } from '../../lib/money';
import { newId } from '../../lib/id';
import { currentYearMonth } from '../../lib/date';

const TIPOS = [
  { value: 'expense' as const, label: 'Gasto' },
  { value: 'income' as const, label: 'Ingreso' },
];

const MODOS = [
  { value: 'auto' as const, label: 'Automático' },
  { value: 'manual' as const, label: 'Manual' },
];

export function RecurrentesSheet({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [editando, setEditando] = useState<Recurrence | 'nuevo' | null>(null);

  return (
    <Sheet
      open={open}
      title={
        editando
          ? editando === 'nuevo'
            ? t('recurrentes.nuevoMovimientoFijo')
            : t('recurrentes.editarMovimientoFijo')
          : t('recurrentes.movimientosFijos')
      }
      subtitle={editando ? undefined : t('recurrentes.loQueSeRepite')}
      onClose={onClose}
      onBack={editando ? () => setEditando(null) : undefined}
    >
      {editando ? (
        <RecurrenteForm
          recurrence={editando === 'nuevo' ? undefined : editando}
          onDone={() => setEditando(null)}
        />
      ) : (
        <ListaRecurrentes onNuevo={() => setEditando('nuevo')} onEditar={setEditando} />
      )}
    </Sheet>
  );
}

function ListaRecurrentes({
  onNuevo,
  onEditar,
}: {
  onNuevo: () => void;
  onEditar: (recurrence: Recurrence) => void;
}) {
  const data = useData();
  const privacy = usePrivacy();
  const applyRecurrence = useApp((state) => state.applyRecurrence);
  const notify = useApp((state) => state.notify);

  const activos = data.recurrences.filter((item) => !item.archived);

  if (activos.length === 0) {
    return (
      <Empty
        mark="🔁"
        title={t('recurrentes.sinMovimientosFijos')}
        text={t('recurrentes.elAlquilerElInternet')}
        action={<Button small onClick={onNuevo}>{t('recurrentes.agregarElPrimero')}</Button>}
      />
    );
  }

  const mes = currentYearMonth();

  return (
    <>
      {activos.map((recurrente) => {
        const yaEsteMes = recurrente.lastAppliedMonth === mes;
        const toca = isDue(recurrente);

        return (
          <Card key={recurrente.id} className="seccion">
            <Row
              icon={recurrente.kind === 'income' ? '💰' : '🔁'}
              title={recurrente.name}
              detail={`Día ${recurrente.dayOfMonth} de cada mes`}
              onClick={() => onEditar(recurrente)}
              right={
                <Amount
                  cents={recurrente.kind === 'income' ? recurrente.amount : -recurrente.amount}
                  currency={recurrente.currency}
                  size="normal"
                  tone={recurrente.kind === 'income' ? 'positiva' : 'negativa'}
                  hidden={privacy}
                />
              }
            />

            <div className="fila-entre" style={{ marginTop: 'var(--e3)' }}>
              <Chip tone={recurrente.autoApply ? 'verde' : 'neutra'}>
                {recurrente.autoApply ? 'Automático' : 'Manual'}
              </Chip>

              {yaEsteMes ? (
                <span className="texto-micro">{t('recurrentes.yaSeRegistroEste')}</span>
              ) : toca ? (
                <Button
                  small
                  variant="suave"
                  onClick={() => {
                    applyRecurrence(recurrente.id);
                    notify(`${recurrente.name} registrado`);
                  }}
                >{t('recurrentes.registrarAhora')}</Button>
              ) : (
                <span className="texto-micro">Pendiente para el día {recurrente.dayOfMonth}</span>
              )}
            </div>
          </Card>
        );
      })}

      <div className="seccion">
        <Button wide variant="contorno" onClick={onNuevo}>{t('recurrentes.agregarOtro')}</Button>
      </div>
    </>
  );
}

function RecurrenteForm({
  recurrence,
  onDone,
}: {
  recurrence?: Recurrence;
  onDone: () => void;
}) {
  const data = useData();
  const addRecurrence = useApp((state) => state.addRecurrence);
  const updateRecurrence = useApp((state) => state.updateRecurrence);
  const removeRecurrence = useApp((state) => state.removeRecurrence);
  const notify = useApp((state) => state.notify);

  const editando = recurrence !== undefined;

  const [tipo, setTipo] = useState<'expense' | 'income'>(recurrence?.kind ?? 'expense');
  const [nombre, setNombre] = useState(recurrence?.name ?? '');
  const [monto, setMonto] = useState(recurrence ? formatNumber(recurrence.amount) : '');
  const [moneda, setMoneda] = useState<Currency>(
    recurrence?.currency ?? data.profile.mainCurrency,
  );
  const [dia, setDia] = useState(String(recurrence?.dayOfMonth ?? 1));
  const [categoria, setCategoria] = useState(recurrence?.categoryId ?? 'vivienda');
  const [fuente, setFuente] = useState(recurrence?.sourceId ?? 'salario');
  const [cuenta, setCuenta] = useState(recurrence?.accountId ?? '');
  const [modo, setModo] = useState<'auto' | 'manual'>(recurrence?.autoApply ? 'auto' : 'manual');
  const [errores, setErrores] = useState<Record<string, string>>({});

  const cuentas = data.accounts.filter((item) => !item.archived);

  function guardar() {
    const fallos: Record<string, string> = {};
    const cantidad = parseAmount(monto);
    const diaNumero = Number(dia);

    if (!nombre.trim()) fallos.nombre = t('recurrentes.ponleUnNombrePara');
    if (!cantidad || cantidad <= 0) fallos.monto = t('recurrentes.escribeCuantoEs');
    if (!Number.isInteger(diaNumero) || diaNumero < 1 || diaNumero > 31) {
      fallos.dia = t('recurrentes.elDiaVaDel');
    }

    setErrores(fallos);
    if (Object.keys(fallos).length > 0) return;

    const ahora = new Date().toISOString();
    const nuevo: Recurrence = {
      id: recurrence?.id ?? newId(),
      kind: tipo,
      name: nombre.trim(),
      amount: cantidad ?? 0,
      currency: moneda,
      dayOfMonth: diaNumero,
      autoApply: modo === 'auto',
      createdAt: recurrence?.createdAt ?? ahora,
      updatedAt: ahora,
    };
    if (tipo === 'expense') nuevo.categoryId = categoria;
    else nuevo.sourceId = fuente;
    if (cuenta) nuevo.accountId = cuenta;
    if (recurrence?.lastAppliedMonth) nuevo.lastAppliedMonth = recurrence.lastAppliedMonth;

    if (editando) {
      updateRecurrence(nuevo.id, nuevo);
      notify(t('recurrentes.movimientoFijoActualizado'));
    } else {
      addRecurrence(nuevo);
      notify(t('recurrentes.movimientoFijoCreado'));
    }
    onDone();
  }

  function borrar() {
    if (!recurrence) return;
    removeRecurrence(recurrence.id);
    notify(t('recurrentes.movimientoFijoEliminado'));
    onDone();
  }

  return (
    <>
      {!editando && (
        <div style={{ marginBottom: 'var(--e4)' }}>
          <Segmented options={TIPOS} value={tipo} onChange={setTipo} label="Tipo" />
        </div>
      )}

      <Field
        label="Nombre"
        type="text"
        placeholder={tipo === 'expense' ? 'Alquiler' : 'Quincena'}
        value={nombre}
        error={errores.nombre}
        onChange={(event) => setNombre(event.target.value)}
      />

      <Field
        label="Monto"
        type="text"
        inputMode="decimal"
        placeholder="0.00"
        value={monto}
        error={errores.monto}
        onChange={(event) => setMonto(event.target.value)}
      />

      <SelectorMoneda value={moneda} onChange={setMoneda} />

      <Field
        label={t('recurrentes.diaDelMes')}
        type="number"
        min={1}
        max={31}
        value={dia}
        error={errores.dia}
        hint={t('recurrentes.siElMesNo')}
        onChange={(event) => setDia(event.target.value)}
      />

      {tipo === 'expense' ? (
        <SelectField
          label={t('comun.categoria')}
          value={categoria}
          onChange={(event) => setCategoria(event.target.value)}
        >
          {data.categories
            .filter((item) => !item.archived)
            .map((item) => (
              <option key={item.id} value={item.id}>
                {item.icon} {item.name}
              </option>
            ))}
        </SelectField>
      ) : (
        <SelectField label="Fuente" value={fuente} onChange={(event) => setFuente(event.target.value)}>
          {data.incomeSources.map((item) => (
            <option key={item.id} value={item.id}>
              {item.icon} {item.name}
            </option>
          ))}
        </SelectField>
      )}

      <SelectField
        label={tipo === 'expense' ? t('recurrentes.sePagaDesde') : 'Entra a'}
        value={cuenta}
        onChange={(event) => setCuenta(event.target.value)}
        hint={t('recurrentes.siEligesUnaCuenta')}
      >
        <option value="">{t('recurrentes.efectivoSinAfectarCuentas')}</option>
        {cuentas.map((item) => (
          <option key={item.id} value={item.id}>
            {item.nickname ?? item.bank}
          </option>
        ))}
      </SelectField>

      <p className="campo__etiqueta">{t('recurrentes.comoSeRegistra')}</p>
      <div style={{ marginBottom: 'var(--e3)' }}>
        <Segmented options={MODOS} value={modo} onChange={setModo} label="Modo" />
      </div>
      <p className="campo__ayuda" style={{ marginBottom: 'var(--e4)' }}>
        {modo === 'auto'
          ? t('recurrentes.laAppLoRegistra')
          : t('recurrentes.teAparecePendienteY')}
      </p>

      {editando && recurrence?.lastAppliedMonth && (
        <div style={{ marginBottom: 'var(--e4)' }}>
          <Notice tone="azul" icon="ℹ️">{t('recurrentes.loQueYaSe')}</Notice>
        </div>
      )}

      <div className="hoja__pie">
        <Button wide onClick={guardar}>
          {editando ? t('recurrentes.guardarCambios') : 'Crear'}
        </Button>
        {editando && (
          <Button wide variant="peligro" className="seccion" onClick={borrar}>
            Eliminar
          </Button>
        )}
      </div>
    </>
  );
}
