/**
 * Importar el estado de cuenta del banco.
 *
 * Tres pasos: eliges el archivo, revisas lo que entendí, confirmas. Lo que no
 * se entiende se aparta a la vista en vez de colarse mal, y lo que ya estaba
 * registrado viene desmarcado.
 */

import { useRef, useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData } from '../../store/useApp';
import { usePremiumActivo } from '../../store/usePremium';
import { Bloqueado } from '../premium/Bloqueado';
import { PremiumSheet } from '../premium/PremiumSheet';
import { Sheet } from '../../ui/overlays';
import { Amount } from '../../ui/Amount';
import { Button, Card, Chip, Notice } from '../../ui/primitives';
import { SelectField, Segmented } from '../../ui/forms';
import { SelectorMoneda } from '../../ui/SelectorMoneda';
import { parseCsv } from '../../lib/csv';
import type { ColumnMap, DateOrder, ImportPreview } from '../../domain/import';
import {
  buildPreview,
  detectColumns,
  findHeaderRow,
  toTransactions,
} from '../../domain/import';
import type { Currency } from '../../lib/money';
import { countOf, plural } from '../../lib/text';
import { relativeDate } from '../../lib/date';

const ORDENES = [
  { value: 'dmy' as const, label: 'Día/Mes' },
  { value: 'mdy' as const, label: 'Mes/Día' },
];

const MAXIMO_EN_PANTALLA = 60;

interface Archivo {
  filas: string[][];
  encabezado: number;
  columnas: ColumnMap;
  nombre: string;
}

export function ImportarSheet({ open, onClose }: { open: boolean; onClose: () => void }) {
  const data = useData();
  const importTransactions = useApp((state) => state.importTransactions);
  const notify = useApp((state) => state.notify);

  const entrada = useRef<HTMLInputElement>(null);
  const [archivo, setArchivo] = useState<Archivo | null>(null);
  const [vista, setVista] = useState<ImportPreview | null>(null);
  const [moneda, setMoneda] = useState<Currency>(data.profile.mainCurrency);
  const [cuenta, setCuenta] = useState('');
  const [error, setError] = useState('');
  const premium = usePremiumActivo();
  const [planesAbiertos, setPlanesAbiertos] = useState(false);

  const cuentas = data.accounts.filter((item) => !item.archived);

  function reiniciar() {
    setArchivo(null);
    setVista(null);
    setError('');
  }

  function cerrar() {
    reiniciar();
    onClose();
  }

  async function leer(input: HTMLInputElement) {
    const elegido = input.files?.[0];
    if (!elegido) return;
    const texto = await elegido.text();
    input.value = '';

    const filas = parseCsv(texto);
    if (filas.length < 2) {
      setError(t('importar.elArchivoEstaVacio'));
      return;
    }

    const encabezado = findHeaderRow(filas);
    if (encabezado < 0) {
      setError(
        t('importar.noEncontreLosEncabezados'),
      );
      return;
    }

    const columnas = detectColumns(filas[encabezado] ?? []);
    if (!columnas) {
      setError(
        t('importar.encontreLosEncabezadosPero'),
      );
      return;
    }

    setError('');
    setArchivo({ filas, encabezado, columnas, nombre: elegido.name });
    setVista(buildPreview(data, filas, encabezado, { columns: columnas, currency: moneda }));
  }

  function cambiarOrden(orden: DateOrder) {
    if (!archivo) return;
    setVista(
      buildPreview(data, archivo.filas, archivo.encabezado, {
        columns: archivo.columnas,
        currency: moneda,
        dateOrder: orden,
      }),
    );
  }

  function alternar(linea: number) {
    if (!vista) return;
    setVista({
      ...vista,
      rows: vista.rows.map((fila) =>
        fila.line === linea ? { ...fila, include: !fila.include } : fila,
      ),
    });
  }

  function importar() {
    if (!vista || !archivo) return;
    const movimientos = toTransactions(
      vista.rows,
      {
        columns: archivo.columnas,
        currency: moneda,
        ...(cuenta ? { accountId: cuenta } : {}),
      },
      data.fx.dopPerUsd,
    );

    const cuantos = importTransactions(movimientos);
    notify(
      cuantos === 1 ? t('importar.seImporto1Movimiento') : `Se importaron ${cuantos} movimientos`,
    );
    cerrar();
  }

  const elegidas = vista?.rows.filter((fila) => fila.include) ?? [];
  const repetidas = vista?.rows.filter((fila) => fila.duplicate).length ?? 0;

  return (
    <Sheet
      open={open}
      title={t('importar.importarDelBanco')}
      subtitle={archivo ? archivo.nombre : t('importar.unArchivoCsvDe')}
      onClose={cerrar}
      onBack={archivo ? reiniciar : undefined}
    >
      {!premium ? (
        <>
          <Bloqueado funcion="importar" onAbrir={() => setPlanesAbiertos(true)} />
          <PremiumSheet
            open={planesAbiertos}
            desde="importar"
            onClose={() => setPlanesAbiertos(false)}
          />
        </>
      ) : !archivo ? (
        <>
          <div className="seccion">
            <Notice tone="azul" icon="📄">
              Descarga tu estado de cuenta en CSV desde la página del banco y súbelo aquí. Entiendo
              los formatos de los bancos de aquí y de Estados Unidos: fechas al derecho o al revés,
              montos con punto o con coma, y columnas de débito y crédito separadas.
            </Notice>
          </div>

          {error && (
            <div className="seccion">
              <Notice tone="roja" icon="⚠️">
                {error}
              </Notice>
            </div>
          )}

          <input
            ref={entrada}
            type="file"
            accept=".csv,text/csv,text/plain"
            style={{ display: 'none' }}
            aria-hidden="true"
            tabIndex={-1}
            onChange={(event) => void leer(event.currentTarget)}
          />
          <div className="hoja__pie">
            <Button wide onClick={() => entrada.current?.click()}>{t('importar.elegirElArchivo')}</Button>
          </div>
        </>
      ) : (
        vista && (
          <>
            <Card className="seccion" title="Dónde va">
              <SelectField
                label="Cuenta"
                value={cuenta}
                onChange={(event) => setCuenta(event.target.value)}
                hint={t('importar.losSaldosSeMueven')}
              >
                <option value="">{t('importar.efectivoSinAfectarCuentas')}</option>
                {cuentas.map((item) => (
                  <option key={item.id} value={item.id}>
                    {item.nickname ?? item.bank}
                  </option>
                ))}
              </SelectField>

              <SelectorMoneda value={moneda} onChange={setMoneda} label={t('importar.monedaDelArchivo')} />
            </Card>

            {vista.dateAmbiguous && (
              <div className="seccion">
                <Notice tone="ambar" icon="📅">
                  No pude saber si las fechas van día/mes o mes/día, porque en este archivo todos
                  los números son 12 o menos. Mira la primera fila y dime cuál es.
                  <div style={{ marginTop: 'var(--e3)' }}>
                    <Segmented
                      options={ORDENES}
                      value={vista.dateOrder === 'mdy' ? 'mdy' : 'dmy'}
                      onChange={cambiarOrden}
                      label={t('importar.ordenDeLaFecha')}
                    />
                  </div>
                </Notice>
              </div>
            )}

            {repetidas > 0 && (
              <div className="seccion">
                <Notice tone="azul" icon="🔁">
                  {repetidas === 1
                    ? t('importar.hay1MovimientoQue')
                    : `Hay ${repetidas} movimientos que ya tenías registrados. Vienen desmarcados.`}
                </Notice>
              </div>
            )}

            {vista.skipped.length > 0 && (
              <div className="seccion">
                <Notice tone="ambar" icon="⚠️">
                  {countOf(vista.skipped.length, 'fila', 'filas')} no se{' '}
                  {plural(vista.skipped.length, 'pudo', 'pudieron')} leer y{' '}
                  {plural(vista.skipped.length, 'queda', 'quedan')} fuera:{' '}
                  {vista.skipped
                    .slice(0, 3)
                    .map((item) => `la ${item.line}`)
                    .join(', ')}
                  {vista.skipped.length > 3 && ' y más'}.{' '}
                  {vista.skipped[0]?.reason}. Esas las puedes registrar a mano.
                </Notice>
              </div>
            )}

            <Card className="seccion" title={`${vista.rows.length} ${plural(vista.rows.length, 'movimiento', 'movimientos')}`}>
              {vista.rows.slice(0, MAXIMO_EN_PANTALLA).map((fila) => (
                <button
                  key={fila.line}
                  type="button"
                  className="fila fila--tocable"
                  aria-pressed={fila.include}
                  onClick={() => alternar(fila.line)}
                >
                  <span className={`casilla${fila.include ? ' casilla--marcada' : ''}`} aria-hidden="true">
                    {fila.include ? '✓' : ''}
                  </span>
                  <span className="fila__centro">
                    <span className="fila__titulo texto-corta">{fila.description}</span>
                    <span className="fila__detalle">
                      {relativeDate(fila.date)}
                      {fila.duplicate && (
                        <>
                          {' '}
                          <Chip tone="neutra">ya registrado</Chip>
                        </>
                      )}
                    </span>
                  </span>
                  <Amount
                    cents={fila.amount}
                    currency={moneda}
                    size="normal"
                    tone={fila.amount < 0 ? 'negativa' : 'positiva'}
                    compact
                  />
                </button>
              ))}

              {vista.rows.length > MAXIMO_EN_PANTALLA && (
                <p className="texto-menor" style={{ marginTop: 'var(--e3)' }}>
                  Y {vista.rows.length - MAXIMO_EN_PANTALLA} más, que también se importan.
                </p>
              )}
            </Card>

            <div className="hoja__pie">
              <Button wide disabled={elegidas.length === 0} onClick={importar}>
                {elegidas.length === 0
                  ? t('importar.noHayNadaMarcado')
                  : `Importar ${elegidas.length} ${plural(elegidas.length, 'movimiento', 'movimientos')}`}
              </Button>
            </div>
          </>
        )
      )}
    </Sheet>
  );
}
