/**
 * Gastos e ingresos que se repiten cada mes.
 *
 * La versión anterior obligaba a tocar "Aplicar" cada vez. Aquí, si la persona
 * lo pide, la app los registra sola al llegar el día, y nunca dos veces en el
 * mismo mes porque cada uno recuerda cuándo se aplicó por última vez.
 */

import type { AppData, ExpenseTx, IncomeTx, Recurrence, Transaction } from './types';
import type { IsoDate, YearMonth } from '../lib/date';
import { currentYearMonth, daysUntilMonthDay, toIsoDate, yearMonthOf } from '../lib/date';
import { newId } from '../lib/id';

/** La fecha que le toca a un recurrente dentro de un mes. */
export function dateForMonth(recurrence: Recurrence, month: YearMonth): IsoDate {
  const anio = Number(month.slice(0, 4));
  const mes = Number(month.slice(5, 7)) - 1;
  const ultimoDia = new Date(anio, mes + 1, 0).getDate();
  // Un recurrente del día 31 en un mes de 30 cae el 30
  const dia = Math.min(recurrence.dayOfMonth, ultimoDia);
  return toIsoDate(new Date(anio, mes, dia));
}

/** ¿Le toca ya a este recurrente en el mes en curso? */
export function isDue(recurrence: Recurrence, hoy: Date = new Date()): boolean {
  if (recurrence.archived) return false;

  const mes = yearMonthOf(toIsoDate(hoy));
  if (recurrence.lastAppliedMonth === mes) return false;

  const fechaQueToca = dateForMonth(recurrence, mes);
  return fechaQueToca <= toIsoDate(hoy);
}

/** Los que ya tocaban y están puestos en automático. */
export function dueRecurrences(data: AppData, hoy: Date = new Date()): Recurrence[] {
  return data.recurrences.filter(
    (recurrence) => recurrence.autoApply && isDue(recurrence, hoy),
  );
}

/** Los que están en manual y ya tocaban, para poder avisar. */
export function pendingManual(data: AppData, hoy: Date = new Date()): Recurrence[] {
  return data.recurrences.filter(
    (recurrence) => !recurrence.autoApply && isDue(recurrence, hoy),
  );
}

/** Construye el movimiento que genera un recurrente. */
export function transactionFrom(
  recurrence: Recurrence,
  data: AppData,
  date: IsoDate,
): Transaction {
  const ahora = new Date().toISOString();
  const base = {
    id: newId(),
    date,
    amount: recurrence.amount,
    currency: recurrence.currency,
    fxRate: data.fx.dopPerUsd,
    note: recurrence.name,
    recurrenceId: recurrence.id,
    createdAt: ahora,
    updatedAt: ahora,
  };

  if (recurrence.kind === 'income') {
    const ingreso: IncomeTx = {
      ...base,
      kind: 'income',
      sourceId: recurrence.sourceId ?? 'otro-ingreso',
    };
    if (recurrence.accountId) ingreso.accountId = recurrence.accountId;
    return ingreso;
  }

  const gasto: ExpenseTx = {
    ...base,
    kind: 'expense',
    categoryId: recurrence.categoryId ?? 'otros',
  };
  if (recurrence.accountId) gasto.accountId = recurrence.accountId;
  return gasto;
}

export interface UpcomingPayment {
  id: string;
  kind: 'recurrente' | 'tarjeta' | 'deuda';
  name: string;
  /** Días que faltan. 0 es hoy. */
  days: number;
  amount: number;
  currency: 'DOP' | 'USD';
}

/** Lo que hay que pagar pronto: recurrentes, tarjetas y deudas. */
export function upcomingPayments(data: AppData, dentroDeDias = 10): UpcomingPayment[] {
  const pagos: UpcomingPayment[] = [];
  const mes = currentYearMonth();

  for (const recurrence of data.recurrences) {
    if (recurrence.archived) continue;
    if (recurrence.lastAppliedMonth === mes) continue;
    const faltan = daysUntilMonthDay(recurrence.dayOfMonth);
    if (faltan === null || faltan > dentroDeDias) continue;
    pagos.push({
      id: recurrence.id,
      kind: 'recurrente',
      name: recurrence.name,
      days: faltan,
      amount: recurrence.amount,
      currency: recurrence.currency,
    });
  }

  for (const cuenta of data.accounts) {
    if (cuenta.archived || cuenta.kind !== 'credit') continue;
    const dia = cuenta.credit?.dueDay;
    if (dia === undefined) continue;
    const faltan = daysUntilMonthDay(dia);
    if (faltan === null || faltan > dentroDeDias) continue;

    for (const moneda of ['DOP', 'USD'] as const) {
      const debe = Math.abs(Math.min(0, cuenta.balances[moneda] ?? 0));
      if (debe <= 0) continue;
      pagos.push({
        id: `${cuenta.id}-${moneda}`,
        kind: 'tarjeta',
        name: cuenta.nickname ?? cuenta.bank,
        days: faltan,
        amount: debe,
        currency: moneda,
      });
    }
  }

  for (const deuda of data.debts) {
    if (deuda.archived || deuda.balance <= 0) continue;
    if (deuda.dueDay === undefined) continue;
    const faltan = daysUntilMonthDay(deuda.dueDay);
    if (faltan === null || faltan > dentroDeDias) continue;
    pagos.push({
      id: deuda.id,
      kind: 'deuda',
      name: deuda.name,
      days: faltan,
      // Lo que vence es la cuota, no la deuda completa
      amount: Math.min(deuda.monthlyPayment ?? deuda.balance, deuda.balance),
      currency: deuda.currency,
    });
  }

  return pagos.sort((a, b) => a.days - b.days);
}
