/**
 * Crear o editar una cuenta de banco o una tarjeta de crédito.
 *
 * Una misma cuenta puede tener saldo en pesos y en dólares a la vez, que es
 * lo normal en República Dominicana, así que los dos campos están siempre.
 */

import { useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData } from '../../store/useApp';
import { useMonedasPermitidas } from '../../store/useMonedas';
import type { Account, AccountKind, Country } from '../../domain/types';
import type { AccountIssue } from '../../domain/accounts';
import type { Cents, Currency } from '../../lib/money';
import { BANCOS_SUGERIDOS, validateAccount } from '../../domain/accounts';
import { formatNumber, parseAmount } from '../../lib/money';
import { Button, Notice } from '../../ui/primitives';
import { Field, Segmented } from '../../ui/forms';
import { newId } from '../../lib/id';

const TIPOS = [
  { value: 'bank' as const, label: t('cuentaForm.cuentaDeBanco') },
  { value: 'credit' as const, label: 'Tarjeta' },
];

const PAISES = [
  { value: 'DO' as const, label: 'República Dominicana' },
  { value: 'US' as const, label: 'Estados Unidos' },
];

/** Texto de un monto guardado, para rellenar el formulario al editar. */
function textoDe(cents: Cents | undefined): string {
  return cents === undefined ? '' : formatNumber(Math.abs(cents));
}

export function CuentaForm({
  account,
  onDone,
}: {
  /** Si viene, se edita; si no, se crea. */
  account?: Account;
  onDone: () => void;
}) {
  const data = useData();
  const addAccount = useApp((state) => state.addAccount);
  const updateAccount = useApp((state) => state.updateAccount);
  const notify = useApp((state) => state.notify);
  const monedas = useMonedasPermitidas();

  const editando = account !== undefined;

  const [tipo, setTipo] = useState<AccountKind>(account?.kind ?? 'bank');
  const [pais, setPais] = useState<Country>(account?.country ?? data.profile.country);
  const [banco, setBanco] = useState(account?.bank ?? '');
  const [apodo, setApodo] = useState(account?.nickname ?? '');
  const [digitos, setDigitos] = useState(account?.last4 ?? '');

  const [saldoDOP, setSaldoDOP] = useState(textoDe(account?.balances.DOP));
  const [saldoUSD, setSaldoUSD] = useState(textoDe(account?.balances.USD));

  const [limiteDOP, setLimiteDOP] = useState(textoDe(account?.credit?.limits.DOP));
  const [limiteUSD, setLimiteUSD] = useState(textoDe(account?.credit?.limits.USD));
  const [usadoDOP, setUsadoDOP] = useState(textoDe(account?.balances.DOP));
  const [usadoUSD, setUsadoUSD] = useState(textoDe(account?.balances.USD));

  const [corte, setCorte] = useState(account?.credit?.statementDay?.toString() ?? '');
  const [pago, setPago] = useState(account?.credit?.dueDay?.toString() ?? '');

  const [problemas, setProblemas] = useState<AccountIssue[]>([]);

  function error(campo: string): string | undefined {
    return problemas.find((problema) => problema.field === campo)?.message;
  }

  function construir(): Account {
    const ahora = new Date().toISOString();
    const base: Account = {
      id: account?.id ?? newId(),
      kind: tipo,
      bank: banco.trim(),
      country: pais,
      balances: {},
      createdAt: account?.createdAt ?? ahora,
      updatedAt: ahora,
    };

    const apodoLimpio = apodo.trim();
    if (apodoLimpio && apodoLimpio !== base.bank) base.nickname = apodoLimpio;

    const digitosLimpios = digitos.replace(/\D/g, '');
    if (digitosLimpios) base.last4 = digitosLimpios;

    if (tipo === 'bank') {
      const dop = parseAmount(saldoDOP);
      const usd = parseAmount(saldoUSD);
      if (saldoDOP.trim() !== '' && dop !== null) base.balances.DOP = dop;
      if (saldoUSD.trim() !== '' && usd !== null) base.balances.USD = usd;
    } else {
      const limites: Partial<Record<Currency, Cents>> = {};
      const limD = parseAmount(limiteDOP);
      const limU = parseAmount(limiteUSD);
      if (limD && limD > 0) limites.DOP = limD;
      if (limU && limU > 0) limites.USD = limU;

      // En la tarjeta lo usado se guarda en negativo: es deuda, no dinero
      const usoD = parseAmount(usadoDOP);
      const usoU = parseAmount(usadoUSD);
      if (limites.DOP !== undefined) base.balances.DOP = -(usoD ?? 0);
      if (limites.USD !== undefined) base.balances.USD = -(usoU ?? 0);

      base.credit = { limits: limites };
      const diaCorte = Number(corte);
      const diaPago = Number(pago);
      if (corte.trim() && Number.isFinite(diaCorte)) base.credit.statementDay = diaCorte;
      if (pago.trim() && Number.isFinite(diaPago)) base.credit.dueDay = diaPago;
    }

    return base;
  }

  function guardar() {
    const cuenta = construir();
    const encontrados = validateAccount(cuenta);
    setProblemas(encontrados);
    if (encontrados.length > 0) return;

    if (editando) {
      updateAccount(cuenta.id, cuenta);
      notify(t('cuentaForm.cuentaActualizada'));
    } else {
      addAccount(cuenta);
      notify(tipo === 'bank' ? t('cuentaForm.cuentaAgregada') : t('cuentaForm.tarjetaAgregada'));
    }
    onDone();
  }

  const listaId = `bancos-${pais}`;

  return (
    <>
      {!editando && (
        <div style={{ marginBottom: 'var(--e5)' }}>
          <Segmented options={TIPOS} value={tipo} onChange={setTipo} label={t('cuentaForm.tipoDeCuenta')} />
        </div>
      )}

      <p className="campo__etiqueta">País</p>
      <div style={{ marginBottom: 'var(--e4)' }}>
        <Segmented options={PAISES} value={pais} onChange={setPais} label="País" />
      </div>

      <Field
        label="Banco"
        type="text"
        list={listaId}
        placeholder={pais === 'DO' ? 'Banreservas' : 'Chase'}
        value={banco}
        error={error('bank')}
        onChange={(event) => setBanco(event.target.value)}
      />
      <datalist id={listaId}>
        {BANCOS_SUGERIDOS[pais].map((nombre) => (
          <option key={nombre} value={nombre} />
        ))}
      </datalist>

      <Field
        label={t('cuentaForm.comoLaLlamas')}
        type="text"
        placeholder={tipo === 'bank' ? t('cuentaForm.miCuentaDeNomina') : 'Visa Popular'}
        hint={t('cuentaForm.opcionalUtilSiTienes')}
        value={apodo}
        onChange={(event) => setApodo(event.target.value)}
      />

      <Field
        label={t('cuentaForm.ultimosCuatroDigitos')}
        type="text"
        inputMode="numeric"
        maxLength={4}
        placeholder="4417"
        hint={t('cuentaForm.opcionalSoloParaReconocerla')}
        value={digitos}
        error={error('last4')}
        onChange={(event) => setDigitos(event.target.value.replace(/\D/g, '').slice(0, 4))}
      />

      {tipo === 'bank' ? (
        <>
          <p className="campo__etiqueta">
            {editando ? t('cuentaForm.ajustarSaldo') : t('cuentaForm.saldoActual')}
          </p>
          {monedas.length > 1 && (
            <p className="campo__ayuda" style={{ marginBottom: 'var(--e3)' }}>{t('cuentaForm.dejaEnBlancoLa')}</p>
          )}
          {monedas.includes('DOP') && (
            <Field
              label={monedas.length > 1 ? 'En pesos' : 'Saldo'}
              type="text"
              inputMode="decimal"
              placeholder="0.00"
              value={saldoDOP}
              onChange={(event) => setSaldoDOP(event.target.value)}
            />
          )}
          {monedas.includes('USD') && (
            <Field
              label={monedas.length > 1 ? 'En dólares' : 'Saldo'}
              type="text"
              inputMode="decimal"
              placeholder="0.00"
              value={saldoUSD}
              onChange={(event) => setSaldoUSD(event.target.value)}
            />
          )}
          {editando && (
            <div style={{ marginBottom: 'var(--e4)' }}>
              <Notice tone="azul" icon="ℹ️">{t('cuentaForm.cambiarElSaldoAqui')}</Notice>
            </div>
          )}
        </>
      ) : (
        <>
          {monedas.includes('DOP') && (
            <>
              {monedas.length > 1 && <p className="campo__etiqueta">En pesos</p>}
              <div className="grid-2">
                <Field
                  label="Límite"
                  type="text"
                  inputMode="decimal"
                  placeholder="0.00"
                  value={limiteDOP}
                  onChange={(event) => setLimiteDOP(event.target.value)}
                />
                <Field
                  label="Usado"
                  type="text"
                  inputMode="decimal"
                  placeholder="0.00"
                  value={usadoDOP}
                  error={error('used-DOP')}
                  onChange={(event) => setUsadoDOP(event.target.value)}
                />
              </div>
            </>
          )}

          {monedas.includes('USD') && (
            <>
              {monedas.length > 1 && <p className="campo__etiqueta">En dólares</p>}
              <div className="grid-2">
                <Field
                  label="Límite"
                  type="text"
                  inputMode="decimal"
                  placeholder="0.00"
                  value={limiteUSD}
                  onChange={(event) => setLimiteUSD(event.target.value)}
                />
                <Field
                  label="Usado"
                  type="text"
                  inputMode="decimal"
                  placeholder="0.00"
                  value={usadoUSD}
                  error={error('used-USD')}
                  onChange={(event) => setUsadoUSD(event.target.value)}
                />
              </div>
            </>
          )}

          {error('limits') && <p className="campo__error">{error('limits')}</p>}

          <div className="grid-2">
            <Field
              label={t('cuentaForm.diaDeCorte')}
              type="number"
              min={1}
              max={31}
              placeholder="15"
              value={corte}
              error={error('statementDay')}
              onChange={(event) => setCorte(event.target.value)}
            />
            <Field
              label={t('cuentaForm.diaDePago')}
              type="number"
              min={1}
              max={31}
              placeholder="5"
              value={pago}
              error={error('dueDay')}
              onChange={(event) => setPago(event.target.value)}
            />
          </div>
        </>
      )}

      <div className="hoja__pie">
        <Button wide onClick={guardar}>
          {editando ? t('cuentaForm.guardarCambios') : tipo === 'bank' ? t('cuentaForm.agregarCuenta') : t('cuentaForm.agregarTarjeta')}
        </Button>
      </div>
    </>
  );
}
