/**
 * Agregados para los reportes.
 *
 * Todo lo que mira al pasado usa la tasa que guardó cada movimiento, nunca la
 * de hoy: un reporte de marzo tiene que decir lo mismo en diciembre.
 */

import type { AppData, Transaction } from './types';
import type { Cents, Currency } from '../lib/money';
import type { YearMonth } from '../lib/date';
import { lastMonths } from '../lib/date';
import { monthTotals, transactionIn, transactionsOfMonth } from './compute';

export interface CategorySpend {
  categoryId: string;
  name: string;
  icon: string;
  amount: Cents;
  /** Parte del gasto total del mes, de 0 a 100. */
  share: number;
  count: number;
}

/** En qué se fue el dinero este mes, de mayor a menor. */
export function spendByCategory(
  data: AppData,
  month: YearMonth,
  target: Currency,
): CategorySpend[] {
  const porCategoria = new Map<string, { amount: Cents; count: number }>();

  for (const tx of transactionsOfMonth(data, month)) {
    if (tx.kind !== 'expense') continue;
    const actual = porCategoria.get(tx.categoryId) ?? { amount: 0, count: 0 };
    actual.amount += transactionIn(tx, target);
    actual.count += 1;
    porCategoria.set(tx.categoryId, actual);
  }

  const total = [...porCategoria.values()].reduce((suma, item) => suma + item.amount, 0);

  return [...porCategoria.entries()]
    .map(([categoryId, { amount, count }]) => {
      const categoria = data.categories.find((item) => item.id === categoryId);
      return {
        categoryId,
        name: categoria?.name ?? 'Sin categoría',
        icon: categoria?.icon ?? '•',
        amount,
        share: total > 0 ? Math.round((amount / total) * 100) : 0,
        count,
      };
    })
    .sort((a, b) => b.amount - a.amount);
}

export interface MonthPoint {
  month: YearMonth;
  income: Cents;
  expense: Cents;
  /** Lo que entró menos lo que salió. Negativo es que gastaste de más. */
  net: Cents;
}

/** Los últimos meses, del más viejo al más nuevo. */
export function monthSeries(
  data: AppData,
  month: YearMonth,
  count: number,
  target: Currency,
): MonthPoint[] {
  return lastMonths(month, count).map((mes) => {
    const { income, expense } = monthTotals(data, mes, target);
    return { month: mes, income, expense, net: income - expense };
  });
}

/** Gasto promedio de los meses anteriores a este, sin contar los vacíos. */
export function averageExpense(
  data: AppData,
  month: YearMonth,
  count: number,
  target: Currency,
): Cents {
  const previos = monthSeries(data, month, count + 1, target).slice(0, -1);
  const conMovimiento = previos.filter((punto) => punto.expense > 0);
  if (conMovimiento.length === 0) return 0;
  const suma = conMovimiento.reduce((total, punto) => total + punto.expense, 0);
  return Math.round(suma / conMovimiento.length);
}

export interface CategoryChange {
  categoryId: string;
  name: string;
  icon: string;
  now: Cents;
  before: Cents;
  /** Cuánto cambió en porcentaje. 50 es "gastaste un 50% más". */
  percent: number;
}

/**
 * Categorías donde el gasto se salió de lo normal comparado con el promedio
 * de los meses anteriores. Solo mira montos que valgan la pena mencionar.
 */
export function unusualCategories(
  data: AppData,
  month: YearMonth,
  target: Currency,
  minimo: Cents,
): CategoryChange[] {
  const previos = lastMonths(month, 4).slice(0, -1);
  if (previos.length === 0) return [];

  const ahora = spendByCategory(data, month, target);
  const cambios: CategoryChange[] = [];

  for (const actual of ahora) {
    if (actual.amount < minimo) continue;

    const historico = previos.map(
      (mes) =>
        spendByCategory(data, mes, target).find((item) => item.categoryId === actual.categoryId)
          ?.amount ?? 0,
    );
    const conGasto = historico.filter((valor) => valor > 0);
    if (conGasto.length === 0) continue;

    const promedio = Math.round(conGasto.reduce((a, b) => a + b, 0) / conGasto.length);
    if (promedio <= 0) continue;

    const porcentaje = Math.round(((actual.amount - promedio) / promedio) * 100);
    if (porcentaje < 50) continue;

    cambios.push({
      categoryId: actual.categoryId,
      name: actual.name,
      icon: actual.icon,
      now: actual.amount,
      before: promedio,
      percent: porcentaje,
    });
  }

  return cambios.sort((a, b) => b.percent - a.percent);
}

/** El movimiento más grande del mes, para explicar un mes raro. */
export function biggestExpense(
  data: AppData,
  month: YearMonth,
  target: Currency,
): Transaction | undefined {
  let mayor: Transaction | undefined;
  let monto = 0;

  for (const tx of transactionsOfMonth(data, month)) {
    if (tx.kind !== 'expense') continue;
    const valor = transactionIn(tx, target);
    if (valor > monto) {
      monto = valor;
      mayor = tx;
    }
  }

  return mayor;
}
