/**
 * Elegir moneda.
 *
 * Si la persona solo puede usar una, no se muestra nada: un selector con una
 * sola opción es ruido. La forma de abrir la otra se explica en la pantalla
 * de planes, no poniéndole un candado a cada formulario.
 */

import { useEffect } from 'react';
import { Segmented } from './forms';
import { useMonedasPermitidas } from '../store/useMonedas';
import type { Currency } from '../lib/money';

const ETIQUETAS: Record<Currency, string> = {
  DOP: 'RD$ Pesos',
  USD: 'US$ Dólares',
};

export function SelectorMoneda({
  value,
  onChange,
  label = 'Moneda',
}: {
  value: Currency;
  onChange: (moneda: Currency) => void;
  label?: string;
}) {
  const monedas = useMonedasPermitidas();

  // Si la moneda elegida dejó de estar permitida, se vuelve a la que sí
  useEffect(() => {
    const primera = monedas[0];
    if (primera && !monedas.includes(value)) onChange(primera);
  }, [monedas, value, onChange]);

  if (monedas.length < 2) return null;

  return (
    <>
      <p className="campo__etiqueta">{label}</p>
      <div style={{ marginBottom: 'var(--e4)' }}>
        <Segmented
          options={monedas.map((moneda) => ({ value: moneda, label: ETIQUETAS[moneda] }))}
          value={value}
          onChange={onChange}
          label={label}
        />
      </div>
    </>
  );
}
