/**
 * Estado de la aplicación.
 *
 * Una sola fuente de verdad: el objeto AppData. Cada cambio se aplica sobre
 * una copia, se guarda en el dispositivo y se publica a las pantallas.
 */

import { create } from 'zustand';
import type {
  Account,
  AppData,
  Budget,
  Country,
  Debt,
  ExpenseTx,
  Goal,
  Recurrence,
  ThemePreference,
  Transaction,
} from '../domain/types';
import type { Cents } from '../lib/money';
import type { MigrationReport } from './migrate';
import { applyTransaction, revertTransaction } from '../domain/ledger';
import { isEmptyData } from '../domain/accounts';
import { dateForMonth, dueRecurrences, transactionFrom } from '../domain/recurrences';
import { currentYearMonth, today } from '../lib/date';
import { newId } from '../lib/id';
import { createEmptyData } from './schema';
import { fromBackupFile, load, recoverFromDevice, save, wipe } from './persist';
import { hashPin, verifyPin } from '../lib/pin';
import { buscarTasa } from '../lib/fx';

/** Copia profunda, con respaldo para navegadores sin structuredClone. */
function clone<T>(value: T): T {
  if (typeof structuredClone === 'function') return structuredClone(value);
  return JSON.parse(JSON.stringify(value)) as T;
}

export interface AppStore {
  data: AppData;
  /** false hasta que se leyeron los datos del dispositivo. */
  ready: boolean;
  /** Resumen de la migración, si la hubo. Se muestra una vez. */
  migration?: MigrationReport;
  /** Mensaje breve que se muestra abajo. */
  note: string | null;
  /** De dónde salieron los datos al arrancar. */
  origin: 'nuevo' | 'guardado' | 'migrado';
  /** false cuando hay PIN puesto y todavía no se ha entrado. */
  unlocked: boolean;
  /** Intentos fallidos seguidos. Vive en memoria, no se guarda. */
  failedAttempts: number;

  init: () => void;
  /** Cambia los datos y los guarda. */
  edit: (recipe: (draft: AppData) => void) => void;

  /** Guarda un movimiento y mueve los saldos que toque. */
  addTransaction: (tx: Transaction) => void;
  /** Borra un movimiento y deshace su efecto en los saldos. */
  removeTransaction: (id: string) => void;
  /** Corrige un movimiento: deshace el viejo y aplica el nuevo. */
  replaceTransaction: (id: string, tx: Transaction) => void;

  /** Agrega una cuenta de banco o una tarjeta. */
  addAccount: (account: Account) => void;
  /** Cambia los datos de una cuenta que ya existe. */
  updateAccount: (id: string, patch: Partial<Account>) => void;
  /** La oculta sin tocar el historial. */
  archiveAccount: (id: string) => void;
  /** La borra de verdad. Solo tiene sentido si ningún movimiento la usa. */
  deleteAccount: (id: string) => void;

  addBudget: (budget: Budget) => void;
  updateBudget: (id: string, patch: Partial<Budget>) => void;
  removeBudget: (id: string) => void;

  addDebt: (debt: Debt) => void;
  updateDebt: (id: string, patch: Partial<Debt>) => void;
  removeDebt: (id: string) => void;
  /** Registra un pago: baja la deuda y sale de la cuenta elegida. */
  payDebt: (id: string, amount: Cents, accountId?: string) => void;

  addGoal: (goal: Goal) => void;
  updateGoal: (id: string, patch: Partial<Goal>) => void;
  removeGoal: (id: string) => void;
  /** Aparta dinero que ya está en el banco. No mueve ningún saldo. */
  reserveInGoal: (id: string, amount: Cents) => void;
  /** Suelta dinero apartado para poder gastarlo. */
  releaseFromGoal: (id: string, amount: Cents) => void;

  addRecurrence: (recurrence: Recurrence) => void;
  updateRecurrence: (id: string, patch: Partial<Recurrence>) => void;
  removeRecurrence: (id: string) => void;
  /** Registra un recurrente ahora, aunque esté en manual. */
  applyRecurrence: (id: string) => void;
  /** Registra los que ya tocaban y están en automático. Devuelve cuántos. */
  applyDueRecurrences: () => number;

  setTheme: (theme: ThemePreference) => void;
  togglePrivacy: () => void;
  /** Cambia la tasa del día y deja constancia de cuándo. */
  setRate: (dopPerUsd: number) => void;
  /** Busca la tasa de hoy en internet. Devuelve true si la cambió. */
  refreshRate: () => Promise<boolean>;

  /** Pone el nombre con que se saluda al abrir. Vacío lo quita. */
  setName: (nombre: string) => void;

  /** Pone o cambia el PIN de entrada. */
  setPin: (pin: string) => Promise<void>;
  /** Quita el PIN. Hay que saber el actual. */
  clearPin: (pin: string) => Promise<boolean>;
  /** Intenta entrar. Devuelve si el PIN era el bueno. */
  unlock: (pin: string) => Promise<boolean>;
  /** Vuelve a cerrar la app. */
  lock: () => void;

  /** Termina el primer arranque: fija el país y su moneda. */
  completarBienvenida: (country: Country) => void;
  /** Reemplaza todo con el contenido de un respaldo. */
  restoreBackup: (raw: string) => boolean;
  /**
   * Si el teléfono arrancó vacío, mira si el sistema guardó una copia.
   * Devuelve true si rescató algo.
   */
  recoverIfEmpty: () => Promise<boolean>;
  /** Mete de golpe los movimientos de un archivo importado. */
  importTransactions: (txs: readonly Transaction[]) => number;
  /** Reemplaza todo con lo que bajó de la nube. */
  restoreFromCloud: (datos: AppData) => boolean;
  /** Deja constancia de la copia que se acaba de subir. */
  markBackedUp: (at: string, count: number) => void;
  /** Deja la app como recién instalada. La usa "borrar mis datos" y las pruebas. */
  resetAll: () => void;
  notify: (text: string) => void;
  clearNote: () => void;
  dismissMigration: () => void;
}

function horasDesde(iso: string): number {
  const fecha = new Date(iso).getTime();
  if (Number.isNaN(fecha)) return Infinity;
  return (Date.now() - fecha) / 3600000;
}

export const useApp = create<AppStore>((set, get) => ({
  data: createEmptyData(),
  ready: false,
  note: null,
  origin: 'nuevo',
  unlocked: true,
  failedAttempts: 0,

  init: () => {
    // React llama dos veces a los efectos en desarrollo. Sin esta guarda, el
    // segundo arranque lee los datos ya migrados y borra el aviso de migración
    // antes de que la persona alcance a leerlo.
    if (get().ready) return;

    const result = load();
    set({
      data: result.data,
      ready: true,
      origin: result.origin,
      migration: result.migration,
      note: result.error ?? null,
      // Si hay PIN puesto, la app arranca cerrada
      unlocked: result.data.settings.pinHash === undefined,
    });
  },

  edit: (recipe) => {
    const draft = clone(get().data);
    recipe(draft);
    draft.updatedAt = new Date().toISOString();
    const saved = save(draft);
    set({ data: draft, note: saved ? get().note : 'No se pudo guardar en este dispositivo.' });
  },

  addTransaction: (tx) => {
    get().edit((draft) => {
      draft.transactions.unshift(tx);
      applyTransaction(draft, tx);
    });
  },

  removeTransaction: (id) => {
    get().edit((draft) => {
      const tx = draft.transactions.find((movimiento) => movimiento.id === id);
      if (!tx) return;
      revertTransaction(draft, tx);
      draft.transactions = draft.transactions.filter((movimiento) => movimiento.id !== id);
    });
  },

  addAccount: (account) => {
    get().edit((draft) => {
      draft.accounts.push(account);
    });
  },

  updateAccount: (id, patch) => {
    get().edit((draft) => {
      const indice = draft.accounts.findIndex((cuenta) => cuenta.id === id);
      const actual = draft.accounts[indice];
      if (!actual) return;
      draft.accounts[indice] = { ...actual, ...patch, id, updatedAt: new Date().toISOString() };
    });
  },

  archiveAccount: (id) => {
    get().updateAccount(id, { archived: true });
  },

  deleteAccount: (id) => {
    get().edit((draft) => {
      draft.accounts = draft.accounts.filter((cuenta) => cuenta.id !== id);
    });
  },

  replaceTransaction: (id, tx) => {
    get().edit((draft) => {
      const indice = draft.transactions.findIndex((movimiento) => movimiento.id === id);
      const anterior = draft.transactions[indice];
      if (!anterior) return;

      // Primero se deshace el efecto del viejo, luego se aplica el nuevo
      revertTransaction(draft, anterior);
      const actualizado = { ...tx, id, createdAt: anterior.createdAt, updatedAt: new Date().toISOString() };
      draft.transactions[indice] = actualizado;
      applyTransaction(draft, actualizado);
    });
  },

  addBudget: (budget) => {
    get().edit((draft) => {
      // Una categoría no puede tener dos presupuestos a la vez
      draft.budgets = draft.budgets.filter((item) => item.categoryId !== budget.categoryId);
      draft.budgets.push(budget);
    });
  },

  updateBudget: (id, patch) => {
    get().edit((draft) => {
      const indice = draft.budgets.findIndex((item) => item.id === id);
      const actual = draft.budgets[indice];
      if (!actual) return;
      draft.budgets[indice] = { ...actual, ...patch, id };
    });
  },

  removeBudget: (id) => {
    get().edit((draft) => {
      draft.budgets = draft.budgets.filter((item) => item.id !== id);
    });
  },

  addDebt: (debt) => {
    get().edit((draft) => {
      draft.debts.push(debt);
    });
  },

  updateDebt: (id, patch) => {
    get().edit((draft) => {
      const indice = draft.debts.findIndex((item) => item.id === id);
      const actual = draft.debts[indice];
      if (!actual) return;
      draft.debts[indice] = { ...actual, ...patch, id, updatedAt: new Date().toISOString() };
    });
  },

  removeDebt: (id) => {
    get().edit((draft) => {
      draft.debts = draft.debts.filter((item) => item.id !== id);
      // Los pagos que ya se registraron quedan como gastos, pero sueltos
      for (const tx of draft.transactions) {
        if (tx.kind === 'expense' && tx.debtId === id) delete tx.debtId;
      }
    });
  },

  payDebt: (id, amount, accountId) => {
    get().edit((draft) => {
      const debt = draft.debts.find((item) => item.id === id);
      if (!debt || amount <= 0) return;

      const ahora = new Date().toISOString();
      const tx: ExpenseTx = {
        id: newId(),
        kind: 'expense',
        date: today(),
        amount: Math.min(amount, debt.balance),
        currency: debt.currency,
        categoryId: 'deuda',
        debtId: id,
        fxRate: draft.fx.dopPerUsd,
        note: debt.name,
        createdAt: ahora,
        updatedAt: ahora,
      };
      if (accountId) tx.accountId = accountId;

      draft.transactions.unshift(tx);
      // El ledger baja la deuda y la cuenta a la vez
      applyTransaction(draft, tx);
    });
  },

  addGoal: (goal) => {
    get().edit((draft) => {
      draft.goals.push(goal);
    });
  },

  updateGoal: (id, patch) => {
    get().edit((draft) => {
      const indice = draft.goals.findIndex((item) => item.id === id);
      const actual = draft.goals[indice];
      if (!actual) return;
      draft.goals[indice] = { ...actual, ...patch, id, updatedAt: new Date().toISOString() };
    });
  },

  removeGoal: (id) => {
    get().edit((draft) => {
      draft.goals = draft.goals.filter((item) => item.id !== id);
    });
  },

  reserveInGoal: (id, amount) => {
    get().edit((draft) => {
      const goal = draft.goals.find((item) => item.id === id);
      if (!goal || amount <= 0) return;
      goal.saved += amount;
      goal.updatedAt = new Date().toISOString();
    });
  },

  releaseFromGoal: (id, amount) => {
    get().edit((draft) => {
      const goal = draft.goals.find((item) => item.id === id);
      if (!goal || amount <= 0) return;
      goal.saved = Math.max(0, goal.saved - amount);
      goal.updatedAt = new Date().toISOString();
    });
  },

  addRecurrence: (recurrence) => {
    get().edit((draft) => {
      draft.recurrences.push(recurrence);
    });
  },

  updateRecurrence: (id, patch) => {
    get().edit((draft) => {
      const indice = draft.recurrences.findIndex((item) => item.id === id);
      const actual = draft.recurrences[indice];
      if (!actual) return;
      draft.recurrences[indice] = {
        ...actual,
        ...patch,
        id,
        updatedAt: new Date().toISOString(),
      };
    });
  },

  removeRecurrence: (id) => {
    get().edit((draft) => {
      draft.recurrences = draft.recurrences.filter((item) => item.id !== id);
    });
  },

  applyRecurrence: (id) => {
    get().edit((draft) => {
      const recurrence = draft.recurrences.find((item) => item.id === id);
      if (!recurrence) return;

      const mes = currentYearMonth();
      const tx = transactionFrom(recurrence, draft, dateForMonth(recurrence, mes));
      draft.transactions.unshift(tx);
      applyTransaction(draft, tx);
      recurrence.lastAppliedMonth = mes;
      recurrence.updatedAt = new Date().toISOString();
    });
  },

  applyDueRecurrences: () => {
    const pendientes = dueRecurrences(get().data);
    if (pendientes.length === 0) return 0;

    get().edit((draft) => {
      const mes = currentYearMonth();
      for (const pendiente of pendientes) {
        const recurrence = draft.recurrences.find((item) => item.id === pendiente.id);
        if (!recurrence) continue;

        const tx = transactionFrom(recurrence, draft, dateForMonth(recurrence, mes));
        draft.transactions.unshift(tx);
        applyTransaction(draft, tx);
        recurrence.lastAppliedMonth = mes;
        recurrence.updatedAt = new Date().toISOString();
      }
    });

    return pendientes.length;
  },

  setRate: (dopPerUsd) => {
    get().edit((draft) => {
      draft.fx.dopPerUsd = dopPerUsd;
      draft.fx.updatedAt = new Date().toISOString();
      draft.fx.source = 'manual';
    });
  },

  refreshRate: async () => {
    const actual = get().data.fx;

    // Lo que la persona escribió a mano manda: ella sabe a cómo le cambian
    if (actual.source === 'manual') return false;

    // La tasa no cambia por minuto, y esto corre en cada arranque
    if (actual.source === 'auto' && horasDesde(actual.updatedAt) < 20) return false;

    const tasa = await buscarTasa();
    if (tasa === null) return false;

    get().edit((draft) => {
      draft.fx.dopPerUsd = tasa;
      draft.fx.updatedAt = new Date().toISOString();
      draft.fx.source = 'auto';
    });
    return true;
  },

  setName: (nombre) => {
    const limpio = nombre.trim();
    get().edit((draft) => {
      // Vacío no se guarda como cadena vacía: se quita, y la app vuelve a
      // saludar sin llamar a nadie.
      if (limpio) draft.profile.name = limpio;
      else delete draft.profile.name;
    });
  },

  setPin: async (pin) => {
    const hash = await hashPin(pin);
    get().edit((draft) => {
      draft.settings.pinHash = hash;
    });
    set({ unlocked: true, failedAttempts: 0 });
  },

  clearPin: async (pin) => {
    const guardado = get().data.settings.pinHash;
    if (!guardado) return true;
    if (!(await verifyPin(pin, guardado))) {
      set({ failedAttempts: get().failedAttempts + 1 });
      return false;
    }
    get().edit((draft) => {
      delete draft.settings.pinHash;
      draft.settings.biometrics = false;
    });
    set({ unlocked: true, failedAttempts: 0 });
    return true;
  },

  unlock: async (pin) => {
    const guardado = get().data.settings.pinHash;
    if (!guardado) {
      set({ unlocked: true });
      return true;
    }
    if (await verifyPin(pin, guardado)) {
      set({ unlocked: true, failedAttempts: 0 });
      return true;
    }
    set({ failedAttempts: get().failedAttempts + 1 });
    return false;
  },

  lock: () => {
    if (get().data.settings.pinHash) set({ unlocked: false });
  },

  recoverIfEmpty: async () => {
    if (get().origin !== 'nuevo') return false;

    const rescatados = await recoverFromDevice();
    if (!rescatados) return false;
    if (isEmptyData(rescatados)) return false;

    set({
      data: rescatados,
      origin: 'guardado',
      unlocked: rescatados.settings.pinHash === undefined,
      note: 'Recuperé tus datos del respaldo del teléfono.',
    });
    return true;
  },

  importTransactions: (txs) => {
    if (txs.length === 0) return 0;
    get().edit((draft) => {
      for (const tx of txs) {
        draft.transactions.unshift(tx);
        applyTransaction(draft, tx);
      }
      // La cinta se lee de arriba abajo por fecha
      draft.transactions.sort((a, b) => b.date.localeCompare(a.date));
    });
    return txs.length;
  },

  completarBienvenida: (country) => {
    get().edit((draft) => {
      draft.profile.country = country;
      draft.profile.mainCurrency = country === 'US' ? 'USD' : 'DOP';
      draft.settings.onboardedAt = new Date().toISOString();
    });
  },

  restoreFromCloud: (datos) => {
    // Pasa por el mismo control que un archivo: si viene roto, no se toca nada
    const limpio = fromBackupFile(JSON.stringify({ data: datos }));
    if (!limpio) return false;
    set({ data: limpio, unlocked: limpio.settings.pinHash === undefined });
    save(limpio);
    return true;
  },

  markBackedUp: (at, count) => {
    get().edit((draft) => {
      draft.settings.lastBackup = { at, count };
    });
  },

  restoreBackup: (raw) => {
    const datos = fromBackupFile(raw);
    if (!datos) return false;
    set({ data: datos, unlocked: datos.settings.pinHash === undefined });
    save(datos);
    return true;
  },

  setTheme: (theme) => {
    get().edit((draft) => {
      draft.settings.theme = theme;
    });
  },

  togglePrivacy: () => {
    get().edit((draft) => {
      draft.settings.privacy = !draft.settings.privacy;
    });
  },

  resetAll: () => {
    // Sin borrar lo guardado, el próximo arranque volvería a leer lo viejo
    wipe();
    set({
      data: createEmptyData(),
      ready: false,
      migration: undefined,
      note: null,
      origin: 'nuevo',
      unlocked: true,
      failedAttempts: 0,
    });
  },

  notify: (text) => set({ note: text }),
  clearNote: () => set({ note: null }),
  dismissMigration: () => set({ migration: undefined }),
}));

/* --- Selectores de uso frecuente ------------------------------------------ */

export const useData = () => useApp((state) => state.data);
export const useSettings = () => useApp((state) => state.data.settings);
export const useProfile = () => useApp((state) => state.data.profile);
export const usePrivacy = () => useApp((state) => state.data.settings.privacy);
