/**
 * Metas de ahorro.
 *
 * Apartar dinero no lo mueve de cuenta: el dinero sigue en el banco, pero
 * ya tiene dueño. Por eso aquí no se registran movimientos.
 */

import { useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData, usePrivacy } from '../../store/useApp';
import type { Goal } from '../../domain/types';
import type { Currency } from '../../lib/money';
import { Sheet } from '../../ui/overlays';
import { Amount } from '../../ui/Amount';
import { Button, Card, Empty, Notice } from '../../ui/primitives';
import { Field } from '../../ui/forms';
import { SelectorMoneda } from '../../ui/SelectorMoneda';
import { goalProgress, isLate, neededPerMonth, overReserved, validateGoal } from '../../domain/goals';
import { formatNumber, parseAmount } from '../../lib/money';
import { relativeDate } from '../../lib/date';
import { newId } from '../../lib/id';

const ICONOS = ['🎯', '✈️', '🏠', '🚗', '🎓', '💍', '🏥', '🎁', '📱', '🛟'];

type Vista = { modo: 'lista' } | { modo: 'detalle'; id: string } | { modo: 'forma'; id?: string };

export function MetasSheet({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [vista, setVista] = useState<Vista>({ modo: 'lista' });
  const data = useData();

  const meta = vista.modo === 'lista' ? undefined : data.goals.find((item) => item.id === vista.id);

  const titulo =
    vista.modo === 'lista'
      ? t('metas.metasDeAhorro')
      : vista.modo === 'detalle'
        ? (meta?.name ?? 'Meta')
        : meta
          ? 'Editar meta'
          : 'Nueva meta';

  return (
    <Sheet
      open={open}
      title={titulo}
      subtitle={vista.modo === 'lista' ? t('metas.dineroConNombreY') : undefined}
      onClose={() => {
        setVista({ modo: 'lista' });
        onClose();
      }}
      onBack={vista.modo === 'lista' ? undefined : () => setVista({ modo: 'lista' })}
    >
      {vista.modo === 'lista' && (
        <ListaMetas
          onNueva={() => setVista({ modo: 'forma' })}
          onAbrir={(id) => setVista({ modo: 'detalle', id })}
        />
      )}

      {vista.modo === 'detalle' && meta && (
        <DetalleMeta
          goal={meta}
          onEditar={() => setVista({ modo: 'forma', id: meta.id })}
        />
      )}

      {vista.modo === 'forma' && <MetaForm goal={meta} onDone={() => setVista({ modo: 'lista' })} />}
    </Sheet>
  );
}

function ListaMetas({ onNueva, onAbrir }: { onNueva: () => void; onAbrir: (id: string) => void }) {
  const data = useData();
  const privacy = usePrivacy();
  const activas = data.goals.filter((item) => !item.archived);

  const sobregiro = (['DOP', 'USD'] as const)
    .map((moneda) => ({ moneda, exceso: overReserved(data, moneda) }))
    .filter((item) => item.exceso > 0);

  if (activas.length === 0) {
    return (
      <Empty
        mark="🎯"
        title={t('metas.sinMetasTodavia')}
        text={t('metas.unViajeUnFondo')}
        action={<Button small onClick={onNueva}>{t('metas.crearMiPrimeraMeta')}</Button>}
      />
    );
  }

  return (
    <>
      {sobregiro.map(({ moneda, exceso }) => (
        <div key={moneda} className="seccion">
          <Notice tone="ambar" icon="⚠️">
            Tienes apartado{' '}
            <Amount cents={exceso} currency={moneda} size="menor" hidden={privacy} /> más de lo que hay
            en tus cuentas de banco. Revisa tus metas o tus saldos.
          </Notice>
        </div>
      ))}

      {activas.map((meta) => {
        const avance = goalProgress(meta);
        const atrasada = isLate(meta);
        const color = avance.done ? 'var(--verde)' : atrasada ? 'var(--ambar)' : 'var(--azul)';

        return (
          <Card key={meta.id} className="seccion">
            <button type="button" style={{ width: '100%', textAlign: 'left' }} onClick={() => onAbrir(meta.id)}>
              <div className="fila-entre" style={{ marginBottom: 8 }}>
                <span className="fila__titulo">
                  {meta.icon ?? '🎯'} {meta.name}
                </span>
                <span style={{ color, fontWeight: 600, fontSize: 'var(--t-menor)' }}>
                  {avance.percent}%
                </span>
              </div>

              <div className="bar">
                <div className="bar-fill" style={{ width: `${avance.percent}%`, background: color }} />
              </div>

              <p className="texto-menor" style={{ marginTop: 8 }}>
                <Amount cents={meta.saved} currency={meta.currency} size="menor" hidden={privacy} />
                {' de '}
                <Amount cents={meta.target} currency={meta.currency} size="menor" hidden={privacy} />
                {meta.targetDate && ` · ${relativeDate(meta.targetDate)}`}
              </p>
            </button>
          </Card>
        );
      })}

      <div className="seccion">
        <Button wide variant="contorno" onClick={onNueva}>{t('metas.agregarOtraMeta')}</Button>
      </div>
    </>
  );
}

function DetalleMeta({ goal, onEditar }: { goal: Goal; onEditar: () => void }) {
  const privacy = usePrivacy();
  const reserveInGoal = useApp((state) => state.reserveInGoal);
  const releaseFromGoal = useApp((state) => state.releaseFromGoal);
  const notify = useApp((state) => state.notify);

  const [monto, setMonto] = useState('');
  const [error, setError] = useState('');

  const avance = goalProgress(goal);
  const porMes = neededPerMonth(goal);
  const atrasada = isLate(goal);

  function mover(direccion: 'apartar' | 'soltar') {
    const cantidad = parseAmount(monto);
    if (!cantidad || cantidad <= 0) {
      setError(t('metas.escribeCuanto'));
      return;
    }
    if (direccion === 'apartar') {
      reserveInGoal(goal.id, cantidad);
      notify(t('metas.dineroApartado'));
    } else {
      releaseFromGoal(goal.id, cantidad);
      notify(t('metas.dineroLiberado'));
    }
    setMonto('');
    setError('');
  }

  return (
    <>
      <Card className="seccion">
        <div className="fila-entre">
          <span className="texto-menor">Apartado</span>
          <Amount cents={goal.saved} currency={goal.currency} size="grande" hidden={privacy} />
        </div>
        <div className="bar" style={{ marginTop: 'var(--e3)' }}>
          <div
            className="bar-fill"
            style={{
              width: `${avance.percent}%`,
              background: avance.done ? 'var(--verde)' : 'var(--azul)',
            }}
          />
        </div>
        <p className="texto-menor" style={{ marginTop: 8 }}>
          {avance.done ? (
            t('metas.llegasteALaMeta')
          ) : (
            <>
              Faltan <Amount cents={avance.left} currency={goal.currency} size="menor" hidden={privacy} />
              {' de '}
              <Amount cents={goal.target} currency={goal.currency} size="menor" hidden={privacy} />
            </>
          )}
        </p>
      </Card>

      {porMes !== null && (
        <div className="seccion">
          <Notice tone={atrasada ? 'ambar' : 'azul'} icon={atrasada ? '⚠️' : '📅'}>
            {atrasada ? (
              <>
                La fecha ya pasó y faltan{' '}
                <Amount cents={avance.left} currency={goal.currency} size="menor" hidden={privacy} />.
                Ponle una fecha nueva o ajusta el objetivo.
              </>
            ) : (
              <>
                Para llegar a tiempo tienes que apartar{' '}
                <Amount cents={porMes} currency={goal.currency} size="menor" hidden={privacy} /> cada mes.
              </>
            )}
          </Notice>
        </div>
      )}

      <Card className="seccion" title={t('metas.moverDinero')}>
        <Field
          label="Monto"
          type="text"
          inputMode="decimal"
          placeholder="0.00"
          value={monto}
          error={error}
          hint={t('metas.apartarNoMueveEl')}
          onChange={(event) => setMonto(event.target.value)}
        />
        <div className="fila-botones">
          <Button onClick={() => mover('apartar')}>Apartar</Button>
          <Button variant="contorno" onClick={() => mover('soltar')}>
            Soltar
          </Button>
        </div>
      </Card>

      <div className="hoja__pie">
        <Button wide variant="contorno" onClick={onEditar}>{t('metas.editarLaMeta')}</Button>
      </div>
    </>
  );
}

function MetaForm({ goal, onDone }: { goal?: Goal; onDone: () => void }) {
  const data = useData();
  const addGoal = useApp((state) => state.addGoal);
  const updateGoal = useApp((state) => state.updateGoal);
  const removeGoal = useApp((state) => state.removeGoal);
  const notify = useApp((state) => state.notify);

  const editando = goal !== undefined;
  const [nombre, setNombre] = useState(goal?.name ?? '');
  const [icono, setIcono] = useState(goal?.icon ?? '🎯');
  const [objetivo, setObjetivo] = useState(goal ? formatNumber(goal.target) : '');
  const [apartado, setApartado] = useState(goal ? formatNumber(goal.saved) : '');
  const [moneda, setMoneda] = useState<Currency>(goal?.currency ?? data.profile.mainCurrency);
  const [fecha, setFecha] = useState(goal?.targetDate ?? '');
  const [errores, setErrores] = useState<Record<string, string>>({});

  function guardar() {
    const ahora = new Date().toISOString();
    const candidata: Goal = {
      id: goal?.id ?? newId(),
      name: nombre.trim(),
      icon: icono,
      currency: moneda,
      target: parseAmount(objetivo) ?? 0,
      saved: parseAmount(apartado) ?? 0,
      createdAt: goal?.createdAt ?? ahora,
      updatedAt: ahora,
    };
    if (fecha) candidata.targetDate = fecha;

    const problemas = validateGoal(candidata);
    if (problemas.length > 0) {
      const mapa: Record<string, string> = {};
      for (const problema of problemas) mapa[problema.field] = problema.message;
      setErrores(mapa);
      return;
    }

    if (editando) {
      updateGoal(candidata.id, candidata);
      notify(t('metas.metaActualizada'));
    } else {
      addGoal(candidata);
      notify('Meta creada');
    }
    onDone();
  }

  function borrar() {
    if (!goal) return;
    removeGoal(goal.id);
    notify(t('metas.metaEliminada'));
    onDone();
  }

  return (
    <>
      <Field
        label="Nombre"
        type="text"
        placeholder={t('metas.viajeASantiago')}
        value={nombre}
        error={errores.name}
        onChange={(event) => setNombre(event.target.value)}
      />

      <p className="campo__etiqueta">Icono</p>
      <div className={t('metas.rejillaSeccion')}>
        {ICONOS.map((item) => (
          <button
            key={item}
            type="button"
            className="ficha"
            aria-pressed={icono === item}
            aria-label={`Icono ${item}`}
            onClick={() => setIcono(item)}
          >
            <span className="ficha__icono">{item}</span>
          </button>
        ))}
      </div>

      <Field
        label={t('metas.cuantoQuieresJuntar')}
        type="text"
        inputMode="decimal"
        placeholder="0.00"
        value={objetivo}
        error={errores.target}
        onChange={(event) => setObjetivo(event.target.value)}
      />

      <Field
        label={t('metas.yaTengoApartado')}
        type="text"
        inputMode="decimal"
        placeholder="0.00"
        value={apartado}
        error={errores.saved}
        hint={t('metas.dineroQueYaEsta')}
        onChange={(event) => setApartado(event.target.value)}
      />

      <SelectorMoneda value={moneda} onChange={setMoneda} />

      <Field
        label={t('metas.paraCuando')}
        type="date"
        placeholder="Opcional"
        value={fecha}
        hint={t('metas.conUnaFechaTe')}
        onChange={(event) => setFecha(event.target.value)}
      />

      <div className="hoja__pie">
        <Button wide onClick={guardar}>
          {editando ? t('metas.guardarCambios') : 'Crear meta'}
        </Button>
        {editando && (
          <Button wide variant="peligro" className="seccion" onClick={borrar}>{t('metas.eliminarMeta')}</Button>
        )}
      </div>
    </>
  );
}
