/**
 * La suscripción.
 *
 * Primero qué se lleva, después cuánto cuesta. Y en claro lo que casi
 * ninguna app dice: que lo esencial sigue siendo gratis.
 */

import { useEffect, useState } from 'react';
import { t } from '../../i18n';
import { usePremium } from '../../store/usePremium';
import { Sheet } from '../../ui/overlays';
import { Button, Card, Notice } from '../../ui/primitives';
import { Row } from '../../ui/Row';
import { explicar, precioDelPlan, textoDeEstado, todasLasFunciones } from '../../domain/premium';
import type { FuncionPremium } from '../../domain/premium';

export function PremiumSheet({
  open,
  onClose,
  desde,
}: {
  open: boolean;
  onClose: () => void;
  /** Desde qué función se abrió, para explicar esa primero. */
  desde?: FuncionPremium;
}) {
  const estado = usePremium((state) => state.estado);
  const planes = usePremium((state) => state.planes);
  const cargando = usePremium((state) => state.cargando);
  const cargarPlanes = usePremium((state) => state.cargarPlanes);
  const comprar = usePremium((state) => state.comprar);
  const restaurar = usePremium((state) => state.restaurar);

  const [error, setError] = useState('');

  useEffect(() => {
    if (open && !estado.sinTienda) void cargarPlanes();
  }, [open, estado.sinTienda, cargarPlanes]);

  async function elegir(productId: string) {
    const fallo = await comprar(productId);
    setError(fallo ?? '');
    if (!fallo && usePremium.getState().estado.activo) onClose();
  }

  async function recuperar() {
    const fallo = await restaurar();
    setError(fallo ?? '');
    if (!fallo) onClose();
  }

  // La función desde la que se llegó va primero
  const funciones = todasLasFunciones().sort((a, b) =>
    a === desde ? -1 : b === desde ? 1 : 0,
  );

  if (estado.activo) {
    return (
      <Sheet open={open} title="GestorRD Premium" subtitle={textoDeEstado(estado)} onClose={onClose}>
        <div className="seccion">
          <Notice tone="verde" icon="✅">{t('planes.tienesPremiumGraciasPor')}</Notice>
        </div>

        <Card className="seccion" title={t('planes.loQueTienesAbierto')}>
          {funciones.map((funcion) => {
            const detalle = explicar(funcion);
            return <Row key={funcion} icon={detalle.icono} title={detalle.titulo} />;
          })}
        </Card>

        <div className="hoja__pie">
          <p className="campo__ayuda">
            Para cambiar de plan o cancelar, ve a Ajustes del iPhone → tu nombre → Suscripciones.
            La app no puede hacerlo por ti.
          </p>
        </div>
      </Sheet>
    );
  }

  return (
    <Sheet
      open={open}
      title="GestorRD Premium"
      subtitle={t('planes.loEsencialSeguiraSiendo')}
      onClose={onClose}
    >
      <Card className="seccion" title={t('planes.queTeLlevas')}>
        {funciones.map((funcion) => {
          const detalle = explicar(funcion);
          return (
            <Row
              key={funcion}
              icon={detalle.icono}
              title={detalle.titulo}
              detail={detalle.texto}
              wrapDetail
            />
          );
        })}
      </Card>

      <div className="seccion">
        <Notice tone="azul" icon="🆓">
          Registrar gastos, tus cuentas y tarjetas, el presupuesto, los movimientos fijos, las
          deudas, las metas y el respaldo en archivo son gratis y van a seguir siéndolo.
        </Notice>
      </div>

      {error && (
        <div className="seccion">
          <Notice tone="roja" icon="⚠️">
            {error}
          </Notice>
        </div>
      )}

      {estado.sinTienda ? (
        <div className="seccion">
          <Notice tone="ambar" icon="📱">
            La suscripción se compra desde la app del iPhone. Aquí en el navegador no se puede
            cobrar.
          </Notice>
        </div>
      ) : planes.length === 0 ? (
        <p className={t('planes.textoMenorSeccion')}>
          {cargando ? t('planes.cargandoLosPlanes') : t('planes.losPlanesNoEstan')}
        </p>
      ) : (
        <div className="seccion">
          {planes.map((plan) => (
            <button
              key={plan.id}
              type="button"
              className="plan"
              disabled={cargando}
              onClick={() => void elegir(plan.id)}
            >
              <span className="plan__centro">
                <span className="plan__nombre">
                  {plan.periodo === 'anual' ? 'Un año' : 'Un mes'}
                </span>
                {plan.pruebaDias !== undefined && plan.pruebaDias > 0 && (
                  <span className="plan__detalle">
                    {plan.pruebaDias} días de prueba, y cancelas cuando quieras
                  </span>
                )}
              </span>
              <span className="plan__precio">{precioDelPlan(plan)}</span>
            </button>
          ))}
        </div>
      )}

      <div className="hoja__pie">
        <Button wide variant="texto" disabled={cargando} onClick={() => void recuperar()}>{t('planes.yaPagueRestaurarMi')}</Button>
        <p className="campo__ayuda" style={{ marginTop: 'var(--e2)' }}>{t('planes.seCobraATu')}</p>
      </div>
    </Sheet>
  );
}
