/**
 * Cambiar pesos por dólares, o al revés.
 *
 * La app propone el monto con la tasa de mercado, pero lo que manda es lo que
 * de verdad te dieron: si cambiaste US$500 y recibiste RD$31,000, la tasa fue
 * 62.00 aunque el mercado estuviera en 63.25. Esa es la tasa que se guarda.
 */

import { useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData } from '../../store/useApp';
import type { Cents, Currency } from '../../lib/money';
import type { ExchangeTx } from '../../domain/types';
import type { ValidationIssue } from '../../domain/ledger';
import { AmountInput } from '../../ui/AmountInput';
import { AccountPicker } from '../../ui/pickers';
import { Button, Notice } from '../../ui/primitives';
import { Field } from '../../ui/forms';
import { Icon } from '../../ui/Icon';
import { overdraftWarning, validateTransaction } from '../../domain/ledger';
import { convert, formatRate, impliedRate } from '../../lib/fx';
import { formatNumber, parseAmount } from '../../lib/money';
import { baseInicial, errorDe, sello } from './comun';
import { today } from '../../lib/date';

export function CambioForm({
  onDone,
  transaction,
}: {
  onDone: () => void;
  transaction?: ExchangeTx;
}) {
  const editando = transaction !== undefined;
  const data = useData();
  const addTransaction = useApp((state) => state.addTransaction);
  const replaceTransaction = useApp((state) => state.replaceTransaction);
  const notify = useApp((state) => state.notify);
  const mercado = data.fx.dopPerUsd;

  const [entregas, setEntregas] = useState<Cents | null>(transaction?.fromAmount ?? null);
  const [monedaEntrega, setMonedaEntrega] = useState<Currency>(
    transaction?.fromCurrency ?? 'USD',
  );
  const [recibes, setRecibes] = useState<Cents | null>(transaction?.toAmount ?? null);
  const [tocado, setTocado] = useState(editando);
  const [origen, setOrigen] = useState<string | undefined>(transaction?.fromAccountId);
  const [destino, setDestino] = useState<string | undefined>(transaction?.toAccountId);
  const [comision, setComision] = useState(
    transaction?.fee ? formatNumber(transaction.fee) : '',
  );
  const [base, setBase] = useState(() =>
    transaction ? { fecha: transaction.date, nota: transaction.note ?? '' } : baseInicial(),
  );
  const [problemas, setProblemas] = useState<ValidationIssue[]>([]);

  const monedaRecibo: Currency = monedaEntrega === 'USD' ? 'DOP' : 'USD';

  /** Mientras no toques el segundo monto, se calcula con la tasa de mercado. */
  function cambiarEntrega(valor: Cents | null) {
    setEntregas(valor);
    if (!tocado) {
      setRecibes(valor === null ? null : convert(valor, monedaEntrega, monedaRecibo, mercado));
    }
  }

  function voltear() {
    const nuevaEntrega = monedaRecibo;
    setMonedaEntrega(nuevaEntrega);
    setEntregas(recibes);
    setRecibes(entregas);
    const o = origen;
    setOrigen(destino);
    setDestino(o);
  }

  const tasaReal =
    entregas && recibes
      ? impliedRate(entregas, monedaEntrega, recibes, monedaRecibo)
      : null;

  /**
   * La tasa sin filtrar, para poder avisar cuando no tiene sentido.
   * impliedRate devuelve null si el resultado se sale de lo posible, y quedarse
   * callada ante un dedazo es peor que decirlo.
   */
  const tasaCruda =
    entregas && recibes
      ? monedaEntrega === 'USD'
        ? recibes / entregas
        : entregas / recibes
      : null;

  const diferencia =
    tasaReal !== null ? Math.round(((tasaReal - mercado) / mercado) * 1000) / 10 : null;

  function construir(): ExchangeTx {
    const tx: ExchangeTx = {
      ...sello(data),
      kind: 'exchange',
      date: base.fecha,
      fromAmount: entregas ?? 0,
      fromCurrency: monedaEntrega,
      toAmount: recibes ?? 0,
      toCurrency: monedaRecibo,
      // Lo que se guarda es la tasa que te dieron, no la del mercado
      fxRate: tasaReal ?? mercado,
    };
    if (origen) tx.fromAccountId = origen;
    if (destino) tx.toAccountId = destino;
    const cobro = parseAmount(comision);
    if (cobro && cobro > 0) tx.fee = cobro;
    if (base.nota.trim()) tx.note = base.nota.trim();
    return tx;
  }

  const aviso = !editando && entregas && origen ? overdraftWarning(data, construir()) : null;

  function guardar() {
    const tx = construir();
    const encontrados = validateTransaction(data, tx);
    setProblemas(encontrados);
    if (encontrados.length > 0) return;

    if (editando) {
      replaceTransaction(transaction.id, tx);
      notify(t('cambio.cambioCorregido'));
    } else {
      addTransaction(tx);
      notify(t('cambio.cambioGuardado'));
    }
    onDone();
  }

  return (
    <>
      <p className="campo__etiqueta">Entregas</p>
      <AmountInput
        cents={entregas}
        currency={monedaEntrega}
        onChange={cambiarEntrega}
        onCurrencyChange={(moneda) => {
          if (moneda !== monedaEntrega) voltear();
        }}
        autoFocus
        label={t('cambio.cuantoEntregas')}
      />
      {errorDe(problemas, 'fromAmount') && (
        <p className="campo__error" style={{ textAlign: 'center', marginTop: 0 }}>
          {errorDe(problemas, 'fromAmount')}
        </p>
      )}

      <div className="cambio__flecha" aria-hidden="true">
        <Icon name="flechaDer" size={20} />
      </div>

      <p className="campo__etiqueta">Recibes</p>
      <AmountInput
        cents={recibes}
        currency={monedaRecibo}
        onChange={(valor) => {
          setTocado(true);
          setRecibes(valor);
        }}
        label={t('cambio.cuantoRecibes')}
      />
      {errorDe(problemas, 'toAmount') && (
        <p className="campo__error" style={{ textAlign: 'center', marginTop: 0 }}>
          {errorDe(problemas, 'toAmount')}
        </p>
      )}

      {tasaReal === null && tasaCruda !== null && (
        <div style={{ marginBottom: 'var(--e4)' }}>
          <Notice tone="ambar" icon="🤔">
            Esos montos dan una tasa de {tasaCruda.toFixed(2)} pesos por dólar. Revisa las cifras,
            porque hoy el dólar está en {formatRate(mercado)}.
          </Notice>
        </div>
      )}

      {tasaReal !== null && (
        <div className="cambio__tasa">
          <span className="texto-menor">{t('cambio.teLaCambiaronA')}</span>
          <span className="monto" style={{ fontWeight: 600 }}>
            {formatRate(tasaReal)}
          </span>
        </div>
      )}

      {diferencia !== null && Math.abs(diferencia) >= 0.5 && (
        <div style={{ marginBottom: 'var(--e4)' }}>
          <Notice tone={diferencia > 0 ? 'verde' : 'ambar'} icon={diferencia > 0 ? '👍' : '📉'}>
            {diferencia > 0
              ? `Te dieron ${diferencia}% por encima del mercado, que hoy está en ${formatRate(mercado)}.`
              : `Te dieron ${Math.abs(diferencia)}% por debajo del mercado, que hoy está en ${formatRate(mercado)}.`}
          </Notice>
        </div>
      )}

      <p className="campo__etiqueta">{t('cambio.deDondeSale')}</p>
      <AccountPicker
        accounts={data.accounts}
        value={origen}
        onChange={setOrigen}
        currency={monedaEntrega}
        exclude={destino}
        banksOnly
      />

      <p className="campo__etiqueta" style={{ marginTop: 'var(--e5)' }}>{t('cambio.aDondeEntra')}</p>
      <AccountPicker
        accounts={data.accounts}
        value={destino}
        onChange={setDestino}
        currency={monedaRecibo}
        exclude={origen}
        banksOnly
      />
      {errorDe(problemas, 'toAccountId') && (
        <p className="campo__error">{errorDe(problemas, 'toAccountId')}</p>
      )}

      {aviso && (
        <div style={{ margin: 'var(--e4) 0' }}>
          <Notice tone="ambar" icon="⚠️">
            {aviso}
          </Notice>
        </div>
      )}

      <div style={{ marginTop: 'var(--e5)' }}>
        <Field
          label="Comisión"
          type="text"
          inputMode="decimal"
          placeholder="0.00"
          hint={`Lo que te cobraron aparte, en ${monedaEntrega === 'DOP' ? 'pesos' : 'dólares'}.`}
          value={comision}
          onChange={(event) => setComision(event.target.value)}
        />
        <Field
          label="Fecha"
          type="date"
          value={base.fecha}
          max={today()}
          onChange={(event) => setBase({ ...base, fecha: event.target.value })}
        />
        <Field
          label="Nota"
          type="text"
          placeholder={t('cambio.casaDeCambioDe')}
          value={base.nota}
          onChange={(event) => setBase({ ...base, nota: event.target.value })}
        />
      </div>

      <div className="hoja__pie">
        <Button wide onClick={guardar}>
          {editando ? t('cambio.guardarCambios') : t('cambio.guardarCambio')}
        </Button>
      </div>
    </>
  );
}
