/**
 * Barra de arriba, igual en todas las pantallas.
 */

import type { ReactNode } from 'react';
import { Icon } from '../ui/Icon';
import type { IconName } from '../ui/Icon';

export interface TopBarAction {
  icon: IconName;
  label: string;
  onClick: () => void;
}

export function TopBar({
  title,
  actions = [],
  leading,
}: {
  title: string;
  actions?: TopBarAction[];
  leading?: ReactNode;
}) {
  return (
    <header className="barra-sup">
      {leading}
      <h1 className="barra-sup__titulo">{title}</h1>
      {actions.map((action) => (
        <button
          key={action.label}
          type="button"
          className="barra-sup__accion"
          onClick={action.onClick}
          aria-label={action.label}
        >
          <Icon name={action.icon} size={20} />
        </button>
      ))}
    </header>
  );
}
