/**
 * La tasa del dólar.
 *
 * Es manual a propósito: la tasa que te dan en el banco o en la remesadora
 * no es la del mercado, y para que las cuentas cuadren tiene que ser la tuya.
 */

import { useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData } from '../../store/useApp';
import { Sheet } from '../../ui/overlays';
import { Button, Notice } from '../../ui/primitives';
import { Field } from '../../ui/forms';
import { isValidRate } from '../../lib/fx';
import { relativeDate, toIsoDate } from '../../lib/date';

export function TasaSheet({ open, onClose }: { open: boolean; onClose: () => void }) {
  const data = useData();
  const setRate = useApp((state) => state.setRate);
  const notify = useApp((state) => state.notify);

  const [valor, setValor] = useState(String(data.fx.dopPerUsd));
  const [error, setError] = useState('');

  function guardar() {
    const numero = Number(valor.replace(',', '.'));
    if (!isValidRate(numero)) {
      setError(t('tasa.escribeCuantosPesosVale'));
      return;
    }
    setRate(numero);
    notify(t('tasa.tasaActualizada'));
    onClose();
  }

  const actualizada = data.fx.updatedAt ? relativeDate(toIsoDate(new Date(data.fx.updatedAt))) : null;

  return (
    <Sheet open={open} title={t('tasa.tasaDelDolar')} subtitle={t('tasa.pesosPorUnDolar')} onClose={onClose}>
      <Field
        label={t('tasa.unDolarSon')}
        type="text"
        inputMode="decimal"
        value={valor}
        error={error}
        hint={actualizada ? `La cambiaste ${actualizada}.` : undefined}
        onChange={(event) => setValor(event.target.value)}
      />

      <div className="seccion">
        <Notice tone="azul" icon="💱">
          Esta tasa se usa para los saldos de hoy. Los movimientos viejos guardaron la tasa del día
          en que pasaron, así que un reporte del mes pasado no cambia cuando el dólar sube.
        </Notice>
      </div>

      <div className="hoja__pie">
        <Button wide onClick={guardar}>{t('tasa.guardarLaTasa')}</Button>
      </div>
    </Sheet>
  );
}
