/**
 * Cálculos sobre los datos.
 *
 * Dos reglas que no se mezclan:
 *  - Los saldos de hoy se convierten con la tasa de hoy, porque el dinero que
 *    tienes ahora vale lo que vale ahora.
 *  - Los movimientos del pasado se convierten con la tasa que guardó cada uno,
 *    para que un reporte viejo no cambie cada vez que se mueve el dólar.
 */

import type { Account, AppData, Transaction } from './types';
import type { Cents, Currency } from '../lib/money';
import type { YearMonth } from '../lib/date';
import { convert } from '../lib/fx';
import { yearMonthOf } from '../lib/date';

/** Saldo de una cuenta en la moneda pedida, con la tasa de hoy. */
export function accountBalance(account: Account, target: Currency, rate: number): Cents {
  let total = 0;
  for (const currency of Object.keys(account.balances) as Currency[]) {
    const amount = account.balances[currency];
    if (amount === undefined) continue;
    total += convert(amount, currency, target, rate);
  }
  return total;
}

/**
 * Cuánto hay disponible de verdad: el dinero en los bancos.
 * Las tarjetas no cuentan aquí, porque su saldo es deuda, no dinero tuyo.
 */
export function availableBalance(data: AppData, target: Currency): Cents {
  return data.accounts
    .filter((account) => account.kind !== 'credit' && !account.archived)
    .reduce((total, account) => total + accountBalance(account, target, data.fx.dopPerUsd), 0);
}

/** Lo que se debe en tarjetas de crédito, como número positivo. */
export function cardDebt(data: AppData, target: Currency): Cents {
  const owed = data.accounts
    .filter((account) => account.kind === 'credit' && !account.archived)
    .reduce((total, account) => total + accountBalance(account, target, data.fx.dopPerUsd), 0);
  return Math.abs(Math.min(0, owed));
}

/** Lo que se debe en préstamos registrados. */
export function loanDebt(data: AppData, target: Currency): Cents {
  return data.debts
    .filter((debt) => !debt.archived)
    .reduce(
      (total, debt) => total + convert(debt.balance, debt.currency, target, data.fx.dopPerUsd),
      0,
    );
}

/**
 * Lo apartado en metas.
 *
 * Este dinero no es un bolsillo aparte: vive en una cuenta de banco y ya está
 * contado en availableBalance. Apartarlo solo significa que tiene dueño.
 */
export function savedInGoals(data: AppData, target: Currency): Cents {
  return data.goals
    .filter((goal) => !goal.archived)
    .reduce(
      (total, goal) => total + convert(goal.saved, goal.currency, target, data.fx.dopPerUsd),
      0,
    );
}

/**
 * El dinero del banco que no está apartado para ninguna meta:
 * lo que de verdad puedes gastar sin tocar tus ahorros.
 */
export function unreservedBalance(data: AppData, target: Currency): Cents {
  return availableBalance(data, target) - savedInGoals(data, target);
}

/**
 * Todo lo que tienes menos todo lo que debes.
 *
 * Las metas no se suman aquí: ese dinero ya está en una cuenta de banco,
 * y sumarlo otra vez lo contaría dos veces.
 */
export function netWorth(data: AppData, target: Currency): Cents {
  return availableBalance(data, target) - cardDebt(data, target) - loanDebt(data, target);
}

/** Convierte un movimiento usando la tasa que quedó guardada en él. */
export function transactionIn(tx: Transaction, target: Currency): Cents {
  if (tx.kind === 'exchange') {
    return convert(tx.toAmount, tx.toCurrency, target, tx.fxRate);
  }
  return convert(tx.amount, tx.currency, target, tx.fxRate);
}

export interface MonthTotals {
  income: Cents;
  expense: Cents;
  /** Lo que entró menos lo que salió. */
  flow: Cents;
}

/** Lo que entró y salió en un mes, en la moneda pedida. */
export function monthTotals(data: AppData, month: YearMonth, target: Currency): MonthTotals {
  let income = 0;
  let expense = 0;

  for (const tx of data.transactions) {
    if (yearMonthOf(tx.date) !== month) continue;
    if (tx.kind === 'income') income += transactionIn(tx, target);
    else if (tx.kind === 'expense') expense += transactionIn(tx, target);
  }

  return { income, expense, flow: income - expense };
}

/** Los movimientos de un mes, del más reciente al más viejo. */
export function transactionsOfMonth(data: AppData, month: YearMonth): Transaction[] {
  return data.transactions
    .filter((tx) => yearMonthOf(tx.date) === month)
    .sort((a, b) => (a.date === b.date ? b.createdAt.localeCompare(a.createdAt) : b.date.localeCompare(a.date)));
}

/** Agrupa movimientos por día, para dibujar la cinta. */
export function groupByDay(transactions: readonly Transaction[]): { date: string; items: Transaction[] }[] {
  const groups = new Map<string, Transaction[]>();

  for (const tx of transactions) {
    const list = groups.get(tx.date);
    if (list) list.push(tx);
    else groups.set(tx.date, [tx]);
  }

  return [...groups.entries()]
    .map(([date, items]) => ({ date, items }))
    .sort((a, b) => b.date.localeCompare(a.date));
}

/** Qué tipo de movimientos mostrar. */
export type TransactionFilter = 'todo' | 'gastos' | 'ingresos' | 'movimientos';

export function matchesFilter(tx: Transaction, filter: TransactionFilter): boolean {
  if (filter === 'todo') return true;
  if (filter === 'gastos') return tx.kind === 'expense';
  if (filter === 'ingresos') return tx.kind === 'income';
  return tx.kind === 'transfer' || tx.kind === 'exchange';
}

/**
 * Busca entre los movimientos por texto: la nota, la categoría, la fuente,
 * la cuenta o el monto escrito.
 */
export function searchTransactions(data: AppData, query: string): Transaction[] {
  const buscado = query.trim().toLowerCase();
  if (buscado.length < 2) return [];

  const nombreCategoria = new Map(data.categories.map((c) => [c.id, c.name.toLowerCase()]));
  const nombreFuente = new Map(data.incomeSources.map((s) => [s.id, s.name.toLowerCase()]));
  const nombreCuenta = new Map(
    data.accounts.map((a) => [a.id, (a.nickname ?? a.bank).toLowerCase()]),
  );

  return data.transactions.filter((tx) => {
    const partes: (string | undefined)[] = [tx.note?.toLowerCase()];

    if (tx.kind === 'expense') {
      partes.push(nombreCategoria.get(tx.categoryId), nombreCuenta.get(tx.accountId ?? ''));
      partes.push(String(tx.amount / 100));
    } else if (tx.kind === 'income') {
      partes.push(nombreFuente.get(tx.sourceId), nombreCuenta.get(tx.accountId ?? ''));
      partes.push(String(tx.amount / 100));
    } else if (tx.kind === 'transfer') {
      partes.push('transferencia', nombreCuenta.get(tx.fromAccountId), nombreCuenta.get(tx.toAccountId));
      partes.push(String(tx.amount / 100));
    } else {
      partes.push('cambio de moneda', nombreCuenta.get(tx.fromAccountId ?? ''));
      partes.push(String(tx.fromAmount / 100), String(tx.toAmount / 100));
    }

    return partes.some((parte) => parte?.includes(buscado));
  });
}
