/**
 * Monto en pantalla.
 *
 * Todos los montos de la app pasan por aquí, para que siempre estén
 * alineados en la misma columna monoespaciada y para que la moneda
 * se marque con su etiqueta en vez de con color.
 */

import type { Cents, Currency } from '../lib/money';
import { CURRENCY_TAG, formatNumber, signOf } from '../lib/money';

export type AmountSize = 'hero' | 'grande' | 'titulo' | 'normal' | 'menor';
export type AmountTone = 'normal' | 'positiva' | 'negativa' | 'apagada';

export interface AmountProps {
  cents: Cents;
  currency: Currency;
  size?: AmountSize;
  tone?: AmountTone;
  /** Muestra RD$ o US$ como etiqueta separada en vez del símbolo pegado. */
  tag?: boolean;
  /** Muestra el signo + en los positivos. */
  sign?: boolean;
  /** Modo privado: tapa la cifra. */
  hidden?: boolean;
  /** Omite los centavos cuando son exactos. */
  compact?: boolean;
  className?: string;
}

const SIZE_CLASS: Record<AmountSize, string> = {
  hero: 'cifra--hero',
  grande: 'cifra--grande',
  titulo: 'cifra--titulo',
  normal: 'cifra--normal',
  menor: 'cifra--menor',
};

const TONE_CLASS: Record<AmountTone, string> = {
  normal: '',
  positiva: 'cifra--positiva',
  negativa: 'cifra--negativa',
  apagada: 'cifra--apagada',
};

export function Amount({
  cents,
  currency,
  size = 'normal',
  tone = 'normal',
  tag = false,
  sign = false,
  hidden = false,
  compact = false,
  className,
}: AmountProps) {
  const classes = ['cifra', SIZE_CLASS[size], TONE_CLASS[tone], className]
    .filter(Boolean)
    .join(' ');

  const label = CURRENCY_TAG[currency];

  if (hidden) {
    return (
      <span className={classes}>
        {tag && <span className="moneda">{label}</span>}
        ••••
      </span>
    );
  }

  const body = formatNumber(cents, { compact });
  const prefix = signOf(cents, sign);

  // Texto plano para lectores de pantalla: "menos 1,234.56 pesos dominicanos"
  const spoken = `${cents < 0 ? 'menos ' : ''}${body} ${currency === 'DOP' ? 'pesos' : 'dólares'}`;

  return (
    <span className={classes} aria-label={spoken}>
      {tag ? (
        <>
          <span className="moneda" aria-hidden="true">
            {label}
          </span>
          <span aria-hidden="true">
            {prefix}
            {body}
          </span>
        </>
      ) : (
        <span aria-hidden="true">
          {prefix}
          {currency === 'DOP' ? 'RD$' : '$'}
          {body}
        </span>
      )}
    </span>
  );
}
