/**
 * Entrar a la cuenta.
 *
 * Con correo se manda un código de seis números, no un enlace: en el teléfono
 * un enlace abre otro navegador y la sesión se queda del otro lado.
 */

import { useEffect, useState } from 'react';
import { t } from '../../i18n';
import { useAuth } from '../../store/useAuth';
import { useApp, useData } from '../../store/useApp';
import { usePremiumActivo } from '../../store/usePremium';
import { Bloqueado } from '../premium/Bloqueado';
import { PremiumSheet } from '../premium/PremiumSheet';
import { Sheet } from '../../ui/overlays';
import { Button, Card, Notice } from '../../ui/primitives';
import { Row } from '../../ui/Row';
import { backupSizeMb, compareWithCloud, shouldOfferRestore } from '../../domain/cloud';
import { bajarCopia } from '../../store/bajarCopia';
import { relativeDate, toIsoDate } from '../../lib/date';

export function CuentaSheet({ open, onClose }: { open: boolean; onClose: () => void }) {
  const estado = useAuth((state) => state.estado);
  const email = useAuth((state) => state.email);

  return (
    <Sheet
      open={open}
      title={estado === 'dentro' ? 'Tu cuenta' : 'Entrar'}
      subtitle={estado === 'dentro' ? (email ?? undefined) : t('cuentaNube.paraGuardarUnaCopia')}
      onClose={onClose}
    >
      {estado === 'sin-config' ? (
        <Notice tone="ambar" icon="⚠️">
          La cuenta no está disponible en esta versión. Tus datos siguen guardados en el teléfono y
          puedes respaldarlos desde Ajustes.
        </Notice>
      ) : estado === 'dentro' ? (
        <Dentro onDone={onClose} />
      ) : (
        <Fuera />
      )}
    </Sheet>
  );
}

function Dentro({ onDone }: { onDone: () => void }) {
  const email = useAuth((state) => state.email);
  const signOut = useAuth((state) => state.signOut);
  const [confirmando, setConfirmando] = useState(false);

  return (
    <>
      <Card className="seccion">
        <Row title="Correo" right={<span className="texto-menor">{email}</span>} wrapDetail />
      </Card>

      <Nube />

      <div className="hoja__pie">
        {confirmando ? (
          <>
            <Notice tone="azul" icon="ℹ️">{t('cuentaNube.salirDeLaCuenta')}</Notice>
            <Button
              wide
              variant="peligro"
              className="seccion"
              onClick={() => {
                void signOut();
                onDone();
              }}
            >{t('cuentaNube.siSalirDeLa')}</Button>
            <Button wide variant="texto" onClick={() => setConfirmando(false)}>
              Mejor no
            </Button>
          </>
        ) : (
          <Button wide variant="contorno" onClick={() => setConfirmando(true)}>{t('cuentaNube.salirDeLaCuenta2')}</Button>
        )}
      </div>
    </>
  );
}

/**
 * La copia en la nube.
 *
 * Nada se sube ni se baja solo. Se muestran las dos cifras — lo que hay aquí
 * y lo que hay allá — y el botón que puede borrar algo lo dice antes.
 */
function Nube() {
  const premium = usePremiumActivo();
  const [planesAbiertos, setPlanesAbiertos] = useState(false);
  const data = useData();
  const cloud = useAuth((state) => state.cloud);
  const cloudEstado = useAuth((state) => state.cloudEstado);
  const fetchCloud = useAuth((state) => state.fetchCloud);
  const pushBackup = useAuth((state) => state.pushBackup);
  const markBackedUp = useApp((state) => state.markBackedUp);
  const notify = useApp((state) => state.notify);

  const [ocupado, setOcupado] = useState(false);
  const [error, setError] = useState('');
  const [confirmando, setConfirmando] = useState<'subir' | 'bajar' | null>(null);

  useEffect(() => {
    void fetchCloud();
  }, [fetchCloud]);

  const comparacion = compareWithCloud(data, cloud);
  const peso = backupSizeMb(data);
  const ofrecerBajar = shouldOfferRestore(data, cloud);

  if (!premium) {
    return (
      <>
        <Bloqueado funcion="nube" onAbrir={() => setPlanesAbiertos(true)} />
        <PremiumSheet
          open={planesAbiertos}
          desde="nube"
          onClose={() => setPlanesAbiertos(false)}
        />
        <p className="campo__ayuda seccion">{t('cuentaNube.elRespaldoEnArchivo')}</p>
      </>
    );
  }

  async function subir() {
    setOcupado(true);
    const fallo = await pushBackup(data);
    setOcupado(false);
    setConfirmando(null);

    if (fallo) {
      setError(fallo);
      return;
    }
    const ahora = useAuth.getState().cloud;
    if (ahora) markBackedUp(ahora.updatedAt, ahora.count);
    setError('');
    notify(t('cuentaNube.copiaGuardadaEnLa'));
  }

  async function bajar() {
    setOcupado(true);
    const fallo = await bajarCopia();
    setOcupado(false);
    setConfirmando(null);
    setError(fallo ?? '');
  }

  return (
    <>
      <Card className="seccion" title={t('cuentaNube.copiaEnLaNube')}>
        {cloudEstado === 'cargando' ? (
          <p className="texto-menor">Consultando…</p>
        ) : (
          <>
            <Row
              title={t('cuentaNube.enEsteTelefono')}
              right={<span className="texto-menor">{comparacion.localCount} movimientos</span>}
            />
            <Row
              title={t('cuentaNube.enLaNube')}
              detail={
                cloud
                  ? `${relativeDate(toIsoDate(new Date(cloud.updatedAt)))}${cloud.device ? ` · desde ${cloud.device}` : ''}`
                  : undefined
              }
              wrapDetail
              right={
                <span className="texto-menor">
                  {cloud ? `${cloud.count} movimientos` : 'Sin copia'}
                </span>
              }
            />
            <p className="texto-menor" style={{ marginTop: 'var(--e3)' }}>
              {comparacion.message}
            </p>
          </>
        )}
      </Card>

      {ofrecerBajar && (
        <div className="seccion">
          <Notice tone="azul" icon="📥">
            Este teléfono está vacío y en la nube hay una copia. Si cambiaste de equipo, bájala y
            sigue donde ibas.
          </Notice>
        </div>
      )}

      {error && (
        <div className="seccion">
          <Notice tone="roja" icon="⚠️">
            {error}
          </Notice>
        </div>
      )}

      {confirmando === 'subir' ? (
        <div className="seccion">
          <Notice tone="ambar" icon="⚠️">
            {comparacion.pushIsRisky
              ? `La copia de la nube tiene ${comparacion.cloudCount} movimientos y este teléfono ${comparacion.localCount}. Subir la reemplaza y lo que solo esté allá se pierde.`
              : t('cuentaNube.estoReemplazaLaCopia')}
          </Notice>
          <Button wide className="seccion" disabled={ocupado} onClick={() => void subir()}>
            {ocupado ? 'Subiendo…' : 'Sí, subir'}
          </Button>
          <Button wide variant="texto" onClick={() => setConfirmando(null)}>
            Mejor no
          </Button>
        </div>
      ) : confirmando === 'bajar' ? (
        <div className="seccion">
          <Notice tone="ambar" icon="⚠️">
            {comparacion.pullIsRisky
              ? `Este teléfono tiene ${comparacion.localCount} movimientos y la copia ${comparacion.cloudCount}. Bajarla reemplaza todo lo de aquí.`
              : t('cuentaNube.estoReemplazaLoQue')}
          </Notice>
          <Button wide className="seccion" disabled={ocupado} onClick={() => void bajar()}>
            {ocupado ? 'Bajando…' : 'Sí, bajar'}
          </Button>
          <Button wide variant="texto" onClick={() => setConfirmando(null)}>
            Mejor no
          </Button>
        </div>
      ) : (
        <div className="seccion">
          <Button
            wide
            disabled={ocupado || comparacion.localCount === 0}
            onClick={() => setConfirmando('subir')}
          >{t('cuentaNube.subirCopia')}</Button>
          <Button
            wide
            variant="contorno"
            className="seccion"
            disabled={ocupado || !cloud}
            onClick={() => setConfirmando('bajar')}
          >{t('cuentaNube.bajarCopia')}</Button>
          {peso >= 2 && (
            <p className="campo__ayuda" style={{ marginTop: 'var(--e2)' }}>
              La copia pesa unos {peso} MB. Si andas con datos móviles, mejor espera al wifi.
            </p>
          )}
        </div>
      )}
    </>
  );
}

/**
 * Entrar.
 *
 * Solo con Apple. Es una app de iPhone, el botón ya está en el teléfono de
 * quien la usa. El código por correo pedía un servidor de correo propio para
 * una sola cosa, y no valía el enredo.
 *
 * Quien ya tenía cuenta de correo vuelve a ella sin hacer nada: Supabase
 * enlaza la identidad de Apple al usuario que ya existe con ese mismo correo,
 * siempre que esté confirmado. Lo único que hay que pedirle es que no esconda
 * el correo, y de eso avisa la pantalla.
 */
function Fuera() {
  const signInWith = useAuth((state) => state.signInWith);

  const [error, setError] = useState('');
  const [ocupado, setOcupado] = useState(false);

  async function entrar() {
    setOcupado(true);
    const fallo = await signInWith('apple');
    setOcupado(false);
    if (fallo) setError(fallo);
  }

  return (
    <>
      <div className="seccion">
        <Notice tone="azul" icon="📱">
          No hace falta cuenta para usar la app. Entrar sirve para guardar una copia en la nube y
          no perderla si cambias de teléfono.
        </Notice>
      </div>

      {/*
        * Lo que decide si una cuenta vieja se recupera o se pierde. Supabase
        * enlaza la identidad de Apple a la cuenta que ya existía solo si el
        * correo coincide; con "Esconder mi correo" Apple manda uno de
        * privaterelay.appleid.com, no hay con qué emparejar, y sale una cuenta
        * nueva y vacía. Va en aviso y no en letra chiquita por eso.
        */}
      <div className="seccion">
        <Notice tone="ambar" icon="📧" title={t('cuentaNube.yaTeniasCuenta')}>
          {t('cuentaNube.escogeCompartirCorreo')}
        </Notice>
      </div>

      {error && (
        <div className="seccion">
          <Notice tone="roja" icon="⚠️">
            {error}
          </Notice>
        </div>
      )}

      <div className="hoja__pie">
        <Button wide disabled={ocupado} onClick={() => void entrar()}>
          {ocupado ? 'Abriendo…' : t('cuentaNube.continuarConApple')}
        </Button>
        <p className="campo__ayuda" style={{ marginTop: 'var(--e3)' }}>
          {t('cuentaNube.siEsTuPrimeraVez')}
        </p>
      </div>
    </>
  );
}
