/**
 * Una línea de la cinta: un movimiento.
 * La usan Inicio y Movimientos, así que vive aquí y no dentro de una pantalla.
 */

import type { AppData, Transaction } from '../domain/types';
import type { Currency } from '../lib/money';
import { describeTransaction } from '../domain/describe';
import { Amount } from './Amount';
import { Row } from './Row';

export function TransactionRow({
  tx,
  data,
  privacy,
  onClick,
}: {
  tx: Transaction;
  data: AppData;
  privacy: boolean;
  onClick?: () => void;
}) {
  const { icon, title, detail } = describeTransaction(tx, data);

  const monto = tx.kind === 'exchange' ? tx.toAmount : tx.amount;
  const moneda: Currency = tx.kind === 'exchange' ? tx.toCurrency : tx.currency;

  const esGasto = tx.kind === 'expense';
  const esIngreso = tx.kind === 'income';

  return (
    <Row
      icon={icon}
      title={title}
      detail={detail}
      onClick={onClick}
      right={
        <Amount
          cents={esGasto ? -monto : monto}
          currency={moneda}
          size="normal"
          tone={esGasto ? 'negativa' : esIngreso ? 'positiva' : 'apagada'}
          hidden={privacy}
          sign={esIngreso}
        />
      }
    />
  );
}
