/**
 * Inicio.
 *
 * Lo primero que se ve es cuánto hay, en la moneda principal, con su
 * equivalente en la otra y la tasa del día. Debajo, el mes en dos cifras
 * y la cinta de movimientos.
 */

import { useState } from 'react';
import { useData, usePrivacy, useApp } from '../store/useApp';
import { TopBar } from '../app/TopBar';
import { Amount } from '../ui/Amount';
import { Button, Empty } from '../ui/primitives';
import { Row, TapeDay } from '../ui/Row';
import { t } from '../i18n';
import {
  availableBalance,
  groupByDay,
  monthTotals,
  savedInGoals,
  transactionsOfMonth,
} from '../domain/compute';
import { allBudgetProgress } from '../domain/budgets';
import { upcomingPayments } from '../domain/recurrences';
import { Card } from '../ui/primitives';
import { goalProgress } from '../domain/goals';
import { PresupuestoSheet } from './plan/PresupuestoSheet';
import { RecurrentesSheet } from './plan/RecurrentesSheet';
import { MetasSheet } from './plan/MetasSheet';
import { TransactionRow } from '../ui/TransactionRow';
import { signedAmount } from '../domain/describe';
import { convert, formatRate } from '../lib/fx';
import { currentYearMonth, monthName, relativeDate } from '../lib/date';
import { saludo } from '../lib/saludo';
import { AvisoDeCopia } from './cuenta/AvisoDeCopia';
import type { Transaction } from '../domain/types';

export function Inicio({ onVerCuentas }: { onVerCuentas: () => void }) {
  const data = useData();
  const privacy = usePrivacy();
  const togglePrivacy = useApp((state) => state.togglePrivacy);

  const main = data.profile.mainCurrency;
  const other = main === 'DOP' ? 'USD' : 'DOP';
  const rate = data.fx.dopPerUsd;
  const month = currentYearMonth();

  const disponible = availableBalance(data, main);
  const equivalente = convert(disponible, main, other, rate);
  const { income, expense } = monthTotals(data, month, main);

  const movimientos = transactionsOfMonth(data, month);
  const dias = groupByDay(movimientos).slice(0, 5);

  const presupuestos = allBudgetProgress(data, month);
  const pagos = upcomingPayments(data, 10);
  const apartado = savedInGoals(data, main);
  const metas = data.goals.filter((goal) => !goal.archived);
  const [hoja, setHoja] = useState<'ninguna' | 'presupuesto' | 'recurrentes' | 'metas'>('ninguna');

  return (
    <>
      <TopBar
        title={monthName(month)}
        actions={[
          {
            icon: privacy ? 'ojoTachado' : 'ojo',
            label: privacy ? t('inicioPant.mostrarLosMontos') : t('inicioPant.ocultarLosMontos'),
            onClick: togglePrivacy,
          },
          { icon: 'cuenta', label: t('inicio.verCuentas'), onClick: onVerCuentas },
        ]}
      />

      <main className="contenido">
        <section className="saldo">
          <p className="saldo__saludo">{saludo(data.profile.name)}</p>
          <p className="saldo__etiqueta">{t('inicio.saldo')}</p>
          <Amount cents={disponible} currency={main} size="hero" tag hidden={privacy} />

          <div className="saldo__equivalente">
            <span className="texto-menor">{t('inicio.equivale')}</span>
            <Amount cents={equivalente} currency={other} size="menor" tag hidden={privacy} />
            <span className="saldo__tasa">
              {t('inicio.tasa')} {formatRate(rate)}
            </span>
          </div>

          {apartado > 0 && (
            <button type="button" className="saldo__apartado" onClick={() => setHoja('metas')}>
              De eso, <Amount cents={apartado} currency={main} size="menor" compact hidden={privacy} /> están
              apartados en metas
            </button>
          )}
        </section>

        <AvisoDeCopia />

        <section className={t('inicioPant.seccionMes')}>
          <div className="mes__caja">
            <p className="mes__etiqueta">{t('inicio.entro')}</p>
            <Amount
              cents={roundToUnit(income)}
              currency={main}
              size="titulo"
              tone="positiva"
              hidden={privacy}
              compact
            />
          </div>
          <div className="mes__caja">
            <p className="mes__etiqueta">{t('inicio.salio')}</p>
            <Amount
              cents={roundToUnit(expense)}
              currency={main}
              size="titulo"
              tone="negativa"
              hidden={privacy}
              compact
            />
          </div>
        </section>

        {pagos.length > 0 && (
          <section className="seccion">
            <Card
              title={t('inicioPant.porPagarPronto')}
              action={
                <button
                  type="button"
                  className="carta__accion"
                  onClick={() => setHoja('recurrentes')}
                >
                  Gestionar
                </button>
              }
            >
              {pagos.slice(0, 4).map((pago) => (
                <Row
                  key={pago.id}
                  icon={pago.kind === 'tarjeta' ? '💳' : pago.kind === 'deuda' ? '📉' : '🔁'}
                  title={pago.name}
                  detail={
                    pago.days === 0
                      ? 'Vence hoy'
                      : pago.days === 1
                        ? t('inicioPant.venceManana')
                        : `En ${pago.days} días`
                  }
                  right={
                    <Amount
                      cents={pago.amount}
                      currency={pago.currency}
                      size="normal"
                      tone={pago.days <= 2 ? 'negativa' : 'apagada'}
                      compact
                      hidden={privacy}
                    />
                  }
                />
              ))}
            </Card>
          </section>
        )}

        {presupuestos.length > 0 && (
          <section className="seccion">
            <Card
              title={`Presupuesto de ${monthName(month).toLowerCase()}`}
              action={
                <button
                  type="button"
                  className="carta__accion"
                  onClick={() => setHoja('presupuesto')}
                >
                  Ver todo
                </button>
              }
            >
              {presupuestos.slice(0, 3).map((avance) => {
                const categoria = data.categories.find(
                  (item) => item.id === avance.budget.categoryId,
                );
                const color = avance.overspent
                  ? 'var(--rojo)'
                  : avance.percent > 80
                    ? 'var(--ambar)'
                    : 'var(--verde)';

                return (
                  <div key={avance.budget.id} style={{ marginBottom: 'var(--e4)' }}>
                    <div className="fila-entre" style={{ marginBottom: 6 }}>
                      <span className="texto-menor" style={{ color: 'var(--tinta)' }}>
                        {categoria?.icon} {categoria?.name}
                      </span>
                      <span className="texto-menor" style={{ color, fontWeight: 600 }}>
                        {avance.percent}%
                      </span>
                    </div>
                    <div className="bar">
                      <div
                        className="bar-fill"
                        style={{ width: `${Math.min(100, avance.percent)}%`, background: color }}
                      />
                    </div>
                  </div>
                );
              })}
            </Card>
          </section>
        )}

        {metas.length > 0 && (
          <section className="seccion">
            <Card
              title={t('inicioPant.metasDeAhorro')}
              action={
                <button type="button" className="carta__accion" onClick={() => setHoja('metas')}>
                  Ver todo
                </button>
              }
            >
              {metas.slice(0, 2).map((meta) => {
                const avance = goalProgress(meta);
                return (
                  <div key={meta.id} style={{ marginBottom: 'var(--e4)' }}>
                    <div className="fila-entre" style={{ marginBottom: 6 }}>
                      <span className={t('inicioPant.textoMenorTextoCorta')} style={{ color: 'var(--tinta)' }}>
                        {meta.icon ?? '🎯'} {meta.name}
                      </span>
                      <span className="texto-menor" style={{ whiteSpace: 'nowrap' }}>
                        <Amount cents={meta.saved} currency={meta.currency} size="menor" compact hidden={privacy} />
                        {' de '}
                        <Amount cents={meta.target} currency={meta.currency} size="menor" compact hidden={privacy} />
                      </span>
                    </div>
                    <div className="bar">
                      <div
                        className="bar-fill"
                        style={{
                          width: `${avance.percent}%`,
                          background: avance.done ? 'var(--verde)' : 'var(--azul)',
                        }}
                      />
                    </div>
                  </div>
                );
              })}
            </Card>
          </section>
        )}

        <section className="seccion">
          {dias.length === 0 ? (
            <Empty
              mark="🧾"
              title={t('inicio.sinMovimientos.titulo')}
              text={t('inicio.sinMovimientos.texto')}
              action={<Button small>{t('inicio.sinMovimientos.accion')}</Button>}
            />
          ) : (
            dias.map((dia) => (
              <div key={dia.date}>
                <TapeDay
                  label={relativeDate(dia.date)}
                  total={
                    <Amount
                      cents={totalDelDia(dia.items, main)}
                      currency={main}
                      size="menor"
                      tone="apagada"
                      hidden={privacy}
                      sign
                    />
                  }
                />
                {dia.items.map((tx) => (
                  <TransactionRow key={tx.id} tx={tx} data={data} privacy={privacy} />
                ))}
              </div>
            ))
          )}
        </section>
      </main>

      <PresupuestoSheet open={hoja === 'presupuesto'} onClose={() => setHoja('ninguna')} />
      <RecurrentesSheet open={hoja === 'recurrentes'} onClose={() => setHoja('ninguna')} />
      <MetasSheet open={hoja === 'metas'} onClose={() => setHoja('ninguna')} />
    </>
  );
}

/**
 * Redondea a la unidad para los dos totales del mes.
 * Puestos lado a lado, uno con centavos y otro sin ellos se ve descuidado,
 * y en un resumen los centavos no aportan nada.
 */
function roundToUnit(cents: number): number {
  return Math.round(cents / 100) * 100;
}

/** Lo que entró menos lo que salió en un día. */
function totalDelDia(items: readonly Transaction[], currency: 'DOP' | 'USD'): number {
  return items.reduce((total, tx) => total + signedAmount(tx, currency), 0);
}
