/**
 * La hoja de registrar: menú de cinco opciones y el formulario que elijas.
 */

import { useState } from 'react';
import { t } from '../../i18n';
import { Sheet } from '../../ui/overlays';
import { GastoForm } from './GastoForm';
import { IngresoForm } from './IngresoForm';
import { TransferenciaForm } from './TransferenciaForm';
import { CambioForm } from './CambioForm';
import { usePuedeCambiarMoneda } from '../../store/useMonedas';
import { Bloqueado } from '../premium/Bloqueado';
import { PremiumSheet } from '../premium/PremiumSheet';

type Vista = 'menu' | 'gasto' | 'ingreso' | 'transferencia' | 'retiro' | 'cambio';

const TITULOS: Record<Vista, { titulo: string; sub?: string }> = {
  menu: { titulo: 'Registrar' },
  gasto: { titulo: 'Nuevo gasto', sub: t('registrar.algoQuePagaste') },
  ingreso: { titulo: t('registrar.nuevoIngreso'), sub: t('registrar.dineroQueEntro') },
  transferencia: { titulo: 'Transferencia', sub: t('registrar.entreDosCuentasTuyas') },
  retiro: { titulo: t('retiro.titulo'), sub: t('retiro.sub') },
  cambio: { titulo: t('registrar.cambioDeMoneda'), sub: t('registrar.dePesosADolares') },
};

const OPCIONES: { vista: Vista; icono: string; titulo: string; detalle: string }[] = [
  { vista: 'gasto', icono: '🧾', titulo: 'Gasto', detalle: t('registrar.algoQuePagaste') },
  { vista: 'ingreso', icono: '💰', titulo: 'Ingreso', detalle: t('registrar.dineroQueEntro') },
  { vista: 'transferencia', icono: '⇄', titulo: 'Transferencia', detalle: t('registrar.entreTusCuentas') },
  { vista: 'retiro', icono: '💵', titulo: t('retiro.titulo'), detalle: t('retiro.detalle') },
  { vista: 'cambio', icono: '💱', titulo: 'Cambio', detalle: t('registrar.pesosADolares') },
];

export function RegistrarSheet({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [vista, setVista] = useState<Vista>('menu');
  const [planesAbiertos, setPlanesAbiertos] = useState(false);
  const puedeCambiar = usePuedeCambiarMoneda();

  const { titulo, sub } = TITULOS[vista];

  return (
    <Sheet
      open={open}
      title={titulo}
      subtitle={sub}
      onClose={onClose}
      onBack={vista === 'menu' ? undefined : () => setVista('menu')}
    >
      {vista === 'menu' && (
        <div className="sh-menu">
          {OPCIONES.map((opcion) => (
            <button
              key={opcion.vista}
              type="button"
              className="sh-menu-b"
              onClick={() => setVista(opcion.vista)}
            >
              <span className="sh-menu-ic" aria-hidden="true">
                {opcion.icono}
              </span>
              <span className="sh-menu-t">{opcion.titulo}</span>
              <span className="sh-menu-s">{opcion.detalle}</span>
            </button>
          ))}
        </div>
      )}

      {vista === 'gasto' && <GastoForm onDone={onClose} />}
      {vista === 'ingreso' && <IngresoForm onDone={onClose} />}
      {vista === 'transferencia' && <TransferenciaForm onDone={onClose} />}
      {vista === 'retiro' && <TransferenciaForm onDone={onClose} haciaEfectivo />}
      {vista === 'cambio' &&
        (puedeCambiar ? (
          <CambioForm onDone={onClose} />
        ) : (
          <>
            <Bloqueado funcion="monedas" onAbrir={() => setPlanesAbiertos(true)} />
            <PremiumSheet
              open={planesAbiertos}
              desde="monedas"
              onClose={() => setPlanesAbiertos(false)}
            />
          </>
        ))}
    </Sheet>
  );
}
