/**
 * Cuentas: el efectivo, los bancos y las tarjetas de crédito.
 */

import { useState } from 'react';
import { useData, usePrivacy } from '../store/useApp';
import { TopBar } from '../app/TopBar';
import { Amount } from '../ui/Amount';
import { Button, Card, Chip, Empty } from '../ui/primitives';
import { Row } from '../ui/Row';
import { Icon } from '../ui/Icon';
import { t } from '../i18n';
import { accountCurrencies, cardAvailable, cardUsagePercent } from '../domain/accounts';
import type { Account } from '../domain/types';
import { CuentasSheet } from './cuentas/CuentasSheet';
import type { CuentaVista } from './cuentas/CuentasSheet';

export function Cuentas({ onVolver }: { onVolver: () => void }) {
  const data = useData();
  const privacy = usePrivacy();
  const [vista, setVista] = useState<CuentaVista>({ modo: 'cerrada' });

  const activas = data.accounts.filter((cuenta) => !cuenta.archived);
  const efectivo = activas.find((cuenta) => cuenta.kind === 'cash');
  const bancos = activas.filter((cuenta) => cuenta.kind === 'bank');
  const tarjetas = activas.filter((cuenta) => cuenta.kind === 'credit');
  const archivadas = data.accounts.filter((cuenta) => cuenta.archived);
  // El efectivo lo tiene todo el mundo desde el primer día, así que no cuenta
  // para decidir si a esta persona le falta registrar sus cuentas.
  const vacio = bancos.length === 0 && tarjetas.length === 0;
  const enNegativo = (efectivo?.balances[data.profile.mainCurrency] ?? 0) < 0;

  return (
    <>
      <TopBar
        title={t('cuentas.titulo')}
        leading={
          <button
            type="button"
            className="barra-sup__accion"
            onClick={onVolver}
            aria-label={t('comun.volver')}
          >
            <Icon name="flechaIzq" size={20} />
          </button>
        }
        actions={[
          { icon: 'mas', label: t('cuentas.agregar'), onClick: () => setVista({ modo: 'nueva' }) },
        ]}
      />

      <main className="contenido">
        {efectivo && (
          <Card>
            <Row
              icon={<span aria-hidden="true">💵</span>}
              title={t('cuentas.efectivo')}
              detail={t('cuentas.efectivoDetalle')}
              onClick={() => setVista({ modo: 'detalle', id: efectivo.id })}
              right={
                <Amount
                  cents={efectivo.balances[data.profile.mainCurrency] ?? 0}
                  currency={data.profile.mainCurrency}
                  size="normal"
                  tag
                  hidden={privacy}
                />
              }
            />
            {enNegativo && (
              <>
                <p className="campo__ayuda" style={{ marginTop: 'var(--e3)' }}>
                  {t('cuentas.efectivoEnNegativo')}
                </p>
                <Button
                  small
                  variant="contorno"
                  className="seccion"
                  onClick={() => setVista({ modo: 'efectivo' })}
                >
                  {t('cuentas.contarEfectivo')}
                </Button>
              </>
            )}
          </Card>
        )}

        {vacio ? (
          <Empty
            mark="🏦"
            title={t('cuentas.vacio.titulo')}
            text={t('cuentas.vacio.texto')}
            action={
              <Button small onClick={() => setVista({ modo: 'nueva' })}>
                {t('cuentas.agregarPrimera')}
              </Button>
            }
          />
        ) : (
          <>
            {bancos.length > 0 && (
              <Card title={t('cuentas.banco')} className="seccion">
                {bancos.map((cuenta) => (
                  <FilaCuenta
                    key={cuenta.id}
                    account={cuenta}
                    privacy={privacy}
                    onClick={() => setVista({ modo: 'detalle', id: cuenta.id })}
                  />
                ))}
              </Card>
            )}

            {tarjetas.length > 0 && (
              <div className="seccion">
                <Card title={t('cuentas.tarjeta')}>
                  {tarjetas.map((cuenta) => (
                    <FilaTarjeta
                      key={cuenta.id}
                      account={cuenta}
                      privacy={privacy}
                      onClick={() => setVista({ modo: 'detalle', id: cuenta.id })}
                    />
                  ))}
                </Card>
              </div>
            )}

            {archivadas.length > 0 && (
              <div className="seccion">
                <Card title="Archivadas">
                  {archivadas.map((cuenta) => (
                    <Row
                      key={cuenta.id}
                      icon={<Icon name={cuenta.kind === 'credit' ? 'tarjeta' : 'cuenta'} size={18} />}
                      title={cuenta.nickname ?? cuenta.bank}
                      detail="Archivada"
                      onClick={() => setVista({ modo: 'detalle', id: cuenta.id })}
                    />
                  ))}
                </Card>
              </div>
            )}

            <div className="seccion">
              <Button wide variant="contorno" onClick={() => setVista({ modo: 'nueva' })}>
                {t('cuentas.agregarOtra')}
              </Button>
            </div>
          </>
        )}
      </main>

      <CuentasSheet
        vista={vista}
        onCerrar={() => setVista({ modo: 'cerrada' })}
        onCambiarVista={setVista}
      />
    </>
  );
}

function detalleCuenta(account: Account): string {
  const pais = account.country === 'US' ? 'Estados Unidos' : 'República Dominicana';
  return account.last4 ? `${pais} · ····${account.last4}` : pais;
}

function FilaCuenta({
  account,
  privacy,
  onClick,
}: {
  account: Account;
  privacy: boolean;
  onClick: () => void;
}) {
  const monedas = accountCurrencies(account);

  return (
    <Row
      icon={<Icon name="cuenta" size={18} />}
      title={account.nickname ?? account.bank}
      detail={detalleCuenta(account)}
      onClick={onClick}
      right={
        <>
          {monedas.map((moneda) => (
            <Amount
              key={moneda}
              cents={account.balances[moneda] ?? 0}
              currency={moneda}
              size="normal"
              tag
              hidden={privacy}
            />
          ))}
        </>
      }
    />
  );
}

function FilaTarjeta({
  account,
  privacy,
  onClick,
}: {
  account: Account;
  privacy: boolean;
  onClick: () => void;
}) {
  const monedas = accountCurrencies(account);
  const principal = monedas[0];
  const porcentaje = principal ? cardUsagePercent(account, principal) : null;

  return (
    <Row
      icon={<Icon name="tarjeta" size={18} />}
      title={account.nickname ?? account.bank}
      detail={
        account.credit?.dueDay !== undefined
          ? `Paga el día ${account.credit.dueDay}`
          : detalleCuenta(account)
      }
      onClick={onClick}
      right={
        <>
          {monedas.map((moneda) => {
            const disponible = cardAvailable(account, moneda);
            if (disponible === null) return null;
            return (
              <span key={moneda} className="disponible-tarjeta">
                <Amount cents={disponible} currency={moneda} size="normal" tag hidden={privacy} />
                <span className="texto-micro">disponible</span>
              </span>
            );
          })}
        </>
      }
      rightDetail={porcentaje !== null ? <Chip tone={porcentaje > 80 ? 'roja' : 'neutra'}>{porcentaje}% usado</Chip> : undefined}
    />
  );
}
