/**
 * Respaldo: sacar una copia de los datos, volver a meterlos, o borrarlo todo.
 *
 * Mientras no haya cuenta en la nube, este archivo es la única forma de
 * cambiar de teléfono sin perder nada.
 */

import { useRef, useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData } from '../../store/useApp';
import { Sheet } from '../../ui/overlays';
import { Button, Card, Notice } from '../../ui/primitives';
import { Row } from '../../ui/Row';
import { toBackupFile } from '../../store/persist';
import { toCsv } from '../../lib/csv';
import { describeTransaction } from '../../domain/describe';
import { formatNumber } from '../../lib/money';
import { countOf } from '../../lib/text';
import { relativeDate } from '../../lib/date';

/** Nombre con la fecha de hoy: gestorrd-respaldo-2026-11-14.json */
function nombreConFecha(prefijo: string, extension: string): string {
  const hoy = new Date().toISOString().slice(0, 10);
  return `${prefijo}-${hoy}.${extension}`;
}

const TIPOS: Record<string, string> = {
  expense: 'Gasto',
  income: 'Ingreso',
  transfer: 'Transferencia',
  exchange: t('respaldo.cambioDeMoneda'),
};

export function RespaldoSheet({ open, onClose }: { open: boolean; onClose: () => void }) {
  const data = useData();
  const restoreBackup = useApp((state) => state.restoreBackup);
  const resetAll = useApp((state) => state.resetAll);
  const notify = useApp((state) => state.notify);

  const archivo = useRef<HTMLInputElement>(null);
  const [confirmando, setConfirmando] = useState(false);
  const [error, setError] = useState('');

  async function exportar() {
    const contenido = JSON.stringify(toBackupFile(data), null, 2);
    const nombre = nombreConFecha('gestorrd-respaldo', 'json');
    const blob = new Blob([contenido], { type: 'application/json' });

    // En el teléfono se abre la hoja de compartir; en el navegador, se descarga
    const puedeCompartir =
      typeof navigator.canShare === 'function' &&
      navigator.canShare({ files: [new File([blob], nombre, { type: 'application/json' })] });

    if (puedeCompartir) {
      try {
        await navigator.share({
          files: [new File([blob], nombre, { type: 'application/json' })],
          title: t('respaldo.respaldoDeGestorrd'),
        });
        return;
      } catch {
        // Si la persona cancela, se descarga igual
      }
    }

    descargar(blob, nombre);
    notify(t('respaldo.respaldoDescargado'));
  }

  function exportarCsv() {
    const filas: string[][] = [['Fecha', 'Tipo', 'Descripción', 'Monto', 'Moneda']];

    for (const tx of data.transactions) {
      const descripcion = describeTransaction(tx, data);
      const moneda = tx.kind === 'exchange' ? tx.fromCurrency : tx.currency;
      const monto = tx.kind === 'exchange' ? tx.fromAmount : tx.amount;
      const signo = tx.kind === 'income' ? '' : '-';
      filas.push([
        tx.date,
        TIPOS[tx.kind] ?? tx.kind,
        descripcion.title,
        `${signo}${formatNumber(monto)}`,
        moneda,
      ]);
    }

    descargar(
      new Blob(['\uFEFF', toCsv(filas)], { type: 'text/csv;charset=utf-8' }),
      nombreConFecha('gestorrd-movimientos', 'csv'),
    );
    notify(t('respaldo.movimientosExportados'));
  }

  function descargar(blob: Blob, nombre: string) {
    const url = URL.createObjectURL(blob);
    const enlace = document.createElement('a');
    enlace.href = url;
    enlace.download = nombre;
    enlace.click();
    URL.revokeObjectURL(url);
  }

  async function importar(entrada: HTMLInputElement) {
    const elegido = entrada.files?.[0];
    if (!elegido) return;

    const texto = await elegido.text();
    entrada.value = '';

    if (restoreBackup(texto)) {
      notify(t('respaldo.datosRestaurados'));
      onClose();
    } else {
      setError(t('respaldo.eseArchivoNoParece'));
    }
  }

  return (
    <Sheet open={open} title="Respaldo" subtitle={t('respaldo.tusDatosFueraDel')} onClose={onClose}>
      <Card className="seccion" title={t('respaldo.loQueHayGuardado')}>
        <Row
          title="Movimientos"
          right={<span className="texto-menor">{data.transactions.length}</span>}
        />
        <Row
          title={t('respaldo.cuentasYTarjetas')}
          right={<span className="texto-menor">{data.accounts.length}</span>}
        />
        <Row
          title={t('respaldo.metasYDeudas')}
          right={
            <span className="texto-menor">{data.goals.length + data.debts.length}</span>
          }
        />
        {data.transactions[0] && (
          <Row
            title={t('respaldo.ultimoMovimiento')}
            right={<span className="texto-menor">{relativeDate(data.transactions[0].date)}</span>}
          />
        )}
      </Card>

      <div className="seccion">
        <Button wide onClick={exportar}>{t('respaldo.guardarUnaCopia')}</Button>
        <p className="campo__ayuda" style={{ marginTop: 'var(--e2)' }}>
          Un archivo con todo: {countOf(data.transactions.length, 'movimiento', 'movimientos')},
          cuentas, presupuestos, deudas y metas. Guárdalo donde no se pierda.
        </p>
      </div>

      <div className="seccion">
        <Button wide variant="contorno" onClick={exportarCsv}>{t('respaldo.exportarMovimientosACsv')}</Button>
        <p className="campo__ayuda" style={{ marginTop: 'var(--e2)' }}>
          Para abrirlos en Excel o en Google Sheets. Este archivo no sirve para restaurar: para eso
          está la copia de arriba.
        </p>
      </div>

      <div className="seccion">
        <input
          ref={archivo}
          type="file"
          accept="application/json,.json"
          style={{ display: 'none' }}
          aria-hidden="true"
          tabIndex={-1}
          onChange={(event) => void importar(event.currentTarget)}
        />
        <Button wide variant="contorno" onClick={() => archivo.current?.click()}>{t('respaldo.restaurarDesdeUnArchivo')}</Button>
        <p className="campo__ayuda" style={{ marginTop: 'var(--e2)' }}>
          Reemplaza todo lo que tienes ahora por lo que traiga el archivo. Sirve también con un
          respaldo de la versión anterior de GestorRD.
        </p>
        {error && (
          <div style={{ marginTop: 'var(--e3)' }}>
            <Notice tone="roja" icon="⚠️">
              {error}
            </Notice>
          </div>
        )}
      </div>

      <div className="hoja__pie">
        {confirmando ? (
          <>
            <Notice tone="roja" icon="⚠️">
              Esto borra todos tus datos de este teléfono y no se puede deshacer. Si no has
              guardado una copia, hazlo antes.
            </Notice>
            <Button
              wide
              variant="peligro"
              className="seccion"
              onClick={() => {
                resetAll();
                window.location.reload();
              }}
            >{t('respaldo.siBorrarTodo')}</Button>
            <Button wide variant="texto" onClick={() => setConfirmando(false)}>
              Mejor no
            </Button>
          </>
        ) : (
          <Button wide variant="texto" onClick={() => setConfirmando(true)}>{t('respaldo.borrarTodosMisDatos')}</Button>
        )}
      </div>
    </Sheet>
  );
}
