/**
 * Reglas de la cuenta que no dependen de la red.
 *
 * Los mensajes de Supabase vienen en inglés y a veces en jerga ("Invalid login
 * credentials"). Aquí se traducen a algo que una persona entienda y pueda
 * resolver. Lo que no se reconoce se dice tal cual, sin inventar.
 */

/** Traduce el error de Supabase a algo accionable. */
export function explainAuthError(mensaje: string): string {
  const texto = mensaje.toLowerCase();

  if (texto.includes('token has expired') || texto.includes('expired')) {
    return 'Ese código ya venció. Pide uno nuevo.';
  }
  if (texto.includes('invalid') && texto.includes('token')) {
    return 'Ese código no es el correcto. Revísalo o pide uno nuevo.';
  }
  if (texto.includes('rate limit') || texto.includes('too many')) {
    return 'Muchos intentos seguidos. Espera un minuto y vuelve a probar.';
  }
  if (texto.includes('network') || texto.includes('fetch')) {
    return 'No hay conexión. Tus datos siguen en el teléfono; prueba más tarde.';
  }
  if (texto.includes('provider is not enabled') || texto.includes('unsupported provider')) {
    return 'Esa forma de entrar todavía no está disponible.';
  }
  if (texto.includes('email') && texto.includes('invalid')) {
    return 'Ese correo no parece válido.';
  }
  if (texto.includes('signups not allowed') || texto.includes('signup is disabled')) {
    return 'Las cuentas nuevas están cerradas por ahora.';
  }

  return mensaje;
}

/** Nombre corto del dispositivo, para saber desde dónde se guardó la copia. */
export function describeDevice(userAgent: string): string {
  if (/iPhone/i.test(userAgent)) return 'iPhone';
  if (/iPad/i.test(userAgent)) return 'iPad';
  if (/Android/i.test(userAgent)) return 'Android';
  if (/Macintosh|Mac OS/i.test(userAgent)) return 'Mac';
  if (/Windows/i.test(userAgent)) return 'Windows';
  return 'Otro dispositivo';
}

/**
 * El nombre que manda el proveedor al entrar.
 *
 * Apple solo lo manda la primera vez que alguien autoriza la app: si no se
 * recoge en ese momento, se pierde para siempre y la persona tiene que
 * escribirlo a mano. Google lo manda cada vez. Cada proveedor usa su propia
 * llave, así que se miran todas.
 */
export function nombreDeLaSesion(metadata: Record<string, unknown> | undefined): string {
  if (!metadata) return '';

  const llaves = ['full_name', 'name', 'given_name', 'preferred_username'];
  for (const llave of llaves) {
    const valor = metadata[llave];
    if (typeof valor === 'string' && valor.trim()) return valor.trim();
  }

  return '';
}

/**
 * Saca el código del enlace con que el teléfono devuelve el control a la app.
 *
 * `exchangeCodeForSession` quiere el código suelto, no la dirección entera.
 * Pasarle la URL completa falla sin explicar por qué, y la persona vuelve de
 * Apple a una app que le sigue pidiendo que entre.
 *
 * Devuelve null cuando no hay código: alguien que cancela vuelve igual, pero
 * con un `error` en vez de un `code`, y eso no es un fallo que reportar.
 */
export function codigoDelEnlace(url: string): string | null {
  const interrogante = url.indexOf('?');
  const almohadilla = url.indexOf('#');

  // El código puede venir en la consulta o detrás de la almohadilla
  const partes: string[] = [];
  if (interrogante >= 0) partes.push(url.slice(interrogante + 1));
  if (almohadilla >= 0) partes.push(url.slice(almohadilla + 1));

  for (const parte of partes) {
    const codigo = new URLSearchParams(parte).get('code');
    if (codigo) return codigo;
  }

  return null;
}
