/**
 * Reportes.
 *
 * Tres preguntas, en este orden: ¿cómo voy este mes?, ¿cómo venía?, ¿en qué
 * se me fue? Debajo, el asesor dice qué hacer con eso.
 */

import { useState } from 'react';
import { TopBar } from '../app/TopBar';
import { useData, usePrivacy } from '../store/useApp';
import { usePremiumActivo } from '../store/usePremium';
import { Bloqueado } from './premium/Bloqueado';
import { PremiumSheet } from './premium/PremiumSheet';
import { Amount } from '../ui/Amount';
import { Button, Card, Chip, Empty, Notice } from '../ui/primitives';
import { Icon } from '../ui/Icon';
import { monthTotals } from '../domain/compute';
import { monthSeries, spendByCategory } from '../domain/reports';
import { allBudgetProgress } from '../domain/budgets';
import { advice } from '../domain/advisor';
import { currentYearMonth, monthName, shiftMonth } from '../lib/date';
import { countOf } from '../lib/text';
import { t } from '../i18n';

const MESES_DE_TENDENCIA = 6;

export function Reportes() {
  const data = useData();
  const privacy = usePrivacy();
  const moneda = data.profile.mainCurrency;
  const hoy = currentYearMonth();

  const [mes, setMes] = useState(hoy);
  const premium = usePremiumActivo();
  const [planesAbiertos, setPlanesAbiertos] = useState(false);

  const { income, expense } = monthTotals(data, mes, moneda);
  const anterior = monthTotals(data, shiftMonth(mes, -1), moneda);
  const serie = monthSeries(data, mes, MESES_DE_TENDENCIA, moneda);
  const categorias = spendByCategory(data, mes, moneda);
  const presupuestos = allBudgetProgress(data, mes);
  const consejos = advice(data, mes);

  const neto = income - expense;
  const tope = Math.max(...serie.map((punto) => Math.abs(punto.net)), 1);
  const mayorCategoria = categorias[0]?.amount ?? 1;
  const vacio = income === 0 && expense === 0;

  // Cuánto cambió el gasto contra el mes pasado
  const deltaGasto =
    anterior.expense > 0 ? Math.round(((expense - anterior.expense) / anterior.expense) * 100) : null;

  return (
    <>
      <TopBar title={t('reportes.titulo')} />

      <main className="contenido">
        <section className="seccion">
          <div className="fila-entre" style={{ marginBottom: 'var(--e3)' }}>
            <Button
              variant="texto"
              small
              aria-label={t('reportesPant.mesAnterior')}
              onClick={() => setMes(shiftMonth(mes, -1))}
            >
              <Icon name="flechaIzq" />
            </Button>
            <span className="fila__titulo">
              {monthName(mes)} {mes.slice(0, 4)}
            </span>
            <Button
              variant="texto"
              small
              aria-label={t('reportesPant.mesSiguiente')}
              disabled={mes >= hoy}
              onClick={() => setMes(shiftMonth(mes, 1))}
            >
              <Icon name="flechaDer" />
            </Button>
          </div>

          <div className="tejas">
            <div className="teja">
              <p className="teja__etiqueta">Entró</p>
              <Amount cents={income} currency={moneda} size="menor" tone="positiva" compact hidden={privacy} />
            </div>
            <div className="teja">
              <p className="teja__etiqueta">Salió</p>
              <Amount cents={expense} currency={moneda} size="menor" tone="negativa" compact hidden={privacy} />
              {deltaGasto !== null && (
                <p className="teja__delta">
                  {deltaGasto === 0
                    ? t('reportesPant.igualQueElMes')
                    : `${Math.abs(deltaGasto)}% ${deltaGasto > 0 ? 'más' : 'menos'} que el mes pasado`}
                </p>
              )}
            </div>
            <div className="teja">
              <p className="teja__etiqueta">{neto >= 0 ? 'Te quedó' : 'Te faltó'}</p>
              <Amount
                cents={Math.abs(neto)}
                currency={moneda}
                size="menor"
                tone={neto >= 0 ? 'positiva' : 'negativa'}
                compact
                hidden={privacy}
              />
            </div>
          </div>
        </section>

        {!premium && (
          <>
            <Bloqueado funcion="reportes" onAbrir={() => setPlanesAbiertos(true)} />
            <PremiumSheet
              open={planesAbiertos}
              desde="reportes"
              onClose={() => setPlanesAbiertos(false)}
            />
          </>
        )}

        {premium && !vacio && (
          <section className="seccion">
            <Card title={`Últimos ${MESES_DE_TENDENCIA} meses`}>
              <p className="texto-menor" style={{ marginBottom: 'var(--e3)' }}>{t('reportesPant.loQueEntroMenos')}</p>

              <div className="tendencia">
                {serie.map((punto) => {
                  const alto = `${Math.round((Math.abs(punto.net) / tope) * 100)}%`;
                  const positivo = punto.net >= 0;
                  const activo = punto.month === mes;

                  return (
                    <button
                      key={punto.month}
                      type="button"
                      className={`tendencia__mes${activo ? ' tendencia__mes--activo' : ''}`}
                      aria-pressed={activo}
                      aria-label={`${monthName(punto.month)}: entró ${punto.income / 100}, salió ${punto.expense / 100}`}
                      onClick={() => setMes(punto.month)}
                    >
                      <span className="tendencia__arriba">
                        {positivo && punto.net !== 0 && (
                          <span
                            className="tendencia__barra tendencia__barra--positiva"
                            style={{ height: alto }}
                          />
                        )}
                      </span>
                      <span className="tendencia__cero" />
                      <span className="tendencia__abajo">
                        {!positivo && (
                          <span
                            className="tendencia__barra tendencia__barra--negativa"
                            style={{ height: alto }}
                          />
                        )}
                      </span>
                      <span className="tendencia__nombre">
                        {monthName(punto.month).slice(0, 3).toLowerCase()}
                      </span>
                    </button>
                  );
                })}
              </div>
            </Card>
          </section>
        )}

        {premium && (
        <section className="seccion">
          <Card title={t('reportesPant.enQueSeFue')}>
            {categorias.length === 0 ? (
              <p className="texto-menor">Sin gastos registrados en {monthName(mes).toLowerCase()}.</p>
            ) : (
              categorias.slice(0, 8).map((categoria) => {
                const presupuesto = presupuestos.find(
                  (item) => item.budget.categoryId === categoria.categoryId,
                );
                const pasado = presupuesto?.overspent ?? false;

                return (
                  <div key={categoria.categoryId} className="gasto-fila">
                    <span className="fila__titulo">
                      {categoria.icon} {categoria.name}
                    </span>
                    <span>
                      <Amount
                        cents={categoria.amount}
                        currency={moneda}
                        size="normal"
                        compact
                        hidden={privacy}
                      />
                    </span>
                    <span className="gasto-fila__barra">
                      <span
                        className={`gasto-fila__relleno${pasado ? ' gasto-fila__relleno--pasado' : ''}`}
                        style={{ width: `${Math.round((categoria.amount / mayorCategoria) * 100)}%` }}
                      />
                    </span>
                    <span className="texto-micro" style={{ gridColumn: '1 / -1' }}>
                      {categoria.share}% del gasto ·{' '}
                      {countOf(categoria.count, 'movimiento', 'movimientos')}
                      {pasado && (
                        <>
                          {' '}
                          <Chip tone="ambar">pasó el presupuesto</Chip>
                        </>
                      )}
                    </span>
                  </div>
                );
              })
            )}
          </Card>
        </section>
        )}

        {premium && (
        <section className="seccion">
          <h2 className="titulo-seccion">Tu asesor</h2>
          {consejos.length === 0 ? (
            <Empty
              mark="🧭"
              title={t('reportesPant.nadaQueSenalar')}
              text={t('reportesPant.cuandoAlgoSeSalga')}
            />
          ) : (
            consejos.map((consejo) => (
              <div key={consejo.id} className="seccion">
                <Notice tone={consejo.tone} icon={consejo.icon} title={consejo.title}>
                  {consejo.text}
                </Notice>
              </div>
            ))
          )}
        </section>
        )}
      </main>
    </>
  );
}
