/**
 * Cómo se describe un movimiento en palabras.
 *
 * Vive aparte de los componentes para que la recarga en caliente de React
 * siga funcionando, y porque es lógica, no interfaz.
 */

import type { AppData, Transaction } from './types';
import type { Currency } from '../lib/money';
import { convert } from '../lib/fx';

export interface TransactionText {
  icon: string;
  title: string;
  detail?: string;
}

function nombreCuenta(data: AppData, id: string | undefined): string {
  if (!id) return 'efectivo';
  const cuenta = data.accounts.find((item) => item.id === id);
  return cuenta ? (cuenta.nickname ?? cuenta.bank) : 'cuenta eliminada';
}

export function describeTransaction(tx: Transaction, data: AppData): TransactionText {
  switch (tx.kind) {
    case 'expense': {
      const categoria = data.categories.find((item) => item.id === tx.categoryId);
      // El mismo nombre que usan los reportes para una categoría que ya no está
      const titulo = tx.note?.trim() || categoria?.name || 'Sin categoría';
      return {
        icon: categoria?.icon ?? '🧺',
        title: titulo,
        detail: categoria && categoria.name !== titulo ? categoria.name : undefined,
      };
    }

    case 'income': {
      const fuente = data.incomeSources.find((item) => item.id === tx.sourceId);
      const titulo = tx.note?.trim() || fuente?.name || 'Sin fuente';
      return {
        icon: fuente?.icon ?? '💰',
        title: titulo,
        detail: fuente && fuente.name !== titulo ? fuente.name : undefined,
      };
    }

    case 'transfer':
      return {
        icon: '⇄',
        title: tx.note?.trim() || 'Transferencia',
        detail: `${nombreCuenta(data, tx.fromAccountId)} a ${nombreCuenta(data, tx.toAccountId)}`,
      };

    case 'exchange': {
      const de = tx.fromCurrency === 'DOP' ? 'pesos' : 'dólares';
      const a = tx.toCurrency === 'DOP' ? 'pesos' : 'dólares';
      return {
        icon: '💱',
        title: tx.note?.trim() || 'Cambio de moneda',
        detail: `De ${de} a ${a}, a ${tx.fxRate.toFixed(2)}`,
      };
    }
  }
}

/**
 * Cuánto suma o resta este movimiento en la moneda pedida.
 * Las transferencias y los cambios mueven dinero entre cuentas propias,
 * así que no suman ni restan al total.
 */
export function signedAmount(tx: Transaction, currency: Currency): number {
  if (tx.kind === 'income') return convert(tx.amount, tx.currency, currency, tx.fxRate);
  if (tx.kind === 'expense') return -convert(tx.amount, tx.currency, currency, tx.fxRate);
  return 0;
}
