/**
 * Hoja inferior y nota flotante.
 *
 * La hoja es donde ocurre todo lo que es "agregar" o "editar": sube desde
 * abajo, se cierra con Escape o tocando fuera, y devuelve el foco al salir.
 */

import { useEffect, useRef } from 'react';
import type { ReactNode } from 'react';

export interface SheetProps {
  open: boolean;
  title: string;
  subtitle?: string;
  onClose: () => void;
  /** Si se pasa, la flecha vuelve a la hoja anterior en vez de cerrar. */
  onBack?: () => void;
  children: ReactNode;
}

export function Sheet({ open, title, subtitle, onClose, onBack, children }: SheetProps) {
  const panel = useRef<HTMLDivElement>(null);
  const previouslyFocused = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (!open) return;

    previouslyFocused.current = document.activeElement as HTMLElement | null;
    document.body.style.overflow = 'hidden';

    function onKey(event: KeyboardEvent) {
      if (event.key === 'Escape') onClose();
    }
    document.addEventListener('keydown', onKey);

    // Lleva el foco al panel para que el lector de pantalla anuncie la hoja
    panel.current?.focus();

    return () => {
      document.removeEventListener('keydown', onKey);
      document.body.style.overflow = '';
      previouslyFocused.current?.focus();
    };
  }, [open, onClose]);

  if (!open) return null;

  return (
    <>
      <div className="velo" onClick={onClose} aria-hidden="true" />
      <div
        className="hoja"
        role="dialog"
        aria-modal="true"
        aria-label={title}
        tabIndex={-1}
        ref={panel}
      >
        <div className="hoja__asa" aria-hidden="true" />
        <header className="hoja__cabeza">
          <button
            type="button"
            className="boton boton--texto"
            onClick={onBack ?? onClose}
            aria-label={onBack ? 'Volver' : 'Cerrar'}
          >
            {onBack ? '←' : '✕'}
          </button>
          <div className="crece">
            <h2 className="titulo-seccion">{title}</h2>
            {subtitle && <p className="texto-menor">{subtitle}</p>}
          </div>
        </header>
        <div className="hoja__cuerpo">{children}</div>
      </div>
    </>
  );
}

/** Mensaje breve de confirmación. */
export function Note({ text }: { text: string }) {
  return (
    <div className="nota" role="status" aria-live="polite">
      {text}
    </div>
  );
}
