/**
 * Conversión entre pesos y dólares.
 *
 * Regla del proyecto: cada movimiento guarda la tasa del día en que ocurrió.
 * Los reportes del pasado usan esa tasa guardada, así que no cambian cuando
 * sube el dólar. Los saldos de hoy sí usan la tasa de hoy, porque el dinero
 * que tienes ahora vale lo que vale ahora.
 */

import type { Cents, Currency } from './money';

/** Pesos dominicanos por un dólar. */
export interface FxRate {
  dopPerUsd: number;
  /** Cuándo se obtuvo, en ISO. */
  updatedAt: string;
  /** 'auto' si vino de internet, 'manual' si la persona la escribió. */
  source: 'auto' | 'manual' | 'default';
}

/** Valor de arranque mientras no hay conexión ni tasa guardada. */
export const DEFAULT_RATE: FxRate = {
  dopPerUsd: 63,
  updatedAt: '1970-01-01T00:00:00.000Z',
  source: 'default',
};

/** Rango aceptable. Fuera de esto la tasa está mal y no la usamos. */
const MIN_RATE = 20;
const MAX_RATE = 200;

export function isValidRate(dopPerUsd: number): boolean {
  return Number.isFinite(dopPerUsd) && dopPerUsd >= MIN_RATE && dopPerUsd <= MAX_RATE;
}

/**
 * Convierte un monto entre monedas usando la tasa indicada.
 * Devuelve centavos de la moneda destino.
 */
export function convert(
  cents: Cents,
  from: Currency,
  to: Currency,
  dopPerUsd: number,
): Cents {
  if (from === to) return Math.round(cents);
  if (!isValidRate(dopPerUsd)) return Math.round(cents);

  if (from === 'DOP' && to === 'USD') return Math.round(cents / dopPerUsd);
  if (from === 'USD' && to === 'DOP') return Math.round(cents * dopPerUsd);

  return Math.round(cents);
}

/**
 * Tasa implícita de un cambio de moneda real.
 * Si cambiaste US$100 y recibiste RD$6,150, la tasa fue 61.50.
 */
export function impliedRate(
  fromCents: Cents,
  fromCurrency: Currency,
  toCents: Cents,
  toCurrency: Currency,
): number | null {
  if (fromCents <= 0 || toCents <= 0) return null;
  if (fromCurrency === toCurrency) return null;

  const rate = fromCurrency === 'USD' ? toCents / fromCents : fromCents / toCents;
  return isValidRate(rate) ? Math.round(rate * 100) / 100 : null;
}

/**
 * De dónde sale la tasa cuando hay internet.
 *
 * Tiene que ser una fuente con DOP, y ahí se cae la mayoría: las que se basan
 * en el Banco Central Europeo (Frankfurter, por ejemplo) no traen el peso
 * dominicano. Esta sí, es gratis y no pide clave.
 *
 * Es una tasa de referencia del mercado, no la de venta de un banco de allá,
 * que suele estar más alta. Por eso lo que la persona escriba a mano manda
 * sobre esto: quien sabe a cómo le cambian el dinero, lo pone y no se le toca.
 */
const URL_TASA = 'https://open.er-api.com/v6/latest/USD';

interface RespuestaTasa {
  result?: string;
  rates?: Record<string, number>;
}

/** Pide la tasa de hoy. Devuelve null si no hay internet o viene rara. */
export async function buscarTasa(): Promise<number | null> {
  try {
    const respuesta = await fetch(URL_TASA);
    if (!respuesta.ok) return null;

    const cuerpo = (await respuesta.json()) as RespuestaTasa;
    if (cuerpo.result !== 'success') return null;

    const tasa = cuerpo.rates?.DOP;
    if (typeof tasa !== 'number' || !isValidRate(tasa)) return null;

    return Math.round(tasa * 100) / 100;
  } catch {
    // Sin internet la app sigue con la tasa que tenga guardada
    return null;
  }
}

/** Formato corto para mostrar la tasa: "RD$63.25" */
export function formatRate(dopPerUsd: number): string {
  return `RD$${dopPerUsd.toFixed(2)}`;
}
