/**
 * Lo que se ve en lugar de una función de pago.
 *
 * No se esconde ni se difumina: se dice qué es, para qué sirve y cuánto
 * cuesta abrirla. Quien no quiera pagar sigue teniendo la app entera para
 * llevar sus cuentas.
 */

import { Button, Card } from '../../ui/primitives';
import { t } from '../../i18n';
import { explicar } from '../../domain/premium';
import type { FuncionPremium } from '../../domain/premium';

export function Bloqueado({
  funcion,
  onAbrir,
}: {
  funcion: FuncionPremium;
  onAbrir: () => void;
}) {
  const detalle = explicar(funcion);

  return (
    <Card className="seccion">
      <div className="bloqueado">
        <span className="bloqueado__icono" aria-hidden="true">
          {detalle.icono}
        </span>
        <h3 className="bloqueado__titulo">{detalle.titulo}</h3>
        <p className="bloqueado__texto">{detalle.texto}</p>
        <Button wide onClick={onAbrir}>{t('bloqueado.verLosPlanes')}</Button>
      </div>
    </Card>
  );
}
