/**
 * Ayudas para escribir texto que concuerde en número.
 *
 * Sin esto salen frases como "1 tarjetas" o "Se omitieron 1 deuda", que es
 * justo lo primero que lee alguien que viene de la versión anterior.
 */

/** Elige la forma singular o plural según la cantidad. */
export function plural(count: number, one: string, many: string): string {
  return Math.abs(count) === 1 ? one : many;
}

/** Devuelve la cantidad con su sustantivo: "1 tarjeta", "3 tarjetas". */
export function countOf(count: number, one: string, many: string): string {
  return `${count} ${plural(count, one, many)}`;
}

/**
 * Une una lista en español: "8 movimientos, 2 cuentas y 1 tarjeta".
 * Descarta las partes vacías.
 */
export function joinList(parts: readonly string[]): string {
  const items = parts.filter((part) => part.length > 0);
  if (items.length === 0) return '';
  if (items.length === 1) return items[0] ?? '';
  const last = items[items.length - 1] ?? '';
  return `${items.slice(0, -1).join(', ')} y ${last}`;
}

/** Mayúscula inicial, sin tocar el resto. */
export function capitalize(value: string): string {
  return value.length === 0 ? value : value[0]!.toUpperCase() + value.slice(1);
}
