/**
 * Las monedas con las que esta persona puede trabajar ahora mismo.
 */

import { useMemo } from 'react';
import { useData } from './useApp';
import { usePremiumActivo } from './usePremium';
import { monedasPermitidas, puedeCambiarMoneda } from '../domain/monedas';
import type { Currency } from '../lib/money';

export function useMonedasPermitidas(): Currency[] {
  const data = useData();
  const premium = usePremiumActivo();
  return useMemo(() => monedasPermitidas(data, premium), [data, premium]);
}

export function usePuedeCambiarMoneda(): boolean {
  const data = useData();
  const premium = usePremiumActivo();
  return useMemo(() => puedeCambiarMoneda(data, premium), [data, premium]);
}
