/**
 * Importar el estado de cuenta del banco.
 *
 * Cada banco exporta a su manera: unos ponen una columna de monto con signo,
 * otros separan débito y crédito; unos escriben 05/11/2026 y otros 11/05/2026;
 * unos 1,234.56 y otros 1.234,56. Aquí se adivina todo eso a partir del propio
 * archivo, y lo que no se puede adivinar sin riesgo se le pregunta a la persona.
 */

import type { AppData, ExpenseTx, IncomeTx, Transaction } from './types';
import type { Cents, Currency } from '../lib/money';
import type { IsoDate } from '../lib/date';
import { isValidIsoDate } from '../lib/date';
import { newId } from '../lib/id';

/* ------------------------------------------------------------------ */
/* Columnas                                                            */
/* ------------------------------------------------------------------ */

export interface ColumnMap {
  date: number;
  description: number;
  /** Columna de monto con signo. */
  amount?: number;
  /** Columnas separadas, como las usan varios bancos. */
  debit?: number;
  credit?: number;
}

const NOMBRES = {
  date: ['fecha', 'date', 'fecha de transaccion', 'fecha transaccion', 'fecha efectiva', 'posted date', 'transaction date', 'dia'],
  description: ['descripcion', 'description', 'concepto', 'detalle', 'referencia', 'memo', 'payee', 'beneficiario', 'comercio', 'transaccion'],
  amount: ['monto', 'importe', 'valor', 'amount', 'total'],
  debit: ['debito', 'debit', 'cargo', 'retiro', 'salida', 'withdrawal', 'gasto'],
  credit: ['credito', 'credit', 'abono', 'deposito', 'entrada', 'deposit', 'ingreso'],
  balance: ['saldo', 'balance', 'saldo disponible'],
};

/** Quita tildes y signos para comparar nombres de columna. */
function normalizar(texto: string): string {
  return texto
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function pegaCon(celda: string, nombres: readonly string[]): boolean {
  const limpio = normalizar(celda);
  if (!limpio) return false;
  return nombres.some((nombre) => limpio === nombre || limpio.includes(nombre));
}

/**
 * Busca la fila de encabezados. Muchos bancos ponen antes el nombre del
 * cliente y el número de cuenta, así que no siempre es la primera.
 */
export function findHeaderRow(filas: readonly (readonly string[])[]): number {
  let mejor = -1;
  let mejorPuntaje = 0;

  for (let i = 0; i < Math.min(filas.length, 25); i++) {
    const fila = filas[i];
    if (!fila || fila.length < 2) continue;

    let puntaje = 0;
    if (fila.some((celda) => pegaCon(celda, NOMBRES.date))) puntaje += 2;
    if (fila.some((celda) => pegaCon(celda, NOMBRES.description))) puntaje += 2;
    if (fila.some((celda) => pegaCon(celda, NOMBRES.amount))) puntaje += 2;
    if (fila.some((celda) => pegaCon(celda, NOMBRES.debit))) puntaje += 1;
    if (fila.some((celda) => pegaCon(celda, NOMBRES.credit))) puntaje += 1;
    if (fila.some((celda) => pegaCon(celda, NOMBRES.balance))) puntaje += 1;

    if (puntaje > mejorPuntaje) {
      mejorPuntaje = puntaje;
      mejor = i;
    }
  }

  return mejorPuntaje >= 3 ? mejor : -1;
}

export function detectColumns(encabezado: readonly string[]): ColumnMap | null {
  const buscar = (nombres: readonly string[]): number =>
    encabezado.findIndex((celda) => pegaCon(celda, nombres));

  const date = buscar(NOMBRES.date);
  const description = buscar(NOMBRES.description);
  const debit = buscar(NOMBRES.debit);
  const credit = buscar(NOMBRES.credit);

  // La columna de saldo se parece a la de monto; se descarta primero
  const saldo = buscar(NOMBRES.balance);
  const amount = encabezado.findIndex(
    (celda, indice) => indice !== saldo && pegaCon(celda, NOMBRES.amount),
  );

  if (date < 0) return null;
  if (amount < 0 && debit < 0 && credit < 0) return null;

  const mapa: ColumnMap = { date, description };
  if (amount >= 0) mapa.amount = amount;
  if (debit >= 0) mapa.debit = debit;
  if (credit >= 0) mapa.credit = credit;
  return mapa;
}

/* ------------------------------------------------------------------ */
/* Montos                                                             */
/* ------------------------------------------------------------------ */

/**
 * Lee un monto escrito como sea: 1,234.56 · 1.234,56 · (123.45) · RD$1,200 · 500-
 * Devuelve centavos con signo, o null si no hay número.
 */
export function parseLooseAmount(texto: string): Cents | null {
  const original = texto.trim();
  if (!original) return null;

  // Los paréntesis y el menos al final son formas de escribir un negativo
  const negativo =
    /^\(.*\)$/.test(original) || original.startsWith('-') || /-\s*$/.test(original);

  const soloNumero = original.replace(/[^0-9.,]/g, '');
  if (!soloNumero || !/\d/.test(soloNumero)) return null;

  const ultimaComa = soloNumero.lastIndexOf(',');
  const ultimoPunto = soloNumero.lastIndexOf('.');
  let decimal = '';

  if (ultimaComa >= 0 && ultimoPunto >= 0) {
    // El que va más a la derecha es el decimal
    decimal = ultimaComa > ultimoPunto ? ',' : '.';
  } else if (ultimaComa >= 0 || ultimoPunto >= 0) {
    const signo = ultimaComa >= 0 ? ',' : '.';
    const posicion = Math.max(ultimaComa, ultimoPunto);
    const despues = soloNumero.length - posicion - 1;
    const veces = soloNumero.split(signo).length - 1;
    // Un solo signo seguido de tres cifras es separador de miles: 1.234
    decimal = veces === 1 && despues <= 2 ? signo : '';
  }

  let limpio = soloNumero;
  if (decimal) {
    const otro = decimal === ',' ? '.' : ',';
    limpio = limpio.split(otro).join('');
    limpio = limpio.replace(decimal, '.');
  } else {
    limpio = limpio.replace(/[.,]/g, '');
  }

  const valor = Number(limpio);
  if (!Number.isFinite(valor)) return null;

  const centavos = Math.round(valor * 100);
  return negativo ? -centavos : centavos;
}

/* ------------------------------------------------------------------ */
/* Fechas                                                             */
/* ------------------------------------------------------------------ */

export type DateOrder = 'dmy' | 'mdy' | 'ymd';

const MESES: Record<string, number> = {
  ene: 1, jan: 1, feb: 2, mar: 3, abr: 4, apr: 4, may: 5, jun: 6, jul: 7,
  ago: 8, aug: 8, sep: 9, set: 9, oct: 10, nov: 11, dic: 12, dec: 12,
};

interface Partes {
  a: number;
  b: number;
  c: number;
  /** true cuando el mes venía escrito con letras y no hay duda. */
  mesLiteral?: boolean;
}

function partir(texto: string): Partes | null {
  const limpio = texto.trim().replace(/\s+\d{1,2}:\d{2}.*$/, '');

  // 12-ene-2026 o 12 ene 2026
  const conLetras = /^(\d{1,2})[\s/-]([a-zA-Zá-ú]{3,})[\s/-](\d{2,4})$/.exec(limpio);
  if (conLetras) {
    const mes = MESES[normalizar(conLetras[2] ?? '').slice(0, 3)];
    if (mes) {
      return {
        a: Number(conLetras[1]),
        b: mes,
        c: Number(conLetras[3]),
        mesLiteral: true,
      };
    }
  }

  const numeros = limpio.split(/[/\-.]/).map((parte) => Number(parte.trim()));
  if (numeros.length !== 3 || numeros.some((valor) => !Number.isFinite(valor))) return null;
  return { a: numeros[0] ?? 0, b: numeros[1] ?? 0, c: numeros[2] ?? 0 };
}

/**
 * Mira todas las fechas del archivo para saber si es día/mes o mes/día.
 * Si ningún número pasa de 12, no se puede saber: devuelve null y hay que preguntar.
 */
export function detectDateOrder(valores: readonly string[]): DateOrder | null {
  let primeroGrande = false;
  let segundoGrande = false;
  let isoClaro = false;

  for (const valor of valores) {
    const partes = partir(valor);
    if (!partes) continue;

    if (partes.a > 31) {
      isoClaro = true;
      continue;
    }
    if (partes.mesLiteral) {
      primeroGrande = true;
      continue;
    }
    if (partes.a > 12) primeroGrande = true;
    if (partes.b > 12) segundoGrande = true;
  }

  if (isoClaro && !primeroGrande && !segundoGrande) return 'ymd';
  if (primeroGrande && !segundoGrande) return 'dmy';
  if (segundoGrande && !primeroGrande) return 'mdy';
  if (isoClaro) return 'ymd';
  return null;
}

/** Convierte a AAAA-MM-DD con el orden que se haya decidido. */
export function parseLooseDate(texto: string, orden: DateOrder): IsoDate | null {
  const partes = partir(texto);
  if (!partes) return null;

  let dia: number;
  let mes: number;
  let anio: number;

  if (partes.a > 31) {
    anio = partes.a;
    mes = partes.b;
    dia = partes.c;
  } else if (partes.mesLiteral) {
    dia = partes.a;
    mes = partes.b;
    anio = partes.c;
  } else if (orden === 'ymd') {
    anio = partes.a;
    mes = partes.b;
    dia = partes.c;
  } else if (orden === 'mdy') {
    mes = partes.a;
    dia = partes.b;
    anio = partes.c;
  } else {
    dia = partes.a;
    mes = partes.b;
    anio = partes.c;
  }

  if (anio < 100) anio += anio > 70 ? 1900 : 2000;
  if (mes < 1 || mes > 12 || dia < 1 || dia > 31) return null;

  const iso = `${anio}-${String(mes).padStart(2, '0')}-${String(dia).padStart(2, '0')}`;
  return isValidIsoDate(iso) ? iso : null;
}

