/* Categoría a partir de la descripción                                */
/* ------------------------------------------------------------------ */

/**
 * Pistas por comercio. El orden importa: la primera que pegue, gana.
 * Están primero las más específicas.
 */
const PISTAS: readonly (readonly [RegExp, string])[] = [
  [/\b(nacional|jumbo|sirena|bravo|pricesmart|ole|pola|supermercad|super\b|market)/i, 'supermercado'],
  [/\b(colmado|bodega)/i, 'colmado'],
  [/\b(uber eats|pedidos ?ya|delivery|glovo)/i, 'delivery'],
  [/\b(uber|indrive|didi|taxi|apolo)/i, 'taxi'],
  [/\b(shell|texaco|sunix|isla|total|petrol|gasolin|combustible|fuel)/i, 'gasolina'],
  [/\b(peaje|paso ?rapido|autopista)/i, 'peaje'],
  [/\b(omsa|metro|telef[eé]rico|guagua)/i, 'transporte-publico'],
  [/\b(claro|altice|viva|wind ?telecom|internet|fibra)/i, 'internet'],
  [/\b(edesur|edenorte|edeeste|ede ?este|energia|luz)/i, 'luz'],
  [/\b(caasd|inapa|corasaan|agua)/i, 'agua'],
  [/\b(netflix|spotify|disney|hbo|max|youtube|apple\.com|icloud|prime video|suscrip)/i, 'suscripciones'],
  [/\b(farmacia|carol|gbc|los hidalgos|medicamento|clinica|hospital|laboratorio|cedimat|ars |senasa|humano)/i, 'salud'],
  [/\b(colegio|universidad|unapec|pucmm|intec|utesa|uasd|matricula|inscripcion)/i, 'colegio'],
  [/\b(pizza|burger|wendy|mcdonald|kfc|pollo|domino|subway|taco)/i, 'comida-rapida'],
  [/\b(restaurant|resto|adrian tropical|bar |cerveceria|grill|comedor)/i, 'restaurantes'],
  [/\b(cafe|starbucks|barista|coffee)/i, 'cafe'],
  [/\b(alquiler|renta|condominio|inquilino)/i, 'vivienda'],
  [/\b(zara|forever|shoes|tienda|boutique|mall|sambil|agora|blue ?mall)/i, 'ropa'],
  [/\b(salon|barberia|spa|belleza|unas|peluqueria)/i, 'belleza'],
  [/\b(gimnasio|gym|smart ?fit|crossfit)/i, 'gimnasio'],
  [/\b(remesa|western union|caribe express|vimenca|ria |moneygram)/i, 'remesas'],
  [/\b(comision|cargo por|mantenimiento de cuenta|itbis|fee)/i, 'comisiones'],
  [/\b(seguro|poliza|humano seguros|mapfre)/i, 'seguros'],
  [/\b(dgii|impuesto|ayuntamiento|tax)/i, 'impuestos'],
  [/\b(prestamo|cuota|financiamiento|banco popular prest)/i, 'deuda'],
  [/\b(cine|caribbean cinemas|teatro|concierto|juego)/i, 'entretenimiento'],
  [/\b(hotel|airbnb|vuelo|arajet|copa|jetblue|boleto)/i, 'viajes'],
  [/\b(veterinari|mascota|petco)/i, 'mascotas'],
];

const PISTAS_INGRESO: readonly (readonly [RegExp, string])[] = [
  [/\b(nomina|salario|sueldo|payroll|quincena)/i, 'salario'],
  [/\b(remesa|western union|caribe express|vimenca|ria |moneygram)/i, 'remesa-recibida'],
  [/\b(reembolso|devolucion|refund)/i, 'reembolso'],
  [/\b(freelance|honorario|factura)/i, 'freelance'],
  [/\b(interes|dividendo|rendimiento)/i, 'inversion-ingreso'],
];

export function guessCategory(descripcion: string): string {
  for (const [patron, categoria] of PISTAS) {
    if (patron.test(descripcion)) return categoria;
  }
  return 'otros';
}

export function guessIncomeSource(descripcion: string): string {
  for (const [patron, fuente] of PISTAS_INGRESO) {
    if (patron.test(descripcion)) return fuente;
  }
  return 'otro-ingreso';
}

/* ------------------------------------------------------------------ */
/* Filas listas para importar                                          */
/* ------------------------------------------------------------------ */

export interface DraftRow {
  /** Número de fila en el archivo, para poder señalarla. */
  line: number;
  date: IsoDate;
  description: string;
  /** Negativo es gasto, positivo es ingreso. */
  amount: Cents;
  categoryId: string;
  /** true cuando ya existe un movimiento igual. */
  duplicate: boolean;
  include: boolean;
}

export interface ImportPreview {
  rows: DraftRow[];
  /** Filas que no se pudieron leer, con el motivo. */
  skipped: { line: number; reason: string }[];
  dateOrder: DateOrder;
  /** true si el orden de la fecha se eligió sin estar seguro. */
  dateAmbiguous: boolean;
}

export interface ImportOptions {
  columns: ColumnMap;
  dateOrder?: DateOrder;
  currency: Currency;
  accountId?: string;
}

export function buildPreview(
  data: AppData,
  filas: readonly (readonly string[])[],
  encabezado: number,
  options: ImportOptions,
): ImportPreview {
  const cuerpo = filas.slice(encabezado + 1);
  const columnas = options.columns;
  const anchoEsperado = (filas[encabezado] ?? []).length;

  const fechas = cuerpo.map((fila) => fila[columnas.date] ?? '');
  const detectado = detectDateOrder(fechas);
  const orden = options.dateOrder ?? detectado ?? 'dmy';

  const rows: DraftRow[] = [];
  const skipped: { line: number; reason: string }[] = [];

  cuerpo.forEach((fila, indice) => {
    const linea = encabezado + indice + 2;

    /*
     * Una fila con más celdas que el encabezado casi siempre significa que el
     * banco escribió un monto como 3,250.00 sin comillas: el separador partió
     * el número y todo lo demás quedó corrido una columna. Importarla daría
     * RD$3 en vez de RD$3,250, así que se aparta en vez de adivinar.
     */
    if (anchoEsperado > 0 && fila.length > anchoEsperado) {
      skipped.push({
        line: linea,
        reason: 'Trae más columnas de las que dice el encabezado',
      });
      return;
    }

    const fecha = parseLooseDate(fila[columnas.date] ?? '', orden);
    if (!fecha) {
      skipped.push({ line: linea, reason: 'La fecha no se entiende' });
      return;
    }

    const monto = montoDeFila(fila, columnas);
    if (monto === null || monto === 0) {
      skipped.push({ line: linea, reason: 'El monto no se entiende' });
      return;
    }

    const descripcion = (fila[columnas.description] ?? '').trim() || 'Sin descripción';

    rows.push({
      line: linea,
      date: fecha,
      description: descripcion,
      amount: monto,
      categoryId: monto < 0 ? guessCategory(descripcion) : guessIncomeSource(descripcion),
      duplicate: yaExiste(data, fecha, monto, descripcion),
      include: true,
    });
  });

  // Marca los que están repetidos dentro del propio archivo
  const vistos = new Set<string>();
  for (const fila of rows) {
    const llave = `${fila.date}|${fila.amount}|${normalizar(fila.description)}`;
    if (vistos.has(llave)) fila.duplicate = true;
    vistos.add(llave);
  }

  for (const fila of rows) {
    if (fila.duplicate) fila.include = false;
  }

  return { rows, skipped, dateOrder: orden, dateAmbiguous: detectado === null };
}

function montoDeFila(fila: readonly string[], columnas: ColumnMap): Cents | null {
  if (columnas.amount !== undefined) {
    return parseLooseAmount(fila[columnas.amount] ?? '');
  }

  const debito = columnas.debit !== undefined ? parseLooseAmount(fila[columnas.debit] ?? '') : null;
  const credito =
    columnas.credit !== undefined ? parseLooseAmount(fila[columnas.credit] ?? '') : null;

  // En columnas separadas el débito viene sin signo: es lo que sale
  if (debito) return -Math.abs(debito);
  if (credito) return Math.abs(credito);
  return null;
}

/** Busca un movimiento igual: mismo día, mismo monto y descripción parecida. */
function yaExiste(data: AppData, fecha: IsoDate, monto: Cents, descripcion: string): boolean {
  const absoluto = Math.abs(monto);
  const limpio = normalizar(descripcion);

  return data.transactions.some((tx) => {
    if (tx.date !== fecha) return false;
    if (tx.kind !== 'expense' && tx.kind !== 'income') return false;
    if (tx.amount !== absoluto) return false;
    if (tx.kind === 'expense' && monto > 0) return false;
    if (tx.kind === 'income' && monto < 0) return false;
    return normalizar(tx.note ?? '') === limpio;
  });
}

/** Convierte las filas elegidas en movimientos de verdad. */
export function toTransactions(
  rows: readonly DraftRow[],
  options: ImportOptions,
  rate: number,
): Transaction[] {
  const ahora = new Date().toISOString();

  return rows
    .filter((fila) => fila.include)
    .map((fila) => {
      const base = {
        id: newId(),
        date: fila.date,
        amount: Math.abs(fila.amount),
        currency: options.currency,
        note: fila.description,
        fxRate: rate,
        // La tasa de hoy no es la del día del movimiento: queda marcada
        fxEstimated: true,
        createdAt: ahora,
        updatedAt: ahora,
      };

      if (fila.amount < 0) {
        const gasto: ExpenseTx = { ...base, kind: 'expense', categoryId: fila.categoryId };
        if (options.accountId) gasto.accountId = options.accountId;
        return gasto;
      }

      const ingreso: IncomeTx = { ...base, kind: 'income', sourceId: fila.categoryId };
      if (options.accountId) ingreso.accountId = options.accountId;
      return ingreso;
    });
}
