/**
 * Corregir un movimiento: abre el mismo formulario con el que se creó.
 */

import type { Transaction } from '../../domain/types';
import { GastoForm } from '../registrar/GastoForm';
import { IngresoForm } from '../registrar/IngresoForm';
import { TransferenciaForm } from '../registrar/TransferenciaForm';
import { CambioForm } from '../registrar/CambioForm';

export function EditarMovimiento({ tx, onDone }: { tx: Transaction; onDone: () => void }) {
  switch (tx.kind) {
    case 'expense':
      return <GastoForm transaction={tx} onDone={onDone} />;
    case 'income':
      return <IngresoForm transaction={tx} onDone={onDone} />;
    case 'transfer':
      return <TransferenciaForm transaction={tx} onDone={onDone} />;
    case 'exchange':
      return <CambioForm transaction={tx} onDone={onDone} />;
  }
}
