/**
 * Fechas.
 *
 * Las fechas de los movimientos se guardan como 'AAAA-MM-DD' sin hora ni zona:
 * un gasto del 5 de noviembre es del 5 de noviembre, viaje la persona donde viaje.
 */

export type IsoDate = string; // AAAA-MM-DD
export type YearMonth = string; // AAAA-MM

export const MONTHS = [
  'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
  'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre',
] as const;

export const MONTHS_SHORT = [
  'Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun',
  'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic',
] as const;

export function today(): IsoDate {
  return toIsoDate(new Date());
}

export function toIsoDate(date: Date): IsoDate {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

export function isValidIsoDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(`${value}T12:00:00`);
  return !Number.isNaN(parsed.getTime()) && toIsoDate(parsed) === value;
}

/** Mediodía local, para que ningún cambio de zona mueva el día. */
export function parseIsoDate(value: IsoDate): Date {
  return new Date(`${value}T12:00:00`);
}

export function yearMonthOf(value: IsoDate): YearMonth {
  return value.slice(0, 7);
}

export function currentYearMonth(): YearMonth {
  return yearMonthOf(today());
}

export function monthIndex(ym: YearMonth): number {
  return Number(ym.slice(5, 7)) - 1;
}

export function yearOf(ym: YearMonth): number {
  return Number(ym.slice(0, 4));
}

export function monthName(ym: YearMonth): string {
  return MONTHS[monthIndex(ym)] ?? '';
}

export function monthShort(ym: YearMonth): string {
  return MONTHS_SHORT[monthIndex(ym)] ?? '';
}

/** Mueve un AAAA-MM hacia atrás o adelante. shiftMonth('2026-01', -1) da '2025-12'. */
export function shiftMonth(ym: YearMonth, delta: number): YearMonth {
  const date = new Date(yearOf(ym), monthIndex(ym) + delta, 1);
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
}

/** Los últimos n meses terminando en ym, del más viejo al más nuevo. */
export function lastMonths(ym: YearMonth, count: number): YearMonth[] {
  return Array.from({ length: count }, (_, i) => shiftMonth(ym, i - count + 1));
}

/** Días que faltan para el próximo día n del mes. Hoy devuelve 0. */
export function daysUntilMonthDay(day: number, from: Date = new Date()): number | null {
  if (!Number.isInteger(day) || day < 1 || day > 31) return null;

  const start = new Date(from.getFullYear(), from.getMonth(), from.getDate());
  let target = new Date(from.getFullYear(), from.getMonth(), day);

  // Si el mes no tiene ese día, usa el último día del mes
  if (target.getMonth() !== from.getMonth()) {
    target = new Date(from.getFullYear(), from.getMonth() + 1, 0);
  }
  if (target < start) {
    target = new Date(from.getFullYear(), from.getMonth() + 1, day);
    if (target.getMonth() !== (from.getMonth() + 1) % 12) {
      target = new Date(from.getFullYear(), from.getMonth() + 2, 0);
    }
  }

  return Math.round((target.getTime() - start.getTime()) / 86_400_000);
}

export function daysInMonth(ym: YearMonth): number {
  return new Date(yearOf(ym), monthIndex(ym) + 1, 0).getDate();
}

/** "Hoy", "Ayer" o "5 Nov" */
export function relativeDate(value: IsoDate, from: Date = new Date()): string {
  const date = parseIsoDate(value);
  const sameDay = (a: Date, b: Date) => a.toDateString() === b.toDateString();

  if (sameDay(date, from)) return 'Hoy';

  const yesterday = new Date(from.getTime() - 86_400_000);
  if (sameDay(date, yesterday)) return 'Ayer';

  return `${date.getDate()} ${MONTHS_SHORT[date.getMonth()] ?? ''}`;
}
