/**
 * Piezas que comparten los cuatro formularios de registro.
 */

import { newId } from '../../lib/id';
import { today } from '../../lib/date';
import type { AppData } from '../../domain/types';

export interface FormBase {
  fecha: string;
  nota: string;
}

export function baseInicial(): FormBase {
  return { fecha: today(), nota: '' };
}

/** Campos que lleva todo movimiento al guardarse. */
export function sello(data: AppData) {
  const ahora = new Date().toISOString();
  return {
    id: newId(),
    fxRate: data.fx.dopPerUsd,
    createdAt: ahora,
    updatedAt: ahora,
  };
}

/** Primer error de un campo, si lo hay. */
export function errorDe(
  problemas: readonly { field: string; message: string }[],
  campo: string,
): string | undefined {
  return problemas.find((problema) => problema.field === campo)?.message;
}
