/**
 * Armazón de la aplicación: barra de arriba, pantalla activa y barra de abajo.
 *
 * La navegación es estado local, sin librería de rutas: la app corre dentro de
 * Capacitor desde el sistema de archivos, donde las URLs no aportan nada.
 */

import { useEffect, useState } from 'react';
import { useApp } from '../store/useApp';
import { Bloqueo } from './Bloqueo';
import { Bienvenida } from '../screens/bienvenida/Bienvenida';
import { useAuth } from '../store/useAuth';
import { usePremium } from '../store/usePremium';
import { t } from '../i18n';
import { countOf, joinList } from '../lib/text';
import { Icon } from '../ui/Icon';
import type { IconName } from '../ui/Icon';
import { Note, Sheet } from '../ui/overlays';
import { RegistrarSheet } from '../screens/registrar/RegistrarSheet';
import { Button } from '../ui/primitives';
import { Inicio } from '../screens/Inicio';
import { Movimientos } from '../screens/Movimientos';
import { Reportes } from '../screens/Reportes';
import { Ajustes } from '../screens/Ajustes';
import { Cuentas } from '../screens/Cuentas';
import './shell.css';

export type ScreenId = 'inicio' | 'movimientos' | 'reportes' | 'ajustes' | 'cuentas';

interface Tab {
  id: ScreenId;
  icon: IconName;
  label: string;
}

const TABS: Tab[] = [
  { id: 'inicio', icon: 'inicio', label: t('nav.inicio') },
  { id: 'movimientos', icon: 'movimientos', label: t('nav.movimientos') },
  { id: 'reportes', icon: 'reportes', label: t('nav.reportes') },
  { id: 'ajustes', icon: 'ajustes', label: t('nav.ajustes') },
];

export function AppShell() {
  const [screen, setScreen] = useState<ScreenId>('inicio');
  const [registrarAbierto, setRegistrarAbierto] = useState(false);

  const ready = useApp((state) => state.ready);
  const unlocked = useApp((state) => state.unlocked);
  const origin = useApp((state) => state.origin);
  const onboardedAt = useApp((state) => state.data.settings.onboardedAt);
  const init = useApp((state) => state.init);
  const applyDueRecurrences = useApp((state) => state.applyDueRecurrences);
  const theme = useApp((state) => state.data.settings.theme);
  const note = useApp((state) => state.note);
  const clearNote = useApp((state) => state.clearNote);
  const migration = useApp((state) => state.migration);
  const dismissMigration = useApp((state) => state.dismissMigration);

  // Carga los datos del dispositivo y registra los recurrentes que ya tocaban
  // Lee la sesión guardada, si la hay. No pide nada a la red.
  useEffect(() => {
    useAuth.getState().init();
    usePremium.getState().init();
  }, []);

  useEffect(() => {
    init();
    // Si el teléfono arrancó vacío, mira si el sistema guardó una copia
    void useApp.getState().recoverIfEmpty();
    // Y la tasa del día, que si no se queda clavada en la de fábrica
    void useApp.getState().refreshRate();
    const aplicados = applyDueRecurrences();
    if (aplicados > 0) {
      useApp
        .getState()
        .notify(
          aplicados === 1
            ? 'Se registró 1 gasto recurrente'
            : `Se registraron ${aplicados} movimientos recurrentes`,
        );
    }
  }, [init, applyDueRecurrences]);

  // Aplica el tema al documento
  useEffect(() => {
    document.documentElement.dataset.tema = theme === 'light' ? 'dia' : theme === 'dark' ? 'noche' : 'auto';
  }, [theme]);

  // La nota se va sola
  useEffect(() => {
    if (!note) return;
    const timer = window.setTimeout(clearNote, 3000);
    return () => window.clearTimeout(timer);
  }, [note, clearNote]);

  if (!ready) return null;
  // Con PIN puesto, no se ve nada de la app hasta entrar
  if (!unlocked) return <Bloqueo />;
  // Teléfono nuevo y sin datos que migrar: primero preguntamos dónde vive
  if (origin === 'nuevo' && onboardedAt === undefined) return <Bienvenida />;

  return (
    <div className="capa">
      {screen === 'inicio' && <Inicio onVerCuentas={() => setScreen('cuentas')} />}
      {screen === 'movimientos' && <Movimientos />}
      {screen === 'reportes' && <Reportes />}
      {screen === 'ajustes' && <Ajustes />}
      {screen === 'cuentas' && <Cuentas onVolver={() => setScreen('inicio')} />}

      <nav className="barra-inf" aria-label={t('nav.inicio')}>
        {TABS.slice(0, 2).map((tab) => (
          <TabButton key={tab.id} tab={tab} active={screen === tab.id} onClick={setScreen} />
        ))}

        <button
          type="button"
          className="pestana__centro"
          onClick={() => setRegistrarAbierto(true)}
          aria-label={t('nav.registrar')}
        >
          <Icon name="mas" size={24} />
        </button>

        {TABS.slice(2).map((tab) => (
          <TabButton key={tab.id} tab={tab} active={screen === tab.id} onClick={setScreen} />
        ))}
      </nav>

      <RegistrarSheet
        key={registrarAbierto ? 'abierta' : 'cerrada'}
        open={registrarAbierto} onClose={() => setRegistrarAbierto(false)} />

      <Sheet
        open={migration !== undefined}
        title={t('migracion.titulo')}
        onClose={dismissMigration}
      >
        {migration && (
          <>
            <p className="texto-menor" style={{ marginBottom: 'var(--e4)' }}>
              {t('migracion.resumen', {
                partes: joinList([
                  migration.transactions > 0
                    ? countOf(migration.transactions, 'movimiento', 'movimientos')
                    : '',
                  migration.accounts > 0 ? countOf(migration.accounts, 'cuenta', 'cuentas') : '',
                  migration.cards > 0 ? countOf(migration.cards, 'tarjeta', 'tarjetas') : '',
                ]),
              })}
            </p>
            {migration.notes.map((nota) => (
              <p key={nota} className="texto-menor" style={{ marginBottom: 'var(--e3)' }}>
                {nota}
              </p>
            ))}
            <Button wide onClick={dismissMigration}>
              {t('migracion.entendido')}
            </Button>
          </>
        )}
      </Sheet>

      {note && <Note text={note} />}
    </div>
  );
}

function TabButton({
  tab,
  active,
  onClick,
}: {
  tab: Tab;
  active: boolean;
  onClick: (id: ScreenId) => void;
}) {
  return (
    <button
      type="button"
      className="pestana"
      aria-current={active ? 'page' : undefined}
      onClick={() => onClick(tab.id)}
    >
      <Icon name={tab.icon} />
      {tab.label}
    </button>
  );
}
