/** Mover dinero entre dos cuentas propias, en la misma moneda. */

import { useState } from 'react';
import { t } from '../../i18n';
import { useApp, useData } from '../../store/useApp';
import type { Cents, Currency } from '../../lib/money';
import type { AppData, TransferTx } from '../../domain/types';
import type { ValidationIssue } from '../../domain/ledger';
import { AmountInput } from '../../ui/AmountInput';
import { AccountPicker } from '../../ui/pickers';
import { Button, Notice } from '../../ui/primitives';
import { Field } from '../../ui/forms';
import { overdraftWarning, validateTransaction } from '../../domain/ledger';
import { formatNumber, parseAmount } from '../../lib/money';
import { baseInicial, errorDe, sello } from './comun';
import { cashAccount } from '../../domain/accounts';
import { today } from '../../lib/date';

export function TransferenciaForm({
  onDone,
  transaction,
  haciaEfectivo = false,
}: {
  onDone: () => void;
  transaction?: TransferTx;
  /** Sacar del cajero: el destino viene puesto y solo falta el monto. */
  haciaEfectivo?: boolean;
}) {
  const editando = transaction !== undefined;
  const data = useData();
  const addTransaction = useApp((state) => state.addTransaction);
  const replaceTransaction = useApp((state) => state.replaceTransaction);
  const notify = useApp((state) => state.notify);

  const [monto, setMonto] = useState<Cents | null>(transaction?.amount ?? null);
  const [moneda, setMoneda] = useState<Currency>(
    transaction?.currency ?? data.profile.mainCurrency,
  );
  const [origen, setOrigen] = useState<string | undefined>(
    () => transaction?.fromAccountId ?? (haciaEfectivo ? primerBanco(data) : undefined),
  );
  const [destino, setDestino] = useState<string | undefined>(
    () => transaction?.toAccountId ?? (haciaEfectivo ? cashAccount(data)?.id : undefined),
  );
  const [comision, setComision] = useState(
    transaction?.fee ? formatNumber(transaction.fee) : '',
  );
  const [base, setBase] = useState(() =>
    transaction ? { fecha: transaction.date, nota: transaction.note ?? '' } : baseInicial(),
  );
  const [problemas, setProblemas] = useState<ValidationIssue[]>([]);

  function construir(): TransferTx {
    const tx: TransferTx = {
      ...sello(data),
      kind: 'transfer',
      date: base.fecha,
      amount: monto ?? 0,
      currency: moneda,
      fromAccountId: origen ?? '',
      toAccountId: destino ?? '',
    };
    const cobro = parseAmount(comision);
    if (cobro && cobro > 0) tx.fee = cobro;
    if (base.nota.trim()) tx.note = base.nota.trim();
    return tx;
  }

  const aviso = !editando && monto && origen ? overdraftWarning(data, construir()) : null;

  function guardar() {
    const tx = construir();
    const encontrados = validateTransaction(data, tx);
    setProblemas(encontrados);
    if (encontrados.length > 0) return;

    if (editando) {
      replaceTransaction(transaction.id, tx);
      notify(t('transferencia.transferenciaCorregida'));
    } else {
      addTransaction(tx);
      notify(t('transferencia.transferenciaGuardada'));
    }
    onDone();
  }

  return (
    <>
      <AmountInput
        cents={monto}
        currency={moneda}
        onChange={setMonto}
        onCurrencyChange={setMoneda}
        rate={data.fx.dopPerUsd}
        autoFocus
        label={t('transferencia.cuantoMueves')}
      />
      {errorDe(problemas, 'amount') && (
        <p className="campo__error" style={{ textAlign: 'center', marginTop: 0 }}>
          {errorDe(problemas, 'amount')}
        </p>
      )}

      <p className="campo__etiqueta">{t('transferencia.deDondeSale')}</p>
      <AccountPicker
        accounts={data.accounts}
        value={origen}
        onChange={setOrigen}
        currency={moneda}
        exclude={destino}
        banksOnly
      />
      {errorDe(problemas, 'fromAccountId') && (
        <p className="campo__error">{errorDe(problemas, 'fromAccountId')}</p>
      )}

      <p className="campo__etiqueta" style={{ marginTop: 'var(--e5)' }}>
        A dónde va
      </p>
      <AccountPicker
        accounts={data.accounts}
        value={destino}
        onChange={setDestino}
        currency={moneda}
        exclude={origen}
        banksOnly
      />
      {errorDe(problemas, 'toAccountId') && (
        <p className="campo__error">{errorDe(problemas, 'toAccountId')}</p>
      )}

      {aviso && (
        <div style={{ margin: 'var(--e4) 0' }}>
          <Notice tone="ambar" icon="⚠️">
            {aviso}
          </Notice>
        </div>
      )}

      <div style={{ marginTop: 'var(--e5)' }}>
        <Field
          label={t('transferencia.comisionDelBanco')}
          type="text"
          inputMode="decimal"
          placeholder="0.00"
          hint={t('transferencia.siElBancoTe')}
          value={comision}
          onChange={(event) => setComision(event.target.value)}
        />
        <Field
          label="Fecha"
          type="date"
          value={base.fecha}
          max={today()}
          onChange={(event) => setBase({ ...base, fecha: event.target.value })}
        />
        <Field
          label="Nota"
          type="text"
          placeholder={t('transferencia.paraElPagoDe')}
          value={base.nota}
          onChange={(event) => setBase({ ...base, nota: event.target.value })}
        />
      </div>

      <div className="hoja__pie">
        <Button wide onClick={guardar}>
          {editando ? t('transferencia.guardarCambios') : t('transferencia.guardarTransferencia')}
        </Button>
      </div>
    </>
  );
}

/** El banco con más movimiento, que es de donde suele salir el efectivo. */
function primerBanco(data: AppData): string | undefined {
  return data.accounts.find((cuenta) => !cuenta.archived && cuenta.kind === 'bank')?.id;
}
