/**
 * Quién puede usar las dos monedas.
 *
 * Con el plan gratis se trabaja en la moneda que se eligió al empezar. Manejar
 * pesos y dólares a la vez es de premium.
 *
 * Con una excepción que importa: a quien YA tiene algo registrado en la otra
 * moneda no se le cierra la puerta. Si alguien venía de la versión vieja con
 * una cuenta en dólares, o pagó, creó cuentas y luego canceló, sus datos
 * siguen siendo suyos y tiene que poder seguir usándolos. Lo que se bloquea es
 * empezar de nuevo en la otra moneda, no lo que ya existe.
 */

import type { AppData } from './types';
import type { Currency } from '../lib/money';

export const TODAS: readonly Currency[] = ['DOP', 'USD'];

export function laOtra(moneda: Currency): Currency {
  return moneda === 'DOP' ? 'USD' : 'DOP';
}

/** ¿Hay algo registrado en esta moneda? */
export function tieneAlgoEn(data: AppData, moneda: Currency): boolean {
  for (const cuenta of data.accounts) {
    if (cuenta.balances[moneda] !== undefined) return true;
    if (cuenta.credit?.limits[moneda] !== undefined) return true;
  }

  for (const tx of data.transactions) {
    if (tx.kind === 'exchange') {
      if (tx.fromCurrency === moneda || tx.toCurrency === moneda) return true;
    } else if (tx.currency === moneda) {
      return true;
    }
  }

  for (const presupuesto of data.budgets) {
    if (presupuesto.currency === moneda) return true;
  }
  for (const deuda of data.debts) {
    if (deuda.currency === moneda) return true;
  }
  for (const meta of data.goals) {
    if (meta.currency === moneda) return true;
  }
  for (const fijo of data.recurrences) {
    if (fijo.currency === moneda) return true;
  }

  return false;
}

/** Las monedas con las que esta persona puede trabajar hoy. */
export function monedasPermitidas(data: AppData, premium: boolean): Currency[] {
  if (premium) return [...TODAS];

  const principal = data.profile.mainCurrency;
  const otra = laOtra(principal);
  return tieneAlgoEn(data, otra) ? [principal, otra] : [principal];
}

export function puedeUsarMoneda(data: AppData, premium: boolean, moneda: Currency): boolean {
  return monedasPermitidas(data, premium).includes(moneda);
}

/** ¿Puede registrar un cambio de moneda? Hacen falta las dos. */
export function puedeCambiarMoneda(data: AppData, premium: boolean): boolean {
  return monedasPermitidas(data, premium).length > 1;
}
