/**
 * Piezas básicas de la interfaz.
 */

import type { ButtonHTMLAttributes, CSSProperties, ReactNode } from 'react';

/* --- Botón ---------------------------------------------------------------- */

export type ButtonVariant = 'principal' | 'suave' | 'contorno' | 'texto' | 'peligro';

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  wide?: boolean;
  small?: boolean;
  children: ReactNode;
}

export function Button({
  variant = 'principal',
  wide = false,
  small = false,
  className,
  type = 'button',
  children,
  ...rest
}: ButtonProps) {
  const classes = [
    'boton',
    `boton--${variant}`,
    wide ? 'boton--ancho' : '',
    small ? 'boton--chico' : '',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <button type={type} className={classes} {...rest}>
      {children}
    </button>
  );
}

/* --- Carta ---------------------------------------------------------------- */

export interface CardProps {
  children: ReactNode;
  /** Título de la tarjeta; si se pasa, se dibuja la cabecera. */
  title?: string;
  /** Acción a la derecha del título. */
  action?: ReactNode;
  variant?: 'normal' | 'plana' | 'hundida';
  className?: string;
  style?: CSSProperties;
}

export function Card({ children, title, action, variant = 'normal', className, style }: CardProps) {
  const classes = [
    'carta',
    variant === 'plana' ? 'carta--plana' : '',
    variant === 'hundida' ? 'carta--hundida' : '',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <section className={classes} style={style}>
      {(title ?? action) && (
        <header className="carta__cabeza">
          {title && <h2 className="titulo-seccion">{title}</h2>}
          {action}
        </header>
      )}
      {children}
    </section>
  );
}

/* --- Pastilla ------------------------------------------------------------- */

export type ChipTone = 'neutra' | 'azul' | 'verde' | 'roja' | 'ambar';

export function Chip({ tone = 'neutra', children }: { tone?: ChipTone; children: ReactNode }) {
  return <span className={`pastilla pastilla--${tone}`}>{children}</span>;
}

/* --- Aviso ---------------------------------------------------------------- */

export type NoticeTone = 'azul' | 'verde' | 'roja' | 'ambar';

const NOTICE_CLASS: Record<NoticeTone, string> = {
  azul: 'aviso--azul',
  verde: 'aviso--verde',
  roja: 'aviso--rojo',
  ambar: 'aviso--ambar',
};

export function Notice({
  tone = 'azul',
  icon,
  title,
  children,
}: {
  tone?: NoticeTone;
  icon?: string;
  /** Encabezado corto, para avisos que dicen algo y lo explican. */
  title?: string;
  children: ReactNode;
}) {
  return (
    <div className={`aviso ${NOTICE_CLASS[tone]}`} role="status">
      {icon && (
        <span className="aviso__icono" aria-hidden="true">
          {icon}
        </span>
      )}
      <div>
        {title && <p className="aviso__titulo">{title}</p>}
        <div>{children}</div>
      </div>
    </div>
  );
}

/* --- Estado vacío --------------------------------------------------------- */

export interface EmptyProps {
  mark?: string;
  title: string;
  text?: string;
  action?: ReactNode;
}

export function Empty({ mark, title, text, action }: EmptyProps) {
  return (
    <div className="vacio">
      {mark && (
        <div className="vacio__marca" aria-hidden="true">
          {mark}
        </div>
      )}
      <p className="vacio__titulo">{title}</p>
      {text && <p className="vacio__texto">{text}</p>}
      {action}
    </div>
  );
}
