/**
 * Puente con el teléfono.
 *
 * Capacitor pone los plugins nativos en window.Capacitor.Plugins. Se llega a
 * ellos así, sin importar paquetes, por dos razones: BiometricAuth es un
 * plugin propio escrito en Swift que no tiene paquete de npm, y la app web se
 * compila aparte del proyecto iOS, así que cuanto menos dependa de él, mejor.
 *
 * En el navegador no existe ninguno de estos y todo devuelve "no disponible",
 * que es justo lo que debe pasar.
 */

interface PluginBiometria {
  isAvailable: () => Promise<{ available: boolean; biometryType: string }>;
  authenticate: () => Promise<{ success: boolean; biometryType: string }>;
}

interface PluginPreferencias {
  get: (opciones: { key: string }) => Promise<{ value: string | null }>;
  set: (opciones: { key: string; value: string }) => Promise<void>;
  remove: (opciones: { key: string }) => Promise<void>;
}

interface PluginNavegador {
  open: (opciones: { url: string; presentationStyle?: string }) => Promise<void>;
  close: () => Promise<void>;
}

interface PluginApp {
  addListener: (
    evento: 'appUrlOpen',
    manejador: (datos: { url: string }) => void,
  ) => Promise<{ remove: () => Promise<void> }>;
}

interface ProductoTienda {
  id: string;
  nombre: string;
  /** Como lo escribe Apple: "USD 24.99". Respaldo para monedas que no sabemos escribir. */
  precio: string;
  /** El importe suelto, para escribirlo nosotros. */
  precioNumero?: number;
  /** Código ISO de la tienda de la persona: USD, DOP, EUR… */
  moneda?: string;
  descripcion: string;
  periodo?: 'mensual' | 'anual';
  pruebaDias?: number;
}

interface RespuestaSuscripcion {
  activo: boolean;
  producto?: string;
  hasta?: string;
  cancelado?: boolean;
  pendiente?: boolean;
}

interface PluginSuscripcion {
  productos: () => Promise<{ productos: ProductoTienda[] }>;
  estado: () => Promise<RespuestaSuscripcion>;
  comprar: (opciones: { productId: string }) => Promise<RespuestaSuscripcion>;
  restaurar: () => Promise<RespuestaSuscripcion>;
  addListener: (
    evento: 'suscripcionCambio',
    manejador: (datos: RespuestaSuscripcion) => void,
  ) => Promise<{ remove: () => Promise<void> }>;
}

export type { ProductoTienda, RespuestaSuscripcion };

interface PuenteCapacitor {
  isNativePlatform?: () => boolean;
  getPlatform?: () => string;
  Plugins?: {
    BiometricAuth?: PluginBiometria;
    Preferences?: PluginPreferencias;
    Browser?: PluginNavegador;
    App?: PluginApp;
    Suscripcion?: PluginSuscripcion;
  };
}

function puente(): PuenteCapacitor | undefined {
  return (globalThis as { Capacitor?: PuenteCapacitor }).Capacitor;
}

export function enElTelefono(): boolean {
  try {
    return puente()?.isNativePlatform?.() === true;
  } catch {
    return false;
  }
}

/* ------------------------------------------------------------------ */
/* Face ID y Touch ID                                                  */
/* ------------------------------------------------------------------ */

export type Biometria = 'faceID' | 'touchID' | 'ninguna';

/** Qué tipo de biometría tiene este teléfono, si tiene alguna. */
export async function tipoDeBiometria(): Promise<Biometria> {
  const plugin = puente()?.Plugins?.BiometricAuth;
  if (!plugin) return 'ninguna';
  try {
    const resultado = await plugin.isAvailable();
    if (!resultado.available) return 'ninguna';
    return resultado.biometryType === 'faceID' ? 'faceID' : 'touchID';
  } catch {
    return 'ninguna';
  }
}

export function nombreDeBiometria(tipo: Biometria): string {
  if (tipo === 'faceID') return 'Face ID';
  if (tipo === 'touchID') return 'Touch ID';
  return '';
}

/** Pide la huella o la cara. Devuelve si la persona pasó la prueba. */
export async function pedirBiometria(): Promise<boolean> {
  const plugin = puente()?.Plugins?.BiometricAuth;
  if (!plugin) return false;
  try {
    const resultado = await plugin.authenticate();
    return resultado.success === true;
  } catch {
    // Cancelar o fallar no es un error de la app: simplemente no entró
    return false;
  }
}

/* ------------------------------------------------------------------ */
/* Volver a la app después de entrar con Apple o Google                */
/* ------------------------------------------------------------------ */

/** Esquema propio de la app. Tiene que coincidir con el Info.plist. */
export const ESQUEMA = 'com.gestorrd.app';
export const VUELTA_DE_LOGIN = `${ESQUEMA}://auth`;

/**
 * Abre la página de Apple o Google en el navegador del sistema.
 *
 * Tiene que ser el del sistema y no un navegador dentro de la app: Google
 * rechaza los inicios de sesión desde webviews incrustadas.
 */
export async function abrirNavegador(url: string): Promise<boolean> {
  const plugin = puente()?.Plugins?.Browser;
  if (!plugin) return false;
  try {
    await plugin.open({ url, presentationStyle: 'popover' });
    return true;
  } catch {
    return false;
  }
}

export async function cerrarNavegador(): Promise<void> {
  const plugin = puente()?.Plugins?.Browser;
  if (!plugin) return;
  try {
    await plugin.close();
  } catch {
    // Puede que ya esté cerrado
  }
}

/**
 * Avisa cuando el teléfono abre la app con un enlace nuestro, que es como
 * vuelve el código después de entrar con Apple o Google.
 */
export async function alVolverDeLogin(manejador: (url: string) => void): Promise<void> {
  const plugin = puente()?.Plugins?.App;
  if (!plugin) return;
  try {
    await plugin.addListener('appUrlOpen', ({ url }) => {
      if (url.startsWith(ESQUEMA)) manejador(url);
    });
  } catch {
    // Sin el plugin, en el teléfono solo funcionará el correo
  }
}

/* ------------------------------------------------------------------ */
/* Suscripción                                                         */
/* ------------------------------------------------------------------ */

export function hayTienda(): boolean {
  const hay = puente()?.Plugins?.Suscripcion !== undefined;
  // Dentro del teléfono y sin plugin: algo se rompió en el registro nativo.
  // Vale la pena gritarlo, porque si no, la pantalla solo se ve vacía. En el
  // navegador no hay nada que gritar: ahí nunca hubo tienda.
  if (!hay && enElTelefono()) console.warn('[GestorRD] El plugin Suscripcion no está registrado.');
  return hay;
}

export async function planesDeLaTienda(): Promise<ProductoTienda[]> {
  const plugin = puente()?.Plugins?.Suscripcion;
  if (!plugin) return [];
  try {
    const { productos } = await plugin.productos();
    return productos;
  } catch (fallo) {
    console.warn('[GestorRD] La tienda no devolvió planes:', fallo);
    return [];
  }
}

export async function estadoDeSuscripcion(): Promise<RespuestaSuscripcion | null> {
  const plugin = puente()?.Plugins?.Suscripcion;
  if (!plugin) return null;
  try {
    return await plugin.estado();
  } catch {
    return null;
  }
}

export async function comprarPlan(productId: string): Promise<RespuestaSuscripcion | string> {
  const plugin = puente()?.Plugins?.Suscripcion;
  if (!plugin) return 'Las suscripciones solo funcionan en la app del teléfono.';
  try {
    return await plugin.comprar({ productId });
  } catch (fallo) {
    return fallo instanceof Error ? fallo.message : 'No se pudo completar la compra.';
  }
}

export async function restaurarCompras(): Promise<RespuestaSuscripcion | string> {
  const plugin = puente()?.Plugins?.Suscripcion;
  if (!plugin) return 'Las suscripciones solo funcionan en la app del teléfono.';
  try {
    return await plugin.restaurar();
  } catch (fallo) {
    return fallo instanceof Error ? fallo.message : 'No se pudo restaurar.';
  }
}

/** Avisa cuando la suscripción cambia por fuera: renovación, familia, otro equipo. */
export async function alCambiarSuscripcion(
  manejador: (datos: RespuestaSuscripcion) => void,
): Promise<void> {
  const plugin = puente()?.Plugins?.Suscripcion;
  if (!plugin) return;
  try {
    await plugin.addListener('suscripcionCambio', manejador);
  } catch {
    // Sin escucha, el estado se refresca al abrir la pantalla
  }
}

/* ------------------------------------------------------------------ */
/* Copia de seguridad en el almacenamiento del sistema                 */
/* ------------------------------------------------------------------ */

/**
 * iOS puede borrar el almacenamiento web de una app para hacer sitio. Es raro,
 * pero en una app de finanzas significaría perderlo todo. Por eso cada vez que
 * se guarda, se deja también una copia en el almacenamiento del sistema, que
 * iOS no toca. Si al arrancar el teléfono aparece vacío y aquí hay algo, se
 * recupera.
 */
const CLAVE_ESPEJO = 'gestorrd.v3.espejo';

export async function guardarEnElSistema(contenido: string): Promise<void> {
  const plugin = puente()?.Plugins?.Preferences;
  if (!plugin) return;
  try {
    await plugin.set({ key: CLAVE_ESPEJO, value: contenido });
  } catch {
    // El espejo es un seguro, no la fuente: si falla, la app sigue igual
  }
}

export async function leerDelSistema(): Promise<string | null> {
  const plugin = puente()?.Plugins?.Preferences;
  if (!plugin) return null;
  try {
    const { value } = await plugin.get({ key: CLAVE_ESPEJO });
    return value ?? null;
  } catch {
    return null;
  }
}
